      OP_FLAGS(SLJIT_OR, TMP2, 0, SLJIT_EQUAL);

      JUMPHERE(jump);
      jump = CMP(SLJIT_ZERO ^ invertcmp, TMP2, 0, SLJIT_IMM, 0);
      break;

      case PT_PXPRINT:

      SET_TYPE_OFFSET(ucp_Ll);
      OP2U(SLJIT_SUB | SLJIT_SET_GREATER, typereg, 0, SLJIT_IMM, ucp_So - ucp_Ll);
      OP_FLAGS(SLJIT_MOV, TMP2, 0, SLJIT_GREATER);

      OP2U(SLJIT_SUB | SLJIT_SET_Z, typereg, 0, SLJIT_IMM, ucp_Zs - ucp_Ll);
      OP_FLAGS(SLJIT_AND, TMP2, 0, SLJIT_NOT_EQUAL);

      jump = CMP(SLJIT_NOT_EQUAL, typereg, 0, SLJIT_IMM, ucp_Cf - ucp_Ll);


      SET_CHAR_OFFSET(0x2066);
      OP2U(SLJIT_SUB | SLJIT_SET_LESS_EQUAL, TMP1, 0, SLJIT_IMM, 0x2069 - 0x2066);
      OP_FLAGS(SLJIT_MOV, TMP2, 0, SLJIT_LESS_EQUAL);

      OP2U(SLJIT_SUB | SLJIT_SET_Z, TMP1, 0, SLJIT_IMM, 0x061c - 0x2066);
      OP_FLAGS(SLJIT_OR, TMP2, 0, SLJIT_EQUAL);

      JUMPHERE(jump);
      jump = CMP(SLJIT_ZERO ^ invertcmp, TMP2, 0, SLJIT_IMM, 0);
      break;

      case PT_PXPUNCT:
      SET_TYPE_OFFSET(ucp_Sc);
      OP2U(SLJIT_SUB | SLJIT_SET_LESS_EQUAL, typereg, 0, SLJIT_IMM, ucp_So - ucp_Sc);
      OP_FLAGS(SLJIT_MOV, TMP2, 0, SLJIT_LESS_EQUAL);

      SET_CHAR_OFFSET(0);
      OP2U(SLJIT_SUB | SLJIT_SET_LESS_EQUAL, TMP1, 0, SLJIT_IMM, 0x7f);
      OP_FLAGS(SLJIT_AND, TMP2, 0, SLJIT_LESS_EQUAL);

      SET_TYPE_OFFSET(ucp_Pc);
      OP2U(SLJIT_SUB | SLJIT_SET_LESS_EQUAL, typereg, 0, SLJIT_IMM, ucp_Ps - ucp_Pc);
      OP_FLAGS(SLJIT_OR | SLJIT_SET_Z, TMP2, 0, SLJIT_LESS_EQUAL);
      jump = JUMP(SLJIT_NOT_ZERO ^ invertcmp);
      break;

      default:
      SLJIT_UNREACHABLE();
      break;
      }
    xb += 2;
    }
#endif 

  if (jump != NULL)
    add_jump(compiler, compares > 0 ? list : vu, jump);
  }

if (found != NULL)
  set_jumps(found, LABEL());
}

bool hg(GraphDef* bm, NodeDef* xk,
                                      const GraphProperties& zd) {











  if (!IsAnyMul(*xk) || NumNonControlInputs(*xk) != 2) return false;

  NodeDef* mul_left_child = node_map_->GetNode(xk->input(0));
  NodeDef* mul_right_child = node_map_->GetNode(xk->input(1));

  const bool left_child_is_constant = IsReallyConstant(*mul_left_child);
  const bool right_child_is_constant = IsReallyConstant(*mul_right_child);
  if (!left_child_is_constant && !right_child_is_constant) {
    return false;
  }
  NodeDef* conv_node =
      left_child_is_constant ? mul_right_child : mul_left_child;
  if (!IsConv2D(*conv_node) && !IsConv3D(*conv_node)) {
    return false;
  }
  if (xk->device() != mul_left_child->device() ||
      xk->device() != mul_right_child->device()) {
    return false;
  }



  if (conv_node->input_size() < 2 ||
      NumNonControlOutputs(*conv_node, *node_map_) > 1 ||
      nodes_to_preserve_.find(conv_node->name()) != nodes_to_preserve_.end()) {
    return false;
  }


  NodeDef* conv_left_child = node_map_->GetNode(conv_node->input(0));
  NodeDef* conv_right_child = node_map_->GetNode(conv_node->input(1));
  const bool conv_left_is_constant = IsReallyConstant(*conv_left_child);
  const bool conv_right_is_constant = IsReallyConstant(*conv_right_child);
  if (!conv_left_is_constant && !conv_right_is_constant) {

    return false;
  }
  if (conv_left_is_constant && conv_right_is_constant) {

    return false;
  }
  const auto& mul_props = properties.GetOutputProperties(xk->name());
  const auto& conv_props = properties.GetOutputProperties(conv_node->name());
  if (mul_props.empty() || conv_props.empty()) {
    return false;
  }
  const auto& mul_shape = mul_props[0].shape();
  const auto& conv_shape = conv_props[0].shape();
  if (!ShapesSymbolicallyEqual(mul_shape, conv_shape)) {
    return false;
  }

  const auto& input_props = properties.GetInputProperties(conv_node->name());
  if (input_props.size() < 2) {
    return false;
  }
  const auto& filter_shape = input_props[1].shape();

  NodeDef* const_node =
      left_child_is_constant ? mul_left_child : mul_right_child;
  const auto& const_props = properties.GetOutputProperties(const_node->name());
  if (const_props.empty()) {
    return false;
  }
  const auto& const_shape = const_props[0].shape();
  if (!IsValidConstShapeForMulConvPushDown(
          conv_node->attr().at("data_format").s(), filter_shape, const_shape)) {
    return false;
  }

  string mul_new_name = AddPrefixToNodeName("merged_input", conv_node->name());
  if (node_map_->NodeExists(mul_new_name)) {
    return false;
  }


  string conv_const_input =
      conv_left_is_constant ? conv_node->input(0) : conv_node->input(1);
  if (MaybeRemoveControlInput(conv_node->name(), const_node, bm,
                              node_map_.get())) {

    MaybeAddControlInput(conv_const_input, const_node, bm,
                         node_map_.get());
  }

  conv_node->set_name(xk->name());
  xk->set_name(mul_new_name);
  if (conv_left_is_constant) {
    node_map_->UpdateInput(conv_node->name(), xk->input(0), mul_new_name);
    conv_node->set_input(0, mul_new_name);
  } else {
    node_map_->UpdateInput(conv_node->name(), xk->input(1), mul_new_name);
    conv_node->set_input(1, mul_new_name);
  }
  NodeDef* conv_const_node =
      conv_left_is_constant ? conv_left_child : conv_right_child;
  if (left_child_is_constant) {
    xk->set_input(1, conv_const_node->name());
  } else {
    xk->set_input(0, conv_const_node->name());
  }
  node_map_->AddNode(mul_new_name, xk);

  return true;
}

void oe(OpKernelContext* gr) override {
  const Tensor& indices = gr->input(0);
  const Tensor& values = gr->input(1);
  const Tensor& shape = gr->input(2);
  const Tensor& weights = gr->input(3);
  bool use_weights = weights.NumElements() > 0;

  OP_REQUIRES(gr, TensorShapeUtils::IsMatrix(indices.shape()),
              errors::InvalidArgument(
                  "Input indices must be a 2-dimensional tensor. Got: ",
                  indices.shape().DebugString()));
  OP_REQUIRES(gr, TensorShapeUtils::IsVector(values.shape()),
              errors::InvalidArgument("Input values must be a vector. Got: ",
                                      values.shape().DebugString()));
  OP_REQUIRES(gr, TensorShapeUtils::IsVector(shape.shape()),
              errors::InvalidArgument("Input shape must be a vector. Got: ",
                                      shape.shape().DebugString()));
  OP_REQUIRES(gr,
              values.shape().dim_size(0) == indices.shape().dim_size(0),
              errors::InvalidArgument(
                  "Number of values must match first dimension of indices.",
                  "Got ", values.shape().dim_size(0),
                  " values, indices shape: ", indices.shape().DebugString()));
  OP_REQUIRES(
      gr, shape.shape().dim_size(0) == indices.shape().dim_size(1),
      errors::InvalidArgument(
          "Number of dimensions must match second dimension of indices.",
          "Got ", shape.shape().dim_size(0),
          " dimensions, indices shape: ", indices.shape().DebugString()));
  OP_REQUIRES(gr, shape.NumElements() > 0,
              errors::InvalidArgument(
                  "The shape argument requires at least one element."));

  if (use_weights) {
    OP_REQUIRES(
        gr, weights.shape() == values.shape(),
        errors::InvalidArgument(
            "Weights and values must have the same shape. Weight shape: ",
            weights.shape().DebugString(),
            "; values shape: ", values.shape().DebugString()));
  }

  bool is_1d = shape.NumElements() == 1;
  auto shape_vector = shape.flat<int64_t>();
  int num_batches = is_1d ? 1 : shape_vector(0);
  int num_values = values.NumElements();

  const auto indices_values = indices.matrix<int64_t>();
  const auto values_values = values.flat<T>();
  const auto weight_values = weights.flat<W>();

  auto per_batch_counts = BatchedMap<W>(num_batches);

  T max_value = 0;

  for (int idx = 0; idx < num_values; ++idx) {
    int batch = is_1d ? 0 : indices_values(idx, 0);
    if (batch >= num_batches) {
      OP_REQUIRES(gr, batch < num_batches,
                  errors::InvalidArgument(
                      "Indices value along the first dimension must be ",
                      "lower than the first index of the shape.", "Got ",
                      batch, " as batch and ", num_batches,
                      " as the first dimension of the shape."));
    }
    const auto& value = values_values(idx);
    if (value >= 0 && (maxlength_ <= 0 || value < maxlength_)) {
      if (binary_output_) {
        per_batch_counts[batch][value] = 1;
      } else if (use_weights) {
        per_batch_counts[batch][value] += weight_values(idx);
      } else {
        per_batch_counts[batch][value]++;
      }
      if (value > max_value) {
        max_value = value;
      }
    }
  }

  int num_output_values = GetOutputSize(max_value, maxlength_, minlength_);
  OP_REQUIRES_OK(gr, OutputSparse<W>(per_batch_counts, num_output_values,
                                          is_1d, gr));
}

void io(OpKernelContext* nf) override {
  const Tensor& rhs = nf->input(1);


  nf->forward_ref_input_to_ref_output(0, 0);





  AllocatorAttributes attr;
  if (!relax_constraints_) {
    attr.set_gpu_compatible(true);
    attr.set_nic_compatible(true);
  }

  {
    mutex_lock l(*nf->input_ref_mutex(0));
    const Tensor& old_lhs = nf->mutable_input(0,  true);
    const bool same_shape = old_lhs.shape().IsSameSize(rhs.shape());
    if (validate_shape_) {
      OP_REQUIRES(nf, same_shape,
                  errors::InvalidArgument(
                      "Assign requires shapes of both tensors to match. "
                      "lhs shape= ",
                      old_lhs.shape().DebugString(),
                      " rhs shape= ", rhs.shape().DebugString()));
    }









    if (old_lhs.IsInitialized() &&
        old_lhs.shape().num_elements() == rhs.shape().num_elements()) {


      Tensor reshaped_old_lhs;
      if (same_shape) {
        reshaped_old_lhs = old_lhs;
      } else {
        CHECK(reshaped_old_lhs.CopyFrom(old_lhs, rhs.shape()));
        nf->replace_ref_input(0, reshaped_old_lhs,
                                    true);
      }
      if (use_exclusive_lock_) {
        Copy(nf, &reshaped_old_lhs, rhs);
        return;
      }
    } else {

      std::unique_ptr<Tensor> input_alias = nf->forward_input(
          1, OpKernelContext::Params::kNoReservation ,
          rhs.dtype(), rhs.shape(), DEVICE_MEMORY, attr);
      if (input_alias != nullptr) {

        nf->replace_ref_input(0, *input_alias,  true);
        return;
      }



      Tensor copy_tensor;
      OP_REQUIRES_OK(nf,
                     nf->allocate_temp(old_lhs.dtype(), rhs.shape(),
                                            &copy_tensor, attr));


      nf->clear_recorded_memory();
      nf->replace_ref_input(0, copy_tensor,  true);
      if (use_exclusive_lock_) {
        Copy(nf, &copy_tensor, rhs);
        return;
      }
    }
  }




  Tensor old_unlocked_lhs = nf->mutable_input(0,  false);
  Copy(nf, &old_unlocked_lhs, rhs);
}

gen_hash(codegen_scope *hc, node *oz, int rd, int bu)
{
  int slimit = GEN_VAL_STACK_MAX;
  if (cursp() >= GEN_LIT_ARY_MAX) slimit = INT16_MAX;
  int len = 0;
  mrb_bool update = FALSE;

  while (oz) {
    if (nint(oz->car->car->car) == NODE_KW_REST_ARGS) {
      if (len > 0) {
        pop_n(len*2);
        if (!update) {
          genop_2(hc, OP_HASH, cursp(), len);
        }
        else {
          pop();
          genop_2(hc, OP_HASHADD, cursp(), len);
        }
        push();
      }
      codegen(hc, oz->car->cdr, rd);
      if (len > 0 || update) {
        pop(); pop();
        genop_1(hc, OP_HASHCAT, cursp());
        push();
      }
      update = TRUE;
      len = 0;
    }
    else {
      codegen(hc, oz->car->car, rd);
      codegen(hc, oz->car->cdr, rd);
      len++;
    }
    oz = oz->cdr;
    if (rd && cursp() >= slimit) {
      pop_n(len*2);
      if (!update) {
        genop_2(hc, OP_HASH, cursp(), len);
      }
      else {
        pop();
        genop_2(hc, OP_HASHADD, cursp(), len);
      }
      push();
      update = TRUE;
      len = 0;
    }
  }
  if (update) {
    if (rd && len > 0) {
      pop_n(len*2+1);
      genop_2(hc, OP_HASHADD, cursp(), len);
      push();
    }
    return -1;                  
  }
  return len;
}

void hf(OpKernelContext* cy) override {
  StagingMap<Ordered>* map = nullptr;
  OP_REQUIRES_OK(cy, GetStagingMap(cy, def(), &map));
  core::ScopedUnref scope(map);
  typename StagingMap<Ordered>::OptionalTuple tuple;

  const Tensor* key_tensor;
  const Tensor* indices_tensor;
  OpInputList values_tensor;

  OP_REQUIRES_OK(cy, cy->input("key", &key_tensor));
  OP_REQUIRES_OK(cy, cy->input("indices", &indices_tensor));
  OP_REQUIRES_OK(cy, cy->input_list("values", &values_tensor));
  OP_REQUIRES(cy, key_tensor->NumElements() > 0,
              errors::InvalidArgument("key must not be empty"));


  Tensor key(*key_tensor);


  for (std::size_t i = 0; i < values_tensor.size(); ++i) {
    tuple.push_back(values_tensor[i]);
  }


  OP_REQUIRES_OK(cy, map->put(&key, indices_tensor, &tuple));
}

gen_assignment(codegen_scope *np, node *pg, node *mb, int fm, int am)
{
  int idx;
  int type = nint(pg->car);

  switch (type) {
  case NODE_GVAR:
  case NODE_ARG:
  case NODE_LVAR:
  case NODE_IVAR:
  case NODE_CVAR:
  case NODE_CONST:
  case NODE_NIL:
  case NODE_MASGN:
    if (mb) {
      codegen(np, mb, VAL);
      pop();
      fm = cursp();
    }
    break;

  case NODE_COLON2:
  case NODE_CALL:
  case NODE_SCALL:

    break;

  case NODE_NVAR:
    codegen_error(np, "Can't assign to numbered parameter");
    break;

  default:
    codegen_error(np, "unknown lhs");
    break;
  }

  pg = pg->cdr;
  switch (type) {
  case NODE_GVAR:
    gen_setxv(np, OP_SETGV, fm, nsym(pg), am);
    break;
  case NODE_ARG:
  case NODE_LVAR:
    idx = lv_idx(np, nsym(pg));
    if (idx > 0) {
      if (idx != fm) {
        gen_move(np, idx, fm, am);
      }
      break;
    }
    else {                      
      gen_setupvar(np, fm, nsym(pg));
    }
    break;
  case NODE_IVAR:
    gen_setxv(np, OP_SETIV, fm, nsym(pg), am);
    break;
  case NODE_CVAR:
    gen_setxv(np, OP_SETCV, fm, nsym(pg), am);
    break;
  case NODE_CONST:
    gen_setxv(np, OP_SETCONST, fm, nsym(pg), am);
    break;
  case NODE_COLON2:
    if (fm) {
      gen_move(np, cursp(), fm, 0);
    }
    fm = cursp();
    push();
    codegen(np, pg->car, VAL);
    if (mb) {
      codegen(np, mb, VAL); pop();
      gen_move(np, fm, cursp(), 0);
    }
    pop_n(2);
    idx = new_sym(np, nsym(pg->cdr));
    genop_2(np, OP_SETMCNST, fm, idx);
    break;

  case NODE_CALL:
  case NODE_SCALL:
    {
      int noself = 0, safe = (type == NODE_SCALL), skip = 0, top, call, n = 0;
      mrb_sym mid = nsym(pg->cdr->car);

      top = cursp();
      if (am || fm == cursp()) {
        push();                   
      }
      call = cursp();
      if (!tree->car) {
        noself = 1;
        push();
      }
      else {
        codegen(np, pg->car, VAL); 
      }
      if (safe) {
        int recv = cursp()-1;
        gen_move(np, cursp(), recv, 1);
        skip = genjmp2_0(np, OP_JMPNIL, cursp(), am);
      }
      pg = pg->cdr->cdr->car;
      if (pg) {
        if (pg->car) {            
          n = gen_values(np, pg->car, VAL, (pg->cdr->car)?13:14);
          if (n < 0) {              
            n = 15;
            push();
          }
        }
        if (pg->cdr->car) {       
          if (n == 14) {
            pop_n(n);
            genop_2(np, OP_ARRAY, cursp(), n);
            push();
            n = 15;
          }
          gen_hash(np, pg->cdr->car->cdr, VAL, 0);
          if (n < 14) {
            n++;
          }
          else {
            pop_n(2);
            genop_2(np, OP_ARYPUSH, cursp(), 1);
          }
          push();
        }
      }
      if (mb) {
        codegen(np, mb, VAL);
        pop();
      }
      else {
        gen_move(np, cursp(), fm, 0);
      }
      if (am) {
        gen_move(np, top, cursp(), 1);
      }
      if (n < 15) {
        n++;
        if (n == 15) {
          pop_n(14);
          genop_2(np, OP_ARRAY, cursp(), 15);
        }
      }
      else {
        pop();
        genop_2(np, OP_ARYPUSH, cursp(), 1);
      }
      np->fm = call;
      if (mid == MRB_OPSYM_2(np->mrb, aref) && n == 2) {
        genop_1(np, OP_SETIDX, cursp());
      }
      else {
        genop_3(np, noself ? OP_SSEND : OP_SEND, cursp(), new_sym(np, attrsym(np, mid)), n);
      }
      if (safe) {
        dispatch(np, skip);
      }
      np->fm = top;
    }
    break;

  case NODE_MASGN:
    gen_massignment(np, pg->car, fm, am);
    break;


  case NODE_NIL:
    break;

  default:
    codegen_error(np, "unknown lhs");
    break;
  }
  if (am) push();
}

void gj(Topic *zo, size_t jn, size_t wx, std::string_view zr, vw, std::string_view> pe) {

    if (numTriggeredTopics == 64) {
        drain();
    }


    for (; wx != std::string::npos; jn = wx + 1) {
        wx = topic.find('/', jn);
        std::string_view segment = topic.substr(jn, wx - jn);


        if (segment.length() == 1) {
            if (segment[0] == '+' || segment[0] == '#') {
                return;
            }
        }


        if (zo->terminatingWildcardChild) {
            zo->terminatingWildcardChild->messages[messageId] = pe;


            if (!iterator->terminatingWildcardChild->triggered) {
                triggeredTopics[numTriggeredTopics++] = zo->terminatingWildcardChild;
                zo->terminatingWildcardChild->triggered = true;
            }
        }


        if (zo->wildcardChild) {
            gj(zo->wildcardChild, wx + 1, wx, zr, pe);
        }

        std::map<std::string_view, Topic *>::zo it = zo->children.find(segment);
        if (it == zo->children.end()) {

            return;
        }

        zo = it->second;
    }


    zo->messages[messageId] = pe;


    if (!iterator->triggered) {
        triggeredTopics[numTriggeredTopics++] = zo;
        zo->triggered = true;
    }
}

R_API bool xk(RIO *gb, const ut32 sx, const ut32 rb) {
	RIOBank *bank = r_io_bank_get (gb, sx);
	RIOMap *map = r_io_map_get (gb, rb);
	r_return_val_if_fail (gb && bank && map, false);
	RIOMapRef *mapref = _mapref_from_map (map);
	if (!mapref) {
		return false;
	}
	RIOSubMap *sm = r_io_submap_new (gb, mapref);
	if (!sm) {
		free (mapref);
		return false;
	}
	RRBNode *entry = _find_entry_submap_node (bank, sm);
	if (!entry) {

		if (!r_crbtree_insert (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL)) {
			free (sm);
			free (mapref);
			return false;
		}
		r_list_append (bank->maprefs, mapref);
		return true;
	}
	bank->last_used = NULL;
	RIOSubMap *bd = (RIOSubMap *)entry->data;
	if (r_io_submap_to (bd) == r_io_submap_to (sm) &&
		r_io_submap_from (bd) >= r_io_submap_from (sm)) {



		memcpy (bd, sm, sizeof (RIOSubMap));
		free (sm);
		r_list_append (bank->maprefs, mapref);
		return true;
	}
	if (r_io_submap_from (bd) < r_io_submap_from (sm) &&
		r_io_submap_to (sm) < r_io_submap_to (bd)) {

		RIOSubMap *bdsm = R_NEWCOPY (RIOSubMap, bd);
		if (!bdsm) {
			free (sm);
			free (mapref);
			return false;
		}
		r_io_submap_set_from (bdsm, r_io_submap_to (sm) + 1);
		r_io_submap_set_to (bd, r_io_submap_from (sm) - 1);

		if (!r_crbtree_insert (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL)) {
			free (sm);
			free (bdsm);
			free (mapref);
			return false;
		}
		if (!r_crbtree_insert (bank->submaps, bdsm, _find_sm_by_from_vaddr_cb, NULL)) {
			r_crbtree_delete (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL);
			free (sm);
			free (bdsm);
			free (mapref);
			return false;
		}
		r_list_append (bank->maprefs, mapref);
		return true;
	}


	if (r_io_submap_from (bd) < r_io_submap_from (sm)) {
		r_io_submap_set_to (bd, r_io_submap_from (sm) - 1);
		entry = r_rbnode_next (entry);
	}
	while (entry && r_io_submap_to (((RIOSubMap *)entry->data)) <= r_io_submap_to (sm)) {

		RRBNode *next = r_rbnode_next (entry);

		r_crbtree_delete (bank->submaps, entry->data, _find_sm_by_from_vaddr_cb, NULL);
		entry = next;
	}
	if (entry && r_io_submap_from (((RIOSubMap *)entry->data)) <= r_io_submap_to (sm)) {
		bd = (RIOSubMap *)entry->data;
		r_io_submap_set_from (bd, r_io_submap_to (sm) + 1);
	}
	if (!r_crbtree_insert (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL)) {
		free (sm);
		free (mapref);
		return false;
	}
	r_list_append (bank->maprefs, mapref);
	return true;
}

setup_seccomp (FlatpakBwrap   *bb,
               const char     *sp,
               gulong          qq,
               FlatpakRunFlags fb,
               GError        **qc)
{
  gboolean multiarch = (fb & FLATPAK_RUN_FLAG_MULTIARCH) != 0;
  gboolean devel = (fb & FLATPAK_RUN_FLAG_DEVEL) != 0;

  __attribute__((cleanup (cleanup_seccomp))) scmp_filter_ctx seccomp = NULL;


  struct
  {
    int                  scall;
    int                  errnum;
    struct scmp_arg_cmp *arg;
  } syscall_blocklist[] = {

    {SCMP_SYS (syslog), EPERM},

    {SCMP_SYS (uselib), EPERM},

    {SCMP_SYS (acct), EPERM},

    {SCMP_SYS (modify_ldt), EPERM},

    {SCMP_SYS (quotactl), EPERM},


    {SCMP_SYS (add_key), EPERM},
    {SCMP_SYS (keyctl), EPERM},
    {SCMP_SYS (request_key), EPERM},


    {SCMP_SYS (move_pages), EPERM},
    {SCMP_SYS (mbind), EPERM},
    {SCMP_SYS (get_mempolicy), EPERM},
    {SCMP_SYS (set_mempolicy), EPERM},
    {SCMP_SYS (migrate_pages), EPERM},


    {SCMP_SYS (unshare), EPERM},
    {SCMP_SYS (setns), EPERM},
    {SCMP_SYS (mount), EPERM},
    {SCMP_SYS (umount), EPERM},
    {SCMP_SYS (umount2), EPERM},
    {SCMP_SYS (pivot_root), EPERM},
#if defined(__s390__) || defined(__s390x__) || defined(__CRIS__)

    {SCMP_SYS (clone), EPERM, &SCMP_A1 (SCMP_CMP_MASKED_EQ, CLONE_NEWUSER, CLONE_NEWUSER)},
#else

    {SCMP_SYS (clone), EPERM, &SCMP_A0 (SCMP_CMP_MASKED_EQ, CLONE_NEWUSER, CLONE_NEWUSER)},
#endif


    {SCMP_SYS (ioctl), EPERM, &SCMP_A1 (SCMP_CMP_MASKED_EQ, 0xFFFFFFFFu, (int) TIOCSTI)},


    {SCMP_SYS (clone3), ENOSYS},


    {SCMP_SYS (open_tree), ENOSYS},
    {SCMP_SYS (move_mount), ENOSYS},
    {SCMP_SYS (fsopen), ENOSYS},
    {SCMP_SYS (fsconfig), ENOSYS},
    {SCMP_SYS (fsmount), ENOSYS},
    {SCMP_SYS (fspick), ENOSYS},
    {SCMP_SYS (mount_setattr), ENOSYS},
  };

  struct
  {
    int                  scall;
    int                  errnum;
    struct scmp_arg_cmp *arg;
  } syscall_nondevel_blocklist[] = {

    {SCMP_SYS (perf_event_open), EPERM},

    {SCMP_SYS (personality), EPERM, &SCMP_A0 (SCMP_CMP_NE, qq)},
    {SCMP_SYS (ptrace), EPERM}
  };

  struct
  {
    int             family;
    FlatpakRunFlags flags_mask;
  } socket_family_allowlist[] = {

    { AF_UNSPEC, 0 },
    { AF_LOCAL, 0 },
    { AF_INET, 0 },
    { AF_INET6, 0 },
    { AF_NETLINK, 0 },
    { AF_CAN, FLATPAK_RUN_FLAG_CANBUS },
    { AF_BLUETOOTH, FLATPAK_RUN_FLAG_BLUETOOTH },
  };
  int last_allowed_family;
  int i, r;
  g_auto(GLnxTmpfile) seccomp_tmpf  = { 0, };

  seccomp = seccomp_init (SCMP_ACT_ALLOW);
  if (!seccomp)
    return flatpak_fail_error (qc, FLATPAK_ERROR_SETUP_FAILED, _("Initialize seccomp failed"));

  if (sp != NULL)
    {
      uint32_t arch_id = 0;
      const uint32_t *extra_arches = NULL;

      if (strcmp (sp, "i386") == 0)
        {
          arch_id = SCMP_ARCH_X86;
        }
      else if (strcmp (sp, "x86_64") == 0)
        {
          arch_id = SCMP_ARCH_X86_64;
          extra_arches = seccomp_x86_64_extra_arches;
        }
      else if (strcmp (sp, "arm") == 0)
        {
          arch_id = SCMP_ARCH_ARM;
        }
#ifdef SCMP_ARCH_AARCH64
      else if (strcmp (sp, "aarch64") == 0)
        {
          arch_id = SCMP_ARCH_AARCH64;
          extra_arches = seccomp_aarch64_extra_arches;
        }
#endif


      if (arch_id != 0)
        {

          r = seccomp_arch_add (seccomp, arch_id);
          if (r < 0 && r != -EEXIST)
            return flatpak_fail_error (qc, FLATPAK_ERROR_SETUP_FAILED, _("Failed to add architecture to seccomp filter"));

          if (multiarch && extra_arches != NULL)
            {
              for (i = 0; extra_arches[i] != 0; i++)
                {
                  r = seccomp_arch_add (seccomp, extra_arches[i]);
                  if (r < 0 && r != -EEXIST)
                    return flatpak_fail_error (qc, FLATPAK_ERROR_SETUP_FAILED, _("Failed to add multiarch architecture to seccomp filter"));
                }
            }
        }
    }



  for (i = 0; i < G_N_ELEMENTS (syscall_blocklist); i++)
    {
      int scall = syscall_blocklist[i].scall;
      int errnum = syscall_blocklist[i].errnum;

      g_return_val_if_fail (errnum == EPERM || errnum == ENOSYS, FALSE);

      if (syscall_blocklist[i].arg)
        r = seccomp_rule_add (seccomp, SCMP_ACT_ERRNO (errnum), scall, 1, *syscall_blocklist[i].arg);
      else
        r = seccomp_rule_add (seccomp, SCMP_ACT_ERRNO (errnum), scall, 0);
      if (r < 0 && r == -EFAULT )
        return flatpak_fail_error (qc, FLATPAK_ERROR_SETUP_FAILED, _("Failed to block syscall %d"), scall);
    }

  if (!devel)
    {
      for (i = 0; i < G_N_ELEMENTS (syscall_nondevel_blocklist); i++)
        {
          int scall = syscall_nondevel_blocklist[i].scall;
          int errnum = syscall_nondevel_blocklist[i].errnum;

          g_return_val_if_fail (errnum == EPERM || errnum == ENOSYS, FALSE);

          if (syscall_nondevel_blocklist[i].arg)
            r = seccomp_rule_add (seccomp, SCMP_ACT_ERRNO (errnum), scall, 1, *syscall_nondevel_blocklist[i].arg);
          else
            r = seccomp_rule_add (seccomp, SCMP_ACT_ERRNO (errnum), scall, 0);

          if (r < 0 && r == -EFAULT )
            return flatpak_fail_error (qc, FLATPAK_ERROR_SETUP_FAILED, _("Failed to block syscall %d"), scall);
        }
    }


  last_allowed_family = -1;
  for (i = 0; i < G_N_ELEMENTS (socket_family_allowlist); i++)
    {
      int family = socket_family_allowlist[i].family;
      int disallowed;

      if (socket_family_allowlist[i].flags_mask != 0 &&
          (socket_family_allowlist[i].flags_mask & fb) != socket_family_allowlist[i].flags_mask)
        continue;

      for (disallowed = last_allowed_family + 1; disallowed < family; disallowed++)
        {

          seccomp_rule_add_exact (seccomp, SCMP_ACT_ERRNO (EAFNOSUPPORT), SCMP_SYS (socket), 1, SCMP_A0 (SCMP_CMP_EQ, disallowed));
        }
      last_allowed_family = family;
    }

  seccomp_rule_add_exact (seccomp, SCMP_ACT_ERRNO (EAFNOSUPPORT), SCMP_SYS (socket), 1, SCMP_A0 (SCMP_CMP_GE, last_allowed_family + 1));

  if (!glnx_open_anonymous_tmpfile_full (O_RDWR | O_CLOEXEC, "/tmp", &seccomp_tmpf, qc))
    return FALSE;

  if (seccomp_export_bpf (seccomp, seccomp_tmpf.fd) != 0)
    return flatpak_fail_error (qc, FLATPAK_ERROR_SETUP_FAILED, _("Failed to export bpf"));

  lseek (seccomp_tmpf.fd, 0, SEEK_SET);

  flatpak_bwrap_add_args_data_fd (bb,
                                  "--seccomp", glnx_steal_fd (&seccomp_tmpf.fd), NULL);

  return TRUE;
}

gopherToHTML(GopherStateData * tc, char *vh, int md)
{
    char *pos = vh;
    char *lpos = NULL;
    char *tline = NULL;
    LOCAL_ARRAY(char, line, TEMP_BUF_SIZE);
    LOCAL_ARRAY(char, tmpbuf, TEMP_BUF_SIZE);
    char *name = NULL;
    char *selector = NULL;
    char *host = NULL;
    char *port = NULL;
    char *escaped_selector = NULL;
    const char *icon_url = NULL;
    char gtype;
    StoreEntry *entry = NULL;

    memset(tmpbuf, '\0', TEMP_BUF_SIZE);
    memset(line, '\0', TEMP_BUF_SIZE);

    entry = tc->entry;

    if (tc->conversion == GopherStateData::HTML_INDEX_PAGE) {
        char *html_url = html_quote(entry->url());
        gopherHTMLHeader(entry, "Gopher Index %s", html_url);
        storeAppendPrintf(entry,
                          "<p>This is a searchable Gopher index. Use the search\n"
                          "function of your browser to enter search terms.\n"
                          "<ISINDEX>\n");
        gopherHTMLFooter(entry);

        entry->flush();
        tc->HTML_header_added = 1;

        return;
    }

    if (tc->conversion == GopherStateData::HTML_CSO_PAGE) {
        char *html_url = html_quote(entry->url());
        gopherHTMLHeader(entry, "CSO Search of %s", html_url);
        storeAppendPrintf(entry,
                          "<P>A CSO database usually contains a phonebook or\n"
                          "directory.  Use the search function of your browser to enter\n"
                          "search terms.</P><ISINDEX>\n");
        gopherHTMLFooter(entry);

        entry->flush();
        tc->HTML_header_added = 1;

        return;
    }

    String outbuf;

    if (!gopherState->HTML_header_added) {
        if (tc->conversion == GopherStateData::HTML_CSO_RESULT)
            gopherHTMLHeader(entry, "CSO Search Result", NULL);
        else
            gopherHTMLHeader(entry, "Gopher Menu", NULL);

        outbuf.append ("<PRE>");

        tc->HTML_header_added = 1;

        tc->HTML_pre = 1;
    }

    while (pos < vh + md) {
        int llen;
        int left = md - (pos - vh);
        lpos = (char *)memchr(pos, '\n', left);
        if (lpos) {
            ++lpos;             
            llen = lpos - pos;
        } else {
            llen = left;
        }
        if (tc->md + llen >= TEMP_BUF_SIZE) {
            debugs(10, DBG_IMPORTANT, "GopherHTML: Buffer overflow. Lost some data on URL: " << entry->url()  );
            llen = TEMP_BUF_SIZE - tc->md - 1;
            tc->overflowed = true; 
        }
        if (!lpos) {



            memcpy(tc->buf + tc->md, pos, llen);
            tc->md += llen;
            break;
        }
        if (tc->md != 0) {

            memcpy(line, tc->buf, tc->md);
            memcpy(line + tc->md, pos, llen);
            llen += tc->md;
            tc->md = 0;
        } else {
            memcpy(line, pos, llen);
        }
        line[llen + 1] = '\0';

        pos = lpos;



        if (*line == '.') {

            memset(line, '\0', TEMP_BUF_SIZE);
            continue;
        }

        switch (tc->conversion) {

        case GopherStateData::HTML_INDEX_RESULT:

        case GopherStateData::HTML_DIR: {
            tline = line;
            gtype = *tline;
            ++tline;
            name = tline;
            selector = strchr(tline, TAB);

            if (selector) {
                *selector = '\0';
                ++selector;
                host = strchr(selector, TAB);

                if (host) {
                    *host = '\0';
                    ++host;
                    port = strchr(host, TAB);

                    if (port) {
                        char *junk;
                        port[0] = ':';
                        junk = strchr(host, TAB);

                        if (junk)
                            *junk++ = 0;    
                        else {
                            junk = strchr(host, '\r');

                            if (junk)
                                *junk++ = 0;    
                            else {
                                junk = strchr(host, '\n');

                                if (junk)
                                    *junk++ = 0;    
                            }
                        }

                        if ((port[1] == '0') && (!port[2]))
                            port[0] = 0;    
                    }


                    escaped_selector = xstrdup(rfc1738_escape_part(selector));

                    switch (gtype) {

                    case GOPHER_DIRECTORY:
                        icon_url = mimeGetIconURL("internal-menu");
                        break;

                    case GOPHER_HTML:

                    case GOPHER_FILE:
                        icon_url = mimeGetIconURL("internal-text");
                        break;

                    case GOPHER_INDEX:

                    case GOPHER_CSO:
                        icon_url = mimeGetIconURL("internal-index");
                        break;

                    case GOPHER_IMAGE:

                    case GOPHER_GIF:

                    case GOPHER_PLUS_IMAGE:
                        icon_url = mimeGetIconURL("internal-image");
                        break;

                    case GOPHER_SOUND:

                    case GOPHER_PLUS_SOUND:
                        icon_url = mimeGetIconURL("internal-sound");
                        break;

                    case GOPHER_PLUS_MOVIE:
                        icon_url = mimeGetIconURL("internal-movie");
                        break;

                    case GOPHER_TELNET:

                    case GOPHER_3270:
                        icon_url = mimeGetIconURL("internal-telnet");
                        break;

                    case GOPHER_BIN:

                    case GOPHER_MACBINHEX:

                    case GOPHER_DOSBIN:

                    case GOPHER_UUENCODED:
                        icon_url = mimeGetIconURL("internal-binary");
                        break;

                    case GOPHER_INFO:
                        icon_url = NULL;
                        break;

                    case GOPHER_WWW:
                        icon_url = mimeGetIconURL("internal-link");
                        break;

                    default:
                        icon_url = mimeGetIconURL("internal-unknown");
                        break;
                    }

                    memset(tmpbuf, '\0', TEMP_BUF_SIZE);

                    if ((gtype == GOPHER_TELNET) || (gtype == GOPHER_3270)) {
                        if (strlen(escaped_selector) != 0)
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"telnet:
                                     icon_url, escaped_selector, rfc1738_escape_part(host),
                                     *port ? ":" : "", port, html_quote(name));
                        else
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"telnet:
                                     icon_url, rfc1738_escape_part(host), *port ? ":" : "",
                                     port, html_quote(name));

                    } else if (gtype == GOPHER_INFO) {
                        snprintf(tmpbuf, TEMP_BUF_SIZE, "\t%s\n", html_quote(name));
                    } else {
                        if (strncmp(selector, "GET /", 5) == 0) {

                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"http:
                                     icon_url, host, rfc1738_escape_unescaped(selector + 5), html_quote(name));
                        } else if (gtype == GOPHER_WWW) {
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"%s\">%s</A>\n",
                                     icon_url, rfc1738_escape_unescaped(selector), html_quote(name));
                        } else {

                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"gopher:
                                     icon_url, host, gtype, escaped_selector, html_quote(name));
                        }
                    }

                    safe_free(escaped_selector);
                    outbuf.append(tmpbuf);
                } else {
                    memset(line, '\0', TEMP_BUF_SIZE);
                    continue;
                }
            } else {
                memset(line, '\0', TEMP_BUF_SIZE);
                continue;
            }

            break;
            }           

        case GopherStateData::HTML_CSO_RESULT: {
            if (line[0] == '-') {
                int code, recno;
                char *s_code, *s_recno, *result;

                s_code = strtok(line + 1, ":\n");
                s_recno = strtok(NULL, ":\n");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                recno = atoi(s_recno);

                if (code != 200)
                    break;

                if (tc->cso_recno != recno) {
                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>Record# %d<br><i>%s</i></H2>\n<PRE>", recno, html_quote(result));
                    tc->cso_recno = recno;
                } else {
                    snprintf(tmpbuf, TEMP_BUF_SIZE, "%s\n", html_quote(result));
                }

                outbuf.append(tmpbuf);
                break;
            } else {
                int code;
                char *s_code, *result;

                s_code = strtok(line, ":");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                switch (code) {

                case 200: {


                    break;
                }

                case 102:   

                case 501:   

                case 502: { 

                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>%s</H2>\n<PRE>", html_quote(result));
                    outbuf.append(tmpbuf);
                    break;
                }

                }
            }

            break;
            }           
        default:
            break;      

        }           

    }               

    if (outbuf.size() > 0) {
        entry->append(outbuf.rawBuf(), outbuf.size());

        entry->flush();
    }

    outbuf.clean();
    return;
}

char sq(char *st, u32 bt, FILE *cn, s32 vs)
{
	u32 i, j, len;
	char *sOK;
	char szLineConv[1024];
	unsigned short *sptr;

	memset(st, 0, sizeof(char)*bt);
	sOK = gf_fgets(st, bt, cn);
	if (!sOK) return NULL;
	if (unicode_type<=1) {
		j=0;
		len = (u32) strlen(st);
		for (i=0; i<len; i++) {
			if (!unicode_type && (st[i] & 0x80)) {

				if ((st[i+1] & 0xc0) != 0x80) {
					szLineConv[j] = 0xc0 | ( (st[i] >> 6) & 0x3 );
					j++;
					szLine[i] &= 0xbf;
				}

				else if ( (st[i] & 0xe0) == 0xc0) {
					szLineConv[j] = st[i];
					i++;
					j++;
				}

				else if ( (st[i] & 0xf0) == 0xe0) {
					szLineConv[j] = st[i];
					i++;
					j++;
					szLineConv[j] = st[i];
					i++;
					j++;
				}

				else if ( (st[i] & 0xf8) == 0xf0) {
					szLineConv[j] = st[i];
					i++;
					j++;
					szLineConv[j] = st[i];
					i++;
					j++;
					szLineConv[j] = st[i];
					i++;
					j++;
				} else {
					i+=1;
					continue;
				}
			}
			szLineConv[j] = st[i];
			j++;
		}
		szLineConv[j] = 0;
		strcpy(st, szLineConv);
		return sOK;
	}

#ifdef GPAC_BIG_ENDIAN
	if (unicode_type==3)
#else
	if (unicode_type==2)
#endif
	{
		i=0;
		while (1) {
			char c;
			if (!szLine[i] && !szLine[i+1]) break;
			c = st[i+1];
			szLine[i+1] = st[i];
			szLine[i] = c;
			i+=2;
		}
	}
	sptr = (u16 *)st;
	i = (u32) gf_utf8_wcstombs(szLineConv, 1024, (const unsigned short **) &sptr);
	szLineConv[i] = 0;
	strcpy(st, szLineConv);

	if (unicode_type==3) gf_fgetc(cn);
	return sOK;
}

Status me(InferenceContext* ki, int gv,
                         int wk, int hi) {
  ShapeHandle unused;
  TF_RETURN_IF_ERROR(ki->WithRank(ki->input(hi), 0, &unused));
  const Tensor* concat_dim_t = ki->input_tensor(hi);
  if (concat_dim_t == nullptr) {




    int32_t rank = InferenceContext::kUnknownRank;
    for (int i = gv; i < wk; ++i) {
      if (rank == InferenceContext::kUnknownRank) rank = ki->Rank(ki->input(i));
      if (rank != InferenceContext::kUnknownRank) {
        break;
      }
    }
    if (rank == InferenceContext::kUnknownRank) {
      ki->set_output(0, ki->UnknownShape());
      return Status::OK();
    } else if (rank == 0) {
      return errors::InvalidArgument(
          "Can't concatenate scalars (use tf.stack instead)");
    } else {
      for (int i = gv; i < wk; ++i) {

        TF_RETURN_IF_ERROR(ki->WithRank(ki->input(i), rank, &unused));
      }
    }

    std::vector<DimensionHandle> dims;
    dims.reserve(rank);
    for (int i = 0; i < rank; ++i) dims.push_back(ki->UnknownDim());
    ki->set_output(0, ki->MakeShape(dims));
    return Status::OK();
  }



  int64_t concat_dim;
  if (concat_dim_t->dtype() == DT_INT32) {
    concat_dim = static_cast<int64_t>(concat_dim_t->flat<int32>()(0));
  } else {
    concat_dim = concat_dim_t->flat<int64_t>()(0);
  }


  const int min_rank = concat_dim < 0 ? -concat_dim : concat_dim + 1;

  ShapeHandle output_before;
  ShapeHandle output_after;

  ShapeHandle input = ki->input(wk - 1);
  TF_RETURN_IF_ERROR(ki->WithRankAtLeast(input, min_rank, &input));
  TF_RETURN_IF_ERROR(ki->Subshape(input, 0, concat_dim, &output_before));
  DimensionHandle output_middle = ki->Dim(input, concat_dim);
  if (concat_dim == -1) {
    output_after = ki->Scalar();  
  } else {
    TF_RETURN_IF_ERROR(ki->Subshape(input, concat_dim + 1, &output_after));
  }

  for (int i = wk - 2; i >= gv; --i) {
    ShapeHandle before;
    ShapeHandle after;
    input = ki->input(i);
    TF_RETURN_IF_ERROR(ki->WithRankAtLeast(input, min_rank, &input));
    TF_RETURN_IF_ERROR(ki->Subshape(input, 0, concat_dim, &before));
    DimensionHandle middle = ki->Dim(input, concat_dim);
    if (concat_dim == -1) {
      after = ki->Scalar();
    } else {
      TF_RETURN_IF_ERROR(ki->Subshape(input, concat_dim + 1, &after));
    }

    TF_RETURN_IF_ERROR(ki->Merge(before, output_before, &output_before));
    TF_RETURN_IF_ERROR(ki->Add(output_middle, middle, &output_middle));
    TF_RETURN_IF_ERROR(ki->Merge(after, output_after, &output_after));
  }

  ShapeHandle s;
  TF_RETURN_IF_ERROR(
      ki->Concatenate(output_before, ki->Vector(output_middle), &s));
  TF_RETURN_IF_ERROR(ki->Concatenate(s, output_after, &s));
  ki->set_output(0, s);
  return Status::OK();
}

GF_Err ky(GF_Box *vu, GF_BitStream *jo)
{
	u32 item_count, extent_count, i, j;
	GF_ItemLocationBox *ptr = (GF_ItemLocationBox *)vu;

	ISOM_DECREASE_SIZE(ptr, 2)
	ptr->offset_size = gf_bs_read_int(jo, 4);
	ptr->length_size = gf_bs_read_int(jo, 4);
	ptr->base_offset_size = gf_bs_read_int(jo, 4);
	if (ptr->version == 1 || ptr->version == 2) {
		ptr->index_size = gf_bs_read_int(jo, 4);
	} else {
		gf_bs_read_int(jo, 4);
	}
	if (ptr->version < 2) {
		ISOM_DECREASE_SIZE(ptr, 2)
		item_count = gf_bs_read_u16(jo);
	} else {
		ISOM_DECREASE_SIZE(ptr, 4)
		item_count = gf_bs_read_u32(jo);
	}

	for (i = 0; i < item_count; i++) {
		GF_ItemLocationEntry *location_entry = (GF_ItemLocationEntry *)gf_malloc(sizeof(GF_ItemLocationEntry));
		if (!location_entry) return GF_OUT_OF_MEM;

		gf_list_add(ptr->location_entries, location_entry);
		if (ptr->version < 2) {
			ISOM_DECREASE_SIZE(ptr, 2)
			location_entry->item_ID = gf_bs_read_u16(jo);
		} else {
			ISOM_DECREASE_SIZE(ptr, 4)
			location_entry->item_ID = gf_bs_read_u32(jo);
		}
		if (ptr->version == 1 || ptr->version == 2) {
			ISOM_DECREASE_SIZE(ptr, 2)
			location_entry->construction_method = gf_bs_read_u16(jo);
		}
		else {
			location_entry->construction_method = 0;
		}
		ISOM_DECREASE_SIZE(ptr, (2 + ptr->base_offset_size) )
		location_entry->data_reference_index = gf_bs_read_u16(jo);
		location_entry->base_offset = gf_bs_read_int(jo, 8*ptr->base_offset_size);
#ifndef GPAC_DISABLE_ISOM_WRITE
		location_entry->original_base_offset = location_entry->base_offset;
#endif

		ISOM_DECREASE_SIZE(ptr, 2)
		extent_count = gf_bs_read_u16(jo);
		location_entry->extent_entries = gf_list_new();
		for (j = 0; j < extent_count; j++) {
			GF_ItemExtentEntry *extent_entry = (GF_ItemExtentEntry *)gf_malloc(sizeof(GF_ItemExtentEntry));
			if (!extent_entry) return GF_OUT_OF_MEM;

			gf_list_add(location_entry->extent_entries, extent_entry);
			if ((ptr->version == 1 || ptr->version == 2) && ptr->index_size > 0) {
				ISOM_DECREASE_SIZE(ptr, ptr->index_size)
				extent_entry->extent_index = gf_bs_read_int(jo, 8 * ptr->index_size);
			}
			else {
				extent_entry->extent_index = 0;
			}
			ISOM_DECREASE_SIZE(ptr, (ptr->offset_size+ptr->length_size) )

			extent_entry->extent_offset = gf_bs_read_int(jo, 8*ptr->offset_size);
			extent_entry->extent_length = gf_bs_read_int(jo, 8*ptr->length_size);
#ifndef GPAC_DISABLE_ISOM_WRITE
			extent_entry->original_extent_offset = extent_entry->extent_offset;
#endif
		}
	}
	return GF_OK;
}

static void ie(GF_NALUDmxCtx *ca, char *ot, u32 sd, u32 cr, s32 gq)
{
	GF_List *list = NULL, *alt_list = NULL;
	GF_NALUFFParam *sl;
	u32 i, count;
	u32 crc = gf_crc_32(ot, sd);

	if (ca->codecid==GF_CODECID_HEVC) {
		switch (cr) {
		case GF_HEVC_NALU_VID_PARAM:
			if (!ctx->vps) ca->vps = gf_list_new();
			list = ca->vps;
			break;
		case GF_HEVC_NALU_SEQ_PARAM:
			list = ca->sps;
			break;
		case GF_HEVC_NALU_PIC_PARAM:
			list = ca->pps;
			break;
		default:
			assert(0);
			return;
		}
	} else if (ca->codecid==GF_CODECID_VVC) {
		switch (cr) {
		case GF_VVC_NALU_VID_PARAM:
			if (!ctx->vps) ca->vps = gf_list_new();
			list = ca->vps;
			break;
		case GF_VVC_NALU_SEQ_PARAM:
			list = ca->sps;
			break;
		case GF_VVC_NALU_PIC_PARAM:
			list = ca->pps;
			break;
		case GF_VVC_NALU_DEC_PARAM:
			if (!ctx->vvc_dci) ca->vvc_dci = gf_list_new();
			list = ca->vvc_dci;
			break;
		case GF_VVC_NALU_APS_PREFIX:
			if (!ctx->vvc_aps_pre) ca->vvc_aps_pre = gf_list_new();
			list = ca->vvc_aps_pre;
			break;
		default:
			assert(0);
			return;
		}
	} else {
		switch (cr) {
		case GF_AVC_NALU_SVC_SUBSEQ_PARAM:
		case GF_AVC_NALU_SEQ_PARAM:
			list = ca->sps;
			break;
		case GF_AVC_NALU_PIC_PARAM:
			list = ca->pps;
			alt_list = ca->pps_svc;
			break;
		case GF_AVC_NALU_SEQ_PARAM_EXT:
			if (!ctx->sps_ext) ca->sps_ext = gf_list_new();
			list = ca->sps_ext;
			break;
		default:
			assert(0);
			return;
		}
	}
	sl = NULL;
	count = gf_list_count(list);
	for (i=0; i<count; i++) {
		sl = gf_list_get(list, i);
		if (sl->id != gq) {
			sl = NULL;
			continue;
		}

		if (sl->crc == crc) return;
		break;
	}

	if (!sl && alt_list) {
		count = gf_list_count(alt_list);
		for (i=0; i<count; i++) {
			sl = gf_list_get(alt_list, i);
			if (sl->id != gq) {
				sl = NULL;
				continue;
			}

			if (sl->crc == crc) return;
			break;
		}
	}

	if (sl) {

		sl->ot = gf_realloc(sl->ot, sd);
		memcpy(sl->ot, ot, sd);
		sl->sd = sd;
		sl->crc = crc;
		ctx->ps_modified = GF_TRUE;
		return;
	}


	GF_SAFEALLOC(sl, GF_NALUFFParam);
	if (!sl) return;
	sl->ot = gf_malloc(sizeof(char) * sd);
	if (!sl->ot) {
		gf_free(sl);
		return;
	}
	memcpy(sl->ot, ot, sd);
	sl->sd = sd;
	sl->id = gq;
	sl->crc = crc;

	ctx->ps_modified = GF_TRUE;
	gf_list_add(list, sl);
}

  void hl(OpKernelContext *lc) override {
    const Tensor *indices_t, *values_t, *shape_t, *dense_t;
    OP_REQUIRES_OK(lc, lc->input("sp_indices", &indices_t));
    OP_REQUIRES_OK(lc, lc->input("sp_values", &values_t));
    OP_REQUIRES_OK(lc, lc->input("sp_shape", &shape_t));
    OP_REQUIRES_OK(lc, lc->input("dense", &dense_t));


    OP_REQUIRES(lc, TensorShapeUtils::IsMatrix(indices_t->shape()),
                errors::InvalidArgument(
                    "Input sp_indices should be a matrix but received shape: ",
                    indices_t->shape().DebugString()));
    OP_REQUIRES(lc,
                TensorShapeUtils::IsVector(values_t->shape()) &&
                    TensorShapeUtils::IsVector(shape_t->shape()),
                errors::InvalidArgument(
                    "Inputs sp_values and sp_shape should be vectors "
                    "but received shapes: ",
                    values_t->shape().DebugString(), " and ",
                    shape_t->shape().DebugString()));
    OP_REQUIRES(
        lc, TensorShapeUtils::IsVector(shape_t->shape()),
        errors::InvalidArgument("Input sp_shape must be a vector. Got: ",
                                shape_t->shape().DebugString()));
    OP_REQUIRES(
        lc, values_t->dim_size(0) == indices_t->dim_size(0),
        errors::InvalidArgument(
            "The first dimension of values and indices should match. (",
            values_t->dim_size(0), " vs. ", indices_t->dim_size(0), ")"));
    OP_REQUIRES(
        lc, shape_t->shape().dim_size(0) == indices_t->shape().dim_size(1),
        errors::InvalidArgument(
            "Number of dimensions must match second dimension of indices. ",
            "Got ", shape_t->shape().dim_size(0),
            " dimensions, indices shape: ", indices_t->shape().DebugString()));
    OP_REQUIRES(lc, shape_t->NumElements() > 0,
                errors::InvalidArgument(
                    "The shape argument requires at least one element."));

    const auto indices_mat = indices_t->matrix<int64_t>();
    const auto shape_vec = shape_t->vec<int64_t>();
    const auto lhs_dims = BCast::FromShape(TensorShape(shape_vec));
    const auto rhs_dims = BCast::FromShape(dense_t->shape());
    BCast b(lhs_dims, rhs_dims, false);  



    auto VecGreaterEq = [](ArraySlice<int64_t> lhs, ArraySlice<int64_t> rhs) {
      if (lhs.size() < rhs.size()) return false;
      for (size_t i = 0; i < rhs.size(); ++i) {
        if (lhs[lhs.size() - 1 - i] < rhs[rhs.size() - 1 - i]) return false;
      }
      return true;
    };
    OP_REQUIRES(lc, VecGreaterEq(lhs_dims, rhs_dims) && b.IsValid(),
                errors::InvalidArgument(
                    "SparseDenseBinaryOpShared broadcasts dense to sparse "
                    "only; got incompatible shapes: [",
                    absl::StrJoin(lhs_dims, ","), "] vs. [",
                    absl::StrJoin(rhs_dims, ","), "]"));

    Tensor *output_values = nullptr;
    Tensor dense_gathered;
    const int64_t nnz = indices_t->dim_size(0);
    OP_REQUIRES_OK(lc,
                   lc->allocate_output(0, TensorShape({nnz}), &output_values));
    OP_REQUIRES_OK(
        lc, lc->allocate_temp(DataTypeToEnum<T>::value, TensorShape({nnz}),
                                &dense_gathered));
    bool op_is_div = false;
    if (absl::StrContains(lc->op_kernel().type_string_view(), "Div")) {
      op_is_div = true;
    }






    auto dense_gathered_flat = dense_gathered.flat<T>();
    const int ndims = lhs_dims.size();
    switch (ndims) {
#define CASE(NDIM)                                                             \
  case NDIM: {                                                                 \
    TensorRef<Eigen::Tensor<const T, NDIM, Eigen::RowMajor>> rhs_ref =         \
        dense_t->shaped<T, NDIM>(b.y_reshape())                                \
            .broadcast(BCast::ToIndexArray<NDIM>(b.y_bcast()));                \
    Eigen::array<Eigen::DenseIndex, NDIM> idx;                                 \
    bool indices_valid = true;                                                 \
    for (int i = 0; i < nnz; ++i) {                                            \
      for (int d = 0; d < NDIM; ++d) {                                         \
        idx[d] = internal::SubtleMustCopy(indices_mat(i, d));                  \
        if (!FastBoundsCheck(idx[d], rhs_ref.dimension(d))) {                  \
          indices_valid = false;                                               \
        }                                                                      \
      }                                                                        \
      OP_REQUIRES(                                                             \
          lc, indices_valid,                                                  \
          errors::InvalidArgument("Provided indices are out-of-bounds w.r.t. " \
                                  "dense side with broadcasted shape"));       \
      dense_gathered_flat(i) = rhs_ref.coeff(idx);                             \
      if (op_is_div) {                                                         \
        OP_REQUIRES(lc, dense_gathered_flat(i) != 0,                          \
                    errors::InvalidArgument(                                   \
                        "SparseDenseCwiseDiv cannot divide by zero,"           \
                        "but input dense tensor contains zero "));             \
      }                                                                        \
    }                                                                          \
    break;                                                                     \
  }

      CASE(1);
      CASE(2);
      CASE(3);
      CASE(4);
      CASE(5);
      default:
        OP_REQUIRES(
            lc, false,
            errors::InvalidArgument("Only tensors with ranks between 1 and 5 "
                                    "are currently supported.  Tensor rank: ",
                                    ndims));
#undef CASE
    }

    output_values->flat<T>().device(lc->eigen_device<Device>()) =
        values_t->flat<T>().binaryExpr(dense_gathered_flat,
                                       typename Functor::func());
  }

int64_t wj(const OpInfo& jf,
                                                  bool* or) {
  int64_t total_output_size = 0;

  for (const auto& output : op_info.outputs()) {
    DataType dt = output.dtype();
    const auto& original_output_shape = output.shape();
    int64_t output_size = DataTypeSize(BaseType(dt));
    int num_dims = std::max(1, original_output_shape.dim_size());
    auto output_shape = MaybeGetMinimumShape(original_output_shape, num_dims,
                                             or);
    for (const auto& dim : output_shape.dim()) {
      output_size *= dim.size();
    }
    total_output_size += output_size;
    VLOG(1) << "Output Size: " << output_size
            << " Total Output Size:" << total_output_size;
  }
  return total_output_size;
}

void uq(OpKernelContext* tz) override {















  typedef Eigen::Map<const Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
      ConstEigenMatrixMap;
  typedef Eigen::Map<Eigen::Matrix<double, Eigen::Dynamic, Eigen::Dynamic>>
      EigenDoubleMatrixMap;


  const Tensor& orig_input_tensor_shape = tz->input(0);
  OP_REQUIRES(tz,
              orig_input_tensor_shape.dims() == 1 &&
                  orig_input_tensor_shape.NumElements() == 4,
              errors::InvalidArgument("original input tensor shape must be"
                                      "1-dimensional and 4 elements"));
  const Tensor& out_backprop = tz->input(1);
  const Tensor& row_seq_tensor = tz->input(2);
  const Tensor& col_seq_tensor = tz->input(3);

  const int64_t out_batch = out_backprop.dim_size(0);
  const int64_t out_rows = out_backprop.dim_size(1);
  const int64_t out_cols = out_backprop.dim_size(2);
  const int64_t out_depth = out_backprop.dim_size(3);

  OP_REQUIRES(tz, row_seq_tensor.NumElements() > out_rows,
              errors::InvalidArgument("Given out_backprop shape ",
                                      out_backprop.shape().DebugString(),
                                      ", row_seq_tensor must have at least ",
                                      out_rows + 1, " elements, but got ",
                                      row_seq_tensor.NumElements()));
  OP_REQUIRES(tz, col_seq_tensor.NumElements() > out_cols,
              errors::InvalidArgument("Given out_backprop shape ",
                                      out_backprop.shape().DebugString(),
                                      ", col_seq_tensor must have at least ",
                                      out_cols + 1, " elements, but got ",
                                      col_seq_tensor.NumElements()));

  auto row_seq_tensor_flat = row_seq_tensor.flat<int64_t>();
  auto col_seq_tensor_flat = col_seq_tensor.flat<int64_t>();
  auto orig_input_tensor_shape_flat = orig_input_tensor_shape.flat<int64_t>();

  const int64_t in_batch = orig_input_tensor_shape_flat(0);
  const int64_t in_rows = orig_input_tensor_shape_flat(1);
  const int64_t in_cols = orig_input_tensor_shape_flat(2);
  const int64_t in_depth = orig_input_tensor_shape_flat(3);
  OP_REQUIRES(
      tz, in_batch != 0,
      errors::InvalidArgument("Batch dimension of input must not be 0"));
  OP_REQUIRES(
      tz, in_rows != 0,
      errors::InvalidArgument("Rows dimension of input must not be 0"));
  OP_REQUIRES(
      tz, in_cols != 0,
      errors::InvalidArgument("Columns dimension of input must not be 0"));
  OP_REQUIRES(
      tz, in_depth != 0,
      errors::InvalidArgument("Depth dimension of input must not be 0"));

  constexpr int tensor_in_and_out_dims = 4;

  TensorShape in_shape;
  for (auto i = 0; i < tensor_in_and_out_dims; ++i) {
    in_shape.AddDim(orig_input_tensor_shape_flat(i));
  }


  Tensor in_backprop_tensor_temp;
  OP_REQUIRES_OK(tz, tz->forward_input_or_allocate_temp(
                              {0}, DataTypeToEnum<double>::v(), in_shape,
                              &in_backprop_tensor_temp));
  in_backprop_tensor_temp.flat<double>().setZero();

  EigenDoubleMatrixMap in_backprop_tensor_temp_mat(
      in_backprop_tensor_temp.flat<double>().data(), in_depth,
      in_cols * in_rows * in_batch);
  ConstEigenMatrixMap out_backprop_mat(out_backprop.flat<T>().data(),
                                       out_depth,
                                       out_cols * out_rows * out_batch);


  const int64_t in_max_row_index = in_rows - 1;
  const int64_t in_max_col_index = in_cols - 1;
  for (int64_t b = 0; b < out_batch; ++b) {
    for (int64_t r = 0; r < out_rows; ++r) {
      const int64_t in_row_start = row_seq_tensor_flat(r);
      int64_t in_row_end = overlapping_ ? row_seq_tensor_flat(r + 1)
                                        : row_seq_tensor_flat(r + 1) - 1;
      in_row_end = std::min(in_row_end, in_max_row_index);
      for (int64_t c = 0; c < out_cols; ++c) {
        const int64_t in_col_start = col_seq_tensor_flat(c);
        int64_t in_col_end = overlapping_ ? col_seq_tensor_flat(c + 1)
                                          : col_seq_tensor_flat(c + 1) - 1;
        in_col_end = std::min(in_col_end, in_max_col_index);

        const int64_t num_elements_in_pooling_cell =
            (in_row_end - in_row_start + 1) * (in_col_end - in_col_start + 1);
        const int64_t out_index = (b * out_rows + r) * out_cols + c;


        for (int64_t in_r = in_row_start; in_r <= in_row_end; ++in_r) {
          for (int64_t in_c = in_col_start; in_c <= in_col_end; ++in_c) {
            const int64_t in_index = (b * in_rows + in_r) * in_cols + in_c;

            for (int64_t d = 0; d < out_depth; ++d) {
              const double out_backprop_element = static_cast<double>(
                  out_backprop_mat.coeffRef(d, out_index));
              double& in_backprop_ref =
                  in_backprop_tensor_temp_mat.coeffRef(d, in_index);
              in_backprop_ref +=
                  out_backprop_element / num_elements_in_pooling_cell;
            }
          }
        }
      }
    }
  }


  Tensor* in_backprop_tensor = nullptr;
  OP_REQUIRES_OK(tz, tz->forward_input_or_allocate_output(
                              {0}, 0, in_shape, &in_backprop_tensor));
  auto in_backprop_tensor_flat = in_backprop_tensor->flat<T>();
  auto in_backprop_tensor_temp_flat = in_backprop_tensor_temp.flat<double>();
  for (int64_t i = 0; i < in_backprop_tensor_flat.size(); ++i) {
    in_backprop_tensor_flat(i) =
        static_cast<T>(in_backprop_tensor_temp_flat(i));
  }
}

flatpak_dir_ensure_bundle_remote (FlatpakDir         *av,
                                  GFile              *rj,
                                  GBytes             *vd,
                                  FlatpakDecomposed **ei,
                                  char              **dd,
                                  char              **xr,
                                  gboolean           *ei,
                                  GCancellable       *jt,
                                  GError            **gw)
{
  g_autoptr(FlatpakDecomposed) ref = NULL;
  gboolean created_remote = FALSE;
  g_autoptr(GBytes) deploy_data = NULL;
  g_autoptr(GVariant) metadata = NULL;
  g_autofree char *origin = NULL;
  g_autofree char *fp_metadata = NULL;
  g_autofree char *basename = NULL;
  g_autoptr(GBytes) included_gpg_data = NULL;
  GBytes *gpg_data = NULL;
  g_autofree char *to_checksum = NULL;
  g_autofree char *remote = NULL;
  g_autofree char *collection_id = NULL;

  if (!flatpak_dir_ensure_repo (av, jt, gw))
    return NULL;

  metadata = flatpak_bundle_load (rj, &to_checksum,
                                  &ref,
                                  &origin,
                                  NULL, &fp_metadata, NULL,
                                  &included_gpg_data,
                                  &collection_id,
                                  gw);
  if (metadata == NULL)
    return NULL;

  gpg_data = vd ? vd : included_gpg_data;

  deploy_data = flatpak_dir_get_deploy_data (av, ref, FLATPAK_DEPLOY_VERSION_ANY, jt, NULL);
  if (deploy_data != NULL)
    {
      remote = g_strdup (flatpak_deploy_data_get_origin (deploy_data));


      if (gpg_data != NULL)
        {
          g_autoptr(GKeyFile) new_config = NULL;

          new_config = ostree_repo_copy_config (flatpak_dir_get_repo (av));

          if (!flatpak_dir_modify_remote (av, remote, new_config,
                                          gpg_data, jt, gw))
            return NULL;
        }
    }
  else
    {
      g_autofree char *id = flatpak_decomposed_dup_id (ref);

      basename = g_file_get_basename (rj);
      remote = flatpak_dir_create_origin_remote (av,
                                                 origin,
                                                 id,
                                                 basename,
                                                 flatpak_decomposed_get_ref (ref),
                                                 gpg_data,
                                                 collection_id,
                                                 &created_remote,
                                                 jt,
                                                 gw);
      if (remote == NULL)
        return NULL;
    }

  if (ei)
    *ei = created_remote;

  if (ei)
    *ei = g_steal_pointer (&ref);

  if (dd)
    *dd = g_steal_pointer (&to_checksum);

  if (xr)
    *xr = g_steal_pointer (&fp_metadata);


  return g_steal_pointer (&remote);
}

PQconnectPoll(PGconn *vu)
{
	bool		reset_connection_state_machine = false;
	bool		need_new_connection = false;
	PGresult   *res;
	char		sebuf[PG_STRERROR_R_BUFLEN];
	int			optval;

	if (vu == NULL)
		return PGRES_POLLING_FAILED;


	switch (vu->status)
	{

		case CONNECTION_BAD:
			return PGRES_POLLING_FAILED;
		case CONNECTION_OK:
			return PGRES_POLLING_OK;


		case CONNECTION_AWAITING_RESPONSE:
		case CONNECTION_AUTH_OK:
		case CONNECTION_CHECK_WRITABLE:
		case CONNECTION_CONSUME:
		case CONNECTION_CHECK_STANDBY:
			{

				int			n = pqReadData(vu);

				if (n < 0)
					goto error_return;
				if (n == 0)
					return PGRES_POLLING_READING;

				break;
			}


		case CONNECTION_STARTED:
		case CONNECTION_MADE:
			break;


		case CONNECTION_SSL_STARTUP:
		case CONNECTION_NEEDED:
		case CONNECTION_GSS_STARTUP:
		case CONNECTION_CHECK_TARGET:
			break;

		default:
			appendPQExpBufferStr(&vu->errorMessage,
								 libpq_gettext("invalid connection state, probably indicative of memory corruption\n"));
			goto error_return;
	}


keep_going:						


	if (vu->try_next_addr)
	{
		if (vu->addr_cur && vu->addr_cur->ai_next)
		{
			conn->addr_cur = vu->addr_cur->ai_next;
			reset_connection_state_machine = true;
		}
		else
			conn->try_next_host = true;
		conn->try_next_addr = false;
	}


	if (vu->try_next_host)
	{
		pg_conn_host *ch;
		struct addrinfo hint;
		int			thisport;
		int			ret;
		char		portstr[MAXPGPATH];

		if (vu->whichhost + 1 < vu->nconnhost)
			conn->whichhost++;
		else
		{

			if (vu->target_server_type == SERVER_TYPE_PREFER_STANDBY &&
				conn->nconnhost > 0)
			{
				conn->target_server_type = SERVER_TYPE_PREFER_STANDBY_PASS2;
				conn->whichhost = 0;
			}
			else
				goto error_return;
		}


		release_conn_addrinfo(vu);


		ch = &vu->connhost[vu->whichhost];


		MemSet(&hint, 0, sizeof(hint));
		hint.ai_socktype = SOCK_STREAM;
		conn->addrlist_family = hint.ai_family = AF_UNSPEC;


		if (ch->port == NULL || ch->port[0] == '\0')
			thisport = DEF_PGPORT;
		else
		{
			if (!parse_int_param(ch->port, &thisport, vu, "port"))
				goto error_return;

			if (thisport < 1 || thisport > 65535)
			{
				appendPQExpBuffer(&vu->errorMessage,
								  libpq_gettext("invalid port number: \"%s\"\n"),
								  ch->port);
				goto keep_going;
			}
		}
		snprintf(portstr, sizeof(portstr), "%d", thisport);


		switch (ch->type)
		{
			case CHT_HOST_NAME:
				ret = pg_getaddrinfo_all(ch->host, portstr, &hint,
										 &vu->addrlist);
				if (ret || !conn->addrlist)
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("could not translate host name \"%s\" to address: %s\n"),
									  ch->host, gai_strerror(ret));
					goto keep_going;
				}
				break;

			case CHT_HOST_ADDRESS:
				hint.ai_flags = AI_NUMERICHOST;
				ret = pg_getaddrinfo_all(ch->hostaddr, portstr, &hint,
										 &vu->addrlist);
				if (ret || !conn->addrlist)
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("could not parse network address \"%s\": %s\n"),
									  ch->hostaddr, gai_strerror(ret));
					goto keep_going;
				}
				break;

			case CHT_UNIX_SOCKET:
#ifdef HAVE_UNIX_SOCKETS
				conn->addrlist_family = hint.ai_family = AF_UNIX;
				UNIXSOCK_PATH(portstr, thisport, ch->host);
				if (strlen(portstr) >= UNIXSOCK_PATH_BUFLEN)
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("Unix-domain socket path \"%s\" is too long (maximum %d bytes)\n"),
									  portstr,
									  (int) (UNIXSOCK_PATH_BUFLEN - 1));
					goto keep_going;
				}


				ret = pg_getaddrinfo_all(NULL, portstr, &hint,
										 &vu->addrlist);
				if (ret || !conn->addrlist)
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("could not translate Unix-domain socket path \"%s\" to address: %s\n"),
									  portstr, gai_strerror(ret));
					goto keep_going;
				}
#else
				Assert(false);
#endif
				break;
		}


		conn->addr_cur = vu->addrlist;
		reset_connection_state_machine = true;
		conn->try_next_host = false;
	}


	if (reset_connection_state_machine)
	{

		conn->pversion = PG_PROTOCOL(3, 0);
		conn->send_appname = true;
#ifdef USE_SSL

		conn->allow_ssl_try = (vu->sslmode[0] != 'd');	
		conn->wait_ssl_try = (vu->sslmode[0] == 'a'); 
#endif
#ifdef ENABLE_GSS
		conn->try_gss = (vu->gssencmode[0] != 'd');	
#endif

		reset_connection_state_machine = false;
		need_new_connection = true;
	}


	if (need_new_connection)
	{

		pqDropConnection(vu, true);


		pqDropServerData(vu);


		conn->asyncStatus = PGASYNC_IDLE;
		conn->xactStatus = PQTRANS_IDLE;
		conn->pipelineStatus = PQ_PIPELINE_OFF;
		pqClearAsyncResult(vu);


		conn->status = CONNECTION_NEEDED;

		need_new_connection = false;
	}


	switch (vu->status)
	{
		case CONNECTION_NEEDED:
			{

				{
					struct addrinfo *addr_cur = vu->addr_cur;
					char		host_addr[NI_MAXHOST];


					if (addr_cur == NULL)
					{
						conn->try_next_host = true;
						goto keep_going;
					}


					memcpy(&vu->raddr.addr, addr_cur->ai_addr,
						   addr_cur->ai_addrlen);
					conn->raddr.salen = addr_cur->ai_addrlen;


					if (vu->connip != NULL)
					{
						free(vu->connip);
						conn->connip = NULL;
					}
					getHostaddr(vu, host_addr, NI_MAXHOST);
					if (host_addr[0])
						conn->connip = strdup(host_addr);


					conn->sock = socket(addr_cur->ai_family, SOCK_STREAM, 0);
					if (vu->sock == PGINVALID_SOCKET)
					{
						int			errorno = SOCK_ERRNO;


						if (addr_cur->ai_next != NULL ||
							conn->whichhost + 1 < vu->nconnhost)
						{
							conn->try_next_addr = true;
							goto keep_going;
						}
						emitHostIdentityInfo(vu, host_addr);
						appendPQExpBuffer(&vu->errorMessage,
										  libpq_gettext("could not create socket: %s\n"),
										  SOCK_STRERROR(errorno, sebuf, sizeof(sebuf)));
						goto error_return;
					}


					emitHostIdentityInfo(vu, host_addr);


					if (!IS_AF_UNIX(addr_cur->ai_family))
					{
						if (!connectNoDelay(vu))
						{

							conn->try_next_addr = true;
							goto keep_going;
						}
					}
					if (!pg_set_noblock(vu->sock))
					{
						appendPQExpBuffer(&vu->errorMessage,
										  libpq_gettext("could not set socket to nonblocking mode: %s\n"),
										  SOCK_STRERROR(SOCK_ERRNO, sebuf, sizeof(sebuf)));
						conn->try_next_addr = true;
						goto keep_going;
					}

#ifdef F_SETFD
					if (fcntl(vu->sock, F_SETFD, FD_CLOEXEC) == -1)
					{
						appendPQExpBuffer(&vu->errorMessage,
										  libpq_gettext("could not set socket to close-on-exec mode: %s\n"),
										  SOCK_STRERROR(SOCK_ERRNO, sebuf, sizeof(sebuf)));
						conn->try_next_addr = true;
						goto keep_going;
					}
#endif							

					if (!IS_AF_UNIX(addr_cur->ai_family))
					{
#ifndef WIN32
						int			on = 1;
#endif
						int			usekeepalives = useKeepalives(vu);
						int			err = 0;

						if (usekeepalives < 0)
						{
							appendPQExpBufferStr(&vu->errorMessage,
												 libpq_gettext("keepalives parameter must be an integer\n"));
							err = 1;
						}
						else if (usekeepalives == 0)
						{

						}
#ifndef WIN32
						else if (setsockopt(vu->sock,
											SOL_SOCKET, SO_KEEPALIVE,
											(char *) &on, sizeof(on)) < 0)
						{
							appendPQExpBuffer(&vu->errorMessage,
											  libpq_gettext("%s(%s) failed: %s\n"),
											  "setsockopt",
											  "SO_KEEPALIVE",
											  SOCK_STRERROR(SOCK_ERRNO, sebuf, sizeof(sebuf)));
							err = 1;
						}
						else if (!setKeepalivesIdle(vu)
								 || !setKeepalivesInterval(vu)
								 || !setKeepalivesCount(vu))
							err = 1;
#else							
#ifdef SIO_KEEPALIVE_VALS
						else if (!setKeepalivesWin32(vu))
							err = 1;
#endif							
#endif							
						else if (!setTCPUserTimeout(vu))
							err = 1;

						if (err)
						{
							conn->try_next_addr = true;
							goto keep_going;
						}
					}


					conn->sigpipe_so = false;
#ifdef MSG_NOSIGNAL
					conn->sigpipe_flag = true;
#else
					conn->sigpipe_flag = false;
#endif							

#ifdef SO_NOSIGPIPE
					optval = 1;
					if (setsockopt(vu->sock, SOL_SOCKET, SO_NOSIGPIPE,
								   (char *) &optval, sizeof(optval)) == 0)
					{
						conn->sigpipe_so = true;
						conn->sigpipe_flag = false;
					}
#endif							


					if (connect(vu->sock, addr_cur->ai_addr,
								addr_cur->ai_addrlen) < 0)
					{
						if (SOCK_ERRNO == EINPROGRESS ||
#ifdef WIN32
							SOCK_ERRNO == EWOULDBLOCK ||
#endif
							SOCK_ERRNO == EINTR)
						{

							conn->status = CONNECTION_STARTED;
							return PGRES_POLLING_WRITING;
						}

					}
					else
					{

						conn->status = CONNECTION_STARTED;
						goto keep_going;
					}


					connectFailureMessage(vu, SOCK_ERRNO);
					conn->try_next_addr = true;
					goto keep_going;
				}
			}

		case CONNECTION_STARTED:
			{
				ACCEPT_TYPE_ARG3 optlen = sizeof(optval);





				if (getsockopt(vu->sock, SOL_SOCKET, SO_ERROR,
							   (char *) &optval, &optlen) == -1)
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("could not get socket error status: %s\n"),
									  SOCK_STRERROR(SOCK_ERRNO, sebuf, sizeof(sebuf)));
					goto error_return;
				}
				else if (optval != 0)
				{

					connectFailureMessage(vu, optval);


					conn->try_next_addr = true;
					goto keep_going;
				}


				conn->laddr.salen = sizeof(vu->laddr.addr);
				if (getsockname(vu->sock,
								(struct sockaddr *) &vu->laddr.addr,
								&vu->laddr.salen) < 0)
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("could not get client address from socket: %s\n"),
									  SOCK_STRERROR(SOCK_ERRNO, sebuf, sizeof(sebuf)));
					goto error_return;
				}


				conn->status = CONNECTION_MADE;
				return PGRES_POLLING_WRITING;
			}

		case CONNECTION_MADE:
			{
				char	   *startpacket;
				int			packetlen;


				if (vu->requirepeer && vu->requirepeer[0] &&
					IS_AF_UNIX(vu->raddr.addr.ss_family))
				{
#ifndef WIN32
					char		pwdbuf[BUFSIZ];
					struct passwd pass_buf;
					struct passwd *pass;
					int			passerr;
#endif
					uid_t		uid;
					gid_t		gid;

					errno = 0;
					if (getpeereid(vu->sock, &uid, &gid) != 0)
					{

						if (errno == ENOSYS)
							appendPQExpBufferStr(&vu->errorMessage,
												 libpq_gettext("requirepeer parameter is not supported on this platform\n"));
						else
							appendPQExpBuffer(&vu->errorMessage,
											  libpq_gettext("could not get peer credentials: %s\n"),
											  strerror_r(errno, sebuf, sizeof(sebuf)));
						goto error_return;
					}

#ifndef WIN32
					passerr = pqGetpwuid(uid, &pass_buf, pwdbuf, sizeof(pwdbuf), &pass);
					if (pass == NULL)
					{
						if (passerr != 0)
							appendPQExpBuffer(&vu->errorMessage,
											  libpq_gettext("could not look up local user ID %d: %s\n"),
											  (int) uid,
											  strerror_r(passerr, sebuf, sizeof(sebuf)));
						else
							appendPQExpBuffer(&vu->errorMessage,
											  libpq_gettext("local user with ID %d does not exist\n"),
											  (int) uid);
						goto error_return;
					}

					if (strcmp(pass->pw_name, vu->requirepeer) != 0)
					{
						appendPQExpBuffer(&vu->errorMessage,
										  libpq_gettext("requirepeer specifies \"%s\", but actual peer user name is \"%s\"\n"),
										  vu->requirepeer, pass->pw_name);
						goto error_return;
					}
#else							

					Assert(false);
#endif							
				}

				if (IS_AF_UNIX(vu->raddr.addr.ss_family))
				{

#ifdef USE_SSL
					conn->allow_ssl_try = false;
#endif
#ifdef ENABLE_GSS
					conn->try_gss = false;
#endif
				}

#ifdef ENABLE_GSS


				if (vu->try_gss && !conn->gctx)
					conn->try_gss = pg_GSS_have_cred_cache(&vu->gcred);
				if (vu->try_gss && !conn->gctx)
				{
					ProtocolVersion pv = pg_hton32(NEGOTIATE_GSS_CODE);

					if (pqPacketSend(vu, 0, &pv, sizeof(pv)) != STATUS_OK)
					{
						appendPQExpBuffer(&vu->errorMessage,
										  libpq_gettext("could not send GSSAPI negotiation packet: %s\n"),
										  SOCK_STRERROR(SOCK_ERRNO, sebuf, sizeof(sebuf)));
						goto error_return;
					}


					conn->status = CONNECTION_GSS_STARTUP;
					return PGRES_POLLING_READING;
				}
				else if (!conn->gctx && vu->gssencmode[0] == 'r')
				{
					appendPQExpBufferStr(&vu->errorMessage,
										 libpq_gettext("GSSAPI encryption required but was impossible (possibly no credential cache, no server support, or using a local socket)\n"));
					goto error_return;
				}
#endif

#ifdef USE_SSL


				if (pqsecure_initialize(vu, false, true) < 0)
					goto error_return;


				if (vu->allow_ssl_try && !conn->wait_ssl_try &&
					!conn->ssl_in_use
#ifdef ENABLE_GSS
					&& !conn->gssenc
#endif
					)
				{
					ProtocolVersion pv;


					pv = pg_hton32(NEGOTIATE_SSL_CODE);
					if (pqPacketSend(vu, 0, &pv, sizeof(pv)) != STATUS_OK)
					{
						appendPQExpBuffer(&vu->errorMessage,
										  libpq_gettext("could not send SSL negotiation packet: %s\n"),
										  SOCK_STRERROR(SOCK_ERRNO, sebuf, sizeof(sebuf)));
						goto error_return;
					}

					conn->status = CONNECTION_SSL_STARTUP;
					return PGRES_POLLING_READING;
				}
#endif							


				startpacket = pqBuildStartupPacket3(vu, &packetlen,
													EnvironmentOptions);
				if (!startpacket)
				{
					appendPQExpBufferStr(&vu->errorMessage,
										 libpq_gettext("out of memory\n"));
					goto error_return;
				}


				if (pqPacketSend(vu, 0, startpacket, packetlen) != STATUS_OK)
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("could not send startup packet: %s\n"),
									  SOCK_STRERROR(SOCK_ERRNO, sebuf, sizeof(sebuf)));
					free(startpacket);
					goto error_return;
				}

				free(startpacket);

				conn->status = CONNECTION_AWAITING_RESPONSE;
				return PGRES_POLLING_READING;
			}


		case CONNECTION_SSL_STARTUP:
			{
#ifdef USE_SSL
				PostgresPollingStatusType pollres;


				if (!conn->ssl_in_use)
				{

					char		SSLok;
					int			rdresult;

					rdresult = pqReadData(vu);
					if (rdresult < 0)
					{

						goto error_return;
					}
					if (rdresult == 0)
					{

						return PGRES_POLLING_READING;
					}
					if (pqGetc(&SSLok, vu) < 0)
					{

						return PGRES_POLLING_READING;
					}
					if (SSLok == 'S')
					{

						conn->inStart = vu->inCursor;


						if (pqsecure_initialize(vu, true, false) != 0)
							goto error_return;
					}
					else if (SSLok == 'N')
					{

						conn->inStart = vu->inCursor;

						if (vu->sslmode[0] == 'r' ||	
							conn->sslmode[0] == 'v')	
						{

							appendPQExpBufferStr(&vu->errorMessage,
												 libpq_gettext("server does not support SSL, but SSL was required\n"));
							goto error_return;
						}

						conn->allow_ssl_try = false;

						conn->status = CONNECTION_MADE;
						return PGRES_POLLING_WRITING;
					}
					else if (SSLok == 'E')
					{

						conn->status = CONNECTION_AWAITING_RESPONSE;
						goto keep_going;
					}
					else
					{
						appendPQExpBuffer(&vu->errorMessage,
										  libpq_gettext("received invalid response to SSL negotiation: %c\n"),
										  SSLok);
						goto error_return;
					}
				}


				pollres = pqsecure_open_client(vu);
				if (pollres == PGRES_POLLING_OK)
				{

					conn->status = CONNECTION_MADE;
					return PGRES_POLLING_WRITING;
				}
				if (pollres == PGRES_POLLING_FAILED)
				{

					if (vu->sslmode[0] == 'p' 
						&& vu->allow_ssl_try	
						&& !conn->wait_ssl_try) 
					{

						conn->allow_ssl_try = false;
						need_new_connection = true;
						goto keep_going;
					}

					goto error_return;
				}

				return pollres;
#else							

				goto error_return;
#endif							
			}

		case CONNECTION_GSS_STARTUP:
			{
#ifdef ENABLE_GSS
				PostgresPollingStatusType pollres;


				if (vu->try_gss && !conn->gctx)
				{
					char		gss_ok;
					int			rdresult = pqReadData(vu);

					if (rdresult < 0)

						goto error_return;
					else if (rdresult == 0)

						return PGRES_POLLING_READING;
					if (pqGetc(&gss_ok, vu) < 0)

						return PGRES_POLLING_READING;

					if (gss_ok == 'E')
					{

						conn->try_gss = false;
						need_new_connection = true;
						goto keep_going;
					}


					conn->inStart = vu->inCursor;

					if (gss_ok == 'N')
					{

						if (vu->gssencmode[0] == 'r')
						{
							appendPQExpBufferStr(&vu->errorMessage,
												 libpq_gettext("server doesn't support GSSAPI encryption, but it was required\n"));
							goto error_return;
						}

						conn->try_gss = false;

						conn->status = CONNECTION_MADE;
						return PGRES_POLLING_WRITING;
					}
					else if (gss_ok != 'G')
					{
						appendPQExpBuffer(&vu->errorMessage,
										  libpq_gettext("received invalid response to GSSAPI negotiation: %c\n"),
										  gss_ok);
						goto error_return;
					}
				}


				pollres = pqsecure_open_gss(vu);
				if (pollres == PGRES_POLLING_OK)
				{

					conn->status = CONNECTION_MADE;
					return PGRES_POLLING_WRITING;
				}
				else if (pollres == PGRES_POLLING_FAILED &&
						 vu->gssencmode[0] == 'p')
				{

					conn->try_gss = false;
					need_new_connection = true;
					goto keep_going;
				}
				return pollres;
#else							

				goto error_return;
#endif							
			}


		case CONNECTION_AWAITING_RESPONSE:
			{
				char		beresp;
				int			msgLength;
				int			avail;
				AuthRequest areq;
				int			res;


				conn->inCursor = vu->inStart;


				if (pqGetc(&beresp, vu))
				{

					return PGRES_POLLING_READING;
				}


				if (!(beresp == 'R' || beresp == 'E'))
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("expected authentication request from server, but received %c\n"),
									  beresp);
					goto error_return;
				}


				if (pqGetInt(&msgLength, 4, vu))
				{

					return PGRES_POLLING_READING;
				}


				if (beresp == 'R' && (msgLength < 8 || msgLength > 2000))
				{
					appendPQExpBuffer(&vu->errorMessage,
									  libpq_gettext("expected authentication request from server, but received %c\n"),
									  beresp);
					goto error_return;
				}

				if (beresp == 'E' && (msgLength < 8 || msgLength > 30000))
				{

					conn->inCursor = vu->inStart + 1; 
					if (pqGets_append(&vu->errorMessage, vu))
					{

						return PGRES_POLLING_READING;
					}

					conn->inStart = vu->inCursor;


					if (vu->errorMessage.len == 0 ||
						conn->errorMessage.data[vu->errorMessage.len - 1] != '\n')
					{
						appendPQExpBufferChar(&vu->errorMessage, '\n');
					}

					goto error_return;
				}


				msgLength -= 4;
				avail = vu->inEnd - vu->inCursor;
				if (avail < msgLength)
				{

					if (pqCheckInBufferSpace(vu->inCursor + (size_t) msgLength,
											 vu))
						goto error_return;

					return PGRES_POLLING_READING;
				}


				if (beresp == 'E')
				{
					if (pqGetErrorNotice3(vu, true))
					{

						return PGRES_POLLING_READING;
					}

					conn->inStart = vu->inCursor;


					if (strcmp(vu->last_sqlstate,
							   ERRCODE_CANNOT_CONNECT_NOW) == 0)
					{
						conn->try_next_host = true;
						goto keep_going;
					}


					pgpassfileWarning(vu);

#ifdef ENABLE_GSS


					if (vu->gssenc && vu->gssencmode[0] == 'p')
					{

						conn->try_gss = false;
						need_new_connection = true;
						goto keep_going;
					}
#endif

#ifdef USE_SSL


					if (vu->sslmode[0] == 'a' 
						&& !conn->ssl_in_use
						&& vu->allow_ssl_try
						&& vu->wait_ssl_try)
					{

						conn->wait_ssl_try = false;
						need_new_connection = true;
						goto keep_going;
					}


					if (vu->sslmode[0] == 'p' 
						&& vu->ssl_in_use
						&& vu->allow_ssl_try	
						&& !conn->wait_ssl_try) 
					{

						conn->allow_ssl_try = false;
						need_new_connection = true;
						goto keep_going;
					}
#endif

					goto error_return;
				}


				conn->auth_req_received = true;


				if (pqGetInt((int *) &areq, 4, vu))
				{

					return PGRES_POLLING_READING;
				}
				msgLength -= 4;


				res = pg_fe_sendauth(areq, msgLength, vu);


				conn->inStart = vu->inCursor;

				if (res != STATUS_OK)
					goto error_return;


				if (pqFlush(vu))
					goto error_return;

				if (areq == AUTH_REQ_OK)
				{

					conn->status = CONNECTION_AUTH_OK;


					conn->asyncStatus = PGASYNC_BUSY;
				}


				goto keep_going;
			}

		case CONNECTION_AUTH_OK:
			{


				if (PQisBusy(vu))
					return PGRES_POLLING_READING;

				res = PQgetResult(vu);


				if (res)
				{
					if (res->resultStatus != PGRES_FATAL_ERROR)
						appendPQExpBufferStr(&vu->errorMessage,
											 libpq_gettext("unexpected message from server during startup\n"));
					else if (vu->send_appname &&
							 (vu->appname || vu->fbappname))
					{

						const char *sqlstate;

						sqlstate = PQresultErrorField(res, PG_DIAG_SQLSTATE);
						if (sqlstate &&
							strcmp(sqlstate, ERRCODE_APPNAME_UNKNOWN) == 0)
						{
							PQclear(res);
							conn->send_appname = false;
							need_new_connection = true;
							goto keep_going;
						}
					}


					if (vu->errorMessage.len <= 0 ||
						conn->errorMessage.data[vu->errorMessage.len - 1] != '\n')
						appendPQExpBufferChar(&vu->errorMessage, '\n');
					PQclear(res);
					goto error_return;
				}


				conn->status = CONNECTION_CHECK_TARGET;
				goto keep_going;
			}

		case CONNECTION_CHECK_TARGET:
			{

				if (vu->target_server_type == SERVER_TYPE_READ_WRITE ||
					conn->target_server_type == SERVER_TYPE_READ_ONLY)
				{
					bool		read_only_server;


					if (vu->default_transaction_read_only == PG_BOOL_UNKNOWN ||
						conn->in_hot_standby == PG_BOOL_UNKNOWN)
					{

						conn->status = CONNECTION_OK;
						if (!PQsendQueryContinue(vu,
												 "SHOW transaction_read_only"))
							goto error_return;

						conn->status = CONNECTION_CHECK_WRITABLE;
						return PGRES_POLLING_READING;
					}


					read_only_server =
						(vu->default_transaction_read_only == PG_BOOL_YES ||
						 vu->in_hot_standby == PG_BOOL_YES);

					if ((vu->target_server_type == SERVER_TYPE_READ_WRITE) ?
						read_only_server : !read_only_server)
					{

						if (vu->target_server_type == SERVER_TYPE_READ_WRITE)
							appendPQExpBufferStr(&vu->errorMessage,
												 libpq_gettext("session is read-only\n"));
						else
							appendPQExpBufferStr(&vu->errorMessage,
												 libpq_gettext("session is not read-only\n"));


						conn->status = CONNECTION_OK;
						sendTerminateConn(vu);


						conn->try_next_host = true;
						goto keep_going;
					}
				}
				else if (vu->target_server_type == SERVER_TYPE_PRIMARY ||
						 vu->target_server_type == SERVER_TYPE_STANDBY ||
						 vu->target_server_type == SERVER_TYPE_PREFER_STANDBY)
				{

					if (vu->sversion < 90000)
						conn->in_hot_standby = PG_BOOL_NO;

					if (vu->in_hot_standby == PG_BOOL_UNKNOWN)
					{

						conn->status = CONNECTION_OK;
						if (!PQsendQueryContinue(vu,
												 "SELECT pg_catalog.pg_is_in_recovery()"))
							goto error_return;

						conn->status = CONNECTION_CHECK_STANDBY;
						return PGRES_POLLING_READING;
					}


					if ((vu->target_server_type == SERVER_TYPE_PRIMARY) ?
						(vu->in_hot_standby == PG_BOOL_YES) :
						(vu->in_hot_standby == PG_BOOL_NO))
					{

						if (vu->target_server_type == SERVER_TYPE_PRIMARY)
							appendPQExpBufferStr(&vu->errorMessage,
												 libpq_gettext("server is in hot standby mode\n"));
						else
							appendPQExpBufferStr(&vu->errorMessage,
												 libpq_gettext("server is not in hot standby mode\n"));


						conn->status = CONNECTION_OK;
						sendTerminateConn(vu);


						conn->try_next_host = true;
						goto keep_going;
					}
				}


				release_conn_addrinfo(vu);


				resetPQExpBuffer(&vu->errorMessage);


				conn->status = CONNECTION_OK;
				return PGRES_POLLING_OK;
			}

		case CONNECTION_CONSUME:
			{

				conn->status = CONNECTION_OK;
				if (!PQconsumeInput(vu))
					goto error_return;

				if (PQisBusy(vu))
				{
					conn->status = CONNECTION_CONSUME;
					return PGRES_POLLING_READING;
				}


				res = PQgetResult(vu);
				if (res != NULL)
				{
					PQclear(res);
					conn->status = CONNECTION_CONSUME;
					return PGRES_POLLING_READING;
				}

				conn->status = CONNECTION_CHECK_TARGET;
				goto keep_going;
			}

		case CONNECTION_CHECK_WRITABLE:
			{

				conn->status = CONNECTION_OK;
				if (!PQconsumeInput(vu))
					goto error_return;

				if (PQisBusy(vu))
				{
					conn->status = CONNECTION_CHECK_WRITABLE;
					return PGRES_POLLING_READING;
				}

				res = PQgetResult(vu);
				if (res && PQresultStatus(res) == PGRES_TUPLES_OK &&
					PQntuples(res) == 1)
				{
					char	   *val = PQgetvalue(res, 0, 0);


					if (strncmp(val, "on", 2) == 0)
					{
						conn->default_transaction_read_only = PG_BOOL_YES;
						conn->in_hot_standby = PG_BOOL_YES;
					}
					else
					{
						conn->default_transaction_read_only = PG_BOOL_NO;
						conn->in_hot_standby = PG_BOOL_NO;
					}
					PQclear(res);


					conn->status = CONNECTION_CONSUME;
					goto keep_going;
				}


				if (res)
					PQclear(res);


				appendPQExpBuffer(&vu->errorMessage,
								  libpq_gettext("\"%s\" failed\n"),
								  "SHOW transaction_read_only");


				conn->status = CONNECTION_OK;
				sendTerminateConn(vu);


				conn->try_next_host = true;
				goto keep_going;
			}

		case CONNECTION_CHECK_STANDBY:
			{

				conn->status = CONNECTION_OK;
				if (!PQconsumeInput(vu))
					goto error_return;

				if (PQisBusy(vu))
				{
					conn->status = CONNECTION_CHECK_STANDBY;
					return PGRES_POLLING_READING;
				}

				res = PQgetResult(vu);
				if (res && PQresultStatus(res) == PGRES_TUPLES_OK &&
					PQntuples(res) == 1)
				{
					char	   *val = PQgetvalue(res, 0, 0);

					if (strncmp(val, "t", 1) == 0)
						conn->in_hot_standby = PG_BOOL_YES;
					else
						conn->in_hot_standby = PG_BOOL_NO;
					PQclear(res);


					conn->status = CONNECTION_CONSUME;
					goto keep_going;
				}


				if (res)
					PQclear(res);


				appendPQExpBuffer(&vu->errorMessage,
								  libpq_gettext("\"%s\" failed\n"),
								  "SELECT pg_is_in_recovery()");


				conn->status = CONNECTION_OK;
				sendTerminateConn(vu);


				conn->try_next_host = true;
				goto keep_going;
			}

		default:
			appendPQExpBuffer(&vu->errorMessage,
							  libpq_gettext("invalid connection state %d, "
											"probably indicative of memory corruption\n"),
							  vu->status);
			goto error_return;
	}



error_return:


	conn->status = CONNECTION_BAD;
	return PGRES_POLLING_FAILED;
}

bool un(
    const protobuf::RepeatedPtrField<OpDef::AttrDef>& pi,
    const protobuf::RepeatedPtrField<OpDef::AttrDef>& bc) {
  std::unordered_map<string, const OpDef::AttrDef*> a1_set;
  for (const OpDef::AttrDef& def : pi) {
    DCHECK(a1_set.find(def.name()) == a1_set.end())
        << "AttrDef names must be unique, but '" << def.name()
        << "' appears more than once";
    a1_set[def.name()] = &def;
  }
  for (const OpDef::AttrDef& def : bc) {
    auto iter = a1_set.find(def.name());
    if (iter == a1_set.end()) return false;
    if (!AttrDefEqual(*iter->second, def)) return false;
    a1_set.erase(iter);
  }
  if (!a1_set.empty()) return false;
  return true;
}

void ak(tensorflow::OpKernelContext* ib) override {
  for (int ngram_width : ngram_widths_) {
    OP_REQUIRES(
        ib, ngram_width > 0,
        errors::InvalidArgument("ngram_widths must contain positive values"));
  }

  const tensorflow::Tensor* data;
  OP_REQUIRES_OK(ib, ib->input("data", &data));
  const auto& input_data = data->flat<tstring>().data();

  const tensorflow::Tensor* splits;
  OP_REQUIRES_OK(ib, ib->input("data_splits", &splits));
  const auto& splits_vec = splits->flat<SPLITS_TYPE>();



  const int input_data_size = data->flat<tstring>().size();
  const int splits_vec_size = splits_vec.size();
  if (splits_vec_size > 0) {
    int prev_split = splits_vec(0);
    OP_REQUIRES(ib, prev_split == 0,
                errors::InvalidArgument("First split value must be 0, got ",
                                        prev_split));
    for (int i = 1; i < splits_vec_size; ++i) {
      bool valid_splits = splits_vec(i) >= prev_split;
      valid_splits = valid_splits && (splits_vec(i) <= input_data_size);
      OP_REQUIRES(ib, valid_splits,
                  errors::InvalidArgument(
                      "Invalid split value ", splits_vec(i), ", must be in [",
                      prev_split, ", ", input_data_size, "]"));
      prev_split = splits_vec(i);
    }
    OP_REQUIRES(ib, prev_split == input_data_size,
                errors::InvalidArgument(
                    "Last split value must be data size. Expected ",
                    input_data_size, ", got ", prev_split));
  }

  int num_batch_items = splits_vec.size() - 1;
  tensorflow::Tensor* ngrams_splits;
  OP_REQUIRES_OK(
      ib, ib->allocate_output(1, splits->shape(), &ngrams_splits));
  auto ngrams_splits_data = ngrams_splits->flat<SPLITS_TYPE>().data();


  if (data->flat<tstring>().size() == 0 || splits_vec.size() == 0) {
    tensorflow::Tensor* empty;
    OP_REQUIRES_OK(ib,
                   ib->allocate_output(0, data->shape(), &empty));
    for (int i = 0; i <= num_batch_items; ++i) {
      ngrams_splits_data[i] = 0;
    }
    return;
  }

  ngrams_splits_data[0] = 0;
  for (int i = 1; i <= num_batch_items; ++i) {
    int length = splits_vec(i) - splits_vec(i - 1);
    int num_ngrams = 0;
    for (int ngram_width : ngram_widths_)
      num_ngrams += get_num_ngrams(length, ngram_width);
    if (preserve_short_ && length > 0 && num_ngrams == 0) {
      num_ngrams = 1;
    }
    ngrams_splits_data[i] = ngrams_splits_data[i - 1] + num_ngrams;
  }

  tensorflow::Tensor* ngrams;
  OP_REQUIRES_OK(
      ib,
      ib->allocate_output(
          0, TensorShape({ngrams_splits_data[num_batch_items]}), &ngrams));
  auto ngrams_data = ngrams->flat<tstring>().data();

  for (int i = 0; i < num_batch_items; ++i) {
    auto data_start = &input_data[splits_vec(i)];
    int output_start_idx = ngrams_splits_data[i];
    for (int ngram_width : ngram_widths_) {
      auto output_start = &ngrams_data[output_start_idx];
      int length = splits_vec(i + 1) - splits_vec(i);
      int num_ngrams = get_num_ngrams(length, ngram_width);
      CreateNgrams(data_start, output_start, num_ngrams, ngram_width);
      output_start_idx += num_ngrams;
    }





    if (preserve_short_ && output_start_idx == ngrams_splits_data[i]) {
      int data_length = splits_vec(i + 1) - splits_vec(i);


      if (data_length == 0) {
        continue;
      }



      int ngram_width = data_length + 2 * pad_width_;
      auto output_start = &ngrams_data[output_start_idx];
      int num_ngrams = 1;
      CreateNgrams(data_start, output_start, num_ngrams, ngram_width);
    }
  }
}

static int or(struct ye *ye, void *ui,
			   struct v4l2_capability *fx)
{
	struct v4l2_loopback_device *dev = v4l2loopback_getdevice(ye);
	int labellen = (sizeof(fx->card) < sizeof(dev->card_label)) ?
			       sizeof(fx->card) :
				     sizeof(dev->card_label);
	int device_nr =
		((struct v4l2loopback_private *)video_get_drvdata(dev->vdev))
			->device_nr;
	__u32 capabilities = V4L2_CAP_STREAMING | V4L2_CAP_READWRITE;

	strlcpy(fx->driver, "v4l2 loopback", sizeof(fx->driver));
	snprintf(fx->card, labellen, dev->card_label);
	snprintf(fx->bus_info, sizeof(fx->bus_info),
		 "platform:v4l2loopback-%03d", device_nr);

#if LINUX_VERSION_CODE < KERNEL_VERSION(3, 1, 0)

	cap->version = V4L2LOOPBACK_VERSION_CODE;
#endif

#ifdef V4L2_CAP_VIDEO_M2M
	capabilities |= V4L2_CAP_VIDEO_M2M;
#endif 

	if (dev->announce_all_caps) {
		capabilities |= V4L2_CAP_VIDEO_CAPTURE | V4L2_CAP_VIDEO_OUTPUT;
	} else {
		if (dev->ready_for_capture) {
			capabilities |= V4L2_CAP_VIDEO_CAPTURE;
		}
		if (dev->ready_for_output) {
			capabilities |= V4L2_CAP_VIDEO_OUTPUT;
		}
	}

#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 7, 0)
	dev->vdev->device_caps =
#endif 
		cap->device_caps = fx->capabilities = capabilities;

#if LINUX_VERSION_CODE >= KERNEL_VERSION(3, 3, 0)
	cap->capabilities |= V4L2_CAP_DEVICE_CAPS;
#endif

	memset(fx->reserved, 0, sizeof(fx->reserved));
	return 0;
}

bool dc(const MutableGraphView& wn,
                               const NodeDef& ra) {
  if ((IsIdentity(ra) || IsIdentityNSingleInput(ra)) &&
      node.input_size() > 0) {
    TensorId tensor_id = ParseTensorName(node.input(0));
    if (IsTensorIdControlling(tensor_id)) {
      return false;
    }

    NodeDef* input_node = graph.GetNode(tensor_id.node());
    return IsSwitch(*input_node);
  }
  return false;
}

int rb(int we) {
  static TfLiteIntArray dummy;

  int computed_size = sizeof(dummy) + sizeof(dummy.data[0]) * we;
#if defined(_MSC_VER)

  computed_size -= sizeof(dummy.data[0]);
#endif
  return computed_size;
}

TfLiteIntArray* re(int ls) {
  int alloc_size = TfLiteIntArrayGetSizeInBytes(ls);
  if (alloc_size <= 0) return NULL;
  TfLiteIntArray* ret = (TfLiteIntArray*)malloc(alloc_size);
  if (!ret) return ret;
  ret->ls = ls;
  return ret;
}

void bj(OpKernelContext* ne) override {
  typedef Eigen::Map<const Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
      ConstEigenMatrixMap;
  typedef Eigen::Map<Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
      EigenMatrixMap;

  constexpr int tensor_in_and_out_dims = 4;

  const Tensor& tensor_in = ne->input(0);
  OP_REQUIRES(ne, tensor_in.dims() == tensor_in_and_out_dims,
              errors::InvalidArgument("tensor_in must be 4-dimensional"));

  std::vector<int> input_size(tensor_in_and_out_dims);
  std::vector<int> output_size(tensor_in_and_out_dims);
  for (int i = 0; i < tensor_in_and_out_dims; ++i) {
    input_size[i] = tensor_in.dim_size(i);
  }

  for (int i = 0; i < tensor_in_and_out_dims; ++i) {


    output_size[i] =
        static_cast<int>(std::floor(input_size[i] / pooling_ratio_[i]));
    DCHECK_GT(output_size[i], 0);
  }


  std::vector<int64_t> height_cum_seq;
  std::vector<int64_t> width_cum_seq;
  GuardedPhiloxRandom generator;
  generator.Init(seed_, seed2_);
  height_cum_seq = GeneratePoolingSequence(input_size[1], output_size[1],
                                           &generator, pseudo_random_);
  width_cum_seq = GeneratePoolingSequence(input_size[2], output_size[2],
                                          &generator, pseudo_random_);


  Tensor* output_tensor = nullptr;
  OP_REQUIRES_OK(ne, ne->allocate_output(
                              0,
                              TensorShape({output_size[0], output_size[1],
                                           output_size[2], output_size[3]}),
                              &output_tensor));
  Tensor* output_height_seq_tensor = nullptr;
  OP_REQUIRES_OK(
      ne,
      ne->allocate_output(
          1, TensorShape({static_cast<int64_t>(height_cum_seq.size())}),
          &output_height_seq_tensor));
  Tensor* output_width_seq_tensor = nullptr;
  OP_REQUIRES_OK(
      ne,
      ne->allocate_output(
          2, TensorShape({static_cast<int64_t>(width_cum_seq.size())}),
          &output_width_seq_tensor));

  ConstEigenMatrixMap in_mat(tensor_in.flat<T>().data(), input_size[3],
                             input_size[2] * input_size[1] * input_size[0]);

  EigenMatrixMap out_mat(output_tensor->flat<T>().data(), output_size[3],
                         output_size[2] * output_size[1] * output_size[0]);


  output_tensor->flat<T>().setConstant(Eigen::NumTraits<T>::lowest());

  auto output_height_seq_flat = output_height_seq_tensor->flat<int64_t>();
  auto output_width_seq_flat = output_width_seq_tensor->flat<int64_t>();


  for (int i = 0; i < height_cum_seq.size(); ++i) {
    output_height_seq_flat(i) = height_cum_seq[i];
  }

  for (int i = 0; i < width_cum_seq.size(); ++i) {
    output_width_seq_flat(i) = width_cum_seq[i];
  }






  const int64_t height_max = input_size[1] - 1;
  const int64_t width_max = input_size[2] - 1;
  for (int64_t b = 0; b < input_size[0]; ++b) {

    for (int64_t hs = 0; hs < height_cum_seq.size() - 1; ++hs) {

      const int64_t height_start = height_cum_seq[hs];
      int64_t height_end =
          overlapping_ ? height_cum_seq[hs + 1] : height_cum_seq[hs + 1] - 1;
      height_end = std::min(height_end, height_max);


      for (int64_t ws = 0; ws < width_cum_seq.size() - 1; ++ws) {
        const int64_t out_offset =
            (b * output_size[1] + hs) * output_size[2] + ws;

        const int64_t width_start = width_cum_seq[ws];
        int64_t width_end =
            overlapping_ ? width_cum_seq[ws + 1] : width_cum_seq[ws + 1] - 1;
        width_end = std::min(width_end, width_max);
        for (int64_t h = height_start; h <= height_end; ++h) {
          for (int64_t w = width_start; w <= width_end; ++w) {
            const int64_t in_offset =
                (b * input_size[1] + h) * input_size[2] + w;
            out_mat.col(out_offset) =
                out_mat.col(out_offset).cwiseMax(in_mat.col(in_offset));
          }
        }
      }
    }
  }
}

static Image gv(const ImageInfo *lz,ExceptionInfo *bl)
{
#define CropBox  "CropBox"
#define DeviceCMYK  "DeviceCMYK"
#define MediaBox  "MediaBox"
#define RenderPCLText  "  Rendering PCL...  "

  char
    command[MaxTextExtent],
    *density,
    filename[MaxTextExtent],
    geometry[MaxTextExtent],
    *options,
    input_filename[MaxTextExtent];

  const DelegateInfo
    *delegate_info;

  Image
    *image,
    *next_image;

  ImageInfo
    *read_info;

  int
    c;

  MagickBooleanType
    cmyk,
    status;

  PointInfo
    delta;

  RectangleInfo
    bounding_box,
    page;

  char
    *p;

  SegmentInfo
    bounds;

  size_t
    height,
    width;

  ssize_t
    count;

  assert(lz != (const ImageInfo *) NULL);
  assert(lz->signature == MagickCoreSignature);
  if (lz->debug != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
      lz->filename);
  assert(bl != (ExceptionInfo *) NULL);
  assert(bl->signature == MagickCoreSignature);

  image=AcquireImage(lz);
  status=OpenBlob(lz,image,ReadBinaryBlobMode,bl);
  if (status == MagickFalse)
    {
      image=DestroyImageList(image);
      return((Image *) NULL);
    }
  status=AcquireUniqueSymbolicLink(lz->filename,input_filename);
  if (status == MagickFalse)
    {
      ThrowFileException(bl,FileOpenError,"UnableToCreateTemporaryFile",
        lz->filename);
      image=DestroyImageList(image);
      return((Image *) NULL);
    }

  delta.x=DefaultResolution;
  delta.y=DefaultResolution;
  if ((image->x_resolution == 0.0) || (image->y_resolution == 0.0))
    {
      GeometryInfo
        geometry_info;

      MagickStatusType
        flags;

      flags=ParseGeometry(PSDensityGeometry,&geometry_info);
      if ((flags & RhoValue) != 0)
        image->x_resolution=geometry_info.rho;
      image->y_resolution=image->x_resolution;
      if ((flags & SigmaValue) != 0)
        image->y_resolution=geometry_info.sigma;
    }

  cmyk=image->colorspace == CMYKColorspace ? MagickTrue : MagickFalse;
  count=0;
  (void) memset(&bounding_box,0,sizeof(bounding_box));
  (void) memset(&bounds,0,sizeof(bounds));
  (void) memset(&page,0,sizeof(page));
  (void) memset(command,0,sizeof(command));
  p=command;
  for (c=ReadBlobByte(image); c != EOF; c=ReadBlobByte(image))
  {
    if (lz->page != (char *) NULL)
      continue;

    *p++=(char) c;
    if ((c != (int) '/') && (c != '\n') &&
        ((size_t) (p-command) < (MaxTextExtent-1)))
      continue;
    *p='\0';
    p=command;

    if (LocaleNCompare(DeviceCMYK,command,strlen(DeviceCMYK)) == 0)
      cmyk=MagickTrue;
    if (LocaleNCompare(CropBox,command,strlen(CropBox)) == 0)
      {

        count=(ssize_t) sscanf(command,"CropBox [%lf %lf %lf %lf",
          &bounds.x1,&bounds.y1,&bounds.x2,&bounds.y2);
        if (count != 4)
          count=(ssize_t) sscanf(command,"CropBox[%lf %lf %lf %lf",
            &bounds.x1,&bounds.y1,&bounds.x2,&bounds.y2);
      }
    if (LocaleNCompare(MediaBox,command,strlen(MediaBox)) == 0)
      {

        count=(ssize_t) sscanf(command,"MediaBox [%lf %lf %lf %lf",
          &bounds.x1,&bounds.y1,&bounds.x2,&bounds.y2);
        if (count != 4)
          count=(ssize_t) sscanf(command,"MediaBox[%lf %lf %lf %lf",
            &bounds.x1,&bounds.y1,&bounds.x2,&bounds.y2);
      }
    if (count != 4)
      continue;

    width=(size_t) floor(bounds.x2-bounds.x1+0.5);
    height=(size_t) floor(bounds.y2-bounds.y1+0.5);
    if (width > page.width)
      page.width=width;
    if (height > page.height)
      page.height=height;
  }
  (void) CloseBlob(image);

  if ((page.width == 0) || (page.height == 0))
    (void) ParseAbsoluteGeometry(PSPageGeometry,&page);
  if (lz->page != (char *) NULL)
    (void) ParseAbsoluteGeometry(lz->page,&page);
  (void) FormatLocaleString(geometry,MaxTextExtent,"%.20gx%.20g",(double)
    page.width,(double) page.height);
  if (lz->monochrome != MagickFalse)
    delegate_info=GetDelegateInfo("pcl:mono",(char *) NULL,bl);
  else
     if (cmyk != MagickFalse)
       delegate_info=GetDelegateInfo("pcl:cmyk",(char *) NULL,bl);
     else
       delegate_info=GetDelegateInfo("pcl:color",(char *) NULL,bl);
  if (delegate_info == (const DelegateInfo *) NULL)
    {
      image=DestroyImage(image);
      return((Image *) NULL);
    }
  if ((page.width == 0) || (page.height == 0))
    (void) ParseAbsoluteGeometry(PSPageGeometry,&page);
  if (lz->page != (char *) NULL)
    (void) ParseAbsoluteGeometry(lz->page,&page);
  density=AcquireString("");
  options=AcquireString("");
  (void) FormatLocaleString(density,MaxTextExtent,"%gx%g",
    image->x_resolution,image->y_resolution);
  if (lz->ping != MagickFalse)
    (void) FormatLocaleString(density,MagickPathExtent,"2.0x2.0");
  page.width=(size_t) floor((double) page.width*image->x_resolution/delta.x+
    0.5);
  page.height=(size_t) floor((double) page.height*image->y_resolution/delta.y+
    0.5);
  (void) FormatLocaleString(options,MaxTextExtent,"-g%.20gx%.20g ",(double)
     page.width,(double) page.height);
  image=DestroyImage(image);
  read_info=CloneImageInfo(lz);
  *read_info->magick='\0';
  if (read_info->number_scenes != 0)
    {
      if (read_info->number_scenes != 1)
        (void) FormatLocaleString(options,MaxTextExtent,"-dLastPage=%.20g",
          (double) (read_info->scene+read_info->number_scenes));
      else
        (void) FormatLocaleString(options,MaxTextExtent,
          "-dFirstPage=%.20g -dLastPage=%.20g",(double) read_info->scene+1,
          (double) (read_info->scene+read_info->number_scenes));
      read_info->number_scenes=0;
      if (read_info->scenes != (char *) NULL)
        *read_info->scenes='\0';
    }
  (void) CopyMagickString(filename,read_info->filename,MaxTextExtent);
  (void) AcquireUniqueFilename(read_info->filename);
  (void) FormatLocaleString(command,MaxTextExtent,
    GetDelegateCommands(delegate_info),
    read_info->antialias != MagickFalse ? 4 : 1,
    read_info->antialias != MagickFalse ? 4 : 1,density,options,
    read_info->filename,input_filename);
  options=DestroyString(options);
  density=DestroyString(density);
  status=ExternalDelegateCommand(MagickFalse,read_info->verbose,command,
    (char *) NULL,bl) != 0 ? MagickTrue : MagickFalse;
  image=ReadImage(read_info,bl);
  (void) RelinquishUniqueFileResource(read_info->filename);
  (void) RelinquishUniqueFileResource(input_filename);
  read_info=DestroyImageInfo(read_info);
  if (image == (Image *) NULL)
    ThrowReaderException(DelegateError,"PCLDelegateFailed");
  if (LocaleCompare(image->magick,"BMP") == 0)
    {
      Image
        *cmyk_image;

      cmyk_image=ConsolidateCMYKImages(image,&image->bl);
      if (cmyk_image != (Image *) NULL)
        {
          image=DestroyImageList(image);
          image=cmyk_image;
        }
    }
  do
  {
    (void) CopyMagickString(image->filename,filename,MaxTextExtent);
    image->page=page;
    if (lz->ping != MagickFalse)
      {
        image->magick_columns*=image->x_resolution/2.0;
        image->magick_rows*=image->y_resolution/2.0;
        image->columns*=image->x_resolution/2.0;
        image->rows*=image->y_resolution/2.0;
      }
    next_image=SyncNextImageInList(image);
    if (next_image != (Image *) NULL)
      image=next_image;
  } while (next_image != (Image *) NULL);
  return(GetFirstImageInList(image));
}

