void kv(QuicServerConnectionState& kt) {


  auto handshakeLayer = conn.serverHandshakeLayer;
  auto zeroRttReadCipher = handshakeLayer->getZeroRttReadCipher();
  auto zeroRttHeaderCipher = handshakeLayer->getZeroRttReadHeaderCipher();




  auto oneRttWriteCipher = handshakeLayer->getOneRttWriteCipher();

  auto oneRttReadCipher = handshakeLayer->getOneRttReadCipher();

  auto oneRttWriteHeaderCipher = handshakeLayer->getOneRttWriteHeaderCipher();
  auto oneRttReadHeaderCipher = handshakeLayer->getOneRttReadHeaderCipher();

  if (zeroRttReadCipher) {
    if (conn.qLogger) {
      conn.qLogger->addTransportStateUpdate(kDerivedZeroRttReadCipher);
    }
    QUIC_TRACE(fst_trace, kt, "derived 0-rtt read cipher");
    conn.readCodec->setZeroRttReadCipher(std::move(zeroRttReadCipher));
  }
  if (zeroRttHeaderCipher) {
    conn.readCodec->setZeroRttHeaderCipher(std::move(zeroRttHeaderCipher));
  }
  if (oneRttWriteHeaderCipher) {
    conn.oneRttWriteHeaderCipher = std::move(oneRttWriteHeaderCipher);
  }
  if (oneRttReadHeaderCipher) {
    conn.readCodec->setOneRttHeaderCipher(std::move(oneRttReadHeaderCipher));
  }

  if (oneRttWriteCipher) {
    if (conn.qLogger) {
      conn.qLogger->addTransportStateUpdate(kDerivedOneRttWriteCipher);
    }
    QUIC_TRACE(fst_trace, kt, "derived 1-rtt write cipher");
    CHECK(!conn.oneRttWriteCipher.get());
    conn.oneRttWriteCipher = std::move(oneRttWriteCipher);

    updatePacingOnKeyEstablished(kt);



    auto clientParams = handshakeLayer->getClientTransportParams();
    if (!clientParams) {
      throw QuicTransportException(
          "No client transport params",
          TransportErrorCode::TRANSPORT_PARAMETER_ERROR);
    }
    processClientInitialParams(kt, std::move(*clientParams));
  }
  if (oneRttReadCipher) {
    if (conn.qLogger) {
      conn.qLogger->addTransportStateUpdate(kDerivedOneRttReadCipher);
    }
    QUIC_TRACE(fst_trace, kt, "derived 1-rtt read cipher");

    conn.writableBytesLimit = folly::none;
    conn.readCodec->setOneRttReadCipher(std::move(oneRttReadCipher));
  }
  auto handshakeReadCipher = handshakeLayer->getHandshakeReadCipher();
  auto handshakeReadHeaderCipher =
      handshakeLayer->getHandshakeReadHeaderCipher();
  if (handshakeReadCipher) {
    CHECK(handshakeReadHeaderCipher);
    conn.readCodec->setHandshakeReadCipher(std::move(handshakeReadCipher));
    conn.readCodec->setHandshakeHeaderCipher(
        std::move(handshakeReadHeaderCipher));
  }
  if (handshakeLayer->isHandshakeDone()) {
    CHECK(conn.oneRttWriteCipher);
    if (conn.version != QuicVersion::MVFST_D24 && !conn.sentHandshakeDone) {
      sendSimpleFrame(kt, HandshakeDoneFrame());
      conn.sentHandshakeDone = true;
    }
  }
}

bool jq(dx)
{
#if ACCUSOFT_CODE
  int lines             = m_ulRemaining[0]; 
  UBYTE preshift        = m_ucLowBit + FractionalColorBitsOf();
  struct Line *line[4];
  UBYTE cx;



  if (m_pFrame->HeightOf() == 0) {
    assert(lines == 0);
    lines = 8;
  }


  if (lines > 8) {
    lines = 8;
  }
  if (m_pFrame->HeightOf() > 0)
    m_ulRemaining[0] -= lines;
  assert(lines > 0);
  assert(m_ucCount < 4);



  for(cx = 0;cx < m_ucCount;cx++) {
    line[cx] = CurrentLine(cx);
  }


  do {
    LONG length = m_ulWidth[0];
    LONG *lp[4];


    for(cx = 0;cx < m_ucCount;cx++) {
      lp[cx] = line[cx]->m_pData;
      StartLine(cx);
    }

    if (BeginReadMCU(m_Stream.ByteStreamOf())) { 

      do {
        LONG a[4],b[4],c[4],d[4]; 
        LONG d1[4],d2[4],d3[4];   
        bool isrun = true;

        for(cx = 0;cx < m_ucCount;cx++) {
          GetContext(cx,a[cx],b[cx],c[cx],d[cx]);

          d1[cx]  = d[cx] - b[cx];    
          d2[cx]  = b[cx] - c[cx];
          d3[cx]  = c[cx] - a[cx];



          if (isrun && !isRunMode(d1[cx],d2[cx],d3[cx]))
            isrun = false;
        }

        if (isrun) {
          LONG run = DecodeRun(length,m_lRunIndex[0]);


          while(run) {


            for(cx = 0;cx < m_ucCount;cx++) {
              UpdateContext(cx,a[cx]);

              *lp[cx]++ = a[cx] << preshift;
            }
            run--,length--;

          }



          if (length) {
            bool negative; 
            LONG errval;   
            LONG merr;     
            LONG rx;       
            UBYTE k;       


            for(cx = 0;cx < m_ucCount;cx++) {

              GetContext(cx,a[cx],b[cx],c[cx],d[cx]);


              negative = a[cx] > b[cx];

              k       = GolombParameter(false);


              merr    = GolombDecode(k,m_lLimit - m_lJ[m_lRunIndex[0]] - 1);

              errval  = InverseErrorMapping(merr,ErrorMappingOffset(false,merr != 0,k));

              rx      = Reconstruct(negative,b[cx],errval);

              UpdateContext(cx,rx);

              *lp[cx]++ = rx << preshift;

              UpdateState(false,errval);
            }



            if (m_lRunIndex[0] > 0)
              m_lRunIndex[0]--;
          } else break; 
        } else {
          UWORD ctxt;
          bool  negative; 
          LONG  px;       
          LONG  rx;       
          LONG  errval;   
          LONG  merr;     
          UBYTE k;        

          for(cx = 0;cx < m_ucCount;cx++) {

            d1[cx]  = QuantizedGradient(d1[cx]);
            d2[cx]  = QuantizedGradient(d2[cx]);
            d3[cx]  = QuantizedGradient(d3[cx]);

            ctxt    = Context(negative,d1[cx],d2[cx],d3[cx]); 

            px      = Predict(a[cx],b[cx],c[cx]);

            px      = CorrectPrediction(ctxt,negative,px);

            k       = GolombParameter(ctxt);

            merr    = GolombDecode(k,m_lLimit);

            errval  = InverseErrorMapping(merr,ErrorMappingOffset(ctxt,k));

            UpdateState(ctxt,errval);

            rx      = Reconstruct(negative,px,errval);

            UpdateContext(cx,rx);

            *lp[cx]++ = rx << preshift;
          }
        }
      } while(--length);
    } 


    for(cx = 0;cx < m_ucCount;cx++) {
      EndLine(cx);
      line[cx] = line[cx]->m_pNext;
    }

  } while(--lines);





  m_Stream.SkipStuffing();
#endif  
  return false;
}

bool nk(jv)
{ 
#if ACCUSOFT_CODE
  int lines             = m_ulRemaining[0]; 
  UBYTE preshift        = m_ucLowBit + FractionalColorBitsOf();
  struct Line *line     = CurrentLine(0);



  if (m_pFrame->HeightOf() == 0) {
    assert(lines == 0);
    lines = 8;
  }

  assert(m_ucCount == 1);



  if (lines > 8) {
    lines = 8;
  }
  if (m_pFrame->HeightOf() > 0)
    m_ulRemaining[0] -= lines;

  assert(lines > 0);


  do {
    LONG length = m_ulWidth[0];
    LONG *lp    = line->m_pData;

#ifdef DEBUG_LS
    int xpos    = 0;
    static int linenumber = 0;
    printf("\n%4d : ",++linenumber);
#endif

    StartLine(0);
    if (BeginReadMCU(m_Stream.ByteStreamOf())) { 
      do {
        LONG a,b,c,d;   
        LONG d1,d2,d3;  

        GetContext(0,a,b,c,d);
        d1  = d - b;    
        d2  = b - c;
        d3  = c - a;

        if (isRunMode(d1,d2,d3)) {
          LONG run = DecodeRun(length,m_lRunIndex[0]);


          while(run) {

            UpdateContext(0,a);

            *lp++ = a << preshift;
#ifdef DEBUG_LS
            printf("%4d:<%2x> ",xpos++,a);
#endif
            run--,length--;

          }



          if (length) {
            bool negative; 
            bool rtype;    
            LONG errval;   
            LONG merr;     
            LONG rx;       
            UBYTE k;       

            GetContext(0,a,b,c,d);

            rtype  = InterruptedPredictionMode(negative,a,b);

            k      = GolombParameter(rtype);

            merr   = GolombDecode(k,m_lLimit - m_lJ[m_lRunIndex[0]] - 1);

            errval = InverseErrorMapping(merr + rtype,ErrorMappingOffset(rtype,rtype || merr,k));

            rx     = Reconstruct(negative,rtype?a:b,errval);

            UpdateContext(0,rx);

            *lp    = rx << preshift;
#ifdef DEBUG_LS
            printf("%4d:<%2x> ",xpos++,*lp);
#endif

            UpdateState(rtype,errval);



            if (m_lRunIndex[0] > 0)
              m_lRunIndex[0]--;
          } else break; 
        } else {
          UWORD ctxt;
          bool  negative; 
          LONG  px;       
          LONG  rx;       
          LONG  errval;   
          LONG  merr;     
          UBYTE k;        

          d1     = QuantizedGradient(d1);
          d2     = QuantizedGradient(d2);
          d3     = QuantizedGradient(d3);

          ctxt   = Context(negative,d1,d2,d3); 

          px     = Predict(a,b,c);

          px     = CorrectPrediction(ctxt,negative,px);

          k      = GolombParameter(ctxt);

          merr   = GolombDecode(k,m_lLimit);

          errval = InverseErrorMapping(merr,ErrorMappingOffset(ctxt,k));

          UpdateState(ctxt,errval);

          rx     = Reconstruct(negative,px,errval);

          UpdateContext(0,rx);

          *lp    = rx << preshift;
#ifdef DEBUG_LS
          printf("%4d:<%2x> ",xpos++,*lp);
#endif
        }
      } while(++lp,--length);
    } 
    EndLine(0);
    line = line->m_pNext;
  } while(--lines); 





  m_Stream.SkipStuffing();
#endif  
  return false;
}

static GF_Err mv(GF_ISOFile *mw, u32 *jr, u64 *eg, Bool nv)
{
	GF_Box *a;
	u64 totSize, mdat_end=0;
	GF_Err e = GF_OK;

#ifndef	GPAC_DISABLE_ISOM_FRAGMENTS
	if (mw->single_moof_mode && mw->single_moof_state == 2) {
		return e;
	}


	totSize = mw->current_top_box_start;
	if (mw->bytes_removed) {
		assert(totSize >= mw->bytes_removed);
		totSize -= mw->bytes_removed;
	}
	gf_bs_seek(mw->movieFileMap->bs, totSize);
#endif



	while (gf_bs_available(mw->movieFileMap->bs)) {
		*eg = 0;
#ifndef	GPAC_DISABLE_ISOM_FRAGMENTS
		mov->current_top_box_start = gf_bs_get_position(mw->movieFileMap->bs) + mw->bytes_removed;
		GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[iso file] Parsing a top-level box at position %d\n", mw->current_top_box_start));
#endif

		e = gf_isom_parse_root_box(&a, mw->movieFileMap->bs, jr, eg, nv);

		if (e >= 0) {

		} else if (e == GF_ISOM_INCOMPLETE_FILE) {

			if (mw->openMode != GF_ISOM_OPEN_READ) {
				GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Incomplete MDAT while file is not read-only\n"));
				return GF_ISOM_INVALID_FILE;
			}
			if ((mw->openMode == GF_ISOM_OPEN_READ) && !progressive_mode) {
				GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Incomplete file while reading for dump - aborting parsing\n"));
				break;
			}
			return e;
		} else {
			return e;
		}

		switch (a->type) {

		case GF_ISOM_BOX_TYPE_MOOV:
			if (mw->moov) {
				GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Duplicate MOOV detected!\n"));
				gf_isom_box_del(a);
				return GF_ISOM_INVALID_FILE;
			}
			mov->moov = (GF_MovieBox *)a;
			mov->original_moov_offset = mw->current_top_box_start;

			mov->moov->mw = mw;
#ifndef GPAC_DISABLE_ISOM_FRAGMENTS
			if (mw->moov->mvex) mw->moov->mvex->mw = mw;

#ifdef GF_ENABLE_CTRN
			if (! (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG)) {
				gf_isom_setup_traf_inheritance(mw);
			}
#endif

#endif
			e = gf_list_add(mw->TopBoxes, a);
			if (e) return e;

			totSize += a->size;

            if (!mov->moov->mvhd) {
                GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Missing MovieHeaderBox\n"));
                return GF_ISOM_INVALID_FILE;
            }

            if (mw->meta) {
				gf_isom_meta_restore_items_ref(mw, mw->meta);
			}


			if (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG) {
				u32 k;
				for (k=0; k<gf_list_count(mw->moov->trackList); k++) {
					GF_TrackBox *trak = (GF_TrackBox *)gf_list_get(mw->moov->trackList, k);

					if (trak->sample_encryption) {
						e = senc_Parse(mw->movieFileMap->bs, trak, NULL, trak->sample_encryption);
						if (e) return e;
					}
				}
			} else {
				u32 k;
				for (k=0; k<gf_list_count(mw->moov->trackList); k++) {
					GF_TrackBox *trak = (GF_TrackBox *)gf_list_get(mw->moov->trackList, k);
					if (trak->Media->information->sampleTable->sampleGroups) {
						convert_compact_sample_groups(trak->Media->information->sampleTable->child_boxes, trak->Media->information->sampleTable->sampleGroups);
					}
				}
			}

            if (mdat_end && mw->signal_frag_bounds && !(mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG) ) {
                gf_isom_push_mdat_end(mw, mdat_end);
                mdat_end=0;
            }
			break;


		case GF_ISOM_BOX_TYPE_META:
			if (mw->meta) {
				GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Duplicate META detected!\n"));
				gf_isom_box_del(a);
				return GF_ISOM_INVALID_FILE;
			}
			mov->meta = (GF_MetaBox *)a;
			mov->original_meta_offset = mw->current_top_box_start;
			e = gf_list_add(mw->TopBoxes, a);
			if (e) {
				return e;
			}
			totSize += a->size;
			gf_isom_meta_restore_items_ref(mw, mw->meta);
			break;


		case GF_ISOM_BOX_TYPE_MDAT:
			if (!mov->first_data_toplevel_offset) {
				mov->first_data_toplevel_offset = mw->current_top_box_start;
				mov->first_data_toplevel_size = a->size;
			}
			totSize += a->size;

#ifndef	GPAC_DISABLE_ISOM_FRAGMENTS
			if (mw->emsgs) {
				gf_isom_box_array_del(mw->emsgs);
				mov->emsgs = NULL;
			}
#endif

			if (mw->openMode == GF_ISOM_OPEN_READ) {
				if (!mov->mdat) {
					mov->mdat = (GF_MediaDataBox *) a;
					e = gf_list_add(mw->TopBoxes, mw->mdat);
					if (e) {
						return e;
					}
				}
#ifndef	GPAC_DISABLE_ISOM_FRAGMENTS
				else if (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG) gf_list_add(mw->TopBoxes, a);
#endif
				else gf_isom_box_del(a); 


				if (mw->signal_frag_bounds && !(mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG) ) {
                    mdat_end = gf_bs_get_position(mw->movieFileMap->bs);
                    if (mw->moov) {
                        gf_isom_push_mdat_end(mw, mdat_end);
                        mdat_end=0;
                    }
				}
			}

			else if (!mov->mdat && (mw->openMode != GF_ISOM_OPEN_READ) && (mw->openMode != GF_ISOM_OPEN_KEEP_FRAGMENTS)) {
				gf_isom_box_del(a);
				mov->mdat = (GF_MediaDataBox *) gf_isom_box_new(GF_ISOM_BOX_TYPE_MDAT);
				if (!mov->mdat) return GF_OUT_OF_MEM;
				e = gf_list_add(mw->TopBoxes, mw->mdat);
				if (e) {
					return e;
				}
			} else {
				gf_isom_box_del(a);
			}
			break;
		case GF_ISOM_BOX_TYPE_FTYP:

			if (mw->brand) {
				gf_isom_box_del(a);
				GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Duplicate 'ftyp' detected!\n"));
				return GF_ISOM_INVALID_FILE;
			}
			mov->brand = (GF_FileTypeBox *)a;
			totSize += a->size;
			e = gf_list_add(mw->TopBoxes, a);
			if (e) return e;
			break;

		case GF_ISOM_BOX_TYPE_OTYP:

			if (mw->otyp) {
				gf_isom_box_del(a);
				GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Duplicate 'otyp' detected!\n"));
				return GF_ISOM_INVALID_FILE;
			}

			if (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG) {
				mov->otyp = (GF_Box *)a;
				totSize += a->size;
				e = gf_list_add(mw->TopBoxes, a);
				if (e) return e;
			} else {
				GF_FileTypeBox *brand = (GF_FileTypeBox *) gf_isom_box_find_child(a->child_boxes, GF_ISOM_BOX_TYPE_FTYP);
				if (brand) {
					s32 pos;
					gf_list_del_item(a->child_boxes, brand);
					pos = gf_list_del_item(mw->TopBoxes, mw->brand);
					gf_isom_box_del((GF_Box *) mw->brand);
					mov->brand = brand;
					if (pos<0) pos=0;
					gf_list_insert(mw->TopBoxes, brand, pos);
				}
				gf_isom_box_del(a);
			}
			break;

		case GF_ISOM_BOX_TYPE_PDIN:

			if (mw->pdin) {
				gf_isom_box_del(a);
				GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Duplicate 'pdin'' detected!\n"));
				return GF_ISOM_INVALID_FILE;
			}
			mov->pdin = (GF_ProgressiveDownloadBox *) a;
			totSize += a->size;
			e = gf_list_add(mw->TopBoxes, a);
			if (e) return e;
			break;


#ifndef	GPAC_DISABLE_ISOM_FRAGMENTS
		case GF_ISOM_BOX_TYPE_STYP:
		{
			u32 brand = ((GF_FileTypeBox *)a)->majorBrand;
			switch (brand) {
			case GF_ISOM_BRAND_SISX:
			case GF_ISOM_BRAND_RISX:
			case GF_ISOM_BRAND_SSSS:
				mov->is_index_segment = GF_TRUE;
				break;
			default:
				break;
			}
		}


		case GF_ISOM_BOX_TYPE_SIDX:
		case GF_ISOM_BOX_TYPE_SSIX:
			if (mw->moov && !mov->first_data_toplevel_offset) {
				mov->first_data_toplevel_offset = mw->current_top_box_start;
				mov->first_data_toplevel_size = a->size;
			}
			totSize += a->size;
			if (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG) {
				e = gf_list_add(mw->TopBoxes, a);
				if (e) return e;
			} else if (mw->signal_frag_bounds && !(mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG)  && (mw->openMode!=GF_ISOM_OPEN_KEEP_FRAGMENTS)
			) {
				if (a->type==GF_ISOM_BOX_TYPE_SIDX) {
					if (mw->root_sidx) gf_isom_box_del( (GF_Box *) mw->root_sidx);
					mov->root_sidx = (GF_SegmentIndexBox *) a;
					mov->sidx_start_offset = mw->current_top_box_start;
					mov->sidx_end_offset = gf_bs_get_position(mw->movieFileMap->bs);

				}
				else if (a->type==GF_ISOM_BOX_TYPE_STYP) {
					mov->styp_start_offset = mw->current_top_box_start;

					if (mw->seg_styp) gf_isom_box_del(mw->seg_styp);
					mov->seg_styp = a;
				} else if (a->type==GF_ISOM_BOX_TYPE_SSIX) {
					if (mw->seg_ssix) gf_isom_box_del(mw->seg_ssix);
					mov->seg_ssix = a;
				} else {
					gf_isom_box_del(a);
				}
				gf_isom_push_mdat_end(mw, mw->current_top_box_start);
			} else if (!mov->NextMoofNumber && (a->type==GF_ISOM_BOX_TYPE_SIDX)) {
				if (mw->main_sidx) gf_isom_box_del( (GF_Box *) mw->main_sidx);
				mov->main_sidx = (GF_SegmentIndexBox *) a;
				mov->main_sidx_end_pos = mw->current_top_box_start + a->size;
			} else {
				gf_isom_box_del(a);
			}
			break;

		case GF_ISOM_BOX_TYPE_MOOF:

			gf_isom_disable_inplace_rewrite(mw);
			if (!mov->moov) {
				GF_LOG(mw->moof ? GF_LOG_DEBUG : GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] Movie fragment but no moov (yet) - possibly broken parsing!\n"));
			}
			if (mw->single_moof_mode) {
				mov->single_moof_state++;
				if (mw->single_moof_state > 1) {
					gf_isom_box_del(a);
					return GF_OK;
				}
			}
			((GF_MovieFragmentBox *)a)->mw = mw;

			totSize += a->size;
			mov->moof = (GF_MovieFragmentBox *) a;


			FixTrackID(mw);
			if (! (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG)) {
				FixSDTPInTRAF(mw->moof);
			} else {
				u32 k;
				for (k=0; k<gf_list_count(mw->moof->TrackList); k++) {
					GF_TrackFragmentBox *traf = (GF_TrackFragmentBox *)gf_list_get(mw->moof->TrackList, k);
					if (traf->sampleGroups) {
						convert_compact_sample_groups(traf->child_boxes, traf->sampleGroups);
					}
				}
			}


			if (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG) {
				u32 k;
				gf_list_add(mw->TopBoxes, a);

				if (mw->moov) {
					for (k=0; k<gf_list_count(mw->moof->TrackList); k++) {
						GF_TrackFragmentBox *traf = gf_list_get(mw->moof->TrackList, k);
						if (traf->tfhd && mw->moov->mvex && mw->moov->mvex->TrackExList) {
							GF_TrackBox *trak = gf_isom_get_track_from_id(mw->moov, traf->tfhd->trackID);
							u32 j=0;
							while ((traf->trex = (GF_TrackExtendsBox*)gf_list_enum(mw->moov->mvex->TrackExList, &j))) {
								if (traf->trex->trackID == traf->tfhd->trackID) {
									if (!traf->trex->track) traf->trex->track = trak;
									break;
								}
								traf->trex = NULL;
							}
						}

						if (traf->trex && traf->tfhd && traf->trex->track && traf->sample_encryption) {
							GF_TrackBox *trak = GetTrackbyID(mw->moov, traf->tfhd->trackID);
							if (trak) {
								trak->current_traf_stsd_idx = traf->tfhd->sample_desc_index ? traf->tfhd->sample_desc_index : traf->trex->def_sample_desc_index;
								e = senc_Parse(mw->movieFileMap->bs, trak, traf, traf->sample_encryption);
								if (e) return e;
								trak->current_traf_stsd_idx = 0;
							}
						}
					}
				} else {
					for (k=0; k<gf_list_count(mw->moof->TrackList); k++) {
						GF_TrackFragmentBox *traf = gf_list_get(mw->moof->TrackList, k);
						if (traf->sample_encryption) {
							e = senc_Parse(mw->movieFileMap->bs, NULL, traf, traf->sample_encryption);
							if (e) return e;
						}
					}

				}
			} else if (mw->openMode==GF_ISOM_OPEN_KEEP_FRAGMENTS) {
				mov->NextMoofNumber = mw->moof->mfhd->sequence_number+1;
				mov->moof = NULL;
				gf_isom_box_del(a);
			} else {

				e = MergeFragment((GF_MovieFragmentBox *)a, mw);
				gf_isom_box_del(a);
				if (e) return e;
			}


			if (mw->root_sidx) {
				gf_isom_box_del((GF_Box *) mw->root_sidx);
				mov->root_sidx = NULL;
			}
			if (mw->root_ssix) {
				gf_isom_box_del(mw->seg_ssix);
				mov->root_ssix = NULL;
			}
			if (mw->seg_styp) {
				gf_isom_box_del(mw->seg_styp);
				mov->seg_styp = NULL;
			}
			mov->sidx_start_offset = 0;
			mov->sidx_end_offset = 0;
			mov->styp_start_offset = 0;
			break;
#endif
		case GF_ISOM_BOX_TYPE_UNKNOWN:
		{
			GF_UnknownBox *box = (GF_UnknownBox*)a;
			if (box->original_4cc == GF_ISOM_BOX_TYPE_JP) {
				u8 *c = (u8 *) box->data;
				if ((box->dataSize==4) && (GF_4CC(c[0],c[1],c[2],c[3])==(u32)0x0D0A870A))
					mov->is_jp2 = 1;
				gf_isom_box_del(a);
			} else {
				e = gf_list_add(mw->TopBoxes, a);
				if (e) return e;
			}
		}
		break;

		case GF_ISOM_BOX_TYPE_PRFT:
#ifndef GPAC_DISABLE_ISOM_FRAGMENTS
			if (!(mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG)) {

				if (mw->last_producer_ref_time)
					gf_isom_box_del(a);
				else
					mov->last_producer_ref_time = (GF_ProducerReferenceTimeBox *)a;
				break;
			}
#endif

		case GF_ISOM_BOX_TYPE_EMSG:
#ifndef GPAC_DISABLE_ISOM_FRAGMENTS
			if (! (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG)) {
				if (!mov->emsgs) mw->emsgs = gf_list_new();
				gf_list_add(mw->emsgs, a);
				break;
			}
#endif
		case GF_ISOM_BOX_TYPE_MFRA:
		case GF_ISOM_BOX_TYPE_MFRO:

			if (! (mw->FragmentsFlags & GF_ISOM_FRAG_READ_DEBUG)) {
				totSize += a->size;
				gf_isom_box_del(a);
				break;
			}
		default:
			totSize += a->size;
			e = gf_list_add(mw->TopBoxes, a);
			if (e) return e;
			break;
		}

#ifndef	GPAC_DISABLE_ISOM_FRAGMENTS

		mov->current_top_box_start = gf_bs_get_position(mw->movieFileMap->bs) + mw->bytes_removed;
#endif
	}


	if (!mov->moov && !mov->meta
#ifndef GPAC_DISABLE_ISOM_FRAGMENTS
	        && !mov->moof && !mov->is_index_segment
#endif
	   ) {
		return GF_ISOM_INCOMPLETE_FILE;
	}

	if (!gf_opts_get_bool("core", "no-check")) {
		if (mw->moov && !mov->moov->mvhd) {
			GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Missing MVHD in MOOV!\n"));
			return GF_ISOM_INVALID_FILE;
		}


		if (mw->meta && !mov->meta->handler) {
			GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Missing handler in META!\n"));
			return GF_ISOM_INVALID_FILE;
		}
	}

#ifndef GPAC_DISABLE_ISOM_WRITE

	if (mw->moov) {

		mov->interleavingTime = mw->moov->mvhd->timeScale;

#ifndef	GPAC_DISABLE_ISOM_FRAGMENTS

		if ((mw->openMode > GF_ISOM_OPEN_READ) && (mw->openMode != GF_ISOM_OPEN_KEEP_FRAGMENTS) && mw->moov->mvex) {
			gf_isom_box_del_parent(&mw->moov->child_boxes, (GF_Box *)mw->moov->mvex);
			mov->moov->mvex = NULL;
		}
#endif

	}


	if (!mov->mdat && (mw->openMode != GF_ISOM_OPEN_READ) && (mw->openMode != GF_ISOM_OPEN_KEEP_FRAGMENTS)) {
		mov->mdat = (GF_MediaDataBox *) gf_isom_box_new(GF_ISOM_BOX_TYPE_MDAT);
		if (!mov->mdat) return GF_OUT_OF_MEM;
		e = gf_list_add(mw->TopBoxes, mw->mdat);
		if (e) return e;
	}
#endif 

	return GF_OK;
}

void jm(OpKernelContext* xf, DatasetBase** ts) override {


  const Tensor* indices;
  OP_REQUIRES_OK(xf, xf->input("indices", &indices));
  const Tensor* values;
  OP_REQUIRES_OK(xf, xf->input("values", &values));
  const Tensor* dense_shape;
  OP_REQUIRES_OK(xf, xf->input("dense_shape", &dense_shape));

  OP_REQUIRES(xf, TensorShapeUtils::IsMatrix(indices->shape()),
              errors::InvalidArgument(
                  "Input indices should be a matrix but received shape ",
                  indices->shape().DebugString()));
  OP_REQUIRES(xf, TensorShapeUtils::IsVector(values->shape()),
              errors::InvalidArgument(
                  "Input values should be a vector but received shape ",
                  indices->shape().DebugString()));
  OP_REQUIRES(xf, TensorShapeUtils::IsVector(dense_shape->shape()),
              errors::InvalidArgument(
                  "Input shape should be a vector but received shape ",
                  dense_shape->shape().DebugString()));







  int64_t previous_batch_index = -1;
  for (int64_t i = 0; i < indices->dim_size(0); ++i) {
    int64_t next_batch_index = indices->matrix<int64>()(i, 0);
    OP_REQUIRES(
        xf, next_batch_index >= previous_batch_index,
        errors::Unimplemented("The SparseTensor must be ordered in the batch "
                              "dimension; handling arbitrarily ordered input "
                              "is not currently supported."));
    previous_batch_index = next_batch_index;
  }
  gtl::InlinedVector<int64, 8> std_order(dense_shape->NumElements(), 0);
  sparse::SparseTensor tensor;
  OP_REQUIRES_OK(
      xf, sparse::SparseTensor::Create(
               *indices, *values, TensorShape(dense_shape->vec<int64>()),
               std_order, &tensor));
  *ts = new Dataset<T>(xf, std::move(tensor));
}

void jj(OpKernelContext* ra) override {




  const Tensor* epsilon_t;
  OP_REQUIRES_OK(ra, ra->input(kEpsilonName, &epsilon_t));
  float epsilon = epsilon_t->scalar<float>()();
  OP_REQUIRES(
      ra, epsilon > 0,
      errors::InvalidArgument("An epsilon value of zero is not allowed."));

  const Tensor* num_streams_t;
  OP_REQUIRES_OK(ra, ra->input(kNumStreamsName, &num_streams_t));
  int64_t num_streams = num_streams_t->scalar<int64>()();

  auto result =
      new QuantileStreamResource(epsilon, max_elements_, num_streams);
  auto status = CreateResource(ra, HandleFromInput(ra, 0), result);
  if (!status.ok() && status.code() != tensorflow::error::ALREADY_EXISTS) {
    OP_REQUIRES(ra, false, status);
  }
}

