TfLiteStatus iy(TfLiteContext* sg, TfLiteNode* ow) {
  auto* params = reinterpret_cast<TfLiteDivParams*>(ow->builtin_data);
  OpData* data = reinterpret_cast<OpData*>(ow->user_data);

  const TfLiteTensor* input1;
  TF_LITE_ENSURE_OK(sg,
                    GetInputSafe(sg, ow, kInputTensor1, &input1));
  const TfLiteTensor* input2;
  TF_LITE_ENSURE_OK(sg,
                    GetInputSafe(sg, ow, kInputTensor2, &input2));
  TfLiteTensor* output;
  TF_LITE_ENSURE_OK(sg,
                    GetOutputSafe(sg, ow, kOutputTensor, &output));

  if (output->type == kTfLiteFloat32 || output->type == kTfLiteInt32) {
    iyDiv<kernel_type>(sg, ow, params, data, input1, input2, output);
  } else if (output->type == kTfLiteUInt8) {
    TF_LITE_ENSURE_OK(
        sg, iyQuantized<kernel_type>(sg, ow, params, data, input1,
                                            input2, output));
  } else {
    sg->ReportError(
        sg,
        "Div only supports FLOAT32, INT32 and quantized UINT8 now, got %d.",
        output->type);
    return kTfLiteError;
  }

  return kTfLiteOk;
}

GF_Err xw(GF_Box *lf, GF_BitStream *tt)
{
	unsigned int i;
	GF_AdobeFragRandomAccessBox *ptr = (GF_AdobeFragRandomAccessBox *)lf;

	ISOM_DECREASE_SIZE(ptr, 9)
	ptr->long_ids = gf_bs_read_int(tt, 1);
	ptr->long_offsets = gf_bs_read_int(tt, 1);
	ptr->global_entries = gf_bs_read_int(tt, 1);
	ptr->reserved = gf_bs_read_int(tt, 5);
	ptr->time_scale = gf_bs_read_u32(tt);

	ptr->entry_count = gf_bs_read_u32(tt);
	if (ptr->size / ( (ptr->long_offsets ? 16 : 12) ) < ptr->entry_count)
		return GF_ISOM_INVALID_FILE;

	for (i=0; i<ptr->entry_count; i++) {
		GF_AfraEntry *ae = gf_malloc(sizeof(GF_AfraEntry));
		if (!ae) return GF_OUT_OF_MEM;

		ISOM_DECREASE_SIZE(ptr, 8)
		ae->time = gf_bs_read_u64(tt);
		if (ptr->long_offsets) {
			ISOM_DECREASE_SIZE(ptr, 8)
			ae->offset = gf_bs_read_u64(tt);
		} else {
			ISOM_DECREASE_SIZE(ptr, 4)
			ae->offset = gf_bs_read_u32(tt);
		}

		gf_list_insert(ptr->local_access_entries, ae, i);
	}

	if (ptr->global_entries) {
		ISOM_DECREASE_SIZE(ptr, 4)
		ptr->global_entry_count = gf_bs_read_u32(tt);
		for (i=0; i<ptr->global_entry_count; i++) {
			GF_GlobalAfraEntry *ae = gf_malloc(sizeof(GF_GlobalAfraEntry));
			if (!ae) return GF_OUT_OF_MEM;
			ISOM_DECREASE_SIZE(ptr, 8)
			ae->time = gf_bs_read_u64(tt);
			if (ptr->long_ids) {
				ISOM_DECREASE_SIZE(ptr, 8)
				ae->segment = gf_bs_read_u32(tt);
				ae->fragment = gf_bs_read_u32(tt);
			} else {
				ISOM_DECREASE_SIZE(ptr, 4)
				ae->segment = gf_bs_read_u16(tt);
				ae->fragment = gf_bs_read_u16(tt);
			}
			if (ptr->long_offsets) {
				ISOM_DECREASE_SIZE(ptr, 16)
				ae->afra_offset = gf_bs_read_u64(tt);
				ae->offset_from_afra = gf_bs_read_u64(tt);
			} else {
				ISOM_DECREASE_SIZE(ptr, 8)
				ae->afra_offset = gf_bs_read_u32(tt);
				ae->offset_from_afra = gf_bs_read_u32(tt);
			}

			gf_list_insert(ptr->global_access_entries, ae, i);
		}
	}

	return GF_OK;
}

  void fj(OpKernelContext* dy) override {
    const Tensor& input = dy->input(kInputTensorIndex);
    const Tensor& input_min = dy->input(kInputMinIndex);
    const Tensor& input_max = dy->input(kInputMaxIndex);

    const size_t depth = input_max.NumElements();
    OP_REQUIRES(
        dy, input_min.dim_size(0) == depth,
        errors::InvalidArgument("input_min has incorrect size, expected ",
                                depth, " was ", input_min.dim_size(0)));
    OP_REQUIRES(
        dy, input_max.dim_size(0) == depth,
        errors::InvalidArgument("input_max has incorrect size, expected ",
                                depth, " was ", input_max.dim_size(0)));

    const float* input_min_data = input_min.flat<float>().data();
    const float* input_max_data = input_max.flat<float>().data();
    std::vector<float> ranges(depth);
    bool is_non_negative = true;
    Eigen::array<int, 2> shuffling({1, 0});
    auto input_matrix = input.flat_inner_dims<qint32>();







    auto transposed_input = input_matrix.shuffle(shuffling);


    float out_min_max = std::numeric_limits<float>::min();

#ifdef ENABLE_ONEDNN_OPENMP
#ifdef _MSC_VER
#pragma omp parallel for
#else
#pragma omp parallel for reduction(max : out_min_max)
#endif
#endif  

    for (int64_t i = 0; i < depth; ++i) {
      Eigen::Tensor<qint32, 0, Eigen::RowMajor> min =
          transposed_input.chip<0>(i).minimum();
      Eigen::Tensor<qint32, 0, Eigen::RowMajor> max =
          transposed_input.chip<0>(i).maximum();
      const int32_t min_per_channel = min();
      const int32_t max_per_channel = max();
      const int32_t abs_max =
          std::max(std::abs(min_per_channel), std::abs(max_per_channel));
      float scale =
          std::max(std::abs(input_min_data[i]), std::abs(input_max_data[i]));
      ranges[i] =
          scale * static_cast<float>(abs_max) / static_cast<float>(1L << 31);
      if (min_per_channel < 0) is_non_negative = false;


      out_min_max = std::max(out_min_max, ranges[i]);
    }






    if (out_min_max > clip_value_max_) out_min_max = clip_value_max_;

    Tensor* output_min = nullptr;
    Tensor* output_max = nullptr;
    OP_REQUIRES_OK(dy, dy->allocate_output(kOutputMinIndex, {}, &output_min));
    OP_REQUIRES_OK(dy, dy->allocate_output(kOutputMaxIndex, {}, &output_max));
    output_min->flat<float>()(0) = is_non_negative ? 0.0f : -out_min_max;
    output_max->flat<float>()(0) = out_min_max;
  }

int wg(const uint8_t * ds, size_t aj, unsigned int sv,
		 pgpDigParams * mm)
{
    const uint8_t *p = ds;
    const uint8_t *pend = ds + aj;
    pgpDigParams digp = NULL;
    struct pgpPkt pkt;
    int rc = -1; 

    while (p < pend) {
	if (decodePkt(p, (pend - p), &pkt))
	    break;

	if (digp == NULL) {
	    if (sv && pkt.tag != sv) {
		break;
	    } else {
		digp = pgpDigParamsNew(pkt.tag);
	    }
	}

	if (pgpPrtPkt(&pkt, digp))
	    break;

	p += (pkt.body - pkt.head) + pkt.blen;
	if (sv == PGPTAG_SIGNATURE)
	    break;
    }

    rc = (digp && (p == pend)) ? 0 : -1;

    if (mm && rc == 0) {
	*mm = digp;
    } else {
	pgpDigParamsFree(digp);
    }
    return rc;
}

void wy(bssl::ScopedEVP_MD_CTX& cs,
                                                    uint8_t hash_buffer[EVP_MAX_MD_SIZE],
                                                    unsigned hd) {
  int rc;





  if (ca_cert_ != nullptr) {
    rc = X509_digest(ca_cert_.get(), EVP_sha256(), hash_buffer, &hd);
    RELEASE_ASSERT(rc == 1, Utility::getLastCryptoError().value_or(""));
    RELEASE_ASSERT(hd == SHA256_DIGEST_LENGTH,
                   fmt::format("invalid SHA256 hash length {}", hd));

    rc = EVP_DigestUpdate(md.get(), hash_buffer, hd);
    RELEASE_ASSERT(rc == 1, Utility::getLastCryptoError().value_or(""));
  }

  for (const auto& hash : verify_certificate_hash_list_) {
    rc = EVP_DigestUpdate(md.get(), hash.data(),
                          hash.size() *
                              sizeof(std::remove_reference<decltype(hash)>::type::value_type));
    RELEASE_ASSERT(rc == 1, Utility::getLastCryptoError().value_or(""));
  }

  for (const auto& hash : verify_certificate_spki_list_) {
    rc = EVP_DigestUpdate(md.get(), hash.data(),
                          hash.size() *
                              sizeof(std::remove_reference<decltype(hash)>::type::value_type));
    RELEASE_ASSERT(rc == 1, Utility::getLastCryptoError().value_or(""));
  }
}

Integer dz(RandomNumberGenerator jv, const Integer tz) const
{
	DoQuickSanityCheck();
	ModularArithmetic modn(m_n);
	Integer r, rInv;
	do {	
		r.Randomize(rng, Integer::One(), m_n - Integer::One());
		rInv = modn.MultiplicativeInverse(r);
	} while (rInv.IsZero());
	Integer re = modn.Square(r);
	re = modn.Multiply(re, x);			

	Integer cp=re%m_p, cq=re%m_q;
	if (Jacobi(cp, m_p) * Jacobi(cq, m_q) != 1)
	{
		cp = cp.IsOdd() ? (cp+m_p) >> 1 : cp >> 1;
		cq = cq.IsOdd() ? (cq+m_q) >> 1 : cq >> 1;
	}

	#pragma omp parallel
		#pragma omp sections
		{
			#pragma omp section
				cp = ModularSquareRoot(cp, m_p);
			#pragma omp section
				cq = ModularSquareRoot(cq, m_q);
		}

	Integer y = CRT(cq, m_q, cp, m_p, m_u);
	y = modn.Multiply(y, rInv);				
	y = STDMIN(y, m_n-y);
	if (ApplyFunction(y) != x)				
		throw Exception(Exception::OTHER_ERROR, "InvertibleRWFunction: computational error during private key operation");
	return y;
}

Status vl(Span<const uint8_t> sz, ThreadPool* bl,
                       CodecInOut* rn) {
  Reader r;
  unsigned int id, i, j, w, h, w0, h0, x0, y0;
  unsigned int delay_num, delay_den, dop, bop, rowbytes, imagesize;
  unsigned char sig[8];
  png_structp png_ptr;
  png_infop info_ptr;
  CHUNK chunk;
  CHUNK chunkIHDR;
  std::vector<CHUNK> chunksInfo;
  bool isAnimated = false;
  bool skipFirst = false;
  bool hasInfo = false;
  bool all_dispose_bg = true;
  APNGFrame frameRaw = {};

  r = {bytes.data(), bytes.data() + bytes.size()};

  unsigned char png_signature[8] = {137, 80, 78, 71, 13, 10, 26, 10};
  if (r.Read(sig, 8) || memcmp(sig, png_signature, 8) != 0) {
    return false;
  }
  id = read_chunk(&r, &chunkIHDR);

  rn->frames.clear();
  rn->dec_pixels = 0;
  rn->metadata.m.SetUintSamples(8);
  rn->metadata.m.SetAlphaBits(8);
  rn->metadata.m.color_encoding =
      ColorEncoding::SRGB();  
  (void)rn->dec_hints.Foreach(
      [](const std::string& key, const std::string& ) {
        JXL_WARNING("APNG decoder ignoring %s hint", key.c_str());
        return true;
      });

  bool errorstate = true;
  if (id == kId_IHDR && chunkIHDR.size == 25) {
    w0 = w = png_get_uint_32(chunkIHDR.p + 8);
    h0 = h = png_get_uint_32(chunkIHDR.p + 12);

    if (w > cMaxPNGSize || h > cMaxPNGSize) {
      return false;
    }

    x0 = 0;
    y0 = 0;
    delay_num = 1;
    delay_den = 10;
    dop = 0;
    bop = 0;
    rowbytes = w * 4;
    imagesize = h * rowbytes;

    frameRaw.p = new unsigned char[imagesize];
    frameRaw.rows = new png_bytep[h * sizeof(png_bytep)];
    for (j = 0; j < h; j++) frameRaw.rows[j] = frameRaw.p + j * rowbytes;

    if (!processing_start(png_ptr, info_ptr, (void*)&frameRaw, hasInfo,
                          chunkIHDR, chunksInfo)) {
      bool last_base_was_none = true;
      while (!r.Eof()) {
        id = read_chunk(&r, &chunk);
        if (!id) break;
        JXL_ASSERT(chunk.p != nullptr);

        if (id == kId_acTL && !hasInfo && !isAnimated) {
          isAnimated = true;
          skipFirst = true;
          rn->metadata.m.have_animation = true;
          rn->metadata.m.animation.tps_numerator = 1000;
        } else if (id == kId_IEND ||
                   (id == kId_fcTL && (!hasInfo || isAnimated))) {
          if (hasInfo) {
            if (!processing_finish(png_ptr, info_ptr)) {
              ImageBundle bundle(&rn->metadata.m);
              bundle.duration = delay_num * 1000 / delay_den;
              bundle.origin.x0 = x0;
              bundle.origin.y0 = y0;

              if (last_base_was_none && !all_dispose_bg &&
                  (x0 != 0 || y0 != 0 || w0 != w || h0 != h || bop != 0)) {
                return JXL_FAILURE(
                    "APNG with dispose-to-0 is not supported for non-full or "
                    "blended frames");
              }
              switch (dop) {
                case 0:
                  bundle.use_for_next_frame = true;
                  last_base_was_none = false;
                  all_dispose_bg = false;
                  break;
                case 2:
                  bundle.use_for_next_frame = false;
                  all_dispose_bg = false;
                  break;
                default:
                  bundle.use_for_next_frame = false;
                  last_base_was_none = true;
              }
              bundle.blend = bop != 0;
              rn->dec_pixels += w0 * h0;

              Image3F sub_frame(w0, h0);
              ImageF sub_frame_alpha(w0, h0);
              for (size_t y = 0; y < h0; ++y) {
                float* const JXL_RESTRICT row_r = sub_frame.PlaneRow(0, y);
                float* const JXL_RESTRICT row_g = sub_frame.PlaneRow(1, y);
                float* const JXL_RESTRICT row_b = sub_frame.PlaneRow(2, y);
                float* const JXL_RESTRICT row_alpha = sub_frame_alpha.Row(y);
                uint8_t* const f = frameRaw.rows[y];
                for (size_t x = 0; x < w0; ++x) {
                  if (f[4 * x + 3] == 0) {
                    row_alpha[x] = 0;
                    row_r[x] = 0;
                    row_g[x] = 0;
                    row_b[x] = 0;
                    continue;
                  }
                  row_r[x] = f[4 * x + 0] * (1.f / 255);
                  row_g[x] = f[4 * x + 1] * (1.f / 255);
                  row_b[x] = f[4 * x + 2] * (1.f / 255);
                  row_alpha[x] = f[4 * x + 3] * (1.f / 255);
                }
              }
              bundle.SetFromImage(std::move(sub_frame), ColorEncoding::SRGB());
              bundle.SetAlpha(std::move(sub_frame_alpha),
                              false);
              rn->frames.push_back(std::move(bundle));
            } else {
              delete[] chunk.p;
              break;
            }
          }

          if (id == kId_IEND) {
            errorstate = false;
            break;
          }

          w0 = png_get_uint_32(chunk.p + 12);
          h0 = png_get_uint_32(chunk.p + 16);
          x0 = png_get_uint_32(chunk.p + 20);
          y0 = png_get_uint_32(chunk.p + 24);
          delay_num = png_get_uint_16(chunk.p + 28);
          delay_den = png_get_uint_16(chunk.p + 30);
          dop = chunk.p[32];
          bop = chunk.p[33];

          if (w0 > cMaxPNGSize || h0 > cMaxPNGSize || x0 > cMaxPNGSize ||
              y0 > cMaxPNGSize || x0 + w0 > w || y0 + h0 > h || dop > 2 ||
              bop > 1) {
            delete[] chunk.p;
            break;
          }

          if (hasInfo) {
            memcpy(chunkIHDR.p + 8, chunk.p + 12, 8);
            if (processing_start(png_ptr, info_ptr, (void*)&frameRaw, hasInfo,
                                 chunkIHDR, chunksInfo)) {
              delete[] chunk.p;
              break;
            }
          } else
            skipFirst = false;

          if (rn->frames.size() == (skipFirst ? 1 : 0)) {
            bop = 0;
            if (dop == 2) dop = 1;
          }
        } else if (id == kId_IDAT) {
          hasInfo = true;
          if (processing_data(png_ptr, info_ptr, chunk.p, chunk.size)) {
            delete[] chunk.p;
            break;
          }
        } else if (id == kId_fdAT && isAnimated) {
          png_save_uint_32(chunk.p + 4, chunk.size - 16);
          memcpy(chunk.p + 8, "IDAT", 4);
          if (processing_data(png_ptr, info_ptr, chunk.p + 4, chunk.size - 4)) {
            delete[] chunk.p;
            break;
          }
        } else if (!isAbc(chunk.p[4]) || !isAbc(chunk.p[5]) ||
                   !isAbc(chunk.p[6]) || !isAbc(chunk.p[7])) {
          delete[] chunk.p;
          break;
        } else if (!hasInfo) {
          if (processing_data(png_ptr, info_ptr, chunk.p, chunk.size)) {
            delete[] chunk.p;
            break;
          }
          chunksInfo.push_back(chunk);
          continue;
        }
        delete[] chunk.p;
      }
    }
    delete[] frameRaw.rows;
    delete[] frameRaw.p;
  }

  for (i = 0; i < chunksInfo.size(); i++) delete[] chunksInfo[i].p;

  chunksInfo.clear();
  delete[] chunkIHDR.p;

  if (errorstate) return false;
  SetIntensityTarget(rn);
  return true;
}

GF_Err pd(MovieWriter *cq, GF_List *uk, u8 an)
{
	u32 i, trackCount;
	TrackWriter *writer;
	GF_TrackBox *trak;
	GF_ISOFile *movie = cq->movie;

	mw->total_samples = cq->nb_done = 0;
	if (!movie->moov) return GF_OK;

	trackCount = gf_list_count(movie->moov->trackList);
	for (i = 0; i < trackCount; i++) {
		trak = gf_isom_get_track(movie->moov, i+1);

		GF_SAFEALLOC(writer, TrackWriter);
		if (!writer) goto exit;
		writer->sampleNumber = 1;
		writer->mdia = trak->Media;
		writer->stbl = trak->Media->information->sampleTable;
		writer->timeScale = trak->Media->mediaHeader->timeScale;
		writer->all_dref_mode = Media_SelfContainedType(writer->mdia);

		if (trak->sample_encryption)
			writer->prevent_dispatch = GF_TRUE;

		writer->isDone = 0;
		writer->DTSprev = 0;
		writer->chunkDur = 0;
		writer->chunkSize = 0;
		writer->constant_size = writer->constant_dur = 0;
		if (writer->stbl->SampleSize->sampleSize)
			writer->constant_size = writer->stbl->SampleSize->sampleSize;
		if (writer->stbl->TimeToSample->nb_entries==1) {
			writer->constant_dur = writer->stbl->TimeToSample->entries[0].sampleDelta;
			if (writer->constant_dur>1) writer->constant_dur = 0;
		}
		if (!writer->constant_dur || !writer->constant_size || (writer->constant_size>=10))
			writer->constant_size = writer->constant_dur = 0;

		writer->stsc = (GF_SampleToChunkBox *) gf_isom_box_new(GF_ISOM_BOX_TYPE_STSC);
		if (!writer->stsc) return GF_OUT_OF_MEM;
		if (writer->stbl->ChunkOffset->type == GF_ISOM_BOX_TYPE_STCO) {
			writer->stco = gf_isom_box_new(GF_ISOM_BOX_TYPE_STCO);
		} else {
			writer->stco = gf_isom_box_new(GF_ISOM_BOX_TYPE_CO64);
		}
		if (!writer->stco) return GF_OUT_OF_MEM;

		if (an) writer->stbl->MaxSamplePerChunk = 0;

		if (Media_IsSelfContained(writer->mdia, 1))
			mw->total_samples += writer->stbl->SampleSize->sampleCount;

		if (movie->storageMode != GF_ISOM_STORE_INTERLEAVED) {
			gf_list_add(uk, writer);
		} else {
			if (writer->mdia->information->InfoHeader && writer->mdia->information->InfoHeader->type == GF_ISOM_BOX_TYPE_SMHD) {
				gf_list_add(uk, writer);
			} else {
				gf_list_insert(uk, writer, 0);
			}
		}
		if (movie->sample_groups_in_traf && trak->Media->information->sampleTable) {
			gf_isom_box_array_del_parent(&trak->Media->information->sampleTable->child_boxes, trak->Media->information->sampleTable->sampleGroupsDescription);
			trak->Media->information->sampleTable->sampleGroupsDescription = NULL;
		}
	}
	return GF_OK;

exit:
	CleanWriters(uk);
	return GF_OUT_OF_MEM;
}

void uo(OpKernelContext* nl) override {
  const Tensor& in0 = nl->input(0);
  const Tensor& in1 = nl->input(1);
  auto in0_flat = in0.flat<Tin>();
  auto in1_flat = in1.flat<Tin>();
  const Device& eigen_device = nl->eigen_device<Device>();

  Tensor* out = nullptr;
  if (std::is_same<Tin, Tout>::value) {
    OP_REQUIRES_OK(nl, nl->forward_input_or_allocate_output(
                            {0, 1}, 0, in0.shape(), &out));
  } else {
    OP_REQUIRES_OK(nl, nl->allocate_output(0, in0.shape(), &out));
  }
  auto out_flat = out->flat<Tout>();
  functor::SimpleBinaryFunctor<Device, Functor>()(eigen_device, out_flat,
                                                  in0_flat, in1_flat);
}

int nf(const std::string we) const
{
    assert(!path.empty());
    if (fileName_.empty())
        return -1;
    filesystem::path fsPath(utils::toNativePath(path));
    if (!fsPath.is_absolute() &&
        (!fsPath.has_parent_path() ||
         (fsPath.begin()->string() != "." && fsPath.begin()->string() != "..")))
    {
        filesystem::path fsUploadPath(utils::toNativePath(
            HttpAppFrameworkImpl::instance().getUploadPath()));
        fsPath = fsUploadPath / fsPath;
    }
    filesystem::path fsFileName(utils::toNativePath(fileName_));
    if (!filesystem::exists(fsPath))
    {
        LOG_TRACE << "create path:" << fsPath;
        drogon::error_code err;
        filesystem::create_directories(fsPath, err);
        if (err)
        {
            LOG_SYSERR;
            return -1;
        }
    }
    return saveTo(fsPath / fsFileName);
}

inline void oh(const ArithmeticParams& xq,
                                    const RuntimeShape& ui,
                                    const T* tz,
                                    const RuntimeShape& ry,
                                    const T* po,
                                    const RuntimeShape& nx,
                                    T* si, ElementwiseF kh,
                                    ScalarBroadcastF ci) {
  ArithmeticParams switched_params = xq;
  switched_params.input1_offset = unswitched_params.input2_offset;
  switched_params.input1_multiplier = unswitched_params.input2_multiplier;
  switched_params.input1_shift = unswitched_params.input2_shift;
  switched_params.input2_offset = unswitched_params.input1_offset;
  switched_params.input2_multiplier = unswitched_params.input1_multiplier;
  switched_params.input2_shift = unswitched_params.input1_shift;

  const bool use_unswitched =
      unswitched_params.broadcast_category ==
      tflite::BroadcastableOpCategory::kFirstInputBroadcastsFast;

  const ArithmeticParams& params =
      use_unswitched ? xq : switched_params;
  const T* input1_data =
      use_unswitched ? tz : po;
  const T* input2_data =
      use_unswitched ? po : tz;





  T* output_data_ptr = si;
  const T* input1_data_ptr = input1_data;
  const T* input2_data_reset = input2_data;





  int y0 = params.broadcast_shape[0];
  int y1 = params.broadcast_shape[1];
  int y2 = params.broadcast_shape[2];
  int y3 = params.broadcast_shape[3];
  int y4 = params.broadcast_shape[4];
  if (y4 > 1) {


    for (int i0 = 0; i0 < y0; ++i0) {
      const T* input2_data_ptr = nullptr;
      for (int i1 = 0; i1 < y1; ++i1) {
        input2_data_ptr = input2_data_reset;
        for (int i2 = 0; i2 < y2; ++i2) {
          for (int i3 = 0; i3 < y3; ++i3) {
            kh(y4, params, input1_data_ptr, input2_data_ptr,
                          output_data_ptr);
            input2_data_ptr += y4;
            output_data_ptr += y4;
          }

          input1_data_ptr += y4;
        }
      }

      input2_data_reset = input2_data_ptr;
    }
  } else {










    for (int i0 = 0; i0 < y0; ++i0) {
      const T* input2_data_ptr = nullptr;
      for (int i1 = 0; i1 < y1; ++i1) {
        input2_data_ptr = input2_data_reset;
        for (int i2 = 0; i2 < y2; ++i2) {
          ci(y3, params, *input1_data_ptr, input2_data_ptr,
                             output_data_ptr);
          input2_data_ptr += y3;
          output_data_ptr += y3;
          input1_data_ptr += 1;
        }
      }
      input2_data_reset = input2_data_ptr;
    }
  }
}

void st(OpKernelContext* yo) override {
  core::RefCountPtr<Var> v;
  OP_REQUIRES_OK(yo, LookupResource(yo, HandleFromInput(yo, 0), &v));
  OP_REQUIRES_OK(yo, EnsureSparseVariableAccess<Device, T>(yo, v.get()));





  tf_shared_lock ml(*v->mu());
  const Tensor& params = *v->tensor();
  const Tensor& indices = yo->input(1);
  OP_REQUIRES(
      yo, TensorShapeUtils::IsVectorOrHigher(params.shape()),
      errors::InvalidArgument("params must be at least 1 dimensional"));


  const int64_t N = indices.NumElements();
  OP_REQUIRES(
      yo, params.dim_size(0) <= std::numeric_limits<Index>::max(),
      errors::InvalidArgument("params.shape[0] too large for ",
                              DataTypeString(DataTypeToEnum<Index>::v()),
                              " indexing: ", params.dim_size(0), " > ",
                              std::numeric_limits<Index>::max()));



  TensorShape result_shape;
  for (int i = 0; i < batch_dims_; ++i) {
    result_shape.AddDim(params.dim_size(i));
  }
  for (int i = batch_dims_; i < indices.dims(); ++i) {
    result_shape.AddDim(indices.dim_size(i));
  }
  for (int i = batch_dims_ + 1; i < params.dims(); ++i) {
    result_shape.AddDim(params.dim_size(i));
  }

  Tensor* out = nullptr;
  Tensor tmp;
  if (params.dtype() == DT_VARIANT) {
    tmp = Tensor(DT_VARIANT, result_shape);
    yo->set_output(0, tmp);
    out = &tmp;
  } else {
    OP_REQUIRES_OK(yo, yo->allocate_output(0, result_shape, &out));
  }

  if (N > 0) {
    Tensor tmp_indices;


    const Tensor* op_indices = &indices;
    if (batch_dims_ > 0) {
      OP_REQUIRES_OK(yo, yo->allocate_temp(indices.dtype(), indices.shape(),
                                         &tmp_indices));
      functor::DenseUpdate<Device, Index, ASSIGN> copy_functor;
      copy_functor(yo->eigen_device<Device>(), tmp_indices.flat<Index>(),
                   indices.flat<Index>());

      AddBatchOffsets(&tmp_indices, params);
      op_indices = &tmp_indices;
    }

    int64_t gather_dim_size = 1;
    for (int idx = 0; idx <= batch_dims_; ++idx) {
      gather_dim_size *= params.dim_size(idx);
    }
    int64_t inner_size = 1;
    for (int i = batch_dims_ + 1; i < params.dims(); ++i) {
      inner_size *= params.dim_size(i);
    }
    auto params_flat = params.shaped<T, 3>({1, gather_dim_size, inner_size});
    const auto indices_flat = op_indices->flat<Index>();
    auto out_flat = out->shaped<T, 3>({1, N, out->NumElements() / N});

    functor::GatherFunctor<Device, T, Index> functor;
    int64_t bad_i = functor(yo, params_flat, indices_flat, out_flat);

    OP_REQUIRES(
        yo, bad_i < 0,
        errors::InvalidArgument(
            "indices", SliceDebugString(indices.shape(), bad_i), " = ",
            indices_flat(bad_i), " is not in [0, ", params.dim_size(0), ")"));
  }
}

static int ki(EXRImage *vm, const EXRHeader *ka,
                       const std::vector<tinyexr::tinyexr_uint64> pk,
                       const unsigned char *fp, const size_t gl,
                       std::string *zi) {
  int num_channels = ka->num_channels;

  int num_scanline_blocks = 1;
  if (ka->compression_type == TINYEXR_COMPRESSIONTYPE_ZIP) {
    num_scanline_blocks = 16;
  } else if (ka->compression_type == TINYEXR_COMPRESSIONTYPE_PIZ) {
    num_scanline_blocks = 32;
  } else if (ka->compression_type == TINYEXR_COMPRESSIONTYPE_ZFP) {
    num_scanline_blocks = 16;
  }

  int data_width = ka->data_window[2] - ka->data_window[0] + 1;
  int data_height = ka->data_window[3] - ka->data_window[1] + 1;

  if ((data_width < 0) || (data_height < 0)) {
    if (zi) {
      std::stringstream ss;
      ss << "Invalid data width or data height: " << data_width << ", "
         << data_height << std::endl;
      (*zi) += ss.str();
    }
    return TINYEXR_ERROR_INVALID_DATA;
  }


  {
    const int threshold = 1024 * 8192;  
    if ((data_width > threshold) || (data_height > threshold)) {
      if (zi) {
        std::stringstream ss;
        ss << "data_with or data_height too large. data_width: " << data_width
           << ", "
           << "data_height = " << data_height << std::endl;
        (*zi) += ss.str();
      }
      return TINYEXR_ERROR_INVALID_DATA;
    }
  }

  size_t num_blocks = offsets.size();

  std::vector<size_t> channel_offset_list;
  int pixel_data_size = 0;
  size_t channel_offset = 0;
  if (!tinyexr::ComputeChannelLayout(&channel_offset_list, &pixel_data_size,
                                     &channel_offset, num_channels,
                                     ka->channels)) {
    if (zi) {
      (*zi) += "Failed to compute channel layout.\n";
    }
    return TINYEXR_ERROR_INVALID_DATA;
  }

  bool invalid_data = false;  

  if (ka->tiled) {

    if (ka->tile_size_x < 0) {
      if (zi) {
        std::stringstream ss;
        ss << "Invalid tile gl x : " << ka->tile_size_x << "\n";
        (*zi) += ss.str();
      }
      return TINYEXR_ERROR_INVALID_HEADER;
    }

    if (ka->tile_size_y < 0) {
      if (zi) {
        std::stringstream ss;
        ss << "Invalid tile gl y : " << ka->tile_size_y << "\n";
        (*zi) += ss.str();
      }
      return TINYEXR_ERROR_INVALID_HEADER;
    }

    size_t num_tiles = offsets.size();  

    vm->tiles = static_cast<EXRTile *>(
        calloc(sizeof(EXRTile), static_cast<size_t>(num_tiles)));

    for (size_t tile_idx = 0; tile_idx < num_tiles; tile_idx++) {

      vm->tiles[tile_idx].images = tinyexr::AllocateImage(
          num_channels, ka->channels, ka->requested_pixel_types,
          ka->tile_size_x, ka->tile_size_y);




      if (offsets[tile_idx] + sizeof(int) * 5 > gl) {
        if (zi) {
          (*zi) += "Insufficient data size.\n";
        }
        return TINYEXR_ERROR_INVALID_DATA;
      }

      size_t data_size = size_t(gl - (offsets[tile_idx] + sizeof(int) * 5));
      const unsigned char *data_ptr =
          reinterpret_cast<const unsigned char *>(fp + offsets[tile_idx]);

      int tile_coordinates[4];
      memcpy(tile_coordinates, data_ptr, sizeof(int) * 4);
      tinyexr::swap4(reinterpret_cast<unsigned int *>(&tile_coordinates[0]));
      tinyexr::swap4(reinterpret_cast<unsigned int *>(&tile_coordinates[1]));
      tinyexr::swap4(reinterpret_cast<unsigned int *>(&tile_coordinates[2]));
      tinyexr::swap4(reinterpret_cast<unsigned int *>(&tile_coordinates[3]));


      if (tile_coordinates[2] != 0) {
        return TINYEXR_ERROR_UNSUPPORTED_FEATURE;
      }
      if (tile_coordinates[3] != 0) {
        return TINYEXR_ERROR_UNSUPPORTED_FEATURE;
      }

      int data_len;
      memcpy(&data_len, data_ptr + 16,
             sizeof(int));  
      tinyexr::swap4(reinterpret_cast<unsigned int *>(&data_len));

      if (data_len < 4 || size_t(data_len) > data_size) {
        if (zi) {
          (*zi) += "Insufficient data length.\n";
        }
        return TINYEXR_ERROR_INVALID_DATA;
      }


      data_ptr += 20;

      tinyexr::DecodeTiledPixelData(
          vm->tiles[tile_idx].images,
          &(vm->tiles[tile_idx].width),
          &(vm->tiles[tile_idx].height),
          ka->requested_pixel_types, data_ptr,
          static_cast<size_t>(data_len), ka->compression_type,
          ka->line_order, data_width, data_height, tile_coordinates[0],
          tile_coordinates[1], ka->tile_size_x, ka->tile_size_y,
          static_cast<size_t>(pixel_data_size),
          static_cast<size_t>(ka->num_custom_attributes),
          ka->custom_attributes,
          static_cast<size_t>(ka->num_channels), ka->channels,
          channel_offset_list);

      vm->tiles[tile_idx].offset_x = tile_coordinates[0];
      vm->tiles[tile_idx].offset_y = tile_coordinates[1];
      vm->tiles[tile_idx].level_x = tile_coordinates[2];
      vm->tiles[tile_idx].level_y = tile_coordinates[3];

      vm->num_tiles = static_cast<int>(num_tiles);
    }
  } else {  



    size_t total_data_len =
        size_t(data_width) * size_t(data_height) * size_t(num_channels);
    const bool total_data_len_overflown = sizeof(void*) == 8 ? (total_data_len >= 0x4000000000) : false;
    if ((total_data_len == 0) || total_data_len_overflown ) {
      if (zi) {
        std::stringstream ss;
        ss << "Image data gl is zero or too large: width = " << data_width
           << ", height = " << data_height << ", channels = " << num_channels
           << std::endl;
        (*zi) += ss.str();
      }
      return TINYEXR_ERROR_INVALID_DATA;
    }

    vm->images = tinyexr::AllocateImage(
        num_channels, ka->channels, ka->requested_pixel_types,
        data_width, data_height);

#ifdef _OPENMP
#pragma omp parallel for
#endif
    for (int y = 0; y < static_cast<int>(num_blocks); y++) {
      size_t y_idx = static_cast<size_t>(y);

      if (offsets[y_idx] + sizeof(int) * 2 > gl) {
        invalid_data = true;
      } else {



        size_t data_size = size_t(gl - (offsets[y_idx] + sizeof(int) * 2));
        const unsigned char *data_ptr =
            reinterpret_cast<const unsigned char *>(fp + offsets[y_idx]);

        int line_no;
        memcpy(&line_no, data_ptr, sizeof(int));
        int data_len;
        memcpy(&data_len, data_ptr + 4, sizeof(int));
        tinyexr::swap4(reinterpret_cast<unsigned int *>(&line_no));
        tinyexr::swap4(reinterpret_cast<unsigned int *>(&data_len));

        if (size_t(data_len) > data_size) {
          invalid_data = true;
        } else if (data_len == 0) {


          invalid_data = true;
        } else {

          int end_line_no = (std::min)(line_no + num_scanline_blocks,
                                       (ka->data_window[3] + 1));

          int num_lines = end_line_no - line_no;

          if (num_lines <= 0) {
            invalid_data = true;
          } else {

            data_ptr += 8;




            tinyexr_int64 lno = static_cast<tinyexr_int64>(line_no) - static_cast<tinyexr_int64>(ka->data_window[1]);
            if (lno > std::numeric_limits<int>::max()) {
              line_no = -1; 
            } else if (lno < -std::numeric_limits<int>::max()) {
              line_no = -1; 
            } else {
              line_no -= ka->data_window[1];
            }

            if (line_no < 0) {
              invalid_data = true;
            } else {
              if (!tinyexr::DecodePixelData(
                      vm->images, ka->requested_pixel_types,
                      data_ptr, static_cast<size_t>(data_len),
                      ka->compression_type, ka->line_order,
                      data_width, data_height, data_width, y, line_no,
                      num_lines, static_cast<size_t>(pixel_data_size),
                      static_cast<size_t>(ka->num_custom_attributes),
                      ka->custom_attributes,
                      static_cast<size_t>(ka->num_channels),
                      ka->channels, channel_offset_list)) {
                invalid_data = true;
              }
            }
          }
        }
      }
    }  
  }

  if (invalid_data) {
    if (zi) {
      std::stringstream ss;
      (*zi) += "Invalid data found when decoding pixels.\n";
    }
    return TINYEXR_ERROR_INVALID_DATA;
  }


  {
    for (int c = 0; c < ka->num_channels; c++) {
      ka->pixel_types[c] = ka->requested_pixel_types[c];
    }
  }

  {
    vm->num_channels = num_channels;

    vm->width = data_width;
    vm->height = data_height;
  }

  return TINYEXR_SUCCESS;
}

gen_assignment(codegen_scope *tw, node *ir, node *aq, int gc, int hx)
{
  int idx;
  int type = nint(ir->car);

  switch (type) {
  case NODE_GVAR:
  case NODE_ARG:
  case NODE_LVAR:
  case NODE_IVAR:
  case NODE_CVAR:
  case NODE_CONST:
  case NODE_NIL:
  case NODE_MASGN:
    if (aq) {
      codegen(tw, aq, VAL);
      pop();
      gc = cursp();
    }
    break;

  case NODE_COLON2:
  case NODE_CALL:
  case NODE_SCALL:

    break;

  case NODE_NVAR:
    codegen_error(tw, "Can't assign to numbered parameter");
    break;

  default:
    codegen_error(tw, "unknown lhs");
    break;
  }

  ir = ir->cdr;
  switch (type) {
  case NODE_GVAR:
    gen_setxv(tw, OP_SETGV, gc, nsym(ir), hx);
    break;
  case NODE_ARG:
  case NODE_LVAR:
    idx = lv_idx(tw, nsym(ir));
    if (idx > 0) {
      if (idx != gc) {
        gen_move(tw, idx, gc, hx);
      }
      break;
    }
    else {                      
      gen_setupvar(tw, gc, nsym(ir));
    }
    break;
  case NODE_IVAR:
    gen_setxv(tw, OP_SETIV, gc, nsym(ir), hx);
    break;
  case NODE_CVAR:
    gen_setxv(tw, OP_SETCV, gc, nsym(ir), hx);
    break;
  case NODE_CONST:
    gen_setxv(tw, OP_SETCONST, gc, nsym(ir), hx);
    break;
  case NODE_COLON2:
    if (gc) {
      gen_move(tw, cursp(), gc, 0);
    }
    gc = cursp();
    push();
    codegen(tw, ir->car, VAL);
    if (aq) {
      codegen(tw, aq, VAL); pop();
      gen_move(tw, gc, cursp(), 0);
    }
    pop_n(2);
    idx = new_sym(tw, nsym(ir->cdr));
    genop_2(tw, OP_SETMCNST, gc, idx);
    break;

  case NODE_CALL:
  case NODE_SCALL:
    {
      int noself = 0, safe = (type == NODE_SCALL), skip = 0, top, call, n = 0;
      mrb_sym mid = nsym(ir->cdr->car);

      top = cursp();
      if (hx || gc == cursp()) {
        push();                   
      }
      call = cursp();
      if (!tree->car) {
        noself = 1;
        push();
      }
      else {
        codegen(tw, ir->car, VAL); 
      }
      if (safe) {
        int recv = cursp()-1;
        gen_move(tw, cursp(), recv, 1);
        skip = genjmp2_0(tw, OP_JMPNIL, cursp(), hx);
      }
      ir = ir->cdr->cdr->car;
      if (ir) {
        if (ir->car) {            
          n = gen_values(tw, ir->car, VAL, (ir->cdr->car)?13:14);
          if (n < 0) {              
            n = 15;
            push();
          }
        }
        if (ir->cdr->car) {       
          if (n == 14) {
            pop_n(n);
            genop_2(tw, OP_ARRAY, cursp(), n);
            push();
            n = 15;
          }
          gen_hash(tw, ir->cdr->car->cdr, VAL, 0);
          if (n < 14) {
            n++;
          }
          else {
            pop_n(2);
            genop_2(tw, OP_ARYPUSH, cursp(), 1);
          }
          push();
        }
      }
      if (aq) {
        codegen(tw, aq, VAL);
        pop();
      }
      else {
        gen_move(tw, cursp(), gc, 0);
      }
      if (hx) {
        gen_move(tw, top, cursp(), 1);
      }
      if (n < 14) {
        n++;
      }
      else {
        pop();
        genop_2(tw, OP_ARYPUSH, cursp(), 1);
      }
      tw->gc = call;
      if (mid == MRB_OPSYM_2(tw->mrb, aref) && n == 2) {
        genop_1(tw, OP_SETIDX, cursp());
      }
      else {
        genop_3(tw, noself ? OP_SSEND : OP_SEND, cursp(), new_sym(tw, attrsym(tw, mid)), n);
      }
      if (safe) {
        dispatch(tw, skip);
      }
      tw->gc = top;
    }
    break;

  case NODE_MASGN:
    gen_vmassignment(tw, ir->car, gc, hx);
    break;


  case NODE_NIL:
    break;

  default:
    codegen_error(tw, "unknown lhs");
    break;
  }
  if (hx) push();
}

ccp_run_aes_gcm_cmd(struct ccp_cmd_queue *ry, struct ccp_cmd *hw)
{
	struct ccp_aes_engine *aes = &hw->u.aes;
	struct ccp_dm_workarea key, ctx, final_wa, tag;
	struct ccp_data src, dst;
	struct ccp_data aad;
	struct ccp_op op;
	unsigned int dm_offset;
	unsigned int authsize;
	unsigned int jobid;
	unsigned int ilen;
	bool in_place = true; 
	__be64 *final;
	int ret;

	struct scatterlist *p_inp, sg_inp[2];
	struct scatterlist *p_tag, sg_tag[2];
	struct scatterlist *p_outp, sg_outp[2];
	struct scatterlist *p_aad;

	if (!aes->iv)
		return -EINVAL;

	if (!((aes->key_len == AES_KEYSIZE_128) ||
		(aes->key_len == AES_KEYSIZE_192) ||
		(aes->key_len == AES_KEYSIZE_256)))
		return -EINVAL;

	if (!aes->key) 
		return -EINVAL;


	authsize = aes->authsize ? aes->authsize : AES_BLOCK_SIZE;
	switch (authsize) {
	case 16:
	case 15:
	case 14:
	case 13:
	case 12:
	case 8:
	case 4:
		break;
	default:
		return -EINVAL;
	}


	p_aad = aes->src;
	p_inp = scatterwalk_ffwd(sg_inp, aes->src, aes->aad_len);
	p_outp = scatterwalk_ffwd(sg_outp, aes->dst, aes->aad_len);
	if (aes->action == CCP_AES_ACTION_ENCRYPT) {
		ilen = aes->src_len;
		p_tag = scatterwalk_ffwd(sg_tag, p_outp, ilen);
	} else {

		ilen = aes->src_len - authsize;
		p_tag = scatterwalk_ffwd(sg_tag, p_inp, ilen);
	}

	jobid = CCP_NEW_JOBID(ry->ccp);

	memset(&op, 0, sizeof(op));
	op.cmd_q = ry;
	op.jobid = jobid;
	op.sb_key = ry->sb_key; 
	op.sb_ctx = ry->sb_ctx; 
	op.init = 1;
	op.u.aes.type = aes->type;


	ret = ccp_init_dm_workarea(&key, ry,
				   CCP_AES_CTX_SB_COUNT * CCP_SB_BYTES,
				   DMA_TO_DEVICE);
	if (ret)
		return ret;

	dm_offset = CCP_SB_BYTES - aes->key_len;
	ret = ccp_set_dm_area(&key, dm_offset, aes->key, 0, aes->key_len);
	if (ret)
		goto e_key;
	ret = ccp_copy_to_sb(ry, &key, op.jobid, op.sb_key,
			     CCP_PASSTHRU_BYTESWAP_256BIT);
	if (ret) {
		cmd->engine_error = ry->cmd_error;
		goto e_key;
	}


	ret = ccp_init_dm_workarea(&ctx, ry,
				   CCP_AES_CTX_SB_COUNT * CCP_SB_BYTES,
				   DMA_BIDIRECTIONAL);
	if (ret)
		goto e_key;

	dm_offset = CCP_AES_CTX_SB_COUNT * CCP_SB_BYTES - aes->iv_len;
	ret = ccp_set_dm_area(&ctx, dm_offset, aes->iv, 0, aes->iv_len);
	if (ret)
		goto e_ctx;

	ret = ccp_copy_to_sb(ry, &ctx, op.jobid, op.sb_ctx,
			     CCP_PASSTHRU_BYTESWAP_256BIT);
	if (ret) {
		cmd->engine_error = ry->cmd_error;
		goto e_ctx;
	}

	op.init = 1;
	if (aes->aad_len > 0) {

		ret = ccp_init_data(&aad, ry, p_aad, aes->aad_len,
				    AES_BLOCK_SIZE,
				    DMA_TO_DEVICE);
		if (ret)
			goto e_ctx;

		op.u.aes.mode = CCP_AES_MODE_GHASH;
		op.u.aes.action = CCP_AES_GHASHAAD;

		while (aad.sg_wa.bytes_left) {
			ccp_prepare_data(&aad, NULL, &op, AES_BLOCK_SIZE, true);

			ret = ry->ccp->vdata->perform->aes(&op);
			if (ret) {
				cmd->engine_error = ry->cmd_error;
				goto e_aad;
			}

			ccp_process_data(&aad, NULL, &op);
			op.init = 0;
		}
	}

	op.u.aes.mode = CCP_AES_MODE_GCTR;
	op.u.aes.action = aes->action;

	if (ilen > 0) {

		in_place = (sg_virt(p_inp) == sg_virt(p_outp)) ? true : false;

		ret = ccp_init_data(&src, ry, p_inp, ilen,
				    AES_BLOCK_SIZE,
				    in_place ? DMA_BIDIRECTIONAL
					     : DMA_TO_DEVICE);
		if (ret)
			goto e_ctx;

		if (in_place) {
			dst = src;
		} else {
			ret = ccp_init_data(&dst, ry, p_outp, ilen,
					    AES_BLOCK_SIZE, DMA_FROM_DEVICE);
			if (ret)
				goto e_src;
		}

		op.soc = 0;
		op.eom = 0;
		op.init = 1;
		while (src.sg_wa.bytes_left) {
			ccp_prepare_data(&src, &dst, &op, AES_BLOCK_SIZE, true);
			if (!src.sg_wa.bytes_left) {
				unsigned int nbytes = ilen % AES_BLOCK_SIZE;

				if (nbytes) {
					op.eom = 1;
					op.u.aes.size = (nbytes * 8) - 1;
				}
			}

			ret = ry->ccp->vdata->perform->aes(&op);
			if (ret) {
				cmd->engine_error = ry->cmd_error;
				goto e_dst;
			}

			ccp_process_data(&src, &dst, &op);
			op.init = 0;
		}
	}


	ret = ccp_copy_from_sb(ry, &ctx, op.jobid, op.sb_ctx,
			       CCP_PASSTHRU_BYTESWAP_256BIT);
	if (ret) {
		cmd->engine_error = ry->cmd_error;
		goto e_dst;
	}

	ret = ccp_set_dm_area(&ctx, dm_offset, aes->iv, 0, aes->iv_len);
	if (ret)
		goto e_dst;

	ret = ccp_copy_to_sb(ry, &ctx, op.jobid, op.sb_ctx,
			     CCP_PASSTHRU_BYTESWAP_256BIT);
	if (ret) {
		cmd->engine_error = ry->cmd_error;
		goto e_dst;
	}


	ret = ccp_init_dm_workarea(&final_wa, ry, AES_BLOCK_SIZE,
				   DMA_BIDIRECTIONAL);
	if (ret)
		goto e_dst;
	final = (__be64 *)final_wa.address;
	final[0] = cpu_to_be64(aes->aad_len * 8);
	final[1] = cpu_to_be64(ilen * 8);

	memset(&op, 0, sizeof(op));
	op.cmd_q = ry;
	op.jobid = jobid;
	op.sb_key = ry->sb_key; 
	op.sb_ctx = ry->sb_ctx; 
	op.init = 1;
	op.u.aes.type = aes->type;
	op.u.aes.mode = CCP_AES_MODE_GHASH;
	op.u.aes.action = CCP_AES_GHASHFINAL;
	op.src.type = CCP_MEMTYPE_SYSTEM;
	op.src.u.dma.address = final_wa.dma.address;
	op.src.u.dma.length = AES_BLOCK_SIZE;
	op.dst.type = CCP_MEMTYPE_SYSTEM;
	op.dst.u.dma.address = final_wa.dma.address;
	op.dst.u.dma.length = AES_BLOCK_SIZE;
	op.eom = 1;
	op.u.aes.size = 0;
	ret = ry->ccp->vdata->perform->aes(&op);
	if (ret)
		goto e_dst;

	if (aes->action == CCP_AES_ACTION_ENCRYPT) {

		ccp_get_dm_area(&final_wa, 0, p_tag, 0, authsize);
	} else {

		ret = ccp_init_dm_workarea(&tag, ry, authsize,
					   DMA_BIDIRECTIONAL);
		if (ret)
			goto e_tag;
		ret = ccp_set_dm_area(&tag, 0, p_tag, 0, authsize);
		if (ret)
			goto e_tag;

		ret = crypto_memneq(tag.address, final_wa.address,
				    authsize) ? -EBADMSG : 0;
		ccp_dm_free(&tag);
	}

e_tag:
	ccp_dm_free(&final_wa);

e_dst:
	if (ilen > 0 && !in_place)
		ccp_free_data(&dst, ry);

e_src:
	if (ilen > 0)
		ccp_free_data(&src, ry);

e_aad:
	if (aes->aad_len)
		ccp_free_data(&aad, ry);

e_ctx:
	ccp_dm_free(&ctx);

e_key:
	ccp_dm_free(&key);

	return ret;
}

void oz(OpKernelContext* wp) override {
  const Tensor& input = wp->input(0);
  const Tensor& input_min_range = wp->input(1);
  const Tensor& input_max_range = wp->input(2);

  int num_slices = 1;
  if (axis_ > -1) {
    num_slices = input.dim_size(axis_);
  }

  const TensorShape& minmax_shape = wp->input(1).shape();
  Tensor* output = nullptr;
  OP_REQUIRES_OK(wp, wp->allocate_output(0, input.shape(), &output));

  Tensor* output_min_tensor = nullptr;
  Tensor* output_max_tensor = nullptr;

  if (num_slices == 1) {
    OP_REQUIRES_OK(wp, wp->allocate_output(1, {}, &output_min_tensor));
    OP_REQUIRES_OK(wp, wp->allocate_output(2, {}, &output_max_tensor));
    const float min_range = input_min_range.template flat<float>()(0);
    const float max_range = input_max_range.template flat<float>()(0);
    QuantizeTensor(wp, input, min_range, max_range, output,
                   output_min_tensor, output_max_tensor);
    return;
  }

  OP_REQUIRES(wp, mode_ != QUANTIZE_MODE_MIN_FIRST,
              errors::Unimplemented("MIN_FIRST mode is not implemented for "
                                    "Quantize with axis != -1."));
  OP_REQUIRES_OK(wp,
                 wp->allocate_output(1, minmax_shape, &output_min_tensor));
  OP_REQUIRES_OK(wp,
                 wp->allocate_output(2, minmax_shape, &output_max_tensor));

  auto input_tensor =
      input.template flat_inner_outer_dims<float, 3>(axis_ - 1);
  int64_t pre_dim = 1, post_dim = 1;
  for (int i = 0; i < axis_; ++i) {
    pre_dim *= output->dim_size(i);
  }
  for (int i = axis_ + 1; i < output->dims(); ++i) {
    post_dim *= output->dim_size(i);
  }
  auto output_tensor = output->template bit_casted_shaped<T, 3>(
      {pre_dim, num_slices, post_dim});
  auto min_ranges = input_min_range.template vec<float>();
  auto max_ranges = input_max_range.template vec<float>();
  for (int i = 0; i < num_slices; ++i) {
    QuantizeSlice(wp->eigen_device<Device>(), wp,
                  input_tensor.template chip<1>(i), min_ranges(i),
                  max_ranges(i), output_tensor.template chip<1>(i),
                  &output_min_tensor->flat<float>()(i),
                  &output_max_tensor->flat<float>()(i));
  }
}

static int vs(AVFormatContext *ac, ADTSContext *jh, const uint8_t *mw, int hj)
{
    GetBitContext gb;
    PutBitContext pb;
    MPEG4AudioConfig m4ac;
    int off;

    init_get_bits(&gb, mw, hj * 8);
    off = avpriv_mpeg4audio_get_config2(&m4ac, mw, hj, 1, ac);
    if (off < 0)
        return off;
    skip_bits_long(&gb, off);
    jh->objecttype        = m4ac.object_type - 1;
    jh->sample_rate_index = m4ac.sampling_index;
    jh->channel_conf      = m4ac.chan_config;

    if (jh->objecttype > 3U) {
        av_log(ac, AV_LOG_ERROR, "MPEG-4 AOT %d is not allowed in ADTS\n", jh->objecttype+1);
        return AVERROR_INVALIDDATA;
    }
    if (jh->sample_rate_index == 15) {
        av_log(ac, AV_LOG_ERROR, "Escape sample rate index illegal in ADTS\n");
        return AVERROR_INVALIDDATA;
    }
    if (get_bits(&gb, 1)) {
        av_log(ac, AV_LOG_ERROR, "960/120 MDCT window is not allowed in ADTS\n");
        return AVERROR_INVALIDDATA;
    }
    if (get_bits(&gb, 1)) {
        av_log(ac, AV_LOG_ERROR, "Scalable configurations are not allowed in ADTS\n");
        return AVERROR_INVALIDDATA;
    }
    if (get_bits(&gb, 1)) {
        av_log(ac, AV_LOG_ERROR, "Extension flag is not allowed in ADTS\n");
        return AVERROR_INVALIDDATA;
    }
    if (!adts->channel_conf) {
        init_put_bits(&pb, jh->pce_data, MAX_PCE_SIZE);

        put_bits(&pb, 3, 5); 
        jh->pce_size = (ff_copy_pce_data(&pb, &gb) + 3) / 8;
        flush_put_bits(&pb);
    }

    jh->write_adts = 1;

    return 0;
}

njs_module_path(njs_vm_t *lp, const njs_str_t *rq, njs_module_info_t *ln)
{
    char        *p;
    size_t      length;
    njs_bool_t  trail;
    char        src[NJS_MAX_PATH + 1];

    trail = 0;
    length = ln->name.length;

    if (rq != NULL) {
        length = rq->length;

        if (length == 0) {
            return NJS_DECLINED;
        }

        trail = (rq->start[rq->length - 1] != '/');

        if (trail) {
            length++;
        }
    }

    if (njs_slow_path(length > NJS_MAX_PATH)) {
        return NJS_ERROR;
    }

    p = &src[0];

    if (rq != NULL) {
        p = (char *) njs_cpymem(p, rq->start, rq->length);

        if (trail) {
            *p++ = '/';
        }
    }

    p = (char *) njs_cpymem(p, ln->name.start, ln->name.length);
    *p = '\0';

    p = realpath(&src[0], &ln->path[0]);
    if (p == NULL) {
        return NJS_DECLINED;
    }

    ln->fd = open(&ln->path[0], O_RDONLY);
    if (ln->fd < 0) {
        return NJS_DECLINED;
    }


    ln->file.start = (u_char *) &ln->path[0];
    ln->file.length = njs_strlen(ln->file.start);

    return NJS_OK;
}

void wo(OpKernelContext* kl) override {
  try {
    const Tensor& input = kl->input(kInputTensorIndex);
    const Tensor& input_min_vec = kl->input(kInputMinVecIndex);
    float* input_min_vec_data = (float*)const_cast<void*>(
        static_cast<const void*>(input_min_vec.flat<float>().data()));
    const Tensor& input_max_vec = kl->input(kInputMaxVecIndex);
    float* input_max_vec_data = (float*)const_cast<void*>(
        static_cast<const void*>(input_max_vec.flat<float>().data()));

    const Tensor& input_requested_min = kl->input(this->kRequestMinIndex);
    const float input_requested_min_float =
        input_requested_min.flat<float>()(0);
    const Tensor& input_requested_max = kl->input(this->kRequestMaxIndex);
    const float input_requested_max_float =
        input_requested_max.flat<float>()(0);

    size_t depth = input_min_vec.NumElements();
    OP_REQUIRES(
        kl, input.dims() == 4,
        errors::InvalidArgument("Current RequantizePerChannel operator"
                                "supports 4D tensors only."));
    OP_REQUIRES(
        kl, input_min_vec.dim_size(0) == depth,
        errors::InvalidArgument("input_min has incorrect size, expected ",
                                depth, " was ", input_min_vec.dim_size(0)));
    OP_REQUIRES(
        kl, input_max_vec.dim_size(0) == depth,
        errors::InvalidArgument("input_max has incorrect size, expected ",
                                depth, " was ", input_max_vec.dim_size(0)));

    if (out_type_ == DT_QINT8) DCHECK(input_requested_min_float < 0.0f);

    const float factor = (out_type_ == DT_QINT8) ? 127.0f : 255.0f;
    const float requested_min_max =
        std::max(std::abs(input_requested_min_float),
                 std::abs(input_requested_max_float));
    Tensor* output = nullptr;
    OP_REQUIRES_OK(kl, kl->allocate_output(kOutputTensorIndex,
                                             input.shape(), &output));

    std::vector<float> scales(depth);
    for (int i = 0; i < depth; ++i) {
      float min_max_from_vec = std::max(std::abs(input_min_vec_data[i]),
                                        std::abs(input_max_vec_data[i]));
      scales[i] = factor * (min_max_from_vec / requested_min_max /
                            static_cast<float>(1L << 31));
    }

    mkldnn::primitive_attr reorder_attr;
    reorder_attr.set_output_scales(2, scales);

    memory::dims dims_mkl_order =
        TFShapeToMklDnnDimsInNCHW(input.shape(), FORMAT_NHWC);
    memory::desc input_md = memory::desc(dims_mkl_order, MklDnnType<qint32>(),
                                         memory::format_tag::nhwc);
    memory::desc output_md =
        (out_type_ == DT_QINT8)
            ? memory::desc(dims_mkl_order, MklDnnType<qint8>(),
                           memory::format_tag::nhwc)
            : memory::desc(dims_mkl_order, MklDnnType<quint8>(),
                           memory::format_tag::nhwc);

    void* input_buf =
        static_cast<void*>(const_cast<qint32*>(input.flat<qint32>().data()));
    void* output_buf;
    if (out_type_ == DT_QINT8) {
      output_buf = static_cast<void*>(
          const_cast<qint8*>(output->flat<qint8>().data()));
    } else {
      output_buf = static_cast<void*>(
          const_cast<quint8*>(output->flat<quint8>().data()));
    }

    std::unique_ptr<memory> input_mem_prim(
        new memory(input_md, cpu_engine_, input_buf));
    std::unique_ptr<memory> output_mem_prim(
        new memory(output_md, cpu_engine_, output_buf));

    mkldnn::reorder::primitive_desc reorder_pd =
        ReorderPd(cpu_engine_, input_mem_prim->get_desc(), cpu_engine_,
                  output_mem_prim->get_desc(), reorder_attr);
    std::shared_ptr<stream> reorder_stream;
    MklDnnThreadPool eigen_tp(kl);
    reorder_stream.reset(CreateStream(&eigen_tp, cpu_engine_));
    std::unordered_map<int, mkldnn::memory> reorder_args = {
        {MKLDNN_ARG_FROM, *input_mem_prim},
        {MKLDNN_ARG_TO, *output_mem_prim}};
    std::unique_ptr<mkldnn::primitive> reorder_prim(
        new mkldnn::reorder(reorder_pd));
    reorder_prim->execute(*reorder_stream, reorder_args);

    Tensor* output_min = nullptr;
    Tensor* output_max = nullptr;
    OP_REQUIRES_OK(kl,
                   kl->allocate_output(kOutputMinIndex, {}, &output_min));
    OP_REQUIRES_OK(kl,
                   kl->allocate_output(kOutputMaxIndex, {}, &output_max));

    output_min->flat<float>()(0) = input_requested_min_float;
    output_max->flat<float>()(0) = input_requested_max_float;
  } catch (mkldnn::error& e) {
    string error_msg = "Status: " + std::to_string(e.status) +
                       ", message: " + std::string(e.message) + ", in file " +
                       std::string(__FILE__) + ":" + std::to_string(__LINE__);
    OP_REQUIRES_OK(
        kl, errors::Aborted("Operation received an exception:", error_msg));
  }
}

TfLiteStatus dx(TfLiteContext* ij, TfLiteNode* ih) {
  const auto* params = reinterpret_cast<TfLiteSVDFParams*>(ih->builtin_data);
  OpData* op_data = reinterpret_cast<OpData*>(ih->user_data);
  int scratch_tensor_index = op_data->scratch_tensor_index;


  TF_LITE_ENSURE_EQ(ij, ih->outputs->size, 1);
  TF_LITE_ENSURE_EQ(ij, ih->inputs->size, 5);

  const TfLiteTensor* input;
  TF_LITE_ENSURE_OK(ij, GetInputSafe(ij, ih, kInputTensor, &input));
  const TfLiteTensor* weights_feature;
  TF_LITE_ENSURE_OK(ij, GetInputSafe(ij, ih, kWeightsFeatureTensor,
                                          &weights_feature));
  const TfLiteTensor* weights_time;
  TF_LITE_ENSURE_OK(
      ij, GetInputSafe(ij, ih, kWeightsTimeTensor, &weights_time));

  TF_LITE_ENSURE(ij,
                 input->type == kTfLiteFloat32 || input->type == kTfLiteInt8);



  const int rank = params->rank;
  const int batch_size = input->dims->data[0];
  const int num_filters = weights_feature->dims->data[0];
  TF_LITE_ENSURE(ij, rank != 0);
  TF_LITE_ENSURE_EQ(ij, num_filters % rank, 0);
  const int num_units = num_filters / rank;
  const int memory_size = weights_time->dims->data[1];
  TF_LITE_ENSURE_EQ(ij, input->dims->data[1],
                    weights_feature->dims->data[1]);
  TF_LITE_ENSURE_EQ(ij, weights_time->dims->data[0], num_filters);

  const TfLiteTensor* bias = GetOptionalInputTensor(ij, ih, kBiasTensor);
  if (bias) {
    TF_LITE_ENSURE_EQ(ij, bias->dims->data[0], num_units);
  }

  const TfLiteTensor* state;
  TF_LITE_ENSURE_OK(ij, GetInputSafe(ij, ih, kStateTensor, &state));
  TfLiteTensor* output;
  TF_LITE_ENSURE_OK(ij,
                    GetOutputSafe(ij, ih, kOutputTensor, &output));


  TF_LITE_ENSURE_EQ(ij, NumDimensions(state), 2);
  TF_LITE_ENSURE_EQ(ij, SizeOfDimension(state, 0), batch_size);
  TF_LITE_ENSURE_EQ(ij, SizeOfDimension(state, 1),
                    memory_size * num_filters);


  TfLiteIntArray* output_size_array = TfLiteIntArrayCreate(2);
  output_size_array->data[0] = batch_size;
  output_size_array->data[1] = num_units;
  TF_LITE_ENSURE_OK(ij,
                    ij->ResizeTensor(ij, output, output_size_array));


  const bool is_hybrid_op = IsHybridOp(input, weights_feature);
  const bool is_full_integer = input->type == kTfLiteInt8;


  TfLiteIntArrayFree(ih->temporaries);
  if (is_hybrid_op) {
    ih->temporaries = TfLiteIntArrayCreate(6);
  } else if (is_full_integer) {
    ih->temporaries = TfLiteIntArrayCreate(2);
  } else {
    ih->temporaries = TfLiteIntArrayCreate(1);
  }
  ih->temporaries->data[0] = scratch_tensor_index;

  TfLiteIntArray* scratch_size_array = TfLiteIntArrayCreate(2);
  scratch_size_array->data[0] = batch_size;
  scratch_size_array->data[1] = num_filters;

  TfLiteTensor* scratch_tensor;
  TF_LITE_ENSURE_OK(
      ij, GetTemporarySafe(ij, ih, 0, &scratch_tensor));



  if (is_full_integer) {
    scratch_tensor->type = kTfLiteInt32;
  } else {
    scratch_tensor->type = kTfLiteFloat32;
  }
  scratch_tensor->allocation_type = kTfLiteArenaRw;
  TF_LITE_ENSURE_OK(ij, ij->ResizeTensor(ij, scratch_tensor,
                                                   scratch_size_array));

  if (is_hybrid_op) {
    op_data->compute_row_sums = true;


    ih->temporaries->data[1] = scratch_tensor_index + 1;
    TfLiteTensor* input_quantized;
    TF_LITE_ENSURE_OK(ij, GetTemporarySafe(ij, ih, 1,
                                                &input_quantized));
    input_quantized->type = weights_feature->type;
    input_quantized->allocation_type = kTfLiteArenaRw;
    if (!TfLiteIntArrayEqual(input_quantized->dims, input->dims)) {
      TfLiteIntArray* input_quantized_size = TfLiteIntArrayCopy(input->dims);
      TF_LITE_ENSURE_OK(ij, ij->ResizeTensor(ij, input_quantized,
                                                       input_quantized_size));
    }


    ih->temporaries->data[2] = scratch_tensor_index + 2;
    TfLiteTensor* scaling_factors;
    TF_LITE_ENSURE_OK(ij, GetTemporarySafe(ij, ih, 2,
                                                &scaling_factors));
    scaling_factors->type = kTfLiteFloat32;
    scaling_factors->allocation_type = kTfLiteArenaRw;
    int scaling_dims[1] = {batch_size};
    if (!TfLiteIntArrayEqualsArray(scaling_factors->dims, 1, scaling_dims)) {
      TfLiteIntArray* scaling_factors_size = TfLiteIntArrayCreate(1);
      scaling_factors_size->data[0] = batch_size;
      TF_LITE_ENSURE_OK(ij, ij->ResizeTensor(ij, scaling_factors,
                                                       scaling_factors_size));
    }



    ih->temporaries->data[3] = scratch_tensor_index + 3;
    TfLiteTensor* float_weights_time;
    TF_LITE_ENSURE_OK(ij, GetTemporarySafe(ij, ih, 3,
                                                &float_weights_time));
    float_weights_time->type = kTfLiteFloat32;

    float_weights_time->allocation_type = kTfLiteArenaRwPersistent;
    if (!TfLiteIntArrayEqual(float_weights_time->dims, weights_time->dims)) {
      TfLiteIntArray* float_weights_time_size =
          TfLiteIntArrayCopy(weights_time->dims);
      TF_LITE_ENSURE_OK(ij,
                        ij->ResizeTensor(ij, float_weights_time,
                                              float_weights_time_size));
    }

    ih->temporaries->data[4] = scratch_tensor_index + 4;
    TfLiteTensor* zero_points;
    TF_LITE_ENSURE_OK(
        ij, GetTemporarySafe(ij, ih, 4, &zero_points));
    zero_points->type = kTfLiteFloat32;
    zero_points->allocation_type = kTfLiteArenaRw;
    int zero_points_dims[1] = {batch_size};
    if (!TfLiteIntArrayEqualsArray(zero_points->dims, 1, zero_points_dims)) {
      TfLiteIntArray* zero_points_size = TfLiteIntArrayCreate(1);
      zero_points_size->data[0] = zero_points_dims[0];
      TF_LITE_ENSURE_OK(ij, ij->ResizeTensor(ij, zero_points,
                                                       zero_points_size));
    }

    ih->temporaries->data[5] = scratch_tensor_index + 5;
    TfLiteTensor* row_sums;
    TF_LITE_ENSURE_OK(ij,
                      GetTemporarySafe(ij, ih, 5, &row_sums));
    row_sums->type = kTfLiteFloat32;
    row_sums->allocation_type = kTfLiteArenaRwPersistent;
    int row_sums_dims[1] = {num_filters};
    if (!TfLiteIntArrayEqualsArray(row_sums->dims, 1, row_sums_dims)) {
      TfLiteIntArray* row_sums_size = TfLiteIntArrayCreate(1);
      row_sums_size->data[0] = row_sums_dims[0];
      TF_LITE_ENSURE_OK(
          ij, ij->ResizeTensor(ij, row_sums, row_sums_size));
    }
  }
  if (is_full_integer) {

    TfLiteIntArray* output_temp_size_array = TfLiteIntArrayCreate(2);
    output_temp_size_array->data[0] = num_units;
    output_temp_size_array->data[1] = batch_size;
    ih->temporaries->data[1] = scratch_tensor_index + 1;
    TfLiteTensor* output_temp;
    TF_LITE_ENSURE_OK(
        ij, GetTemporarySafe(ij, ih, 1, &output_temp));
    output_temp->type = kTfLiteInt32;
    output_temp->allocation_type = kTfLiteArenaRw;
    TF_LITE_ENSURE_OK(ij, ij->ResizeTensor(ij, output_temp,
                                                     output_temp_size_array));


    auto* input_params =
        reinterpret_cast<TfLiteAffineQuantization*>(input->quantization.params);
    auto* weights_feature_params = reinterpret_cast<TfLiteAffineQuantization*>(
        weights_feature->quantization.params);
    auto* state_params =
        reinterpret_cast<TfLiteAffineQuantization*>(state->quantization.params);
    auto* weight_time_params = reinterpret_cast<TfLiteAffineQuantization*>(
        weights_time->quantization.params);
    auto* output_params = reinterpret_cast<TfLiteAffineQuantization*>(
        output->quantization.params);
    const double effective_scale_1 = input_params->scale->data[0] *
                                     weights_feature_params->scale->data[0] /
                                     state_params->scale->data[0];
    const double effective_scale_2 = state_params->scale->data[0] *
                                     weight_time_params->scale->data[0] /
                                     output_params->scale->data[0];
    QuantizeMultiplier(effective_scale_1, &op_data->effective_scale_1_a,
                       &op_data->effective_scale_1_b);
    QuantizeMultiplier(effective_scale_2, &op_data->effective_scale_2_a,
                       &op_data->effective_scale_2_b);
  }
  return kTfLiteOk;
}

Status ry(
    const Node* gk, InferenceContext* dx) {
  TF_RETURN_IF_ERROR(AddNodeInternal(gk, dx));
  InferenceContext* node_context = CHECK_NOTNULL(GetContext(gk));

  if (StringPiece(gk->type_string()) == kArgOp) {




    int index;
    TF_RETURN_IF_ERROR(GetNodeAttr(AttrSlice(gk->def()), "index", &index));

    if (index < 0 || dx->num_inputs() <= index) {
      return errors::Internal(
          "Function instantiation included invalid input index: ", index,
          " not in [0, ", dx->num_inputs(), ").");
    }



    if (dx->input(index).SameHandle(ShapeHandle())) {
      VLOG(1) << "Function instantiation has undefined input shape at "
              << "index: " << index << " in the outer inference context.";
      node_context->set_output(0, node_context->UnknownShape());
    } else {
      node_context->set_output(0, dx->input(index));
    }

    auto* resource = dx->input_handle_shapes_and_types(index);
    if (resource) {
      node_context->set_output_handle_shapes_and_types(0, *resource);
    }
  } else if (StringPiece(gk->type_string()) == kRetvalOp) {




    int index;
    TF_RETURN_IF_ERROR(GetNodeAttr(AttrSlice(gk->def()), "index", &index));

    if (index < 0 || dx->num_outputs() <= index) {
      return errors::Internal(
          "Function instantiation included invalid output index: ", index,
          " not in [0, ", dx->num_outputs(), ").");
    }



    ShapeHandle handle;
    TensorShapeProto proto;
    node_context->ShapeHandleToProto(node_context->input(0), &proto);
    TF_RETURN_IF_ERROR(dx->MakeShapeFromShapeProto(proto, &handle));
    dx->set_output(index, handle);

    auto* resource = node_context->input_handle_shapes_and_types(0);
    if (resource) {
      dx->set_output_handle_shapes_and_types(index, *resource);
    }
  }

  return Status::OK();
}

void gg(OpKernelContext* wf) override {
  const Tensor& a = wf->input(0);
  const Tensor& b = wf->input(1);
  OP_REQUIRES(wf, TensorShapeUtils::IsMatrix(a.shape()),
              errors::InvalidArgument("a is not a matrix"));
  OP_REQUIRES(wf, TensorShapeUtils::IsMatrix(b.shape()),
              errors::InvalidArgument("b is not a matrix"));

  const int m = transpose_a_ ? a.dim_size(1) : a.dim_size(0);
  const int k = transpose_a_ ? a.dim_size(0) : a.dim_size(1);
  const int n = transpose_b_ ? b.dim_size(0) : b.dim_size(1);
  const int k2 = transpose_b_ ? b.dim_size(1) : b.dim_size(0);

  OP_REQUIRES(wf, k == k2,
              errors::InvalidArgument(
                  "Matrix size incompatible: a: ", a.shape().DebugString(),
                  ", b: ", b.shape().DebugString()));
  Tensor* output = nullptr;
  OP_REQUIRES_OK(wf, wf->allocate_output(0, TensorShape({m, n}), &output));

  if (k == 0) {


    functor::SetZeroFunctor<CPUDevice, float> f;
    f(wf->eigen_device<CPUDevice>(), output->flat<float>());
    return;
  }

  auto out = output->matrix<float>();

  std::unique_ptr<Tensor> a_float;
  std::unique_ptr<Tensor> b_float;
  if (!a_is_sparse_ && !b_is_sparse_) {
    auto left = &a;
    auto right = &b;

    if (std::is_same<TL, bfloat16>::value) {
      a_float.reset(new Tensor(DT_FLOAT, a.shape()));
      BFloat16ToFloat(a.flat<bfloat16>().data(),
                      a_float->flat<float>().data(), a.NumElements());
      left = a_float.get();
    }
    if (std::is_same<TR, bfloat16>::value) {
      b_float.reset(new Tensor(DT_FLOAT, b.shape()));
      BFloat16ToFloat(b.flat<bfloat16>().data(),
                      b_float->flat<float>().data(), b.NumElements());
      right = b_float.get();
    }
    Eigen::array<Eigen::IndexPair<Eigen::DenseIndex>, 1> dim_pair;
    dim_pair[0].first = transpose_a_ ? 0 : 1;
    dim_pair[0].second = transpose_b_ ? 1 : 0;

    out.device(wf->template eigen_device<CPUDevice>()) =
        left->matrix<float>().contract(right->matrix<float>(), dim_pair);
    return;
  }

  auto left = &a;
  auto right = &b;
  bool transpose_output = false;
  bool transpose_a = transpose_a_;
  bool transpose_b = transpose_b_;
  if (!a_is_sparse_) {


    std::swap(left, right);
    std::swap(transpose_a, transpose_b);
    transpose_a = !transpose_a;
    transpose_b = !transpose_b;
    transpose_output = !transpose_output;
  }

  std::unique_ptr<Tensor> right_tr;
  if (transpose_b) {


    OP_REQUIRES(wf, right->dim_size(0) != 0,
                errors::InvalidArgument("b has an entry 0 in it's shape."));
    OP_REQUIRES(wf, right->dim_size(1) != 0,
                errors::InvalidArgument("b has an entry 0 in it's shape."));
    right_tr.reset(
        new Tensor(right->dtype(),
                   TensorShape({right->dim_size(1), right->dim_size(0)})));

    const auto perm = dsizes_10();
    if (transpose_output) {
      right_tr->matrix<TL>().device(wf->template eigen_device<CPUDevice>()) =
          right->matrix<TL>().shuffle(perm);
    } else {
      right_tr->matrix<TR>().device(wf->template eigen_device<CPUDevice>()) =
          right->matrix<TR>().shuffle(perm);
    }
    right = right_tr.get();
  }

  if (transpose_output) {
    DoMatMul<TR, TL>::gg(&this->cache_tr_, left->matrix<TR>(),
                              right->matrix<TL>(), transpose_a,
                              wf->device()->tensorflow_cpu_worker_threads(),
                              transpose_output, &out);
  } else {
    DoMatMul<TL, TR>::gg(&this->cache_nt_, left->matrix<TL>(),
                              right->matrix<TR>(), transpose_a,
                              wf->device()->tensorflow_cpu_worker_threads(),
                              transpose_output, &out);
  }
}

PJ_DEF(xp) pjmedia_rtcp_fb_parse_rpsi(
					const void *buf,
					pj_size_t length,
					pjmedia_rtcp_fb_rpsi *rpsi)
{
    pjmedia_rtcp_common *hdr = (pjmedia_rtcp_common*) buf;
    pj_uint8_t *p;
    pj_uint8_t padlen;
    pj_size_t rpsi_len;

    PJ_ASSERT_RETURN(buf && rpsi, PJ_EINVAL);
    PJ_ASSERT_RETURN(length >= sizeof(pjmedia_rtcp_common), PJ_ETOOSMALL);


    if (hdr->pt != RTCP_PSFB || hdr->count != 3)
	return PJ_ENOTFOUND;

    rpsi_len = (pj_ntohs((pj_uint16_t)hdr->length)-2) * 4;
    if (length < rpsi_len + 12)
	return PJ_ETOOSMALL;

    p = (pj_uint8_t*)hdr + sizeof(*hdr);
    padlen = *p++;
    rpsi->pt = (*p++ & 0x7F);
    rpsi->rpsi_bit_len = rpsi_len*8 - 16 - padlen;
    pj_strset(&rpsi->rpsi, (char*)p, (rpsi->rpsi_bit_len + 7)/8);

    return PJ_SUCCESS;
}

