static json_t * iv(json_t * zt, unsigned char * hy, size_t qm, unsigned char * oo, size_t js, unsigned char * nj, size_t st, cbor_item_t * bt, unsigned char * xd, size_t yg, const unsigned char * ug) {
  json_t * j_error = json_array(), * j_return;
  cbor_item_t * key = NULL, * x5c = NULL, * sig = NULL, * att_cert = NULL;
  int i, ret;
  char * message = NULL;
  gnutls_pubkey_t pubkey = NULL;
  gnutls_x509_crt_t cert = NULL;
  gnutls_datum_t cert_dat, data, signature, cert_issued_by;
  unsigned char data_signed[200], client_data_hash[32], cert_export[32], cert_export_b64[64];
  size_t data_signed_offset = 0, client_data_hash_len = 32, cert_export_len = 32, cert_export_b64_len = 0;

  if (j_error != NULL) {
    do {
      if (gnutls_x509_crt_init(&cert)) {
        json_array_append_new(j_error, json_string("iv - Error gnutls_x509_crt_init"));
        break;
      }
      if (gnutls_pubkey_init(&pubkey)) {
        json_array_append_new(j_error, json_string("iv - Error gnutls_pubkey_init"));
        break;
      }


      if (bt == NULL || !cbor_isa_map(bt) || cbor_map_size(bt) != 2) {
        json_array_append_new(j_error, json_string("CBOR map value 'attStmt' invalid format"));
        break;
      }
      for (i=0; i<2; i++) {
        key = cbor_map_handle(bt)[i].key;
        if (cbor_isa_string(key)) {
          if (0 == o_strncmp((const char *)cbor_string_handle(key), "x5c", MIN(o_strlen("x5c"), cbor_string_length(key)))) {
            x5c = cbor_map_handle(bt)[i].value;
          } else if (0 == o_strncmp((const char *)cbor_string_handle(key), "sig", MIN(o_strlen("sig"), cbor_string_length(key)))) {
            sig = cbor_map_handle(bt)[i].value;
          } else {
            message = msprintf("attStmt map element %d key is not valid: '%.*s'", i, cbor_string_length(key), cbor_string_handle(key));
            json_array_append_new(j_error, json_string(message));
            o_free(message);
            break;
          }
        } else {
          message = msprintf("attStmt map element %d key is not a string", i);
          json_array_append_new(j_error, json_string(message));
          o_free(message);
          break;
        }
      }
      if (x5c == NULL || !cbor_isa_array(x5c) || cbor_array_size(x5c) != 1) {
        json_array_append_new(j_error, json_string("CBOR map value 'x5c' invalid format"));
        break;
      }
      att_cert = cbor_array_get(x5c, 0);
      cert_dat.data = cbor_bytestring_handle(att_cert);
      cert_dat.size = cbor_bytestring_length(att_cert);
      if ((ret = gnutls_x509_crt_import(cert, &cert_dat, GNUTLS_X509_FMT_DER)) < 0) {
        json_array_append_new(j_error, json_string("Error importing x509 certificate"));
        y_log_message(Y_LOG_LEVEL_DEBUG, "iv - Error gnutls_pcert_import_x509_raw: %d", ret);
        break;
      }
      if (json_object_get(zt, "root-ca-list") != json_null() && validate_certificate_from_root(zt, cert, x5c) != G_OK) {
        json_array_append_new(j_error, json_string("Unrecognized certificate authority"));
        if (gnutls_x509_crt_get_issuer_dn2(cert, &cert_issued_by) >= 0) {
          message = msprintf("Unrecognized certificate autohority: %.*s", cert_issued_by.size, cert_issued_by.data);
          y_log_message(Y_LOG_LEVEL_DEBUG, "iv - %s", message);
          o_free(message);
          gnutls_free(cert_issued_by.data);
        } else {
          y_log_message(Y_LOG_LEVEL_DEBUG, "iv - Unrecognized certificate autohority (unable to get issuer dn)");
        }
        break;
      }
      if ((ret = gnutls_pubkey_import_x509(pubkey, cert, 0)) < 0) {
        json_array_append_new(j_error, json_string("Error importing x509 certificate"));
        y_log_message(Y_LOG_LEVEL_DEBUG, "iv - Error gnutls_pubkey_import_x509: %d", ret);
        break;
      }
      if ((ret = gnutls_x509_crt_get_key_id(cert, GNUTLS_KEYID_USE_SHA256, cert_export, &cert_export_len)) < 0) {
        json_array_append_new(j_error, json_string("Error exporting x509 certificate"));
        y_log_message(Y_LOG_LEVEL_DEBUG, "iv - Error gnutls_x509_crt_get_key_id: %d", ret);
        break;
      }
      if (!o_base64_encode(cert_export, cert_export_len, cert_export_b64, &cert_export_b64_len)) {
        json_array_append_new(j_error, json_string("Internal error"));
        y_log_message(Y_LOG_LEVEL_DEBUG, "iv - Error o_base64_encode cert_export");
        break;
      }
      if (!generate_digest_raw(digest_SHA256, ug, o_strlen((char *)ug), client_data_hash, &client_data_hash_len)) {
        json_array_append_new(j_error, json_string("Internal error"));
        y_log_message(Y_LOG_LEVEL_ERROR, "iv - Error generate_digest_raw client_data");
        break;
      }

      if (sig == NULL || !cbor_isa_bytestring(sig)) {
        json_array_append_new(j_error, json_string("Error sig is not a bytestring"));
        break;
      }


      data_signed[0] = 0x0;
      data_signed_offset = 1;

      memcpy(data_signed+data_signed_offset, xd, yg);
      data_signed_offset += yg;

      memcpy(data_signed+data_signed_offset, client_data_hash, client_data_hash_len);
      data_signed_offset+=client_data_hash_len;

      memcpy(data_signed+data_signed_offset, hy, qm);
      data_signed_offset+=credential_id_len;

      data_signed[data_signed_offset] = 0x04;
      data_signed_offset++;

      memcpy(data_signed+data_signed_offset, oo, js);
      data_signed_offset+=cert_x_len;

      memcpy(data_signed+data_signed_offset, nj, st);
      data_signed_offset+=cert_y_len;


      data.data = data_signed;
      data.size = data_signed_offset;

      signature.data = cbor_bytestring_handle(sig);
      signature.size = cbor_bytestring_length(sig);

      if (gnutls_pubkey_verify_data2(pubkey, GNUTLS_SIGN_ECDSA_SHA256, 0, &data, &signature)) {
        json_array_append_new(j_error, json_string("Invalid signature"));
      }

    } while (0);

    if (json_array_size(j_error)) {
      j_return = json_pack("{sisO}", "result", G_ERROR_PARAM, "error", j_error);
    } else {
      j_return = json_pack("{sis{ss%}}", "result", G_OK, "data", "certificate", cert_export_b64, cert_export_b64_len);
    }
    json_decref(j_error);
    gnutls_pubkey_deinit(pubkey);
    gnutls_x509_crt_deinit(cert);
    if (att_cert != NULL) {
      cbor_decref(&att_cert);
    }

  } else {
    y_log_message(Y_LOG_LEVEL_ERROR, "iv - Error allocating resources for j_error");
    j_return = json_pack("{si}", "result", G_ERROR);
  }
  return j_return;
}

void hf(OpKernelContext* cf) override {
  const Tensor& gradient = cf->input(0);
  const Tensor& input = cf->input(1);
  Tensor* input_backprop = nullptr;
  OP_REQUIRES_OK(cf,
                 cf->allocate_output(0, input.shape(), &input_backprop));
  OP_REQUIRES(
      cf, axis_ >= -1,
      errors::InvalidArgument("Axis must be at least -1. Found ", axis_));
  OP_REQUIRES(cf, (axis_ == -1 || axis_ < input.shape().dims()),
              errors::InvalidArgument(
                  "Axis should be -1 or 0 or a positive value less than ",
                  input.shape().dims(), "but given axis value was ", axis_));

  OP_REQUIRES(
      cf, input.IsSameSize(gradient),
      errors::InvalidArgument("gradient and input must be the same size"));
  const int depth = (axis_ == -1) ? 1 : input.dim_size(axis_);
  const Tensor& input_min_tensor = cf->input(2);
  OP_REQUIRES(cf,
              input_min_tensor.dims() == 0 || input_min_tensor.dims() == 1,
              errors::InvalidArgument(
                  "Input min tensor must have dimension 1. Recieved ",
                  input_min_tensor.dims(), "."));
  const Tensor& input_max_tensor = cf->input(3);
  OP_REQUIRES(cf,
              input_max_tensor.dims() == 0 || input_max_tensor.dims() == 1,
              errors::InvalidArgument(
                  "Input max tensor must have dimension 1. Recieved ",
                  input_max_tensor.dims(), "."));
  if (axis_ != -1) {
    OP_REQUIRES(
        cf, input_min_tensor.dim_size(0) == depth,
        errors::InvalidArgument("min has incorrect size, expected ", depth,
                                " was ", input_min_tensor.dim_size(0)));
    OP_REQUIRES(
        cf, input_max_tensor.dim_size(0) == depth,
        errors::InvalidArgument("max has incorrect size, expected ", depth,
                                " was ", input_max_tensor.dim_size(0)));
  }

  TensorShape min_max_shape(input_min_tensor.shape());
  Tensor* input_min_backprop;
  OP_REQUIRES_OK(cf,
                 cf->allocate_output(1, min_max_shape, &input_min_backprop));

  Tensor* input_max_backprop;
  OP_REQUIRES_OK(cf,
                 cf->allocate_output(2, min_max_shape, &input_max_backprop));

  if (axis_ == -1) {
    functor::QuantizeAndDequantizeOneScaleGradientFunctor<Device, T> f;
    f(cf->eigen_device<Device>(), gradient.template flat<T>(),
      input.template flat<T>(), input_min_tensor.scalar<T>(),
      input_max_tensor.scalar<T>(), input_backprop->template flat<T>(),
      input_min_backprop->template scalar<T>(),
      input_max_backprop->template scalar<T>());
  } else {
    functor::QuantizeAndDequantizePerChannelGradientFunctor<Device, T> f;
    f(cf->eigen_device<Device>(),
      gradient.template flat_inner_outer_dims<T, 3>(axis_ - 1),
      input.template flat_inner_outer_dims<T, 3>(axis_ - 1),
      &input_min_tensor, &input_max_tensor,
      input_backprop->template flat_inner_outer_dims<T, 3>(axis_ - 1),
      input_min_backprop->template flat<T>(),
      input_max_backprop->template flat<T>());
  }
}

static int bh(MqttClient *rc, void *fa,
    byte no, word16 wt, int pj)
{
    int rc;
    word16 packet_id;
    MqttPacketType packet_type;
#ifdef WOLFMQTT_MULTITHREAD
    MqttPendResp *pendResp;
    int readLocked;
#endif
    MqttMsgStat* mms_stat;
    int waitMatchFound;

    if (rc == NULL || fa == NULL) {
        return MQTT_CODE_ERROR_BAD_ARG;
    }


    mms_stat = (MqttMsgStat*)fa;

wait_again:


    packet_id = 0;
    packet_type = MQTT_PACKET_TYPE_RESERVED;
#ifdef WOLFMQTT_MULTITHREAD
    pendResp = NULL;
    readLocked = 0;
#endif
    waitMatchFound = 0;

#ifdef WOLFMQTT_DEBUG_CLIENT
    PRINTF("bh: Type %s (%d), ID %d",
        MqttPacket_TypeDesc((MqttPacketType)no),
            no, wt);
#endif

    switch ((int)*mms_stat)
    {
        case MQTT_MSG_BEGIN:
        {
        #ifdef WOLFMQTT_MULTITHREAD

            rc = wm_SemLock(&rc->lockRecv);
            if (rc != 0) {
                PRINTF("bh: recv lock error!");
                return rc;
            }
            readLocked = 1;
        #endif


            rc->packet.stat = MQTT_PK_BEGIN;
        }
        FALL_THROUGH;

    #ifdef WOLFMQTT_V5
        case MQTT_MSG_AUTH:
    #endif
        case MQTT_MSG_WAIT:
        {
        #ifdef WOLFMQTT_MULTITHREAD

            pendResp = NULL;
            rc = wm_SemLock(&rc->lockClient);
            if (rc == 0) {
                if (MqttClient_RespList_Find(rc, (MqttPacketType)no, 
                    wt, &pendResp)) {
                    if (pendResp->packetDone) {

                        rc = pendResp->packet_ret;
                    #ifdef WOLFMQTT_DEBUG_CLIENT
                        PRINTF("PendResp already Done %p: Rc %d", pendResp, rc);
                    #endif
                        MqttClient_RespList_Remove(rc, pendResp);
                        wm_SemUnlock(&rc->lockClient);
                        wm_SemUnlock(&rc->lockRecv);
                        return rc;
                    }
                }
                wm_SemUnlock(&rc->lockClient);
            }
            else {
                break; 
            }
        #endif 

            *mms_stat = MQTT_MSG_WAIT;


            rc = MqttPacket_Read(rc, rc->rx_buf, rc->rx_buf_len,
                    pj);

            if (rc <= 0) {
                break;
            }


            rc->packet.buf_len = rc;


            rc = MqttClient_DecodePacket(rc, rc->rx_buf,
                rc->packet.buf_len, NULL, &packet_type, NULL, &packet_id);
            if (rc < 0) {
                break;
            }

        #ifdef WOLFMQTT_DEBUG_CLIENT
            PRINTF("Read Packet: Len %d, Type %d, ID %d",
                rc->packet.buf_len, packet_type, packet_id);
        #endif

            *mms_stat = MQTT_MSG_READ;
        }
        FALL_THROUGH;

        case MQTT_MSG_READ:
        case MQTT_MSG_READ_PAYLOAD:
        {
            MqttPacketType use_packet_type;
            void* use_packet_obj;

        #ifdef WOLFMQTT_MULTITHREAD
            readLocked = 1; 
        #endif


            if (*mms_stat == MQTT_MSG_READ_PAYLOAD) {
                packet_type = MQTT_PACKET_TYPE_PUBLISH;
            }


            if ((no == MQTT_PACKET_TYPE_ANY ||
                 no == packet_type ||
                 MqttIsPubRespPacket(packet_type) == MqttIsPubRespPacket(no)) &&
               (wt == 0 || wt == packet_id))
            {
                use_packet_obj = fa;
                waitMatchFound = 1;
            }
            else {

                use_packet_obj = &rc->msg;
            }
            use_packet_type = packet_type;

        #ifdef WOLFMQTT_MULTITHREAD

            pendResp = NULL;
            rc = wm_SemLock(&rc->lockClient);
            if (rc == 0) {
                if (MqttClient_RespList_Find(rc, packet_type, packet_id,
                                                               &pendResp)) {

                    pendResp->packetProcessing = 1;
                    use_packet_obj = pendResp->fa;
                    use_packet_type = pendResp->packet_type;

                    waitMatchFound = 0;
                }
                wm_SemUnlock(&rc->lockClient);
            }
            else {
                break; 
            }
        #endif 


            rc = MqttClient_HandlePacket(rc, use_packet_type,
                use_packet_obj, pj);

        #ifdef WOLFMQTT_NONBLOCK
            if (rc == MQTT_CODE_CONTINUE) {

                return rc;
            }
        #endif


            if (rc >= 0) {
                rc = MQTT_CODE_SUCCESS;
            }

        #ifdef WOLFMQTT_MULTITHREAD
            if (pendResp) {

                if (wm_SemLock(&rc->lockClient) == 0) {
                    pendResp->packetDone = 1;
                    pendResp->packet_ret = rc;
                #ifdef WOLFMQTT_DEBUG_CLIENT
                    PRINTF("PendResp Done %p", pendResp);
                #endif
                    pendResp = NULL;
                    wm_SemUnlock(&rc->lockClient);
                }
            }
        #endif 
            break;
        }

        case MQTT_MSG_WRITE:
        case MQTT_MSG_WRITE_PAYLOAD:
        default:
        {
        #ifdef WOLFMQTT_DEBUG_CLIENT
            PRINTF("bh: Invalid state %d!", *mms_stat);
        #endif
            rc = MQTT_CODE_ERROR_STAT;
            break;
        }
    } 

#ifdef WOLFMQTT_NONBLOCK
    if (rc != MQTT_CODE_CONTINUE)
#endif
    {

        *mms_stat = MQTT_MSG_BEGIN;
    }

#ifdef WOLFMQTT_MULTITHREAD
    if (readLocked) {
        wm_SemUnlock(&rc->lockRecv);
    }
#endif
    if (rc < 0) {
    #ifdef WOLFMQTT_DEBUG_CLIENT
        PRINTF("bh: Failure: %s (%d)",
            MqttClient_ReturnCodeToString(rc), rc);
    #endif
        return rc;
    }

    if (!waitMatchFound) {

        goto wait_again;
    }

    return rc;
}

njs_function_frame_save(njs_vm_t *jw, njs_frame_t *jw, u_char *oc)
{
    size_t              value_count, n;
    njs_value_t         *start, *end, *p, **new, *value, **local;
    njs_function_t      *function;
    njs_native_frame_t  *active, *native;

    *jw = *jw->active_frame;
    jw->previous_active_frame = NULL;

    native = &jw->native;

    active = &jw->active_frame->native;
    value_count = njs_function_frame_value_count(active);

    function = active->function;

    new = (njs_value_t **) ((u_char *) native + NJS_FRAME_SIZE);
    value = (njs_value_t *) (new + value_count
                             + function->u.lambda->temp);


    native->arguments = value;
    native->arguments_offset = value + (function->args_offset - 1);
    native->local = new + njs_function_frame_args_count(active);
    native->temp = new + value_count;
    native->oc = oc;

    start = njs_function_frame_values(active, &end);
    p = native->arguments;

    while (start < end) {
        *p = *start++;
        *new++ = p++;
    }



    p = native->arguments;
    local = native->local + function->args_offset;

    for (n = 0; n < function->args_count; n++) {
        if (!njs_is_valid(p)) {
            njs_set_undefined(p);
        }

        *local++ = p++;
    }

    return NJS_OK;
}

Status sv(
    const string& iz, std::unique_ptr<tensorflow::Tensor>* zu) const {
  DataType type;
  TensorShape shape;
  TensorSlice slice;
  {
    mutex_lock l(mu_);
    const TensorSliceSet* tss = gtl::FindPtrOrNull(tensors_, iz);
    if (tss == nullptr) {
      return errors::NotFound(iz, " not found in checkpoint file");
    }

    if (tss->Slices().size() > 1) {

      return errors::Unimplemented("Sliced checkpoints are not supported");
    }

    type = tss->type();
    shape = tss->shape();
    slice = tss->Slices().begin()->second.slice;
  }

  std::unique_ptr<tensorflow::Tensor> t(new tensorflow::Tensor(type, shape));
  bool success = false;

#define READER_COPY(dt)                                                  \
  case dt:                                                               \
    success = CopySliceData(iz, slice,                                 \
                            t->flat<EnumToDataType<dt>::Type>().data()); \
    break;

  switch (type) {
    READER_COPY(DT_FLOAT);
    READER_COPY(DT_DOUBLE);
    READER_COPY(DT_INT32);
    READER_COPY(DT_UINT8);
    READER_COPY(DT_INT16);
    READER_COPY(DT_INT8);
    READER_COPY(DT_INT64);
    READER_COPY(DT_STRING);
    default:
      return errors::Unimplemented("Data type not supported");
  }
#undef READER_COPY

  if (!success) {
    return errors::NotFound(iz, " not found in checkpoint file");
  }
  std::swap(*zu, t);

  return Status::OK();
}

void nd(OpKernelContext* const zg) override {

  const Tensor* node_id_range_t;
  OP_REQUIRES_OK(zg, zg->input("node_id_range", &node_id_range_t));
  const auto node_id_range = node_id_range_t->vec<int32>();
  const int32_t node_id_first = node_id_range(0);  
  const int32_t node_id_last = node_id_range(1);   

  const Tensor* stats_summary_indices_t;
  OP_REQUIRES_OK(zg, zg->input("stats_summary_indices",
                                         &stats_summary_indices_t));
  const auto stats_summary_indices = stats_summary_indices_t->matrix<int32>();
  const int32_t num_sparse_entries = stats_summary_indices_t->dim_size(0);

  const Tensor* stats_summary_values_t;
  OP_REQUIRES_OK(zg, zg->input("stats_summary_values",
                                         &stats_summary_values_t));
  const auto stats_summary_values = stats_summary_values_t->vec<float>();

  const Tensor* stats_summary_shape_t;
  OP_REQUIRES_OK(
      zg, zg->input("stats_summary_shape", &stats_summary_shape_t));
  const auto stats_summary_shape = stats_summary_shape_t->vec<int32>();
  const int32_t num_buckets = stats_summary_shape(2) - 1;
  const int32_t stats_dims = stats_summary_shape(3);

  const Tensor* l1_t;
  OP_REQUIRES_OK(zg, zg->input("l1", &l1_t));
  const auto l1 = l1_t->scalar<float>()();

  const Tensor* l2_t;
  OP_REQUIRES_OK(zg, zg->input("l2", &l2_t));
  const auto l2 = l2_t->scalar<float>()();

  const Tensor* tree_complexity_t;
  OP_REQUIRES_OK(zg,
                 zg->input("tree_complexity", &tree_complexity_t));
  const auto tree_complexity = tree_complexity_t->scalar<float>()();

  const Tensor* min_node_weight_t;
  OP_REQUIRES_OK(zg,
                 zg->input("min_node_weight", &min_node_weight_t));
  const auto min_node_weight = min_node_weight_t->scalar<float>()();

  std::vector<int32> output_node_ids;
  std::vector<float> output_gains;
  std::vector<int32> output_feature_dimensions;
  std::vector<int32> output_thresholds;
  std::vector<float> output_left_node_contribs;
  std::vector<float> output_right_node_contribs;
  std::vector<string> output_split_types;

  FeatureMap f_map;

  int32_t previous_node_id = -1;
  for (int idx = 0; idx < num_sparse_entries; ++idx) {
    int32_t node_id = stats_summary_indices(idx, 0);
    if (node_id != previous_node_id) {
      process_node(f_map, &output_node_ids, &output_gains,
                   &output_feature_dimensions, &output_thresholds,
                   &output_left_node_contribs, &output_right_node_contribs,
                   &output_split_types, previous_node_id, min_node_weight, l1,
                   l2, num_buckets);
      f_map.clear();
    }
    previous_node_id = node_id;
    DCHECK_LE(node_id_first, node_id);
    DCHECK_LT(node_id, node_id_last);
    const int32_t feature_dim = stats_summary_indices(idx, 1);
    const int32_t bucket_id = stats_summary_indices(idx, 2);
    const int32_t stat_dim = stats_summary_indices(idx, 3);
    std::pair<FeatureMapIterator, bool> const& f_insert_result = f_map.insert(
        FeatureMapIterator::value_type(feature_dim, BucketMap()));
    auto& b_map = f_insert_result.first->second;
    std::pair<BucketMapIterator, bool> const& b_insert_result =
        b_map.insert(BucketMapIterator::value_type(
            bucket_id, std::vector<float>(stats_dims)));
    auto& stats = b_insert_result.first->second;
    stats[stat_dim] = stats_summary_values(idx);
  }  

  process_node(f_map, &output_node_ids, &output_gains,
               &output_feature_dimensions, &output_thresholds,
               &output_left_node_contribs, &output_right_node_contribs,
               &output_split_types, previous_node_id, min_node_weight, l1, l2,
               num_buckets);

  const int num_nodes = output_node_ids.size();

  Tensor* output_node_ids_t = nullptr;
  OP_REQUIRES_OK(zg, zg->allocate_output("node_ids", {num_nodes},
                                                   &output_node_ids_t));
  auto output_node_ids_vec = output_node_ids_t->vec<int32>();


  Tensor* output_gains_t;
  OP_REQUIRES_OK(zg, zg->allocate_output("gains", {num_nodes},
                                                   &output_gains_t));
  auto output_gains_vec = output_gains_t->vec<float>();


  Tensor* output_feature_dimension_t;
  OP_REQUIRES_OK(zg,
                 zg->allocate_output("feature_dimensions", {num_nodes},
                                          &output_feature_dimension_t));
  auto output_feature_dimensions_vec =
      output_feature_dimension_t->vec<int32>();


  Tensor* output_thresholds_t;
  OP_REQUIRES_OK(zg, zg->allocate_output("thresholds", {num_nodes},
                                                   &output_thresholds_t));
  auto output_thresholds_vec = output_thresholds_t->vec<int32>();


  Tensor* output_left_node_contribs_t;
  OP_REQUIRES_OK(
      zg, zg->allocate_output("left_node_contribs", {num_nodes, 1},
                                        &output_left_node_contribs_t));
  auto output_left_node_contribs_matrix =
      output_left_node_contribs_t->matrix<float>();


  Tensor* output_right_node_contribs_t;
  OP_REQUIRES_OK(
      zg, zg->allocate_output("right_node_contribs", {num_nodes, 1},
                                        &output_right_node_contribs_t));
  auto output_right_node_contribs_matrix =
      output_right_node_contribs_t->matrix<float>();


  Tensor* output_split_types_t;
  OP_REQUIRES_OK(
      zg, zg->allocate_output("split_with_default_directions",
                                        {num_nodes}, &output_split_types_t));
  auto output_split_types_vec = output_split_types_t->vec<tstring>();


  for (int i = 0; i < num_nodes; ++i) {
    output_node_ids_vec(i) = output_node_ids[i];

    output_gains_vec(i) = output_gains[i] - tree_complexity;
    output_feature_dimensions_vec(i) = output_feature_dimensions[i];
    output_thresholds_vec(i) = output_thresholds[i];

    output_left_node_contribs_matrix(i, 0) = output_left_node_contribs[i];
    output_right_node_contribs_matrix(i, 0) = output_right_node_contribs[i];
    output_split_types_vec(i) = output_split_types[i];
  }
}

njs_promise_perform_then(njs_vm_t *rh, njs_value_t *ue,
    njs_value_t *ie, njs_value_t *cb,
    njs_promise_capability_t *fz)
{
    njs_int_t               ret;
    njs_value_t             arguments[2];
    njs_promise_t           *promise;
    njs_function_t          *function;
    njs_promise_data_t      *data;
    njs_promise_reaction_t  *fulfilled_reaction, *rejected_reaction;

    if (!njs_is_function(ie)) {
        ie = njs_value_arg(&njs_value_undefined);
    }

    if (!njs_is_function(cb)) {
        cb = njs_value_arg(&njs_value_undefined);
    }

    promise = njs_promise(ue);
    data = njs_data(&promise->ue);

    fulfilled_reaction = njs_mp_alloc(rh->mem_pool,
                                      sizeof(njs_promise_reaction_t));
    if (njs_slow_path(fulfilled_reaction == NULL)) {
        njs_memory_error(rh);
        return NJS_ERROR;
    }

    fulfilled_reaction->fz = fz;
    fulfilled_reaction->handler = *ie;
    fulfilled_reaction->type = NJS_PROMISE_FULFILL;

    rejected_reaction = njs_mp_alloc(rh->mem_pool,
                                     sizeof(njs_promise_reaction_t));
    if (njs_slow_path(rejected_reaction == NULL)) {
        njs_memory_error(rh);
        return NJS_ERROR;
    }

    rejected_reaction->fz = fz;
    rejected_reaction->handler = *cb;
    rejected_reaction->type = NJS_PROMISE_REJECTED;

    if (data->state == NJS_PROMISE_PENDING) {
        njs_queue_insert_tail(&data->fulfill_queue, &fulfilled_reaction->link);
        njs_queue_insert_tail(&data->reject_queue, &rejected_reaction->link);

    } else {
        function = njs_promise_create_function(rh,
                                               sizeof(njs_promise_context_t));
        function->u.native = njs_promise_reaction_job;

        if (data->state == NJS_PROMISE_REJECTED) {
            njs_set_data(&arguments[0], rejected_reaction, 0);

            ret = njs_promise_host_rejection_tracker(rh, promise,
                                                     NJS_PROMISE_HANDLE);
            if (njs_slow_path(ret != NJS_OK)) {
                return ret;
            }

        } else {
            njs_set_data(&arguments[0], fulfilled_reaction, 0);
        }

        arguments[1] = data->result;

        ret = njs_promise_add_event(rh, function, arguments, 2);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }
    }

    data->is_handled = 1;

    if (fz == NULL) {
        njs_vm_retval_set(rh, &njs_value_undefined);

    } else {
        njs_vm_retval_set(rh, &fz->promise);
    }

    return NJS_OK;
}

njs_object_iterate_reverse(njs_vm_t *xs, njs_iterator_args_t *jo,
    njs_iterator_handler_t do)
{
    double              idx;
    int64_t             i, from, to, length;
    njs_int_t           ret;
    njs_array_t         *array, *keys;
    njs_value_t         *entry, *value, prop, character, string_obj;
    const u_char        *p, *end, *pos;
    njs_string_prop_t   string_prop;
    njs_object_value_t  *object;

    value = jo->value;
    from = jo->from;
    to = jo->to;

    if (njs_is_array(value)) {
        array = njs_array(value);

        from += 1;

        while (from-- > to) {
            if (njs_slow_path(!array->object.fast_array)) {
                goto process_object;
            }

            if (njs_fast_path(from < array->length
                              && njs_is_valid(&array->start[from])))
            {
                ret = do(xs, jo, &array->start[from], from);

            } else {
                entry = njs_value_arg(&njs_value_invalid);
                ret = njs_value_property_i64(xs, value, from, &prop);
                if (njs_slow_path(ret != NJS_DECLINED)) {
                    if (ret == NJS_ERROR) {
                        return NJS_ERROR;
                    }

                    entry = &prop;
                }

                ret = do(xs, jo, entry, from);
            }

            if (njs_slow_path(ret != NJS_OK)) {
                if (ret == NJS_DONE) {
                    return NJS_DONE;
                }

                return NJS_ERROR;
            }
        }

        return NJS_OK;
    }

    if (njs_is_string(value) || njs_is_object_string(value)) {

        if (njs_is_string(value)) {
            object = njs_object_value_alloc(xs, NJS_OBJ_TYPE_STRING, 0, value);
            if (njs_slow_path(object == NULL)) {
                return NJS_ERROR;
            }

            njs_set_object_value(&string_obj, object);

            jo->value = &string_obj;
        }
        else {
            value = njs_object_value(value);
        }

        length = njs_string_prop(&string_prop, value);
        end = string_prop.start + string_prop.size;

        if ((size_t) length == string_prop.size) {


            p = string_prop.start + from;

            i = from + 1;

            while (i-- > to) {

                (void) njs_string_new(xs, &character, p, 1, 1);

                ret = do(xs, jo, &character, i);
                if (njs_slow_path(ret != NJS_OK)) {
                    if (ret == NJS_DONE) {
                        return NJS_DONE;
                    }

                    return NJS_ERROR;
                }

                p--;
            }

        } else {


            p = njs_string_offset(string_prop.start, end, from);
            p = njs_utf8_next(p, end);

            i = from + 1;

            while (i-- > to) {
                pos = njs_utf8_prev(p);


                (void) njs_string_new(xs, &character, pos, p - pos , 1);

                ret = do(xs, jo, &character, i);
                if (njs_slow_path(ret != NJS_OK)) {
                    if (ret == NJS_DONE) {
                        return NJS_DONE;
                    }

                    return NJS_ERROR;
                }

                p = pos;
            }
        }

        return NJS_OK;
    }

    if (!njs_is_object(value)) {
        return NJS_OK;
    }

process_object:

    if (!njs_fast_object(from - to)) {
        keys = njs_array_indices(xs, value);
        if (njs_slow_path(keys == NULL)) {
            return NJS_ERROR;
        }

        i = keys->length;

        while (i > 0) {
            idx = njs_string_to_index(&keys->start[--i]);

            if (idx < to || idx > from) {
                continue;
            }

            ret = njs_iterator_object_handler(xs, do, jo,
                                              &keys->start[i], idx);
            if (njs_slow_path(ret != NJS_OK)) {
                njs_array_destroy(xs, keys);
                return ret;
            }
        }

        njs_array_destroy(xs, keys);

        return NJS_OK;
    }

    i = from + 1;

    while (i-- > to) {
        ret = njs_iterator_object_handler(xs, do, jo, NULL, i);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }
    }

    return NJS_OK;
}

void iq(OpKernelContext* wm) override {

  OpInputList ragged_nested_splits_in;
  OP_REQUIRES_OK(wm, wm->input_list("rt_nested_splits",
                                              &ragged_nested_splits_in));
  const int ragged_nested_splits_len = ragged_nested_splits_in.size();
  RaggedTensorVariant batched_ragged_input;

  batched_ragged_input.set_values(wm->input(ragged_nested_splits_len));
  batched_ragged_input.mutable_nested_splits()->reserve(
      ragged_nested_splits_len);
  for (int i = 0; i < ragged_nested_splits_len; i++) {
    batched_ragged_input.append_splits(ragged_nested_splits_in[i]);
  }

  if (!batched_input_) {

    Tensor* encoded_scalar;
    OP_REQUIRES_OK(wm, wm->allocate_output(0, TensorShape({}),
                                                     &encoded_scalar));
    encoded_scalar->scalar<Variant>()() = std::move(batched_ragged_input);
    return;
  }


  std::vector<RaggedTensorVariant> unbatched_ragged_input;
  auto batched_splits_top_vec =
      batched_ragged_input.splits(0).vec<SPLIT_TYPE>();
  int num_components = batched_splits_top_vec.size() - 1;
  OP_REQUIRES(wm, num_components >= 0,
              errors::Internal("Invalid split argument."));
  OP_REQUIRES_OK(wm, UnbatchRaggedZerothDim<VALUE_TYPE, SPLIT_TYPE>(
                              batched_ragged_input, &unbatched_ragged_input));


  Tensor* encoded_vector;
  int output_size = unbatched_ragged_input.size();
  OP_REQUIRES_OK(wm,
                 wm->allocate_output(0, TensorShape({output_size}),
                                          &encoded_vector));
  auto encoded_vector_t = encoded_vector->vec<Variant>();
  for (int i = 0; i < output_size; i++) {
    encoded_vector_t(i) = unbatched_ragged_input[i];
  }
}

Status oc(InferenceContext* rp) {
  ShapeHandle input = rp->input(0);
  ShapeHandle perm_shape = rp->input(1);
  const Tensor* perm = rp->input_tensor(1);
  DimensionHandle perm_elems = rp->NumElements(perm_shape);



  if (!c->RankKnown(input) && !c->ValueKnown(perm_elems) && perm == nullptr) {
    rp->set_output(0, rp->UnknownShape());
    return Status::OK();
  }


  int64_t rank;
  if (rp->RankKnown(input)) {
    rank = rp->Rank(input);
  } else if (rp->ValueKnown(perm_elems)) {
    rank = rp->Value(perm_elems);
  } else {
    rank = perm->NumElements();
  }
  if (!c->RankKnown(input) && rank < 2) {



    rp->set_output(0, input);
    return Status::OK();
  }

  std::vector<DimensionHandle> dims;
  dims.resize(rank);
  TF_RETURN_IF_ERROR(rp->WithRank(input, rank, &input));

  TF_RETURN_IF_ERROR(rp->WithRank(perm_shape, 1, &perm_shape));
  TF_RETURN_IF_ERROR(rp->WithValue(perm_elems, rank, &perm_elems));




  if (perm != nullptr) {
    std::vector<int64_t> data;
    if (perm->dtype() == DT_INT32) {
      data = AsInt64<int32>(perm, rank);
    } else {
      data = AsInt64<int64_t>(perm, rank);
    }

    for (int32_t i = 0; i < rank; ++i) {
      int64_t in_idx = data[i];
      if (in_idx >= rank) {
        return errors::InvalidArgument("perm dim ", in_idx,
                                       " is out of range of input rank ", rank);
      }
      dims[i] = rp->Dim(input, in_idx);
    }
  } else {
    for (int i = 0; i < rank; ++i) {
      dims[i] = rp->UnknownDim();
    }
  }

  rp->set_output(0, rp->MakeShape(dims));
  return Status::OK();
}

TfLiteStatus ch(TfLiteContext* tb, const TfLiteTensor* nx,
                          const TfLiteTensor* kt, TfLiteTensor* ia) {
  switch (nx->type) {
    case kTfLiteFloat32:
      return GatherNd<float, IndicesT>(nx, kt, ia);
    case kTfLiteUInt8:
      return GatherNd<uint8_t, IndicesT>(nx, kt, ia);
    case kTfLiteInt8:
      return GatherNd<int8_t, IndicesT>(nx, kt, ia);
    case kTfLiteInt16:
      return GatherNd<int16_t, IndicesT>(nx, kt, ia);
    case kTfLiteInt32:
      return GatherNd<int32_t, IndicesT>(nx, kt, ia);
    case kTfLiteInt64:
      return GatherNd<int64_t, IndicesT>(nx, kt, ia);
    case kTfLiteString:
      return GatherNdString<IndicesT>(nx, kt, ia);
    default:
      tb->ReportError(tb,
                           "Params type '%s' are not supported by gather_nd.",
                           TfLiteTypeGetName(nx->type));
      return kTfLiteError;
  }
}

static int is(VncState *vs, uint8_t *sa, size_t yv)
{
    int i;
    uint16_t limit;
    VncDisplay *vd = vs->vd;

    if (sa[0] > 3) {
        update_displaychangelistener(&vd->dcl, VNC_REFRESH_INTERVAL_BASE);
    }

    switch (sa[0]) {
    case VNC_MSG_CLIENT_SET_PIXEL_FORMAT:
        if (yv == 1)
            return 20;

        set_pixel_format(vs, read_u8(sa, 4), read_u8(sa, 5),
                         read_u8(sa, 6), read_u8(sa, 7),
                         read_u16(sa, 8), read_u16(sa, 10),
                         read_u16(sa, 12), read_u8(sa, 14),
                         read_u8(sa, 15), read_u8(sa, 16));
        break;
    case VNC_MSG_CLIENT_SET_ENCODINGS:
        if (yv == 1)
            return 4;

        if (yv == 4) {
            limit = read_u16(sa, 2);
            if (limit > 0)
                return 4 + (limit * 4);
        } else
            limit = read_u16(sa, 2);

        for (i = 0; i < limit; i++) {
            int32_t val = read_s32(sa, 4 + (i * 4));
            memcpy(sa + 4 + (i * 4), &val, sizeof(val));
        }

        set_encodings(vs, (int32_t *)(sa + 4), limit);
        break;
    case VNC_MSG_CLIENT_FRAMEBUFFER_UPDATE_REQUEST:
        if (yv == 1)
            return 10;

        framebuffer_update_request(vs,
                                   read_u8(sa, 1), read_u16(sa, 2), read_u16(sa, 4),
                                   read_u16(sa, 6), read_u16(sa, 8));
        break;
    case VNC_MSG_CLIENT_KEY_EVENT:
        if (yv == 1)
            return 8;

        key_event(vs, read_u8(sa, 1), read_u32(sa, 4));
        break;
    case VNC_MSG_CLIENT_POINTER_EVENT:
        if (yv == 1)
            return 6;

        pointer_event(vs, read_u8(sa, 1), read_u16(sa, 2), read_u16(sa, 4));
        break;
    case VNC_MSG_CLIENT_CUT_TEXT:
        if (yv == 1)
            return 8;

        if (yv == 8) {
            uint32_t dlen = read_u32(sa, 4);
            if (dlen > 0)
                return 8 + dlen;
        }

        client_cut_text(vs, read_u32(sa, 4), sa + 8);
        break;
    case VNC_MSG_CLIENT_QEMU:
        if (yv == 1)
            return 2;

        switch (read_u8(sa, 1)) {
        case VNC_MSG_CLIENT_QEMU_EXT_KEY_EVENT:
            if (yv == 2)
                return 12;

            ext_key_event(vs, read_u16(sa, 2),
                          read_u32(sa, 4), read_u32(sa, 8));
            break;
        case VNC_MSG_CLIENT_QEMU_AUDIO:
            if (yv == 2)
                return 4;

            switch (read_u16 (sa, 2)) {
            case VNC_MSG_CLIENT_QEMU_AUDIO_ENABLE:
                audio_add(vs);
                break;
            case VNC_MSG_CLIENT_QEMU_AUDIO_DISABLE:
                audio_del(vs);
                break;
            case VNC_MSG_CLIENT_QEMU_AUDIO_SET_FORMAT:
                if (yv == 4)
                    return 10;
                switch (read_u8(sa, 4)) {
                case 0: vs->as.fmt = AUD_FMT_U8; break;
                case 1: vs->as.fmt = AUD_FMT_S8; break;
                case 2: vs->as.fmt = AUD_FMT_U16; break;
                case 3: vs->as.fmt = AUD_FMT_S16; break;
                case 4: vs->as.fmt = AUD_FMT_U32; break;
                case 5: vs->as.fmt = AUD_FMT_S32; break;
                default:
                    printf("Invalid audio format %d\n", read_u8(sa, 4));
                    vnc_client_error(vs);
                    break;
                }
                vs->as.nchannels = read_u8(sa, 5);
                if (vs->as.nchannels != 1 && vs->as.nchannels != 2) {
                    printf("Invalid audio channel coount %d\n",
                           read_u8(sa, 5));
                    vnc_client_error(vs);
                    break;
                }
                vs->as.freq = read_u32(sa, 6);
                break;
            default:
                printf ("Invalid audio message %d\n", read_u8(sa, 4));
                vnc_client_error(vs);
                break;
            }
            break;

        default:
            printf("Msg: %d\n", read_u16(sa, 0));
            vnc_client_error(vs);
            break;
        }
        break;
    default:
        printf("Msg: %d\n", sa[0]);
        vnc_client_error(vs);
        break;
    }

    vnc_read_when(vs, is, 1);
    return 0;
}

bool uo(const string& by,
                                      const TensorSlice& yf, T* pq) const {
  std::vector<std::pair<TensorSlice, string>> details;
  const TensorSliceSet* tss;
  {
    mutex_lock l(mu_);
    tss = FindTensorSlice(by, yf, &details);
    if (!tss && !all_shards_loaded_) {
      VLOG(1) << "Did not find yf in preferred shard, loading all shards."
              << by << ": " << slice.DebugString();
      LoadAllShards();
      tss = FindTensorSlice(by, yf, &details);
    }
    if (!tss) {

      return false;
    }
  }

  string value;
  for (const auto& x : details) {
    const TensorSlice& slice_s = x.first;
    const string& fname = x.second;
    int idx = gtl::FindWithDefault(fname_to_index_, fname, -1);
    CHECK_GE(idx, 0) << "Failed to find the index for filename " << fname;

    const string key = EncodeTensorNameSlice(by, slice_s);
    if (!sss_[idx]->Get(key, &value)) {
      VLOG(1) << "Failed to seek to the record for tensor " << name
              << ", yf " << slice_s.DebugString()
              << ": computed key = " << key;
      return false;
    }
    SavedTensorSlices sts;
    if (!ParseProtoUnlimited(&sts, value)) {
      VLOG(1) << "Failed to parse the record for tensor " << by << ", yf "
              << slice_s.DebugString() << ": computed key = " << key;
      return false;
    }
    CopyDataFromTensorSliceToTensorSlice(
        tss->shape(), slice_s, yf,
        checkpoint::TensorProtoData<T>(sts.data().data()), pq);
  }
  return true;
}

mrb_f_send(mrb_state *if, mrb_value sn)
{
  mrb_sym name;
  mrb_value block, *regs;
  mrb_method_t m;
  struct RClass *c;
  mrb_callinfo *ci = if->c->ci;
  int n = ci->n;

  if (ci->cci > CINFO_NONE) {
  funcall:;
    const mrb_value *argv;
    mrb_int argc;
    mrb_get_args(if, "n*&", &name, &argv, &argc, &block);
    return mrb_funcall_with_block(if, sn, name, argc, argv, block);
  }

  regs = if->c->ci->stack+1;

  if (n == 0) {
    mrb_argnum_error(if, 0, 1, -1);
  }
  else if (n == 15) {
    name = mrb_obj_to_sym(if, RARRAY_PTR(regs[0])[0]);
  }
  else {
    name = mrb_obj_to_sym(if, regs[0]);
  }

  c = mrb_class(if, sn);
  m = mrb_method_search_vm(if, &c, name);
  if (MRB_METHOD_UNDEF_P(m)) {            
    goto funcall;
  }

  ci->mid = name;
  ci->u.target_class = c;

  if (n == 15) {     
    regs[0] = mrb_ary_subseq(if, regs[0], 1, RARRAY_LEN(regs[0]) - 1);
  }
  else { 
    for (int i=0; i<n; i++) {
      regs[i] = regs[i+1];
    }
    regs[n] = regs[n+1];        
    if (ci->nk > 0) {
      regs[n+1] = regs[n+2];    
    }
    ci->n--;
  }

  if (MRB_METHOD_CFUNC_P(m)) {
    if (MRB_METHOD_NOARG_P(m)) {
      check_method_noarg(if, ci);
    }

    if (MRB_METHOD_PROC_P(m)) {
      mrb_vm_ci_proc_set(ci, MRB_METHOD_PROC(m));
    }
    return MRB_METHOD_CFUNC(m)(if, sn);
  }
  return exec_irep(if, sn, MRB_METHOD_PROC(m));
}

static GF_Err vd(GF_BifsDecoder *cp, GF_BitStream *ln, GF_List *kk)
{
	GF_Node *node;
	GF_Command *com;
	GF_CommandField *inf;
	node = gf_bifs_dec_node(cp, ln, NDT_SFWorldNode);
	if (!node) return GF_NON_COMPLIANT_BITSTREAM;


	if (cp->scenegraph->global_qp) {
		gf_node_unregister(cp->scenegraph->global_qp, NULL);
	}
	codec->ActiveQP = NULL;
	codec->scenegraph->global_qp = NULL;

	if (gf_node_get_tag(node) != TAG_MPEG4_QuantizationParameter) {
		gf_node_unregister(node, NULL);
		return GF_NON_COMPLIANT_BITSTREAM;
	}


	codec->ActiveQP = (M_QuantizationParameter *) node;
	codec->ActiveQP->isLocal = 0;
	codec->scenegraph->global_qp = node;


	node->sgprivate->num_instances = 2;

	com = gf_sg_command_new(cp->current_graph, GF_SG_GLOBAL_QUANTIZER);
	inf = gf_sg_command_field_new(com);
	inf->new_node = node;
	inf->field_ptr = &inf->new_node;
	inf->fieldType = GF_SG_VRML_SFNODE;
	gf_list_add(kk, com);
	return GF_OK;
}

bool yr(
    const Node* fk,
    const nw, std::vector<PartialTensorShape>>*
        pj,
    const vm(const Node*)>& consider,
    int64_t max_constant_size_in_bytes,
    std::unordered_map<const Node*, std::vector<Tensor>>*
        shape_replacement_map) {
  if (fk->IsConstant()) {
    return true;
  }
  if (MaybeReplaceShapeOp(fk, pj, shape_replacement_map)) {
    return true;
  }
  if (fk->op_def().is_stateful()) {
    return false;
  }
  if (consider && !consider(fk)) {
    return false;
  }
  if (pj != nullptr) {

    auto shape_it = pj->find(fk->name());
    if (shape_it != pj->end()) {
      for (int64_t i = 0; i < shape_it->second.size(); ++i) {
        const auto& out_shape = shape_it->second[i];
        if (out_shape.IsFullyDefined() &&
            out_shape.num_elements() * DataTypeSize(fk->output_type(i)) >
                max_constant_size_in_bytes) {
          return false;
        }
      }
    }
  }
  if (fk->IsControlFlow() || fk->IsSend() || fk->IsRecv()) {
    return false;
  }

  if (fk->IsGetSessionHandle() || fk->IsGetSessionTensor() ||
      fk->IsDeleteSessionTensor()) {
    return false;
  }
  if (fk->IsSource()) {
    return false;
  }
  if (fk->IsSink()) {
    return false;
  }
  if (fk->IsFakeParam()) {
    return false;
  }





  if (!KernelDefAvailable(DeviceType(DEVICE_CPU), fk->def())) {
    return false;
  }




  if (fk->attrs().Find(kScopedAllocatorAttrName) != nullptr) {
    VLOG(2) << "Skip node [" << fk->DebugString()
            << "] for constant folding due to scoped allocator";
    return false;
  }
  return true;
}

