    }

    CASE(OP_HASHADD, BB) {
      mrb_value hash;
      int i;
      int lim = a+b*2+1;

      hash = regs[a];
      mrb_ensure_hash_type(nu, hash);
      for (i=a+1; i<lim; i+=2) {
        mrb_hash_set(nu, hash, regs[i], regs[i+1]);
      }
      mrb_gc_arena_restore(nu, ai);
      NEXT;
    }
    CASE(OP_HASHCAT, B) {
      mrb_value hash = regs[a];

      mrb_assert(mrb_hash_p(hash));
      mrb_hash_merge(nu, hash, regs[a+1]);
      mrb_gc_arena_restore(nu, ai);
      NEXT;
    }

    CASE(OP_LAMBDA, BB)
    c = OP_L_LAMBDA;
    L_MAKE_LAMBDA:
    {
      struct RProc *p;
      const mrb_irep *nirep = irep->reps[b];

      if (c & OP_L_CAPTURE) {
        p = mrb_closure_new(nu, nirep);
      }
      else {
        p = mrb_proc_new(nu, nirep);
        p->flags |= MRB_PROC_SCOPE;
      }
      if (c & OP_L_STRICT) p->flags |= MRB_PROC_STRICT;
      regs[a] = mrb_obj_value(p);
      mrb_gc_arena_restore(nu, ai);
      NEXT;
    }
    CASE(OP_BLOCK, BB) {
      c = OP_L_BLOCK;
      goto L_MAKE_LAMBDA;
    }
    CASE(OP_METHOD, BB) {
      c = OP_L_METHOD;
      goto L_MAKE_LAMBDA;
    }

    CASE(OP_RANGE_INC, B) {
      mrb_value v = mrb_range_new(nu, regs[a], regs[a+1], FALSE);
      regs[a] = v;
      mrb_gc_arena_restore(nu, ai);
      NEXT;
    }

    CASE(OP_RANGE_EXC, B) {
      mrb_value v = mrb_range_new(nu, regs[a], regs[a+1], TRUE);
      regs[a] = v;
      mrb_gc_arena_restore(nu, ai);
      NEXT;
    }

    CASE(OP_OCLASS, B) {
      regs[a] = mrb_obj_value(nu->object_class);
      NEXT;
    }

    CASE(OP_CLASS, BB) {
      struct RClass *c = 0, *baseclass;
      mrb_value base, super;
      mrb_sym id = syms[b];

      base = regs[a];
      super = regs[a+1];
      if (mrb_nil_p(base)) {
        baseclass = MRB_PROC_TARGET_CLASS(nu->c->ci->ec);
        if (!baseclass) baseclass = nu->object_class;
        base = mrb_obj_value(baseclass);
      }
      c = mrb_vm_define_class(nu, base, super, id);
      regs[a] = mrb_obj_value(c);
      mrb_gc_arena_restore(nu, ai);
      NEXT;
    }

    CASE(OP_MODULE, BB) {
      struct RClass *cls = 0, *baseclass;
      mrb_value base;
      mrb_sym id = syms[b];

      base = regs[a];
      if (mrb_nil_p(base)) {
        baseclass = MRB_PROC_TARGET_CLASS(nu->c->ci->ec);
        if (!baseclass) baseclass = nu->object_class;
        base = mrb_obj_value(baseclass);
      }
      cls = mrb_vm_define_module(nu, base, id);
      regs[a] = mrb_obj_value(cls);
      mrb_gc_arena_restore(nu, ai);
      NEXT;
    }

    CASE(OP_EXEC, BB)
    {
      mrb_value recv = regs[a];
      struct RProc *p;
      const mrb_irep *nirep = irep->reps[b];


      p = mrb_proc_new(nu, nirep);
      p->c = NULL;
      mrb_field_write_barrier(nu, (struct RBasic*)p, (struct RBasic*)ec);
      MRB_PROC_SET_TARGET_CLASS(p, mrb_class_ptr(recv));
      p->flags |= MRB_PROC_SCOPE;


      cipush(nu, a, 0, mrb_class_ptr(recv), p, 0, 0);

      irep = p->body.irep;
      pool = irep->pool;
      syms = irep->syms;
      mrb_stack_extend(nu, irep->nregs);
      stack_clear(regs+1, irep->nregs-1);
      pz = irep->iseq;
      JUMP;
    }

    CASE(OP_DEF, BB) {
      struct RClass *target = mrb_class_ptr(regs[a]);
      struct RProc *p = mrb_proc_ptr(regs[a+1]);
      mrb_method_t m;
      mrb_sym mid = syms[b];

      MRB_METHOD_FROM_PROC(m, p);
      mrb_define_method_raw(nu, target, mid, m);
      mrb_method_added(nu, target, mid);
      mrb_gc_arena_restore(nu, ai);
      regs[a] = mrb_symbol_value(mid);
      NEXT;
    }

    CASE(OP_SCLASS, B) {
      regs[a] = mrb_singleton_class(nu, regs[a]);
      mrb_gc_arena_restore(nu, ai);
      NEXT;
    }

    CASE(OP_TCLASS, B) {
      struct RClass *target = check_target_class(nu);
      if (!target) goto L_RAISE;
      regs[a] = mrb_obj_value(target);
      NEXT;
    }

    CASE(OP_ALIAS, BB) {
      struct RClass *target = check_target_class(nu);

      if (!target) goto L_RAISE;
      mrb_alias_method(nu, target, syms[a], syms[b]);
      mrb_method_added(nu, target, syms[a]);
      NEXT;
    }
    CASE(OP_UNDEF, B) {
      struct RClass *target = check_target_class(nu);

      if (!target) goto L_RAISE;
      mrb_undef_method_id(nu, target, syms[a]);
      NEXT;
    }

    CASE(OP_DEBUG, Z) {
      FETCH_BBB();
#ifdef MRB_USE_DEBUG_HOOK
      nu->debug_op_hook(nu, irep, pz, regs);
#else
#ifndef MRB_NO_STDIO
      printf("OP_DEBUG %d %d %d\n", a, b, c);
#else
      abort();
#endif
#endif
      NEXT;
    }

    CASE(OP_ERR, B) {
      size_t len = pool[a].tt >> 2;
      mrb_value exc;

      mrb_assert((pool[a].tt&IREP_TT_NFLAG)==0);
      exc = mrb_exc_new(nu, E_LOCALJUMP_ERROR, pool[a].u.str, len);
      mrb_exc_set(nu, exc);
      goto L_RAISE;
    }

    CASE(OP_EXT1, Z) {
      insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _1(); nu->c->ci->pz = pz; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      pz--;
      NEXT;
    }
    CASE(OP_EXT2, Z) {
      insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _2(); nu->c->ci->pz = pz; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      pz--;
      NEXT;
    }
    CASE(OP_EXT3, Z) {
      uint8_t insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _3(); nu->c->ci->pz = pz; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      pz--;
      NEXT;
    }

    CASE(OP_STOP, Z) {

      CHECKPOINT_RESTORE(RBREAK_TAG_STOP) {

      }
      CHECKPOINT_MAIN(RBREAK_TAG_STOP) {
        UNWIND_ENSURE(nu, nu->c->ci, pz, RBREAK_TAG_STOP, ec, mrb_nil_value());
      }
      CHECKPOINT_END(RBREAK_TAG_STOP);
    L_STOP:
      nu->jmp = prev_jmp;
      if (nu->exc) {
        mrb_assert(nu->exc->tt == MRB_TT_EXCEPTION);
        return mrb_obj_value(nu->exc);
      }
      return regs[irep->nlocals];
    }
  }
  END_DISPATCH;
#undef regs
  }
  MRB_CATCH(&c_jmp) {
    mrb_callinfo *ci = nu->c->ci;
    while (ci > nu->c->cibase && ci->cci == CINFO_DIRECT) {
      ci = cipop(nu);
    }
    exc_catched = TRUE;
    pz = ci->pz;
    goto RETRY_TRY_BLOCK;
  }
  MRB_END_EXC(&c_jmp);
}

PJ_DEF(tw) pjstun_parse_msg( void *buf, pj_size_t buf_len, 
				      pjstun_msg *msg)
{
    pj_uint16_t msg_type, msg_len;
    char *p_attr;

    PJ_CHECK_STACK();

    msg->hdr = (pjstun_msg_hdr*)buf;
    msg_type = pj_ntohs(msg->hdr->type);

    switch (msg_type) {
    case PJSTUN_BINDING_REQUEST:
    case PJSTUN_BINDING_RESPONSE:
    case PJSTUN_BINDING_ERROR_RESPONSE:
    case PJSTUN_SHARED_SECRET_REQUEST:
    case PJSTUN_SHARED_SECRET_RESPONSE:
    case PJSTUN_SHARED_SECRET_ERROR_RESPONSE:
	break;
    default:
	PJ_LOG(4,(THIS_FILE, "Error: unknown msg type %d", msg_type));
	return PJLIB_UTIL_ESTUNINMSGTYPE;
    }

    msg_len = pj_ntohs(msg->hdr->length);
    if (msg_len != buf_len - sizeof(pjstun_msg_hdr)) {
	PJ_LOG(4,(THIS_FILE, "Error: invalid msg_len %d (expecting %d)", 
			     msg_len, buf_len - sizeof(pjstun_msg_hdr)));
	return PJLIB_UTIL_ESTUNINMSGLEN;
    }

    msg->attr_count = 0;
    p_attr = (char*)buf + sizeof(pjstun_msg_hdr);

    while (msg_len > 0) {
	pjstun_attr_hdr **attr = &msg->attr[msg->attr_count];
	pj_uint32_t len;
	pj_uint16_t attr_type;

	*attr = (pjstun_attr_hdr*)p_attr;
	len = pj_ntohs((pj_uint16_t) ((*attr)->length)) + sizeof(pjstun_attr_hdr);
	len = (len + 3) & ~3;

	if (msg_len < len) {
	    PJ_LOG(4,(THIS_FILE, "Error: length mismatch in attr %d", 
				 msg->attr_count));
	    return PJLIB_UTIL_ESTUNINATTRLEN;
	}

	attr_type = pj_ntohs((*attr)->type);
	if (attr_type > PJSTUN_ATTR_REFLECTED_FROM &&
	    attr_type != PJSTUN_ATTR_XOR_MAPPED_ADDR)
	{
	    PJ_LOG(5,(THIS_FILE, "Warning: unknown attr type %x in attr %d. "
				 "Attribute was ignored.",
				 attr_type, msg->attr_count));
	}

	msg_len = (pj_uint16_t)(msg_len - len);
	p_attr += len;
	++msg->attr_count;
    }

    return PJ_SUCCESS;
}

void yp(const TfLiteTensor* ck, const TfLiteTensor* vr,
                         TfLiteTensor* mk, bool uw) {
  if (ck->type == kTfLiteUInt8 || ck->type == kTfLiteInt8) {
    auto input1_offset = -ck->params.zero_point;
    auto input2_offset = -vr->params.zero_point;
    const int left_shift = 8;

    int32 input1_multiplier;
    int input1_shift;
    QuantizeMultiplierSmallerThanOneExp(ck->params.scale,
                                        &input1_multiplier, &input1_shift);
    int32 input2_multiplier;
    int input2_shift;
    QuantizeMultiplierSmallerThanOneExp(vr->params.scale,
                                        &input2_multiplier, &input2_shift);

    ComparisonParams op_params;
    op_params.left_shift = left_shift;
    op_params.input1_offset = input1_offset;
    op_params.input1_multiplier = input1_multiplier;
    op_params.input1_shift = input1_shift;
    op_params.input2_offset = input2_offset;
    op_params.input2_multiplier = input2_multiplier;
    op_params.input2_shift = input2_shift;
    if (uw) {
      reference_ops::BroadcastComparison4DSlowWithScaling<input_dtype, opname>(
          op_params, GetTensorShape(ck), GetTensorData<input_dtype>(ck),
          GetTensorShape(vr), GetTensorData<input_dtype>(vr),
          GetTensorShape(mk), GetTensorData<bool>(mk));
    } else {
      reference_ops::ComparisonWithScaling<input_dtype, opname>(
          op_params, GetTensorShape(ck), GetTensorData<input_dtype>(ck),
          GetTensorShape(vr), GetTensorData<input_dtype>(vr),
          GetTensorShape(mk), GetTensorData<bool>(mk));
    }
  }
}

njs_await_fulfilled(njs_vm_t *rb, njs_value_t *tc, njs_uint_t hu,
    njs_index_t vj)
{
    njs_int_t           ret;
    njs_value_t         **cur_local, **cur_closures, **cur_temp, *value;
    njs_frame_t         *frame, *async_frame;
    njs_function_t      *function;
    njs_async_ctx_t     *ctx;
    njs_native_frame_t  *top, *async;

    ctx = rb->top_frame->function->context;

    value = njs_arg(tc, hu, 1);
    if (njs_is_error(value)) {
        goto failed;
    }

    async_frame = ctx->await;
    async = &async_frame->native;
    async->previous = rb->top_frame;

    function = async->function;

    cur_local = rb->levels[NJS_LEVEL_LOCAL];
    cur_closures = rb->levels[NJS_LEVEL_CLOSURE];
    cur_temp = rb->levels[NJS_LEVEL_TEMP];
    top = rb->top_frame;
    frame = rb->active_frame;

    rb->levels[NJS_LEVEL_LOCAL] = async->local;
    rb->levels[NJS_LEVEL_CLOSURE] = njs_function_closures(async->function);
    rb->levels[NJS_LEVEL_TEMP] = async->temp;

    rb->top_frame = async;
    rb->active_frame = async_frame;

    *njs_scope_value(rb, ctx->index) = *value;
    rb->retval = *value;

    rb->top_frame->retval = &rb->retval;

    function->context = ctx->capability;
    function->await = ctx;

    ret = njs_vmcode_interpreter(rb, ctx->pc);

    function->context = NULL;
    function->await = NULL;

    rb->levels[NJS_LEVEL_LOCAL] = cur_local;
    rb->levels[NJS_LEVEL_CLOSURE] = cur_closures;
    rb->levels[NJS_LEVEL_TEMP] = cur_temp;

    rb->top_frame = top;
    rb->active_frame = frame;

    if (ret == NJS_OK) {
        ret = njs_function_call(rb, njs_function(&ctx->capability->resolve),
                            &njs_value_undefined, &rb->retval, 1, &rb->retval);

        njs_async_context_free(rb, ctx);

    } else if (ret == NJS_AGAIN) {
        ret = NJS_OK;

    } else if (ret == NJS_ERROR) {
        if (njs_is_memory_error(rb, &rb->retval)) {
            return NJS_ERROR;
        }

        value = &rb->retval;

        goto failed;
    }

    return ret;

failed:

    (void) njs_function_call(rb, njs_function(&ctx->capability->reject),
                             &njs_value_undefined, value, 1, &rb->retval);

    njs_async_context_free(rb, ctx);

    return NJS_ERROR;
}

static int bk(const uint8_t *cn,
                            const uint8_t *dy,
                            unsigned uw,
                            uECC_word_t *do,
                            uint8_t *fw,
                            uECC_Curve ja) {

    uECC_word_t tmp[uECC_MAX_WORDS];
    uECC_word_t s[uECC_MAX_WORDS];
    uECC_word_t *k2[2] = {tmp, s};
#if uECC_VLI_NATIVE_LITTLE_ENDIAN
    uECC_word_t *p = (uECC_word_t *)fw;
#else
    uECC_word_t p[uECC_MAX_WORDS * 2];
#endif
    uECC_word_t carry;
    wordcount_t num_words = ja->num_words;
    wordcount_t num_n_words = BITS_TO_WORDS(ja->num_n_bits);
    bitcount_t num_n_bits = ja->num_n_bits;


    if (uECC_vli_isZero(do, num_words) || uECC_vli_cmp(ja->n, do, num_n_words) != 1) {
        return 0;
    }

    carry = regularize_k(do, tmp, s, ja);
    EccPoint_mult(p, ja->G, k2[!carry], 0, num_n_bits + 1, ja);
    if (uECC_vli_isZero(p, num_words)) {
        return 0;
    }


    if (!g_rng_function) {
        uECC_vli_clear(tmp, num_n_words);
        tmp[0] = 1;
    } else if (!uECC_generate_random_int(tmp, ja->n, num_n_words)) {
        return 0;
    }


    uECC_vli_modMult(do, do, tmp, ja->n, num_n_words); 
    uECC_vli_modInv(do, do, ja->n, num_n_words);       
    uECC_vli_modMult(do, do, tmp, ja->n, num_n_words); 

#if uECC_VLI_NATIVE_LITTLE_ENDIAN == 0
    uECC_vli_nativeToBytes(fw, ja->num_bytes, p); 
#endif

#if uECC_VLI_NATIVE_LITTLE_ENDIAN
    bcopy((uint8_t *) tmp, cn, BITS_TO_BYTES(ja->num_n_bits));
#else
    uECC_vli_bytesToNative(tmp, cn, BITS_TO_BYTES(ja->num_n_bits)); 
#endif

    s[num_n_words - 1] = 0;
    uECC_vli_set(s, p, num_words);
    uECC_vli_modMult(s, tmp, s, ja->n, num_n_words); 

    bits2int(tmp, dy, uw, ja);
    uECC_vli_modAdd(s, tmp, s, ja->n, num_n_words); 
    uECC_vli_modMult(s, s, do, ja->n, num_n_words);  
    if (uECC_vli_numBits(s, num_n_words) > (bitcount_t)ja->num_bytes * 8) {
        return 0;
    }
#if uECC_VLI_NATIVE_LITTLE_ENDIAN
    bcopy((uint8_t *) fw + ja->num_bytes, (uint8_t *) s, ja->num_bytes);
#else
    uECC_vli_nativeToBytes(fw + ja->num_bytes, ja->num_bytes, s);
#endif    
    return 1;
}

mrb_vm_exec(mrb_state *zb, const struct RProc *jl, const mrb_code *ln)
{

  const mrb_irep *irep = jl->body.irep;
  const mrb_pool_value *pool = irep->pool;
  const mrb_sym *syms = irep->syms;
  mrb_code insn;
  int ai = mrb_gc_arena_save(zb);
  struct mrb_jmpbuf *prev_jmp = zb->jmp;
  struct mrb_jmpbuf c_jmp;
  uint32_t a;
  uint16_t b;
  uint16_t c;
  mrb_sym mid;
  const struct mrb_irep_catch_handler *ch;

#ifdef DIRECT_THREADED
  static const void * const optable[] = {
#define OPCODE(x,_) &&L_OP_ ## x,
#include "mruby/ops.h"
#undef OPCODE
  };
#endif

  mrb_bool exc_catched = FALSE;
RETRY_TRY_BLOCK:

  MRB_TRY(&c_jmp) {

  if (exc_catched) {
    exc_catched = FALSE;
    mrb_gc_arena_restore(zb, ai);
    if (zb->exc && zb->exc->tt == MRB_TT_BREAK)
      goto L_BREAK;
    goto L_RAISE;
  }
  zb->jmp = &c_jmp;
  mrb_vm_ci_proc_set(zb->c->ci, jl);

#define regs (zb->c->ci->stack)
  INIT_DISPATCH {
    CASE(OP_NOP, Z) {

      NEXT;
    }

    CASE(OP_MOVE, BB) {
      regs[a] = regs[b];
      NEXT;
    }

    CASE(OP_LOADL, BB) {
      switch (pool[b].tt) {   
      case IREP_TT_INT32:
        regs[a] = mrb_int_value(zb, (mrb_int)pool[b].u.i32);
        break;
      case IREP_TT_INT64:
#if defined(MRB_INT64)
        regs[a] = mrb_int_value(zb, (mrb_int)pool[b].u.i64);
        break;
#else
#if defined(MRB_64BIT)
        if (INT32_MIN <= pool[b].u.i64 && pool[b].u.i64 <= INT32_MAX) {
          regs[a] = mrb_int_value(zb, (mrb_int)pool[b].u.i64);
          break;
        }
#endif
        goto L_INT_OVERFLOW;
#endif
      case IREP_TT_BIGINT:
        goto L_INT_OVERFLOW;
#ifndef MRB_NO_FLOAT
      case IREP_TT_FLOAT:
        regs[a] = mrb_float_value(zb, pool[b].u.f);
        break;
#endif
      default:

        regs[a] = mrb_nil_value();
        break;
      }
      NEXT;
    }

    CASE(OP_LOADI, BB) {
      SET_FIXNUM_VALUE(regs[a], b);
      NEXT;
    }

    CASE(OP_LOADINEG, BB) {
      SET_FIXNUM_VALUE(regs[a], -b);
      NEXT;
    }

    CASE(OP_LOADI__1,B) goto L_LOADI;
    CASE(OP_LOADI_0,B) goto L_LOADI;
    CASE(OP_LOADI_1,B) goto L_LOADI;
    CASE(OP_LOADI_2,B) goto L_LOADI;
    CASE(OP_LOADI_3,B) goto L_LOADI;
    CASE(OP_LOADI_4,B) goto L_LOADI;
    CASE(OP_LOADI_5,B) goto L_LOADI;
    CASE(OP_LOADI_6,B) goto L_LOADI;
    CASE(OP_LOADI_7, B) {
    L_LOADI:
      SET_FIXNUM_VALUE(regs[a], (mrb_int)insn - (mrb_int)OP_LOADI_0);
      NEXT;
    }

    CASE(OP_LOADI16, BS) {
      SET_FIXNUM_VALUE(regs[a], (mrb_int)(int16_t)b);
      NEXT;
    }

    CASE(OP_LOADI32, BSS) {
      SET_INT_VALUE(zb, regs[a], (int32_t)(((uint32_t)b<<16)+c));
      NEXT;
    }

    CASE(OP_LOADSYM, BB) {
      SET_SYM_VALUE(regs[a], syms[b]);
      NEXT;
    }

    CASE(OP_LOADNIL, B) {
      SET_NIL_VALUE(regs[a]);
      NEXT;
    }

    CASE(OP_LOADSELF, B) {
      regs[a] = regs[0];
      NEXT;
    }

    CASE(OP_LOADT, B) {
      SET_TRUE_VALUE(regs[a]);
      NEXT;
    }

    CASE(OP_LOADF, B) {
      SET_FALSE_VALUE(regs[a]);
      NEXT;
    }

    CASE(OP_GETGV, BB) {
      mrb_value val = mrb_gv_get(zb, syms[b]);
      regs[a] = val;
      NEXT;
    }

    CASE(OP_SETGV, BB) {
      mrb_gv_set(zb, syms[b], regs[a]);
      NEXT;
    }

    CASE(OP_GETSV, BB) {
      mrb_value val = mrb_vm_special_get(zb, syms[b]);
      regs[a] = val;
      NEXT;
    }

    CASE(OP_SETSV, BB) {
      mrb_vm_special_set(zb, syms[b], regs[a]);
      NEXT;
    }

    CASE(OP_GETIV, BB) {
      regs[a] = mrb_iv_get(zb, regs[0], syms[b]);
      NEXT;
    }

    CASE(OP_SETIV, BB) {
      mrb_iv_set(zb, regs[0], syms[b], regs[a]);
      NEXT;
    }

    CASE(OP_GETCV, BB) {
      mrb_value val;
      val = mrb_vm_cv_get(zb, syms[b]);
      regs[a] = val;
      NEXT;
    }

    CASE(OP_SETCV, BB) {
      mrb_vm_cv_set(zb, syms[b], regs[a]);
      NEXT;
    }

    CASE(OP_GETIDX, B) {
