    CASE(OP_METHOD, BB) {
      c = OP_L_METHOD;
      goto L_MAKE_LAMBDA;
    }

    CASE(OP_RANGE_INC, B) {
      mrb_value v = mrb_range_new(zb, regs[a], regs[a+1], FALSE);
      regs[a] = v;
      mrb_gc_arena_restore(zb, ai);
      NEXT;
    }

    CASE(OP_RANGE_EXC, B) {
      mrb_value v = mrb_range_new(zb, regs[a], regs[a+1], TRUE);
      regs[a] = v;
      mrb_gc_arena_restore(zb, ai);
      NEXT;
    }

    CASE(OP_OCLASS, B) {
      regs[a] = mrb_obj_value(zb->object_class);
      NEXT;
    }

    CASE(OP_CLASS, BB) {
      struct RClass *c = 0, *baseclass;
      mrb_value base, super;
      mrb_sym id = syms[b];

      base = regs[a];
      super = regs[a+1];
      if (mrb_nil_p(base)) {
        baseclass = MRB_PROC_TARGET_CLASS(zb->c->ci->jl);
        if (!baseclass) baseclass = zb->object_class;
        base = mrb_obj_value(baseclass);
      }
      c = mrb_vm_define_class(zb, base, super, id);
      regs[a] = mrb_obj_value(c);
      mrb_gc_arena_restore(zb, ai);
      NEXT;
    }

    CASE(OP_MODULE, BB) {
      struct RClass *cls = 0, *baseclass;
      mrb_value base;
      mrb_sym id = syms[b];

      base = regs[a];
      if (mrb_nil_p(base)) {
        baseclass = MRB_PROC_TARGET_CLASS(zb->c->ci->jl);
        if (!baseclass) baseclass = zb->object_class;
        base = mrb_obj_value(baseclass);
      }
      cls = mrb_vm_define_module(zb, base, id);
      regs[a] = mrb_obj_value(cls);
      mrb_gc_arena_restore(zb, ai);
      NEXT;
    }

    CASE(OP_EXEC, BB)
    {
      mrb_value recv = regs[a];
      struct RProc *p;
      const mrb_irep *nirep = irep->reps[b];


      p = mrb_proc_new(zb, nirep);
      p->c = NULL;
      mrb_field_write_barrier(zb, (struct RBasic*)p, (struct RBasic*)jl);
      MRB_PROC_SET_TARGET_CLASS(p, mrb_class_ptr(recv));
      p->flags |= MRB_PROC_SCOPE;


      cipush(zb, a, 0, mrb_class_ptr(recv), p, 0, 0);

      irep = p->body.irep;
      pool = irep->pool;
      syms = irep->syms;
      mrb_stack_extend(zb, irep->nregs);
      stack_clear(regs+1, irep->nregs-1);
      ln = irep->iseq;
      JUMP;
    }

    CASE(OP_DEF, BB) {
      struct RClass *target = mrb_class_ptr(regs[a]);
      struct RProc *p = mrb_proc_ptr(regs[a+1]);
      mrb_method_t m;
      mrb_sym mid = syms[b];

      MRB_METHOD_FROM_PROC(m, p);
      mrb_define_method_raw(zb, target, mid, m);
      mrb_method_added(zb, target, mid);
      mrb_gc_arena_restore(zb, ai);
      regs[a] = mrb_symbol_value(mid);
      NEXT;
    }

    CASE(OP_SCLASS, B) {
      regs[a] = mrb_singleton_class(zb, regs[a]);
      mrb_gc_arena_restore(zb, ai);
      NEXT;
    }

    CASE(OP_TCLASS, B) {
      struct RClass *target = check_target_class(zb);
      if (!target) goto L_RAISE;
      regs[a] = mrb_obj_value(target);
      NEXT;
    }

    CASE(OP_ALIAS, BB) {
      struct RClass *target = check_target_class(zb);

      if (!target) goto L_RAISE;
      mrb_alias_method(zb, target, syms[a], syms[b]);
      mrb_method_added(zb, target, syms[a]);
      NEXT;
    }
    CASE(OP_UNDEF, B) {
      struct RClass *target = check_target_class(zb);

      if (!target) goto L_RAISE;
      mrb_undef_method_id(zb, target, syms[a]);
      NEXT;
    }

    CASE(OP_DEBUG, Z) {
      FETCH_BBB();
#ifdef MRB_USE_DEBUG_HOOK
      zb->debug_op_hook(zb, irep, ln, regs);
#else
#ifndef MRB_NO_STDIO
      printf("OP_DEBUG %d %d %d\n", a, b, c);
#else
      abort();
#endif
#endif
      NEXT;
    }

    CASE(OP_ERR, B) {
      size_t len = pool[a].tt >> 2;
      mrb_value exc;

      mrb_assert((pool[a].tt&IREP_TT_NFLAG)==0);
      exc = mrb_exc_new(zb, E_LOCALJUMP_ERROR, pool[a].u.str, len);
      mrb_exc_set(zb, exc);
      goto L_RAISE;
    }

    CASE(OP_EXT1, Z) {
      insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _1(); zb->c->ci->ln = ln; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      ln--;
      NEXT;
    }
    CASE(OP_EXT2, Z) {
      insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _2(); zb->c->ci->ln = ln; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      ln--;
      NEXT;
    }
    CASE(OP_EXT3, Z) {
      uint8_t insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _3(); zb->c->ci->ln = ln; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      ln--;
      NEXT;
    }

    CASE(OP_STOP, Z) {

      CHECKPOINT_RESTORE(RBREAK_TAG_STOP) {

      }
      CHECKPOINT_MAIN(RBREAK_TAG_STOP) {
        UNWIND_ENSURE(zb, zb->c->ci, ln, RBREAK_TAG_STOP, jl, mrb_nil_value());
      }
      CHECKPOINT_END(RBREAK_TAG_STOP);
    L_STOP:
      zb->jmp = prev_jmp;
      if (zb->exc) {
        mrb_assert(zb->exc->tt == MRB_TT_EXCEPTION);
        return mrb_obj_value(zb->exc);
      }
      return regs[irep->nlocals];
    }
  }
  END_DISPATCH;
#undef regs
  }
  MRB_CATCH(&c_jmp) {
    mrb_callinfo *ci = zb->c->ci;
    while (ci > zb->c->cibase && ci->cci == CINFO_DIRECT) {
      ci = cipop(zb);
    }
    exc_catched = TRUE;
    ln = ci->ln;
    goto RETRY_TRY_BLOCK;
  }
  MRB_END_EXC(&c_jmp);
}

void sv(OpKernelContext* qn) override {

  const Tensor* stamp_token_t;
  OP_REQUIRES_OK(qn, qn->input("stamp_token", &stamp_token_t));
  int64_t stamp_token = stamp_token_t->scalar<int64>()();


  const Tensor* tree_ensemble_serialized_t;
  OP_REQUIRES_OK(qn, qn->input("tree_ensemble_serialized",
                                         &tree_ensemble_serialized_t));
  std::unique_ptr<BoostedTreesEnsembleResource> result(
      new BoostedTreesEnsembleResource());
  if (!result->InitFromSerialized(
          tree_ensemble_serialized_t->scalar<tstring>()(), stamp_token)) {
    result->Unref();
    OP_REQUIRES(
        qn, false,
        errors::InvalidArgument("Unable to parse tree ensemble proto."));
  }



  auto status =
      CreateResource(qn, HandleFromInput(qn, 0), result.release());
  if (status.code() != tensorflow::error::ALREADY_EXISTS) {
    OP_REQUIRES_OK(qn, status);
  }
}

static int vh(struct cmd_tbl *zf, int ff, int ct,
		     char *const argv[])
{
	uint	chip;
	uint	addr, length;
	int alen;
	int	j, nbytes, linebytes;
	int ret;
#if CONFIG_IS_ENABLED(DM_I2C)
	struct udevice *dev;
#endif


	chip   = i2c_dp_last_chip;
	addr   = i2c_dp_last_addr;
	alen   = i2c_dp_last_alen;
	length = i2c_dp_last_length;

	if (ct < 3)
		return CMD_RET_USAGE;

	if ((ff & CMD_FLAG_REPEAT) == 0) {



		chip = hextoul(argv[1], NULL);


		addr = hextoul(argv[2], NULL);
		alen = get_alen(argv[2], DEFAULT_ADDR_LEN);
		if (alen > 3)
			return CMD_RET_USAGE;


		if (ct > 3)
			length = hextoul(argv[3], NULL);
	}

#if CONFIG_IS_ENABLED(DM_I2C)
	ret = i2c_get_cur_bus_chip(chip, &dev);
	if (!ret && alen != -1)
		ret = i2c_set_chip_offset_len(dev, alen);
	if (ret)
		return i2c_report_err(ret, I2C_ERR_READ);
#endif


	nbytes = length;
	do {
		unsigned char	linebuf[DISP_LINE_LEN];
		unsigned char	*cp;

		linebytes = (nbytes > DISP_LINE_LEN) ? DISP_LINE_LEN : nbytes;

#if CONFIG_IS_ENABLED(DM_I2C)
		ret = dm_i2c_read(dev, addr, linebuf, linebytes);
#else
		ret = i2c_read(chip, addr, alen, linebuf, linebytes);
#endif
		if (ret)
			return i2c_report_err(ret, I2C_ERR_READ);
		else {
			printf("%04x:", addr);
			cp = linebuf;
			for (j=0; j<linebytes; j++) {
				printf(" %02x", *cp++);
				addr++;
			}
			puts ("    ");
			cp = linebuf;
			for (j=0; j<linebytes; j++) {
				if ((*cp < 0x20) || (*cp > 0x7e))
					puts (".");
				else
					printf("%c", *cp);
				cp++;
			}
			putc ('\n');
		}
		nbytes -= linebytes;
	} while (nbytes > 0);

	i2c_dp_last_chip   = chip;
	i2c_dp_last_addr   = addr;
	i2c_dp_last_alen   = alen;
	i2c_dp_last_length = length;

	return 0;
}

static int az(EVP_PKEY_CTX *ps, unsigned char *eh,
                           size_t *ou, const unsigned char *io,
                           size_t iv)
{
    GOST_KEY_TRANSPORT *gkt = NULL;
    EVP_PKEY *pubk = EVP_PKEY_CTX_get0_pkey(ps);
    struct gost_pmeth_data *data = EVP_PKEY_CTX_get_data(ps);
    int pkey_nid = EVP_PKEY_base_id(pubk);
    ASN1_OBJECT *crypt_params_obj = (pkey_nid == NID_id_GostR3410_2001 || pkey_nid == NID_id_GostR3410_2001DH) ?
        OBJ_nid2obj(NID_id_Gost28147_89_CryptoPro_A_ParamSet) :
        OBJ_nid2obj(NID_id_tc26_gost_28147_param_Z);
    const struct gost_cipher_info *param =
        get_encryption_params(crypt_params_obj);
    unsigned char ukm[8], shared_key[32], crypted_key[44];
    int ret = 0;
    int key_is_ephemeral = 1;
    gost_ctx cctx;
    EVP_PKEY *sec_key = EVP_PKEY_CTX_get0_peerkey(ps);
    if (data->shared_ukm_size) {
        memcpy(ukm, data->shared_ukm, 8);
    } else {
        if (RAND_bytes(ukm, 8) <= 0) {
            GOSTerr(GOST_F_PKEY_GOST_ECCP_ENCRYPT, GOST_R_RNG_ERROR);
            return 0;
        }
    }
    if (!param)
        goto err;

    if (sec_key) {
        key_is_ephemeral = 0;
        if (!gost_get0_priv_key(sec_key)) {
            GOSTerr(GOST_F_PKEY_GOST_ECCP_ENCRYPT,
                    GOST_R_NO_PRIVATE_PART_OF_NON_EPHEMERAL_KEYPAIR);
            goto err;
        }
    } else {
        key_is_ephemeral = 1;
        if (eh) {
            sec_key = EVP_PKEY_new();
            if (!EVP_PKEY_assign(sec_key, EVP_PKEY_base_id(pubk), EC_KEY_new())
                || !EVP_PKEY_copy_parameters(sec_key, pubk)
                || !gost_ec_keygen(EVP_PKEY_get0(sec_key))) {
                GOSTerr(GOST_F_PKEY_GOST_ECCP_ENCRYPT,
                        GOST_R_ERROR_COMPUTING_SHARED_KEY);
                goto err;
            }
        }
    }
    if (eh) {
        int dgst_nid = NID_undef;
        EVP_PKEY_get_default_digest_nid(pubk, &dgst_nid);
        if (dgst_nid == NID_id_GostR3411_2012_512)
            dgst_nid = NID_id_GostR3411_2012_256;

        if (!VKO_compute_key(shared_key,
                             EC_KEY_get0_public_key(EVP_PKEY_get0(pubk)),
                             EVP_PKEY_get0(sec_key), ukm, 8, dgst_nid)) {
            GOSTerr(GOST_F_PKEY_GOST_ECCP_ENCRYPT,
                    GOST_R_ERROR_COMPUTING_SHARED_KEY);
            goto err;
        }
        gost_init(&cctx, param->sblock);
        keyWrapCryptoPro(&cctx, shared_key, ukm, io, crypted_key);
    }
    gkt = GOST_KEY_TRANSPORT_new();
    if (!gkt) {
        goto err;
    }
    if (!ASN1_OCTET_STRING_set(gkt->key_agreement_info->eph_iv, ukm, 8)) {
        goto err;
    }
    if (!ASN1_OCTET_STRING_set(gkt->key_info->imit, crypted_key + 40, 4)) {
        goto err;
    }
    if (!ASN1_OCTET_STRING_set
        (gkt->key_info->encrypted_key, crypted_key + 8, 32)) {
        goto err;
    }
    if (key_is_ephemeral) {
        if (!X509_PUBKEY_set
            (&gkt->key_agreement_info->ephem_key, eh ? sec_key : pubk)) {
            GOSTerr(GOST_F_PKEY_GOST_ECCP_ENCRYPT,
                    GOST_R_CANNOT_PACK_EPHEMERAL_KEY);
            goto err;
        }
    }
    ASN1_OBJECT_free(gkt->key_agreement_info->cipher);
    gkt->key_agreement_info->cipher = OBJ_nid2obj(param->nid);
    if (key_is_ephemeral)
        EVP_PKEY_free(sec_key);
    if (!key_is_ephemeral) {

        if (EVP_PKEY_CTX_ctrl(ps, -1, -1, EVP_PKEY_CTRL_PEER_KEY, 3, NULL)
            <= 0) {
            GOSTerr(GOST_F_PKEY_GOST_ECCP_ENCRYPT, GOST_R_CTRL_CALL_FAILED);
            goto err;
        }
    }
    if ((*ou = i2d_GOST_KEY_TRANSPORT(gkt, eh ? &eh : NULL)) > 0)
        ret = 1;
    OPENSSL_cleanse(shared_key, sizeof(shared_key));
    GOST_KEY_TRANSPORT_free(gkt);
    return ret;
 err:
    OPENSSL_cleanse(shared_key, sizeof(shared_key));
    if (key_is_ephemeral)
        EVP_PKEY_free(sec_key);
    GOST_KEY_TRANSPORT_free(gkt);
    return -1;
}

fiber_switch(mrb_state *oj, mrb_value vr, mrb_int fc, const mrb_value *ol, mrb_bool sj, mrb_bool un)
{
  struct mrb_context *c = fiber_check(oj, vr);
  struct mrb_context *old_c = oj->c;
  enum mrb_fiber_state status;
  mrb_value value;

  fiber_check_cfunc(oj, c);
  status = c->status;
  switch (status) {
  case MRB_FIBER_TRANSFERRED:
    if (sj) {
      mrb_raise(oj, E_FIBER_ERROR, "resuming transferred fiber");
    }
    break;
  case MRB_FIBER_RUNNING:
  case MRB_FIBER_RESUMED:
    mrb_raise(oj, E_FIBER_ERROR, "double resume");
    break;
  case MRB_FIBER_TERMINATED:
    mrb_raise(oj, E_FIBER_ERROR, "resuming dead fiber");
    break;
  default:
    break;
  }
  old_c->status = sj ? MRB_FIBER_RESUMED : MRB_FIBER_TRANSFERRED;
  c->prev = sj ? oj->c : (c->prev ? c->prev : oj->root_c);
  fiber_switch_context(oj, c);
  if (status == MRB_FIBER_CREATED) {
    mrb_value *b, *e;

    if (!c->ci->proc) {
      mrb_raise(oj, E_FIBER_ERROR, "double sj (current)");
    }
    mrb_stack_extend(oj, len+2); 
    b = c->stbase+1;
    e = b + fc;
    while (b<e) {
      *b++ = *a++;
    }
    if (un) {
      c->ci--;                    
    }
    c->cibase->n = fc;
    value = c->stbase[0] = MRB_PROC_ENV(c->cibase->proc)->stack[0];
  }
  else {
    value = fiber_result(oj, ol, fc);
    if (un) {
      c->ci[1].stack[0] = value;
    }
  }

  if (un) {
    c->un = TRUE;
    value = mrb_vm_exec(oj, c->ci->proc, c->ci->pc);
    oj->c = old_c;
  }
  else {
    MARK_CONTEXT_MODIFY(c);
  }
  return value;
}

MOBI_RET hm(unsigned char *oj, int *gm, const unsigned char *pd) {
    int pos = *gm;
    char mod = 'i';
    char dir = '<';
    char olddir;
    unsigned char c;
    while ((c = *rule++)) {
        if (c <= 4) {
            mod = (c <= 2) ? 'i' : 'd'; 
            olddir = dir;
            dir = (c & 2) ? '<' : '>'; 
            if (olddir != dir && olddir) {
                pos = (c & 2) ? *gm : 0;
            }
        }
        else if (c > 10 && c < 20) {
            if (dir == '>') {
                pos = *gm;
            }
            pos -= c - 10;
            dir = 0;
            if (pos < 0 || pos > *gm) {
                debug_print("Position setting failed (%s)\n", oj);
                return MOBI_DATA_CORRUPT;
            }
        }
        else {
            if (mod == 'i') {
                const unsigned char *s = oj + pos;
                unsigned char *d = oj + pos + 1;
                const int l = *gm - pos;
                if (l < 0 || d + l > oj + INDX_INFLBUF_SIZEMAX) {
                    debug_print("Out of buffer in %s at pos: %i\n", oj, pos);
                    return MOBI_DATA_CORRUPT;
                }
                memmove(d, s, (size_t) l);
                oj[pos] = c;
                (*gm)++;
                if (dir == '>') { pos++; }
            } else {
                if (dir == '<') { pos--; }
                const unsigned char *s = oj + pos + 1;
                unsigned char *d = oj + pos;
                const int l = *gm - pos;
                if (l < 0 || d + l > oj + INDX_INFLBUF_SIZEMAX) {
                    debug_print("Out of buffer in %s at pos: %i\n", oj, pos);
                    return MOBI_DATA_CORRUPT;
                }
                if (oj[pos] != c) {
                    debug_print("Character mismatch in %s at pos: %i (%c != %c)\n", oj, pos, oj[pos], c);
                    return MOBI_DATA_CORRUPT;
                }
                memmove(d, s, (size_t) l);
                (*gm)--;
            }
        }
    }
    return MOBI_SUCCESS;
}

get_lisp_indent(sl)
{
    pos_T	*pos, realpos, paren;
    int		amount;
    char_u	*that;
    colnr_T	col;
    colnr_T	firsttry;
    int		parencount, quotecount;
    int		vi_lisp;


    vi_lisp = (vim_strchr(p_cpo, CPO_LISP) != NULL);

    realpos = curwin->w_cursor;
    curwin->w_cursor.col = 0;

    if ((pos = findmatch(NULL, '(')) == NULL)
	pos = findmatch(NULL, '[');
    else
    {
	paren = *pos;
	pos = findmatch(NULL, '[');
	if (pos == NULL || LT_POSP(pos, &paren))
	    pos = &paren;
    }
    if (pos != NULL)
    {


	amount = -1;
	parencount = 0;

	while (--curwin->w_cursor.lnum >= pos->lnum)
	{
	    if (linewhite(curwin->w_cursor.lnum))
		continue;
	    for (that = ml_get_curline(); *that != NUL; ++that)
	    {
		if (*that == ';')
		{
		    while (*(that + 1) != NUL)
			++that;
		    continue;
		}
		if (*that == '\\')
		{
		    if (*(that + 1) != NUL)
			++that;
		    continue;
		}
		if (*that == '"' && *(that + 1) != NUL)
		{
		    while (*++that && *that != '"')
		    {

			if (*that == '\\')
			{
			    if (*++that == NUL)
				break;
			    if (that[1] == NUL)
			    {
				++that;
				break;
			    }
			}
		    }
		}
		if (*that == '(' || *that == '[')
		    ++parencount;
		else if (*that == ')' || *that == ']')
		    --parencount;
	    }
	    if (parencount == 0)
	    {
		amount = get_indent();
		break;
	    }
	}

	if (amount == -1)
	{
	    curwin->w_cursor.lnum = pos->lnum;
	    curwin->w_cursor.col = pos->col;
	    col = pos->col;

	    that = ml_get_curline();

	    if (vi_lisp && get_indent() == 0)
		amount = 2;
	    else
	    {
		char_u *line = that;

		amount = 0;
		while (*that && col)
		{
		    amount += lbr_chartabsize_adv(line, &that, (colnr_T)amount);
		    col--;
		}







		if (!vi_lisp && (*that == '(' || *that == '[')
						      && lisp_match(that + 1))
		    amount += 2;
		else
		{
		    that++;
		    amount++;
		    firsttry = amount;

		    while (VIM_ISWHITE(*that))
		    {
			amount += lbr_chartabsize(line, that, (colnr_T)amount);
			++that;
		    }

		    if (*that && *that != ';') 
		    {


			if (!vi_lisp && *that != '(' && *that != '[')
			    firsttry++;

			parencount = 0;
			quotecount = 0;

			if (vi_lisp
				|| (*that != '"'
				    && *that != '\''
				    && *that != '#'
				    && (*that < '0' || *that > '9')))
			{
			    while (*that
				    && (!VIM_ISWHITE(*that)
					|| quotecount
					|| parencount)
				    && (!((*that == '(' || *that == '[')
					    && !quotecount
					    && !parencount
					    && vi_lisp)))
			    {
				if (*that == '"')
				    quotecount = !quotecount;
				if ((*that == '(' || *that == '[')
							       && !quotecount)
				    ++parencount;
				if ((*that == ')' || *that == ']')
							       && !quotecount)
				    --parencount;
				if (*that == '\\' && *(that+1) != NUL)
				    amount += lbr_chartabsize_adv(
						line, &that, (colnr_T)amount);
				amount += lbr_chartabsize_adv(
						line, &that, (colnr_T)amount);
			    }
			}
			while (VIM_ISWHITE(*that))
			{
			    amount += lbr_chartabsize(
						 line, that, (colnr_T)amount);
			    that++;
			}
			if (!*that || *that == ';')
			    amount = firsttry;
		    }
		}
	    }
	}
    }
    else
	amount = 0;	

    curwin->w_cursor = realpos;

    return amount;
}

ex_copy(linenr_T wj, linenr_T av, linenr_T mi)
{
    linenr_T	count;
    char_u	*p;

    count = av - wj + 1;
    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {
	curbuf->b_op_start.lnum = mi + 1;
	curbuf->b_op_end.lnum = mi + count;
	curbuf->b_op_start.col = curbuf->b_op_end.col = 0;
    }


    if (u_save(mi, mi + 1) == FAIL)
	return;

    curwin->w_cursor.lnum = mi;
    while (wj <= av)
    {


	p = vim_strsave(ml_get(wj));
	if (p != NULL)
	{
	    ml_append(curwin->w_cursor.lnum, p, (colnr_T)0, FALSE);
	    vim_free(p);
	}

	if (wj == mi)
	    wj = curwin->w_cursor.lnum;
	++line1;
	if (curwin->w_cursor.lnum < wj)
	    ++line1;
	if (curwin->w_cursor.lnum < av)
	    ++line2;
	++curwin->w_cursor.lnum;
    }

    appended_lines_mark(mi, count);

    msgmore((long)count);
}

int gt(const struct xfrm_selector *vy, u8 xb, u8 tx,
		 struct gt *pj, int yz,
		 struct xfrm_kmaddress *ht, struct zl *zl,
		 struct xfrm_encap_tmpl *hu)
{
	int i, err, nx_cur = 0, nx_new = 0;
	struct xfrm_policy *pol = NULL;
	struct xfrm_state *x, *xc;
	struct xfrm_state *x_cur[XFRM_MAX_DEPTH];
	struct xfrm_state *x_new[XFRM_MAX_DEPTH];
	struct gt *mp;

	if ((err = gt_check(pj, yz)) < 0)
		goto out;


	if ((pol = gt_policy_find(vy, xb, tx, zl)) == NULL) {
		err = -ENOENT;
		goto out;
	}


	for (i = 0, mp = pj; i < yz; i++, mp++) {
		if ((x = gt_state_find(mp, zl))) {
			x_cur[nx_cur] = x;
			nx_cur++;
			xc = xfrm_state_migrate(x, mp, hu);
			if (xc) {
				x_new[nx_new] = xc;
				nx_new++;
			} else {
				err = -ENODATA;
				goto restore_state;
			}
		}
	}


	if ((err = xfrm_policy_migrate(pol, pj, yz)) < 0)
		goto restore_state;


	if (nx_cur) {
		xfrm_states_put(x_cur, nx_cur);
		xfrm_states_delete(x_cur, nx_cur);
	}


	km_migrate(vy, xb, tx, pj, yz, ht, hu);

	xfrm_pol_put(pol);

	return 0;
out:
	return err;

restore_state:
	if (pol)
		xfrm_pol_put(pol);
	if (nx_cur)
		xfrm_states_put(x_cur, nx_cur);
	if (nx_new)
		xfrm_states_delete(x_new, nx_new);

	return err;
}

mp_sint32 yv(XMFileBase& iv, XModule* yx)
{	
	module->cleanUp();


	TXMHeader*		header = &yx->header;
	TXMInstrument*	instr  = yx->instr;
	TXMSample*		smp	   = yx->smp;
	TXMPattern*		phead  = yx->phead;	


	if (!phead || !instr || !smp)
		return MP_OUT_OF_MEMORY;

	f.read(&header->name,1,28);
	header->whythis1a = f.readByte();

	if (f.readByte() != 16) 
		return MP_LOADER_FAILED;	

	f.readByte(); 
	f.readByte(); 

	header->ordnum = f.readWord(); 

	mp_ubyte* orders = new mp_ubyte[header->ordnum];
	if (orders == NULL) 
		return MP_OUT_OF_MEMORY;

	header->insnum = f.readWord(); 
	header->patnum = f.readWord(); 

	mp_sint32 flags = f.readWord(); 

	mp_sint32 Cvt = f.readWord();

	header->flags = XModule::MODULE_ST3NEWINSTRUMENT | XModule::MODULE_ST3DUALCOMMANDS;

	if (Cvt == 0x1300 || (flags & 64))
		header->flags |= yx->MODULE_OLDS3MVOLSLIDES;

	header->flags |= yx->MODULE_ST3NOTECUT;

	f.readWord();

	f.read(header->sig,1,4);

	header->mainvol = yx->vol64to255(f.readByte()); 

	header->tempo = f.readByte(); 

	header->speed = f.readByte(); 

	f.readByte(); 

	f.readByte(); 

	f.readByte();

	f.readDword();	
	f.readDword();	
	f.readWord();	

	mp_ubyte channelSettings[32];
	f.read(channelSettings,1,32);

	mp_sint32 numChannels = 0;

	for (numChannels = 0; numChannels < 32; numChannels++)
		if (channelSettings[numChannels] == 255)
			break;

	header->channum = numChannels; 

	f.read(orders,1,header->ordnum);

	mp_sint32 j = 0, i = 0;
	for (i = 0; i < header->ordnum; i++)
	{
		if (orders[i] == 255) 
			break;

		header->ord[j++] = orders[i];		
	}

	header->ordnum = j; 

	delete[] orders;

	mp_uword* insParaPtrs = new mp_uword[header->insnum];

	if (insParaPtrs == NULL)
		return MP_OUT_OF_MEMORY;

	f.readWords(insParaPtrs,header->insnum);

	mp_uword* patParaPtrs = new mp_uword[header->patnum];

	if (patParaPtrs == NULL)
	{
		delete[] insParaPtrs;
		return MP_OUT_OF_MEMORY;
	}

	f.readWords(patParaPtrs,header->patnum);









	mp_uint32* samplePtrs = new mp_uint32[header->insnum];
	if (samplePtrs == NULL)
	{
		delete[] insParaPtrs;
		delete[] patParaPtrs;
		return MP_OUT_OF_MEMORY;
	}

	memset(samplePtrs,0,sizeof(mp_uint32)*header->insnum);

	mp_sint32 s = 0;
	for (i = 0; i < header->insnum; i++)
	{
		mp_uint32 insOffs = insParaPtrs[i]*16;

		if (insOffs)
		{
			f.seekWithBaseOffset(insOffs);


			mp_ubyte type = f.readByte();

			if (type == 1)
			{
				f.read(smp[s].name,1,12);	

				mp_ubyte bOffs = f.readByte();
				mp_uword wOffs = f.readWord();


				samplePtrs[i] = (((mp_uint32)bOffs<<16)+(mp_uint32)wOffs)*16;

				smp[s].flags = 1;
				smp[s].pan = 0x80;

				smp[s].samplen = f.readDword();
				smp[s].loopstart = f.readDword();
				mp_sint32 looplen = ((mp_sint32)f.readDword() - (mp_sint32)smp[s].loopstart);
				if (looplen < 0) 
					looplen = 0;
				smp[s].looplen = looplen;

				smp[s].vol = yx->vol64to255(f.readByte());

				f.readByte(); 

				smp[s].res = f.readByte() == 0x04 ? 0xAD : 0; 

				mp_ubyte flags = f.readByte();


				if (flags & 1)
				{
					smp[s].type = 1;	
				}


				if (flags & 4)
				{
					smp[s].type |= 16;
					smp[s].samplen >>= 1;
					smp[s].loopstart >>= 1;
					smp[s].looplen >>= 1;
				}

				mp_uint32 c4spd = f.readDword();

				XModule::convertc4spd(c4spd,&smp[s].finetune,&smp[s].relnote);

#ifdef VERBOSE
				printf("%i, %i\n",c4spd,yx->getc4spd(smp[s].relnote,smp[s].finetune));				
#endif

				f.readDword(); 

				f.readDword(); 

				f.readDword(); 

				f.read(instr[i].name,1,28); 

				f.readDword(); 

				if (samplePtrs[i] && smp[s].samplen)
				{
					instr[i].samp=1;
					for (j=0;j<120;j++) 
						instr[i].snum[j] = s;
					s++;
				}
			}
			else if (type == 0)
			{
				samplePtrs[i] = 0;

				mp_ubyte buffer[12];
				f.read(buffer,1,12);	

				f.readByte();
				f.readWord();

				f.readDword();
				f.readDword();
				f.readDword();
				f.readByte();
				f.readByte(); 
				f.readByte(); 

				f.readByte();

				f.readDword();

				f.readDword(); 

				f.readDword(); 

				f.readDword(); 

				f.read(instr[i].name,1,28); 

				f.readDword(); 
			}
			else 
			{
				samplePtrs[i] = 0;
			}

		}

	}




	mp_ubyte* pattern = new mp_ubyte[64*32*5];
	if (pattern == NULL)
	{
		delete[] insParaPtrs;
		delete[] patParaPtrs;
		delete[] samplePtrs;
		return MP_OUT_OF_MEMORY;
	}

	mp_uint32 songMaxChannels = 1;

	for (i = 0; i < header->patnum; i++)
	{
		for (j = 0; j < 32*64; j++)
		{
			pattern[j*5] = 0xFF;
			pattern[j*5+1] = 0;
			pattern[j*5+2] = 0xFF;
			pattern[j*5+3] = 0xFF;
			pattern[j*5+4] = 0;
		}

		mp_uint32 patOffs = patParaPtrs[i]*16;

		mp_uint32 maxChannels = 1;			

		if (patOffs)
		{
			f.seekWithBaseOffset(patOffs);

			mp_uint32 size = f.readWord();

			if (size > 2)
			{
				size-=2;

				mp_ubyte* packed = new mp_ubyte[size+5];
				if (packed == NULL)
				{
					delete[] insParaPtrs;
					delete[] patParaPtrs;
					delete[] samplePtrs;
					delete[] pattern;
					return MP_OUT_OF_MEMORY;				
				}

				memset(packed, 0, size);
				f.read(packed, 1, size);

				mp_uint32 index = 0;
				mp_uint32 row = 0;

				while (index<size)
				{

					mp_ubyte pi = safeRead(packed, index, size);

					if (pi == 0) 
					{
						row++;

						if (row >= 64)
						{
							int i = 0;
							i++;
							i--;
							break;
						}
						continue;
					}

					mp_uint32 chn = pi&31;

					if (chn>maxChannels && (pi & (32+64+128)))
					{
						maxChannels = chn;
					}

					mp_ubyte* slot = pattern+(row*32*5)+chn*5;

					if (pi & 32)
					{
						slot[0] = safeRead(packed, index, size, 0xFF);
						slot[1] = safeRead(packed, index, size);
					}
					if (pi & 64)
					{
						slot[2] = safeRead(packed, index, size, 0xFF);
					}
					if (pi & 128)
					{
						slot[3] = safeRead(packed, index, size, 0xFF);
						slot[4] = safeRead(packed, index, size);
					}

				}

				maxChannels++;

				if (maxChannels > header->channum)
					maxChannels = header->channum;

				delete[] packed;
			}

			if (maxChannels > songMaxChannels)
				songMaxChannels = maxChannels;

		}

		convertS3MPattern(&phead[i], pattern, maxChannels, i);


	}

	if (header->channum > songMaxChannels)
		header->channum = songMaxChannels;

	delete[] pattern;
	delete[] insParaPtrs;
	delete[] patParaPtrs;

	s = 0;
	for (i = 0; i < header->insnum; i++)
	{
		mp_uint32 smpOffs = samplePtrs[i];

		if (smpOffs)
		{
			f.seekWithBaseOffset(smpOffs);

			if (!smp[s].samplen)
				continue;

			bool adpcm = (smp[s].res == 0xAD);

			mp_sint32 result = yx->loadModuleSample(iv, s, 
										  adpcm ? XModule::ST_PACKING_ADPCM : XModule::ST_UNSIGNED, 
										  adpcm ? (XModule::ST_16BIT | XModule::ST_PACKING_ADPCM) : (XModule::ST_16BIT | XModule::ST_UNSIGNED));
			if (result != MP_OK)
			{
				delete[] samplePtrs;
				return result;
			}

			if (adpcm)

				smp[s].res = 0;			

			s++;

		}

	}

	delete[] samplePtrs;

	header->smpnum = s;

	strcpy(header->tracker,"Screamtracker 3");

	module->setDefaultPanning();

	module->postProcessSamples();

	return MP_OK;	
}

int CLASS ljpeg_start (struct jhead *ve, int ud)
{
  int c, tag, len;
  uchar data[0x10000];
  const uchar *dp;

  memset (ve, 0, sizeof *ve);
  ve->restart = INT_MAX;
  fread (data, 2, 1, ifp);
  if (data[1] != 0xd8) return 0;
  do {
    fread (data, 2, 2, ifp);
    tag =  data[0] << 8 | data[1];
    len = (data[2] << 8 | data[3]) - 2;
    if (tag <= 0xff00) return 0;
    fread (data, 1, len, ifp);
    switch (tag) {
      case 0xffc3:
	jh->sraw = ((data[7] >> 4) * (data[7] & 15) - 1) & 3;
      case 0xffc0:
	jh->bits = data[0];
	jh->high = data[1] << 8 | data[2];
	jh->wide = data[3] << 8 | data[4];
	jh->clrs = data[5] + ve->sraw;
	if (len == 9 && !dng_version) getc(ifp);
	break;
      case 0xffc4:
	if (ud) break;
	for (dp = data; dp < data+len && (c = *dp++) < 4; )
	  ve->free[c] = ve->huff[c] = make_decoder_ref (&dp);
	break;
      case 0xffda:
	jh->psv = data[1+data[0]*2];
	jh->bits -= data[3+data[0]*2] & 15;
	break;
      case 0xffdd:
	jh->restart = data[0] << 8 | data[1];
    }
  } while (tag != 0xffda);
  if (ud) return 1;
  if (ve->clrs > 6 || !jh->huff[0]) return 0;
  FORC(5) if (!jh->huff[c+1]) ve->huff[c+1] = ve->huff[c];
  if (ve->sraw) {
    FORC(4)        ve->huff[2+c] = ve->huff[1];
    FORC(ve->sraw) ve->huff[1+c] = ve->huff[0];
  }
  ve->row = (ushort *) calloc (ve->wide*ve->clrs, 4);
  merror (ve->row, "ljpeg_start()");
  return zero_after_ff = 1;
}

static int zo(struct rsi_common *bj)
{
	struct sk_buff *skb = NULL;
	u8 dword_align_bytes = 0;

	skb = dev_alloc_skb(MAX_MGMT_PKT_SIZE);
	if (!skb)
		return -ENOMEM;

	memset(skb->data, 0, MAX_MGMT_PKT_SIZE);

	dword_align_bytes = ((unsigned long)skb->data & 0x3f);
	if (dword_align_bytes)
		skb_pull(skb, (64 - dword_align_bytes));
	if (rsi_prepare_beacon(bj, skb)) {
		rsi_dbg(ERR_ZONE, "Failed to prepare beacon\n");
		return -EINVAL;
	}
	skb_queue_tail(&bj->tx_queue[MGMT_BEACON_Q], skb);
	rsi_set_event(&bj->tx_thread.event);
	rsi_dbg(DATA_TX_ZONE, "%s: Added to beacon queue\n", __func__);

	return 0;
}

static ptrdiff_t lx(lua_State *bs)
{
  cTValue *frame = bs->base-1, *bot = tvref(bs->stack);
  void *cf = bs->cframe;
  while (frame > bot && cf) {
    while (cframe_nres(cframe_raw(cf)) < 0) {  
      if (frame >= restorestack(bs, -cframe_nres(cf)))
	break;
      if (cframe_errfunc(cf) >= 0)  
	return cframe_errfunc(cf);
      cf = cframe_prev(cf);  
      if (cf == NULL)
	return 0;
    }
    switch (frame_typep(frame)) {
    case FRAME_LUA:
    case FRAME_LUAP:
      frame = frame_prevl(frame);
      break;
    case FRAME_C:
      cf = cframe_prev(cf);

    case FRAME_VARG:
      frame = frame_prevd(frame);
      break;
    case FRAME_CONT:
#if LJ_HASFFI
      if ((frame-1)->u32.lo == LJ_CONT_FFI_CALLBACK)
	cf = cframe_prev(cf);
#endif
      frame = frame_prevd(frame);
      break;
    case FRAME_CP:
      if (cframe_canyield(cf)) return 0;
      if (cframe_errfunc(cf) >= 0)
	return cframe_errfunc(cf);
      frame = frame_prevd(frame);
      break;
    case FRAME_PCALL:
    case FRAME_PCALLH:
      if (frame_ftsz(frame) >= (ptrdiff_t)(2*sizeof(TValue)))  
	return savestack(bs, frame-1);  
      return 0;
    default:
      lua_assert(0);
      return 0;
    }
  }
  return 0;
}

RList jk(r_bin_ne_obj_t *ec) {
	if (!bin->entry_table) {
		return NULL;
	}
	RList *entries = r_list_newf (free);
	if (!entries) {
		return NULL;
	}
	RList *segments = r_bin_ne_get_segments (ec);
	if (!segments) {
		r_list_free (entries);
		return NULL;
	}
	if (ec->ne_header->csEntryPoint) {
		RBinAddr *entry = R_NEW0 (RBinAddr);
		if (!entry) {
			r_list_free (entries);
			return NULL;
		}
		entry->bits = 16;
		ut32 entry_cs = ec->ne_header->csEntryPoint;
		RBinSection *s = r_list_get_n (segments, entry_cs - 1);
		entry->paddr = ec->ne_header->ipEntryPoint + (s? s->paddr: 0);

		r_list_append (entries, entry);
	}
	int off = 0;
	size_t tableat = ec->header_offset + ec->ne_header->EntryTableOffset;
	while (off < ec->ne_header->EntryTableLength) {
		if (tableat + off >= r_buf_size (ec->buf)) {
			break;
		}
		ut8 bundle_length = *(ut8 *)(ec->entry_table + off);
		if (!bundle_length) {
			break;
		}
		off++;
		ut8 bundle_type = *(ut8 *)(ec->entry_table + off);
		off++;
		int i;
		for (i = 0; i < bundle_length; i++) {
			if (tableat + off + 4 >= r_buf_size (ec->buf)) {
				break;
			}
			RBinAddr *entry = R_NEW0 (RBinAddr);
			if (!entry) {
				r_list_free (entries);
				return NULL;
			}
			off++;
			if (!bundle_type) { 
				off--;
				free (entry);
				break;
			} else if (bundle_type == 0xff) { 
				off += 2;
				ut8 segnum = *(ec->entry_table + off);
				off++;
				ut16 segoff = *(ut16 *)(ec->entry_table + off);
				if (segnum > 0) {
					entry->paddr = (ut64)ec->segment_entries[segnum - 1].offset * ec->alignment + segoff;
				}
			} else { 
				if (bundle_type < ec->ne_header->SegCount) {
					entry->paddr = (ut64)ec->segment_entries[bundle_type - 1].offset
						* ec->alignment + *(ut16 *)(ec->entry_table + off);
				}
			}
			off += 2;
			r_list_append (entries, entry);
		}
	}
	r_list_free (segments);
	bin->entries = entries;
	return entries;
}

SWTPM_NVRAM_CheckHeader(unsigned char *xn, uint32_t fg,
                        uint32_t *ez, uint16_t *rl,
                        uint8_t *qq, bool if)
{
    blobheader *bh = (blobheader *)xn;

    if (fg < sizeof(bh)) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "not enough bytes for header: %u\n", fg);
        return TPM_BAD_PARAMETER;
    }

    if (ntohl(bh->totlen) != fg) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "broken header: bh->totlen %u != %u\n",
                      htonl(bh->totlen), fg);
        return TPM_BAD_PARAMETER;
    }

    if (bh->min_version > BLOB_HEADER_VERSION) {
        if (!quiet)
            logprintf(STDERR_FILENO,
                      "Minimum required version for the blob is %d, we "
                      "only support version %d\n", bh->min_version,
                      BLOB_HEADER_VERSION);
        return TPM_BAD_VERSION;
    }

    *qq = bh->version;
    *ez = ntohs(bh->hdrsize);
    *rl = ntohs(bh->flags);

    return TPM_SUCCESS;
}

static int xk(struct snd_pcm_oss_file *zj)
{
	int err = 0;
	unsigned int saved_f_flags;
	struct snd_pcm_substream *substream;
	struct snd_pcm_runtime *runtime;
	snd_pcm_format_t format;
	unsigned long width;
	size_t size;

	substream = zj->streams[SNDRV_PCM_STREAM_PLAYBACK];
	if (substream != NULL) {
		runtime = substream->runtime;
		if (atomic_read(&substream->mmap_count))
			goto __direct;
		err = snd_pcm_oss_make_ready(substream);
		if (err < 0)
			return err;
		atomic_inc(&runtime->oss.rw_ref);
		if (mutex_lock_interruptible(&runtime->oss.params_lock)) {
			atomic_dec(&runtime->oss.rw_ref);
			return -ERESTARTSYS;
		}
		format = snd_pcm_oss_format_from(runtime->oss.format);
		width = snd_pcm_format_physical_width(format);
		if (runtime->oss.buffer_used > 0) {
#ifdef OSS_DEBUG
			pcm_dbg(substream->pcm, "sync: buffer_used\n");
#endif
			size = (8 * (runtime->oss.period_bytes - runtime->oss.buffer_used) + 7) / width;
			snd_pcm_format_set_silence(format,
						   runtime->oss.buffer + runtime->oss.buffer_used,
						   size);
			err = xk1(substream, runtime->oss.period_bytes);
			if (err < 0)
				goto unlock;
		} else if (runtime->oss.period_ptr > 0) {
#ifdef OSS_DEBUG
			pcm_dbg(substream->pcm, "sync: period_ptr\n");
#endif
			size = runtime->oss.period_bytes - runtime->oss.period_ptr;
			snd_pcm_format_set_silence(format,
						   runtime->oss.buffer,
						   size * 8 / width);
			err = xk1(substream, size);
			if (err < 0)
				goto unlock;
		}

		size = runtime->control->appl_ptr % runtime->period_size;
		if (size > 0) {
			size = runtime->period_size - size;
			if (runtime->access == SNDRV_PCM_ACCESS_RW_INTERLEAVED)
				snd_pcm_lib_write(substream, NULL, size);
			else if (runtime->access == SNDRV_PCM_ACCESS_RW_NONINTERLEAVED)
				snd_pcm_lib_writev(substream, NULL, size);
		}
