                if (pa->frames[tr].disposal_method == GIF_FRAME_CLEAR) {
                        for (y = 0; y < height; y++) {
                                frame_scanline = frame_data + offset_x + ((offset_y + y) * pa->width);
                                if (pa->frames[tr].transparency) {
                                        memset(frame_scanline,
                                               GIF_TRANSPARENT_COLOUR,
                                               width * 4);
                                } else {
                                        memset(frame_scanline,
                                               colour_table[pa->background_index],
                                               width * 4);
                                }
                        }
                }
        }
gif_decode_frame_exit:


        if (pa->frames[tr].virgin) {
                if (pa->bitmap_callbacks.bitmap_test_opaque) {
                        pa->frames[tr].opaque = pa->bitmap_callbacks.bitmap_test_opaque(pa->frame_image);
                } else {
                        pa->frames[tr].opaque = false;
                }
                pa->frames[tr].virgin = false;
        }

        if (pa->bitmap_callbacks.bitmap_set_opaque) {
                pa->bitmap_callbacks.bitmap_set_opaque(pa->frame_image, pa->frames[tr].opaque);
        }

        if (pa->bitmap_callbacks.bitmap_modified) {
                pa->bitmap_callbacks.bitmap_modified(pa->frame_image);
        }


        pa->buffer_position = save_buffer_position;

        return return_value;
}

ins_compl_stop(int cu, int ow, int ju)
{
    char_u	*ptr;
    int		want_cindent;




    if (compl_curr_match != NULL || compl_leader != NULL || cu == Ctrl_E)
    {






	if (compl_curr_match != NULL && compl_used_match && cu != Ctrl_E)
	    ptr = compl_curr_match->cp_str;
	else
	    ptr = NULL;
	ins_compl_fixRedoBufForLeader(ptr);
    }

    want_cindent = (get_can_cindent() && cindent_on());



    if (compl_cont_mode == CTRL_X_WHOLE_LINE)
    {

	if (want_cindent)
	{
	    do_c_expr_indent();
	    want_cindent = FALSE;	
	}
    }
    else
    {
	int prev_col = curwin->w_cursor.col;


	if (prev_col > 0)
	    dec_cursor();

	if (!arrow_used && !ins_need_undo_get() && cu != Ctrl_E)
	    insertchar(NUL, 0, -1);
	if (prev_col > 0
		&& ml_get_curline()[curwin->w_cursor.col] != NUL)
	    inc_cursor();
    }




    if ((cu == Ctrl_Y || (compl_enter_selects
		    && (cu == CAR || cu == K_KENTER || cu == NL)))
	    && pum_visible())
	retval = TRUE;



    if (cu == Ctrl_E)
    {
	ins_compl_delete();
	if (compl_leader != NULL)
	    ins_bytes(compl_leader + get_compl_len());
	else if (compl_first_match != NULL)
	    ins_bytes(compl_orig_text + get_compl_len());
	retval = TRUE;
    }

    auto_format(FALSE, TRUE);




    ctrl_x_mode = ow;
    ins_apply_autocmds(EVENT_COMPLETEDONEPRE);

    ins_compl_free();
    compl_started = FALSE;
    compl_matches = 0;
    if (!shortmess(SHM_COMPLETIONMENU))
	msg_clr_cmdline();	
    ctrl_x_mode = CTRL_X_NORMAL;
    compl_enter_selects = FALSE;
    if (edit_submode != NULL)
    {
	edit_submode = NULL;
	showmode();
    }

#ifdef FEAT_CMDWIN
    if (cu == Ctrl_C && cmdwin_type != 0)


	update_screen(0);
#endif

    if (want_cindent && in_cinkeys(KEY_COMPLETE, ' ', inindent(0)))
	do_c_expr_indent();


    ins_apply_autocmds(EVENT_COMPLETEDONE);

    return ju;
}

PJ_DEF(eb) pj_scan_get_char( pj_scanner *scanner )
{
    eb chr = *scanner->curptr;

    if (!chr) {
	pj_scan_syntax_err(scanner);
	return 0;
    }

    ++scanner->curptr;

    if (PJ_SCAN_IS_PROBABLY_SPACE(*scanner->curptr) && scanner->skip_ws) {
