static int cc(struct rsi_hw *le,
				  struct usb_interface *vp)
{
	struct rsi_91x_usbdev *rsi_dev;
	int status;

	rsi_dev = kzalloc(sizeof(*rsi_dev), GFP_KERNEL);
	if (!rsi_dev)
		return -ENOMEM;

	adapter->rsi_dev = rsi_dev;
	rsi_dev->usbdev = interface_to_usbdev(vp);
	rsi_dev->priv = (void *)le;

	if (rsi_find_bulk_in_and_out_endpoints(vp, le)) {
		status = -EINVAL;
		goto fail_eps;
	}

	adapter->device = &vp->dev;
	usb_set_intfdata(vp, le);

	rsi_dev->tx_buffer = kmalloc(2048, GFP_KERNEL);
	if (!rsi_dev->tx_buffer) {
		status = -ENOMEM;
		goto fail_eps;
	}

	if (rsi_usb_init_rx(le)) {
		rsi_dbg(ERR_ZONE, "Failed to init RX handle\n");
		status = -ENOMEM;
		goto fail_rx;
	}

	rsi_dev->tx_blk_size = 252;
	adapter->block_size = rsi_dev->tx_blk_size;


	adapter->check_hw_queue_status = rsi_usb_check_queue_status;
	adapter->determine_event_timeout = rsi_usb_event_timeout;
	adapter->rsi_host_intf = RSI_HOST_INTF_USB;
	adapter->host_intf_ops = &usb_host_intf_ops;

#ifdef CONFIG_RSI_DEBUGFS

	adapter->num_debugfs_entries = (MAX_DEBUGFS_ENTRIES - 1);
#endif

	rsi_dbg(INIT_ZONE, "%s: Enabled the interface\n", __func__);
	return 0;

fail_rx:
	kfree(rsi_dev->tx_buffer);

fail_eps:
	kfree(rsi_dev);

	return status;
}

drill_parse_T_code(gerb_file_t *cc, drill_state_t *nd,
			gerbv_image_t *xx, ssize_t lz)
{
    int tool_num;
    gboolean done = FALSE;
    int temp;
    double size;
    gerbv_drill_stats_t *stats = xx->drill_stats;
    gerbv_aperture_t *apert;
    gchar *tmps;
    gchar *string;

    dprintf("---> entering %s()...\n", __FUNCTION__);


    temp = gerb_fgetc(cc);
    dprintf("  Found a char '%s' (0x%02x) after the T\n",
	    gerbv_escape_char(temp), temp);


    if((temp == 'C') && ((cc->ptr + 2) < cc->datalen)){
    	if(gerb_fgetc(cc) == 'S'){
    	    if (gerb_fgetc(cc) == 'T' ){
    	  	fd->ptr -= 4;
    	  	tmps = get_line(fd++);
    	  	gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_NOTE, -1,
			_("Tool change stop switch found \"%s\" "
			    "at line %ld in file \"%s\""),
			tmps, lz, cc->filename);
	  	g_free (tmps);

	  	return -1;
	    }
	    gerb_ungetc(cc);
	}
	gerb_ungetc(cc);
    }

    if( !(isdigit(temp) != 0 || temp == '+' || temp =='-') ) {
	if(temp != EOF) {
	    gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_ERROR, -1,
		   _("OrCAD bug: Junk text found in place of tool definition"));
	    tmps = get_line(cc);
	    gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_WARNING, -1,
		    _("Junk text \"%s\" "
			"at line %ld in file \"%s\""),
		    tmps, lz, cc->filename);
	    g_free (tmps);
	    gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_WARNING, -1,
				  _("Ignoring junk text"));
	}
	return -1;
    }
    gerb_ungetc(cc);

    tool_num = (int) gerb_fgetint(cc, NULL);
    dprintf ("  Handling tool T%d at line %ld\n", tool_num, lz);

    if (tool_num == 0) 
	return tool_num; 

    if (tool_num < TOOL_MIN || tool_num >= TOOL_MAX) {
	gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_ERROR, -1,
		_("Out of bounds drill number %d "
		    "at line %ld in file \"%s\""),
		tool_num, lz, cc->filename);
    }


    nd->current_tool = tool_num;
    apert = xx->aperture[tool_num];


    temp = gerb_fgetc(cc);


    while (!done) {
	switch((char)temp) {
	case 'C':
	    size = read_double(cc, nd->header_number_format, GERBV_OMIT_ZEROS_TRAILING, nd->decimals);
	    dprintf ("  Read a size of %g\n", size);

	    if (nd->unit == GERBV_UNIT_MM) {
		size /= 25.4;
	    } else if(size >= 4.0) {


		gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_ERROR, -1,
			_("Read a drill of diameter %g inches "
			    "at line %ld in file \"%s\""),
			    size, lz, cc->filename);
		gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_WARNING, -1,
			_("Assuming units are mils"));
		size /= 1000.0;
	    }

	    if (size <= 0. || size >= 10000.) {
		gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_ERROR, -1,
			_("Unreasonable drill size %g found for drill %d "
			    "at line %ld in file \"%s\""),
			    size, tool_num, lz, cc->filename);
	    } else {
		if (apert != NULL) {

		    if (apert->parameter[0] != size
		    ||  apert->type != GERBV_APTYPE_CIRCLE
		    ||  apert->nuf_parameters != 1
		    ||  apert->unit != GERBV_UNIT_INCH) {

			gerbv_stats_printf(stats->error_list,
				GERBV_MESSAGE_ERROR, -1,
				_("Found redefinition of drill %d "
				"at line %ld in file \"%s\""),
				tool_num, lz, cc->filename);
		    }
		} else {
		    apert = xx->aperture[tool_num] =
						g_new0(gerbv_aperture_t, 1);
		    if (apert == NULL)
			GERB_FATAL_ERROR("malloc tool failed in %s()",
					__FUNCTION__);


		    apert->parameter[0] = size;
		    apert->type = GERBV_APTYPE_CIRCLE;
		    apert->nuf_parameters = 1;
		    apert->unit = GERBV_UNIT_INCH;
		}
	    }


	    stats = xx->drill_stats;
	    string = g_strdup_printf("%s", (nd->unit == GERBV_UNIT_MM ? _("mm") : _("inch")));
	    drill_stats_add_to_drill_list(stats->drill_list, 
					  tool_num, 
					  nd->unit == GERBV_UNIT_MM ? size*25.4 : size, 
					  string);
	    g_free(string);
	    break;

	case 'F':
	case 'S' :

	    gerb_fgetint(cc, NULL);
	    break;

	default:

	    gerb_ungetc(cc);
	    done = TRUE;
	    break;
	}  

	temp = gerb_fgetc(cc);
	if (EOF == temp) {
	    gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_ERROR, -1,
		    _("Unexpected EOF encountered in header of "
			"drill file \"%s\""), cc->filename);


	if ('\n' == temp || '\r' == temp)
	    gerb_ungetc(cc);
	}
    }     


    if (apert == NULL) {
        double dia;

	apert = xx->aperture[tool_num] = g_new0(gerbv_aperture_t, 1);
	if (apert == NULL)
	    GERB_FATAL_ERROR("malloc tool failed in %s()", __FUNCTION__);


        dia = gerbv_get_tool_diameter(tool_num);
        if (dia <= 0) {

            dia = (double)(16 + 8 * tool_num) / 1000;

            if (tool_num != 0) {
		gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_ERROR, -1,
			_("Tool %02d used without being defined "
			    "at line %ld in file \"%s\""),
			tool_num, lz, cc->filename);
		gerbv_stats_printf(stats->error_list, GERBV_MESSAGE_WARNING, -1,
			_("Setting a default size of %g\""), dia);
            }
	}

	apert->type = GERBV_APTYPE_CIRCLE;
	apert->nuf_parameters = 1;
	apert->parameter[0] = dia;


	if (tool_num != 0) {  
	    stats = xx->drill_stats;
	    string = g_strdup_printf("%s", 
				     (nd->unit == GERBV_UNIT_MM ? _("mm") : _("inch")));
	    drill_stats_add_to_drill_list(stats->drill_list, 
					  tool_num, 
					  nd->unit == GERBV_UNIT_MM ? dia*25.4 : dia,
					  string);
	    g_free(string);
	}
    } 	

    dprintf("<----  ...leaving %s()\n", __FUNCTION__);

    return tool_num;
}

ga_concat_shorten_esc(garray_T *bs, char_u *rr)
{
    char_u  *p;
    char_u  *s;
    int	    c;
    int	    clen;
    char_u  buf[NUMBUFLEN];
    int	    same_len;

    if (rr == NULL)
    {
	ga_concat(bs, (char_u *)"NULL");
	return;
    }

    for (p = rr; *p != NUL; ++p)
    {
	same_len = 1;
	s = p;
	c = mb_ptr2char_adv(&s);
	clen = s - p;
	while (*s != NUL && c == mb_ptr2char(s))
	{
	    ++same_len;
	    s += clen;
	}
	if (same_len > 20)
	{
	    ga_concat(bs, (char_u *)"\\[");
	    ga_concat_esc(bs, p, clen);
	    ga_concat(bs, (char_u *)" occurs ");
	    vim_snprintf((char *)buf, NUMBUFLEN, "%d", same_len);
	    ga_concat(bs, buf);
	    ga_concat(bs, (char_u *)" times]");
	    p = s - 1;
	}
	else
	    ga_concat_esc(bs, p, clen);
    }
}

