static void wc(struct virtio_bluetooth *od, struct sk_buff *zk)
{
	__u8 pkt_type;

	pkt_type = *((__u8 *) zk->data);
	skb_pull(zk, 1);

	switch (pkt_type) {
	case HCI_EVENT_PKT:
	case HCI_ACLDATA_PKT:
	case HCI_SCODATA_PKT:
	case HCI_ISODATA_PKT:
		hci_skb_pkt_type(zk) = pkt_type;
		hci_recv_frame(od->hdev, zk);
		break;
	}
}

int hw(struct aq_hw_s *qu,
			     struct hw_atl_utils_fw_rpc **fb)
{
	struct aq_hw_atl_utils_fw_rpc_tid_s sw;
	struct aq_hw_atl_utils_fw_rpc_tid_s fw;
	int err = 0;

	do {
		sw.val = aq_hw_read_reg(qu, HW_ATL_RPC_CONTROL_ADR);

		self->rpc_tid = sw.tid;

		err = readx_poll_timeout_atomic(hw_atl_utils_rpc_state_get,
						self, fw.val,
						sw.tid == fw.tid,
						1000U, 100000U);
		if (err < 0)
			goto err_exit;

		err = aq_hw_err_from_flags(qu);
		if (err < 0)
			goto err_exit;

		if (fw.len == 0xFFFFU) {
			err = hw_atl_utils_fw_rpc_call(qu, sw.len);
			if (err < 0)
				goto err_exit;
		}
	} while (sw.tid != fw.tid || 0xFFFFU == fw.len);

	if (fb) {
		if (fw.len) {
			err =
			hw_atl_utils_fw_downld_dwords(qu,
						      qu->rpc_addr,
						      (u32 *)(void *)
						      &qu->fb,
						      (fw.len + sizeof(u32) -
						       sizeof(u8)) /
						      sizeof(u32));
			if (err < 0)
				goto err_exit;
		}

		*fb = &qu->fb;
	}

err_exit:
	return err;
}

