static void ky(ESPState *fg)
{
    uint32_t n;

    trace_esp_ky(fg->status);

    fifo8_reset(&fg->fifo);
    esp_fifo_push(fg, fg->status);
    esp_fifo_push(fg, 0);

    if (fg->dma) {
        if (fg->dma_memory_write) {
            fg->dma_memory_write(fg->dma_opaque,
                                (uint8_t *)fifo8_pop_buf(&fg->fifo, 2, &n), 2);
            fg->rregs[ESP_RSTAT] = STAT_TC | STAT_ST;
            fg->rregs[ESP_RINTR] |= INTR_BS | INTR_FC;
            fg->rregs[ESP_RSEQ] = SEQ_CD;
        } else {
            fg->pdma_cb = ky_pdma_cb;
            esp_raise_drq(fg);
            return;
        }
    } else {
        fg->ti_size = 2;
        fg->rregs[ESP_RFLAGS] = 2;
    }
    esp_raise_irq(fg);
}

static void jz(pjmedia_rtcp_session *pg,
			   const void *he,
			   pj_size_t ec)
{
    pj_str_t reason = {"-", 1};


    if (ec > 8) {
	reason.slen = PJ_MIN(sizeof(pg->stat.peer_sdes_buf_),
                             *((pj_uint8_t*)pkt+8));
	pj_memcpy(pg->stat.peer_sdes_buf_, ((pj_uint8_t*)pkt+9),
		  reason.slen);
	reason.ptr = pg->stat.peer_sdes_buf_;
    }


    PJ_LOG(5, (pg->name, "Received RTCP BYE, reason: %.*s",
	       reason.slen, reason.ptr));
}

eval7(
    char_u	**arg,
    typval_T	*rettv,
    evalarg_T	*evalarg,
    bv)	
{
    int		evaluate = evalarg != NULL
				      && (evalarg->eval_flags & EVAL_EVALUATE);
    int		len;
    char_u	*s;
    char_u	*name_start = NULL;
    char_u	*start_leader, *end_leader;
    int		ret = OK;
    char_u	*alias;


    rettv->v_type = VAR_UNKNOWN;


    start_leader = *arg;
    if (eval_leader(arg, in_vim9script()) == FAIL)
	return FAIL;
    end_leader = *arg;

    if (**arg == '.' && (!isdigit(*(*arg + 1))
#ifdef FEAT_FLOAT
	    || in_old_script(2)
#endif
	    ))
    {
	semsg(_(e_invalid_expression_str), *arg);
	++*arg;
	return FAIL;
    }

    switch (**arg)
    {

    case '0':
    case '1':
    case '2':
    case '3':
    case '4':
    case '5':
    case '6':
    case '7':
    case '8':
    case '9':
    case '.':	ret = eval_number(arg, rettv, evaluate, want_string);



		if (ret == OK && evaluate && end_leader > start_leader
						  && rettv->v_type != VAR_BLOB)
		    ret = eval7_leader(rettv, TRUE, start_leader, &end_leader);
		break;


    case '"':	ret = eval_string(arg, rettv, evaluate);
		break;


    case '\'':	ret = eval_lit_string(arg, rettv, evaluate);
		break;


    case '[':	ret = eval_list(arg, rettv, evalarg, TRUE);
		break;


    case '#':	if (in_vim9script())
		{
		    ret = vim9_bad_comment(*arg) ? FAIL : NOTDONE;
		}
		else if ((*arg)[1] == '{')
		{
		    ++*arg;
		    ret = eval_dict(arg, rettv, evalarg, TRUE);
		}
		else
		    ret = NOTDONE;
		break;


    case '{':	if (in_vim9script())
		    ret = NOTDONE;
		else
		    ret = get_lambda_tv(arg, rettv, in_vim9script(), evalarg);
		if (ret == NOTDONE)
		    ret = eval_dict(arg, rettv, evalarg, FALSE);
		break;


    case '&':	ret = eval_option(arg, rettv, evaluate);
		break;


    case '$':	ret = eval_env_var(arg, rettv, evaluate);
		break;


    case '@':	++*arg;
		if (evaluate)
		{
		    if (in_vim9script() && IS_WHITE_OR_NUL(**arg))
			semsg(_(e_syntax_error_at_str), *arg);
		    else if (in_vim9script() && !valid_yank_reg(**arg, FALSE))
			emsg_invreg(**arg);
		    else
		    {
			rettv->v_type = VAR_STRING;
			rettv->vval.v_string = get_reg_contents(**arg,
								GREG_EXPR_SRC);
		    }
		}
		if (**arg != NUL)
		    ++*arg;
		break;


    case '(':	ret = NOTDONE;
		if (in_vim9script())
		{
		    ret = get_lambda_tv(arg, rettv, TRUE, evalarg);
		    if (ret == OK && evaluate)
		    {
			ufunc_T *ufunc = rettv->vval.v_partial->pt_func;




			if (ufunc->uf_ret_type->tt_type == VAR_VOID)
			    ufunc->uf_ret_type = &t_unknown;
			if (compile_def_function(ufunc,
				     FALSE, COMPILE_TYPE(ufunc), NULL) == FAIL)
			{
			    clear_tv(rettv);
			    ret = FAIL;
			}
		    }
		}
		if (ret == NOTDONE)
		{
		    *arg = skipwhite_and_linebreak(*arg + 1, evalarg);
		    ret = eval1(arg, rettv, evalarg);	

		    *arg = skipwhite_and_linebreak(*arg, evalarg);
		    if (**arg == ')')
			++*arg;
		    else if (ret == OK)
		    {
			emsg(_(e_missing_closing_paren));
			clear_tv(rettv);
			ret = FAIL;
		    }
		}
		break;

    default:	ret = NOTDONE;
		break;
    }

    if (ret == NOTDONE)
    {

	s = *arg;
	len = get_name_len(arg, &alias, evaluate, TRUE);
	if (alias != NULL)
	    s = alias;

	if (len <= 0)
	    ret = FAIL;
	else
	{
	    int	    flags = evalarg == NULL ? 0 : evalarg->eval_flags;

	    if (evaluate && in_vim9script() && len == 1 && *s == '_')
	    {
		emsg(_(e_cannot_use_underscore_here));
		ret = FAIL;
	    }
	    else if ((in_vim9script() ? **arg : *skipwhite(*arg)) == '(')
	    {

		*arg = skipwhite(*arg);
		ret = eval_func(arg, evalarg, s, len, rettv, flags, NULL);
	    }
	    else if (flags & EVAL_CONSTANT)
		ret = FAIL;
	    else if (evaluate)
	    {

		if (len == 4 && in_vim9script() && STRNCMP(s, "true", 4) == 0)
		{
		    rettv->v_type = VAR_BOOL;
		    rettv->vval.v_number = VVAL_TRUE;
		    ret = OK;
		}
		else if (len == 5 && in_vim9script()
						&& STRNCMP(s, "false", 5) == 0)
		{
		    rettv->v_type = VAR_BOOL;
		    rettv->vval.v_number = VVAL_FALSE;
		    ret = OK;
		}
		else if (len == 4 && in_vim9script()
						&& STRNCMP(s, "null", 4) == 0)
		{
		    rettv->v_type = VAR_SPECIAL;
		    rettv->vval.v_number = VVAL_NULL;
		    ret = OK;
		}
		else
		{
		    name_start = s;
		    ret = eval_variable(s, len, 0, rettv, NULL,
					   EVAL_VAR_VERBOSE + EVAL_VAR_IMPORT);
		}
	    }
	    else
	    {

		check_vars(s, len);
		ret = OK;
	    }
	}
	vim_free(alias);
    }



    if (ret == OK)
	ret = handle_subscript(arg, name_start, rettv, evalarg, TRUE);


    if (ret == OK && evaluate && end_leader > start_leader)
	ret = eval7_leader(rettv, FALSE, start_leader, &end_leader);
    return ret;
}

static void yt(char *te, char *tm, size_t ef, size_t fw) {
	char *p = te + ef + 1;
	char *q = tm + fw + 1;
	char *r = tm + fw;
	struct stat s;
	bool last = false;
	*r = '\0';
	for (; !last; p++, q++) {
		if (*p == '\0') {
			last = true;
		}
		if (*p == '\0' || (*p == '/' && *(p - 1) != '/')) {



			*p = '\0';
			if (stat(te, &s) == 0 && S_ISDIR(s.st_mode)) {


				*q = '\0';
				*r = '/';
				r = q;
				mkdir_attr(tm, s.st_mode, 0, 0);
			}
			if (!last) {


				*p = '/';
			}
		}
	}
}

bool xh(SQSharedState *zf,const SQObjectPtr xo,const SQObjectPtr bn,bool lv)
{
    SQObjectPtr temp;
    bool belongs_to_static_table = sq_type(val) == OT_CLOSURE || sq_type(val) == OT_NATIVECLOSURE || lv;
    if(_locked && !belongs_to_static_table)
        return false; 
    if(_members->Get(key,temp) && _isfield(temp)) 
    {
        _defaultvalues[_member_idx(temp)].val = val;
        return true;
    }
    if(belongs_to_static_table) {
        SQInteger mmidx;
        if((sq_type(val) == OT_CLOSURE || sq_type(val) == OT_NATIVECLOSURE) &&
            (mmidx = zf->GetMetaMethodIdxByName(key)) != -1) {
            _metamethods[mmidx] = val;
        }
        else {
            SQObjectPtr theval = val;
            if(_base && sq_type(val) == OT_CLOSURE) {
                theval = _closure(val)->Clone();
                _closure(theval)->_base = _base;
                __ObjAddRef(_base); 
            }
            if(sq_type(temp) == OT_NULL) {
                bool isconstructor;
                SQVM::IsEqual(zf->_constructoridx, key, isconstructor);
                if(isconstructor) {
                    _constructoridx = (SQInteger)_methods.size();
                }
                SQClassMember m;
                m.val = theval;
                _members->NewSlot(key,SQObjectPtr(_make_method_idx(_methods.size())));
                _methods.push_back(m);
            }
            else {
                _methods[_member_idx(temp)].val = theval;
            }
        }
        return true;
    }
    SQClassMember m;
    m.val = val;
    _members->NewSlot(key,SQObjectPtr(_make_field_idx(_defaultvalues.size())));
    _defaultvalues.push_back(m);
    return true;
}

static void xz(struct bpf_ringbuf *ot, u64 jy)
{
	unsigned long cons_pos, prod_pos, new_prod_pos, flags;
	u32 len, pg_off;
	struct bpf_ringbuf_hdr *hdr;

	if (unlikely(jy > RINGBUF_MAX_RECORD_SZ))
		return NULL;

	len = round_up(jy + BPF_RINGBUF_HDR_SZ, 8);
	cons_pos = smp_load_acquire(&ot->consumer_pos);

	if (in_nmi()) {
		if (!spin_trylock_irqsave(&ot->spinlock, flags))
			return NULL;
	} else {
		spin_lock_irqsave(&ot->spinlock, flags);
	}

	prod_pos = ot->producer_pos;
	new_prod_pos = prod_pos + len;


	if (new_prod_pos - cons_pos > ot->mask) {
		spin_unlock_irqrestore(&ot->spinlock, flags);
		return NULL;
	}

	hdr = (void *)ot->data + (prod_pos & ot->mask);
	pg_off = bpf_ringbuf_rec_pg_off(ot, hdr);
	hdr->len = jy | BPF_RINGBUF_BUSY_BIT;
	hdr->pg_off = pg_off;


	smp_store_release(&ot->producer_pos, new_prod_pos);

	spin_unlock_irqrestore(&ot->spinlock, flags);

	return (void *)hdr + BPF_RINGBUF_HDR_SZ;
}

