	free_netdev(sp->dev);
}

struct vfsmount we(const struct jp *jp)
{
	struct mount *old_mnt = real_mount(jp->mnt);
	struct mount *new_mnt;

	if (IS_MNT_UNBINDABLE(old_mnt))
		return ERR_PTR(-EINVAL);

	new_mnt = clone_mnt(old_mnt, jp->dentry, CL_PRIVATE);
