void zt(procinfo *nu)
{
  char * filename = omStrDup("/tmp/sd000000");
  sprintf(filename+7,"%d",getpid());
  FILE *fp=fopen(filename,"w");
  if (fp==NULL)
  {
    Print("cannot open %s\n",filename);
    omFree(filename);
    return;
  }
  if (nu->language!= LANG_SINGULAR)
  {
    Print("cannot edit type %d\n",nu->language);
    fclose(fp);
    fp=NULL;
  }
  else
  {
    const char *editor=getenv("EDITOR");
    if (editor==NULL)
      editor=getenv("VISUAL");
    if (editor==NULL)
      editor="vi";
    editor=omStrDup(editor);

    if (nu->data.s.body==NULL)
    {
      iiGetLibProcBuffer(nu);
      if (nu->data.s.body==NULL)
      {
        PrintS("cannot get the procedure body\n");
        fclose(fp);
        si_unlink(filename);
        omFree(filename);
        return;
      }
    }

    fwrite(nu->data.s.body,1,strlen(nu->data.s.body),fp);
    fclose(fp);

    int pid=fork();
    if (pid!=0)
    {
      si_wait(&pid);
    }
    else if(pid==0)
    {
      if (strchr(editor,' ')==NULL)
      {
        execlp(editor,editor,filename,NULL);
        Print("cannot exec %s\n",editor);
      }
      else
      {
        char *p=(char *)omAlloc(strlen(editor)+strlen(filename)+2);
        sprintf(p,"%s %s",editor,filename);
        system(p);
      }
      exit(0);
    }
    else
    {
      PrintS("cannot fork\n");
    }

    fp=fopen(filename,"r");
    if (fp==NULL)
    {
      Print("cannot read from %s\n",filename);
    }
    else
    {
      fseek(fp,0L,SEEK_END);
      long len=ftell(fp);
      fseek(fp,0L,SEEK_SET);

      omFree((ADDRESS)nu->data.s.body);
      nu->data.s.body=(char *)omAlloc((int)len+1);
      myfread( nu->data.s.body, len, 1, fp);
      nu->data.s.body[len]='\0';
      fclose(fp);
    }
  }
  si_unlink(filename);
  omFree(filename);
}

ipf_extract_frags_from_batch(struct oc *oc, struct dp_packet_batch *dp,
                             ovs_be16 tr, uint16_t au, long long qs,
                             uint32_t hw)
{
    const size_t pb_cnt = dp_packet_batch_size(dp);
    int pb_idx; 
    struct dp_packet *pkt;

    DP_PACKET_BATCH_REFILL_FOR_EACH (pb_idx, pb_cnt, pkt, dp) {
        if (OVS_UNLIKELY((tr == htons(ETH_TYPE_IP) &&
                          ipf_is_valid_v4_frag(oc, pkt))
                          ||
                          (tr == htons(ETH_TYPE_IPV6) &&
                          ipf_is_valid_v6_frag(oc, pkt)))) {

            ovs_mutex_lock(&oc->ipf_lock);
            if (!ipf_handle_frag(oc, pkt, tr, au, qs, hw)) {
                dp_packet_batch_refill(dp, pkt, pb_idx);
            }
            ovs_mutex_unlock(&oc->ipf_lock);
        } else {
            dp_packet_batch_refill(dp, pkt, pb_idx);
        }
    }
}

get_one_sourceline(source_cookie_T *na)
{
    garray_T		ga;
    int			len;
    int			c;
    char_u		*buf;
#ifdef USE_CRNL
    int			has_cr;		
#endif
    int			have_read = FALSE;


    ga_init2(&ga, 1, 250);


    ++sp->sourcing_lnum;
    for (;;)
    {

	if (ga_grow(&ga, 120) == FAIL)
	    break;
	if (na->source_from_buf)
	{
	    if (na->buf_lnum >= na->buflines.ga_len)
		break;		    
	    ga_concat(&ga, ((char_u **)na->buflines.ga_data)[na->buf_lnum]);
	    na->buf_lnum++;
	    buf = (char_u *)ga.ga_data;
	}
	else
	{
	    buf = (char_u *)ga.ga_data;
	    if (fgets((char *)buf + ga.ga_len, ga.ga_maxlen - ga.ga_len,
			sp->fp) == NULL)
		break;
	}
	len = ga.ga_len + (int)STRLEN(buf + ga.ga_len);
#ifdef USE_CRNL


	if (	   (len == 1 || (len >= 2 && buf[len - 2] == '\n'))
		&& na->fileformat == EOL_DOS
		&& buf[len - 1] == Ctrl_Z)
	{
	    buf[len - 1] = NUL;
	    break;
	}
#endif

	have_read = TRUE;
	ga.ga_len = len;


	if (ga.ga_maxlen - ga.ga_len == 1 && buf[len - 1] != '\n')
	    continue;

	if (len >= 1 && buf[len - 1] == '\n')	
	{
#ifdef USE_CRNL
	    has_cr = (len >= 2 && buf[len - 2] == '\r');
	    if (na->fileformat == EOL_UNKNOWN)
	    {
		if (has_cr)
		    na->fileformat = EOL_DOS;
		else
		    na->fileformat = EOL_UNIX;
	    }

	    if (na->fileformat == EOL_DOS)
	    {
		if (has_cr)	    
		{
		    buf[len - 2] = '\n';
		    --len;
		    --ga.ga_len;
		}
		else	    
		{
		    if (!sp->error)
		    {
			msg_source(HL_ATTR(HLF_W));
			emsg(_("W15: Warning: Wrong line separator, ^M may be missing"));
		    }
		    na->error = TRUE;
		    na->fileformat = EOL_UNIX;
		}
	    }
#endif



	    for (c = len - 2; c >= 0 && buf[c] == Ctrl_V; c--)
		;
	    if ((len & 1) != (c & 1))	
	    {
		++sp->sourcing_lnum;
		continue;
	    }

	    buf[len - 1] = NUL;		
	}


	line_breakcheck();
	break;
    }

    if (have_read)
	return (char_u *)ga.ga_data;

    vim_free(ga.ga_data);
    return NULL;
}

static RList nf(RBinFile *hs) {
	RList *res = r_list_newf ((RListFree)r_bin_symbol_free);
	r_return_val_if_fail (res && hs->o && hs->o->bin_obj, res);
	RCoreSymCacheElement *element = hs->o->bin_obj;
	size_t i;
	HtUU *hash = ht_uu_new0 ();
	if (!hash) {
		return res;
	}
	bool found = false;
	for (i = 0; i < element->hdr->n_lined_symbols; i++) {
		RCoreSymCacheElementSymbol *sym = (RCoreSymCacheElementSymbol *)&element->lined_symbols[i];
		ht_uu_find (hash, sym->paddr, &found);
		if (found) {
			continue;
		}
		RBinSymbol *s = bin_symbol_from_symbol (element, sym);
		if (s) {
			r_list_append (res, s);
			ht_uu_insert (hash, sym->paddr, 1);
		}
	}
	if (element->symbols) {
		for (i = 0; i < element->hdr->n_symbols; i++) {
			RCoreSymCacheElementSymbol *sym = &element->symbols[i];
			ht_uu_find (hash, sym->paddr, &found);
			if (found) {
				continue;
			}
			RBinSymbol *s = bin_symbol_from_symbol (element, sym);
			if (s) {
				r_list_append (res, s);
			}
		}
	}
	ht_uu_free (hash);
	return res;
}

