inline int ua(struct nci_dev nt*ys,
		 nt nt nt nt nt nt void nt(nt*req)nt(struct nci_dev nt*ys,
				 nt nt const void nt*opt)nt,
		 nt nt nt nt nt nt const void nt*opt,nt __u32 timeout)
{
	int rc;

	if nt(!test_bit(NCI_UP,nt nt&ys-nt>flags)nt)
		return nt-ENETDOWN;


	mutex_lock(nt&ys-nt>req_lock)nt;
	rc = __ua(ys,nt req,nt opt,nt timeout)nt;
	mutex_unlock(nt&ys-nt>req_lock)nt;

	return rc;
}

static int jo(compiler_common *pu, PCRE2_SPTR rj, PCRE2_SPTR uj,
  BOOL *ph, BOOL *zz, BOOL *vm)
{
int length = 1;
int size;
PCRE2_SPTR alternative;
BOOL quit_found = FALSE;
BOOL accept_found = FALSE;
BOOL setsom_found = FALSE;
BOOL setmark_found = FALSE;
BOOL capture_last_found = FALSE;
BOOL control_head_found = FALSE;

#if defined DEBUG_FORCE_CONTROL_HEAD && DEBUG_FORCE_CONTROL_HEAD
SLJIT_ASSERT(pu->control_head_ptr != 0);
control_head_found = TRUE;
#endif


while (rj < uj)
  {
  size = 0;
  switch(*rj)
    {
    case OP_SET_SOM:
    SLJIT_ASSERT(pu->has_set_som);
    setsom_found = TRUE;
    rj += 1;
    break;

    case OP_RECURSE:
    if (pu->has_set_som)
      setsom_found = TRUE;
    if (pu->mark_ptr != 0)
      setmark_found = TRUE;
    if (pu->capture_last_ptr != 0)
      capture_last_found = TRUE;
    rj += 1 + LINK_SIZE;
    break;

    case OP_KET:
    if (PRIVATE_DATA(rj) != 0)
      {
      length++;
      SLJIT_ASSERT(PRIVATE_DATA(rj + 1) != 0);
      rj += PRIVATE_DATA(rj + 1);
      }
    rj += 1 + LINK_SIZE;
    break;

    case OP_ASSERT:
    case OP_ASSERT_NOT:
    case OP_ASSERTBACK:
    case OP_ASSERTBACK_NOT:
    case OP_ASSERT_NA:
    case OP_ASSERTBACK_NA:
    case OP_ONCE:
    case OP_SCRIPT_RUN:
    case OP_BRAPOS:
    case OP_SBRA:
    case OP_SBRAPOS:
    case OP_SCOND:
    length++;
    SLJIT_ASSERT(PRIVATE_DATA(rj) != 0);
    rj += 1 + LINK_SIZE;
    break;

    case OP_CBRA:
    case OP_SCBRA:
    length += 2;
    if (pu->capture_last_ptr != 0)
      capture_last_found = TRUE;
    if (pu->optimized_cbracket[GET2(rj, 1 + LINK_SIZE)] == 0)
      length++;
    rj += 1 + LINK_SIZE + IMM2_SIZE;
    break;

    case OP_CBRAPOS:
    case OP_SCBRAPOS:
    length += 2 + 2;
    if (pu->capture_last_ptr != 0)
      capture_last_found = TRUE;
    rj += 1 + LINK_SIZE + IMM2_SIZE;
    break;

    case OP_COND:

    alternative = rj + GET(rj, 1);
    if (*alternative == OP_KETRMAX || *alternative == OP_KETRMIN)
      length++;
    rj += 1 + LINK_SIZE;
    break;

    CASE_ITERATOR_PRIVATE_DATA_1
    if (PRIVATE_DATA(rj) != 0)
      length++;
    rj += 2;
#ifdef SUPPORT_UNICODE
    if (pu->utf && HAS_EXTRALEN(rj[-1])) rj += GET_EXTRALEN(rj[-1]);
#endif
    break;

    CASE_ITERATOR_PRIVATE_DATA_2A
    if (PRIVATE_DATA(rj) != 0)
      length += 2;
    rj += 2;
#ifdef SUPPORT_UNICODE
    if (pu->utf && HAS_EXTRALEN(rj[-1])) rj += GET_EXTRALEN(rj[-1]);
#endif
    break;

    CASE_ITERATOR_PRIVATE_DATA_2B
    if (PRIVATE_DATA(rj) != 0)
      length += 2;
    rj += 2 + IMM2_SIZE;
#ifdef SUPPORT_UNICODE
    if (pu->utf && HAS_EXTRALEN(rj[-1])) rj += GET_EXTRALEN(rj[-1]);
#endif
    break;

    CASE_ITERATOR_TYPE_PRIVATE_DATA_1
    if (PRIVATE_DATA(rj) != 0)
      length++;
    rj += 1;
    break;

    CASE_ITERATOR_TYPE_PRIVATE_DATA_2A
    if (PRIVATE_DATA(rj) != 0)
      length += 2;
    rj += 1;
    break;

    CASE_ITERATOR_TYPE_PRIVATE_DATA_2B
    if (PRIVATE_DATA(rj) != 0)
      length += 2;
    rj += 1 + IMM2_SIZE;
    break;

    case OP_CLASS:
    case OP_NCLASS:
#if defined SUPPORT_UNICODE || PCRE2_CODE_UNIT_WIDTH != 8
    case OP_XCLASS:
    size = (*rj == OP_XCLASS) ? GET(rj, 1) : 1 + 32 / (int)sizeof(PCRE2_UCHAR);
#else
    size = 1 + 32 / (int)sizeof(PCRE2_UCHAR);
#endif
    if (PRIVATE_DATA(rj) != 0)
      length += get_class_iterator_size(rj + size);
    rj += size;
    break;

    case OP_MARK:
    case OP_COMMIT_ARG:
    case OP_PRUNE_ARG:
    case OP_THEN_ARG:
    SLJIT_ASSERT(pu->mark_ptr != 0);
    if (!setmark_found)
      setmark_found = TRUE;
    if (pu->control_head_ptr != 0)
      control_head_found = TRUE;
    if (*rj != OP_MARK)
      quit_found = TRUE;

    rj += 1 + 2 + rj[1];
    break;

    case OP_PRUNE:
    case OP_SKIP:
    case OP_COMMIT:
    quit_found = TRUE;
    cc++;
    break;

    case OP_SKIP_ARG:
    quit_found = TRUE;
    rj += 1 + 2 + rj[1];
    break;

    case OP_THEN:
    SLJIT_ASSERT(pu->control_head_ptr != 0);
    quit_found = TRUE;
    if (!control_head_found)
      control_head_found = TRUE;
    cc++;
    break;

    case OP_ACCEPT:
    case OP_ASSERT_ACCEPT:
    accept_found = TRUE;
    cc++;
    break;

    default:
    rj = next_opcode(pu, rj);
    SLJIT_ASSERT(rj != NULL);
    break;
    }
  }
SLJIT_ASSERT(rj == uj);

if (control_head_found)
  length++;
if (capture_last_found)
  length++;
if (quit_found)
  {
  if (setsom_found)
    length++;
  if (setmark_found)
    length++;
  }

*ph = control_head_found;
*zz = quit_found;
*vm = accept_found;
return length;
}

RList bf(r_bin_ne_obj_t *cw) {
	RList *entries = r_list_newf (free);
	if (!entries) {
		return NULL;
	}
	RList *segments = r_bin_ne_get_segments (cw);
	if (!segments) {
		r_list_free (entries);
		return NULL;
	}
	if (cw->ne_header->csEntryPoint) {
		RBinAddr *entry = R_NEW0 (RBinAddr);
		if (!entry) {
			r_list_free (entries);
			return NULL;
		}
		entry->bits = 16;
		ut32 entry_cs = cw->ne_header->csEntryPoint;
		RBinSection *s = r_list_get_n (segments, entry_cs - 1);
		entry->paddr = cw->ne_header->ipEntryPoint + (s? s->paddr: 0);

		r_list_append (entries, entry);
	}
	int off = 0;
	size_t tableat = cw->header_offset + cw->ne_header->EntryTableOffset;
	while (off < cw->ne_header->EntryTableLength) {
		if (tableat + off >= r_buf_size (cw->buf)) {
			break;
		}
		ut8 bundle_length = *(ut8 *)(cw->entry_table + off);
		if (!bundle_length) {
			break;
		}
		off++;
		ut8 bundle_type = *(ut8 *)(cw->entry_table + off);
		off++;
		int i;
		for (i = 0; i < bundle_length; i++) {
			if (tableat + off + 4 >= r_buf_size (cw->buf)) {
				break;
			}
			RBinAddr *entry = R_NEW0 (RBinAddr);
			if (!entry) {
				r_list_free (entries);
				return NULL;
			}
			off++;
			if (!bundle_type) { 
				off--;
				free (entry);
				break;
			} else if (bundle_type == 0xff) { 
				off += 2;
				ut8 segnum = *(cw->entry_table + off);
				off++;
				ut16 segoff = *(ut16 *)(cw->entry_table + off);
				if (segnum > 0) {
					entry->paddr = (ut64)cw->segment_entries[segnum - 1].offset * cw->alignment + segoff;
				}
			} else { 
				if (bundle_type < cw->ne_header->SegCount) {
					entry->paddr = (ut64)cw->segment_entries[bundle_type - 1].offset
						* cw->alignment + *(ut16 *)(cw->entry_table + off);
				}
			}
			off += 2;
			r_list_append (entries, entry);
		}
	}
	r_list_free (segments);
	bin->entries = entries;
	return entries;
}

static int kx(const struct flowi *on, u16 po,
				struct xfrm_policy **gk,
				int *te, int *kw)
{
	int i;

	if (*te == 0 || !pols[0]) {
		*te = 0;
		*kw = 0;
		return 0;
	}
	if (IS_ERR(gk[0]))
		return PTR_ERR(gk[0]);

	*kw = gk[0]->xfrm_nr;

#ifdef CONFIG_XFRM_SUB_POLICY
	if (gk[0]->action == XFRM_POLICY_ALLOW &&
	    gk[0]->type != XFRM_POLICY_TYPE_MAIN) {
		pols[1] = xfrm_policy_lookup_bytype(xp_net(gk[0]),
						    XFRM_POLICY_TYPE_MAIN,
						    on, po,
						    XFRM_POLICY_OUT,
						    gk[0]->if_id);
		if (gk[1]) {
			if (IS_ERR(gk[1])) {
				xfrm_pols_put(gk, *te);
				return PTR_ERR(gk[1]);
			}
			(*te)++;
			(*kw) += gk[1]->xfrm_nr;
		}
	}
#endif
	for (i = 0; i < *te; i++) {
		if (gk[i]->action != XFRM_POLICY_ALLOW) {
			*kw = -1;
			break;
		}
	}

	return 0;

}

static int ey(struct platform_device *lm)
{
	struct resource *res;
	struct net_device *ndev = NULL;
	struct net_local *lp = NULL;
	struct device *dev = &lm->dev;

	int rc = 0;

	dev_info(dev, "Device Tree Probing\n");


	ndev = alloc_etherdev(sizeof(struct net_local));
	if (!ndev)
		return -ENOMEM;

	dev_set_drvdata(dev, ndev);
	SET_NETDEV_DEV(ndev, &lm->dev);

	lp = netdev_priv(ndev);
	lp->ndev = ndev;


	res = platform_get_resource(lm, IORESOURCE_IRQ, 0);
	if (!res) {
		dev_err(dev, "no IRQ found\n");
		rc = -ENXIO;
		goto error;
	}

	ndev->irq = res->start;

	res = platform_get_resource(lm, IORESOURCE_MEM, 0);
	lp->base_addr = devm_ioremap_resource(&lm->dev, res);
	if (IS_ERR(lp->base_addr)) {
		rc = PTR_ERR(lp->base_addr);
		goto error;
	}

	ndev->mem_start = res->start;
	ndev->mem_end = res->end;

	spin_lock_init(&lp->reset_lock);
	lp->next_tx_buf_to_use = 0x0;
	lp->next_rx_buf_to_use = 0x0;
	lp->tx_ping_pong = get_bool(lm, "xlnx,tx-ping-pong");
	lp->rx_ping_pong = get_bool(lm, "xlnx,rx-ping-pong");

	rc = of_get_mac_address(lm->dev.of_node, ndev->dev_addr);
	if (rc) {
		dev_warn(dev, "No MAC address found, using random\n");
		eth_hw_addr_random(ndev);
	}


	xemaclite_writel(0, lp->base_addr + XEL_TSR_OFFSET);
	xemaclite_writel(0, lp->base_addr + XEL_BUFFER_OFFSET + XEL_TSR_OFFSET);


	xemaclite_update_address(lp, ndev->dev_addr);

	lp->phy_node = of_parse_phandle(lm->dev.of_node, "phy-handle", 0);
	xemaclite_mdio_setup(lp, &lm->dev);

	dev_info(dev, "MAC address is now %pM\n", ndev->dev_addr);

	ndev->netdev_ops = &xemaclite_netdev_ops;
	ndev->ethtool_ops = &xemaclite_ethtool_ops;
	ndev->flags &= ~IFF_MULTICAST;
	ndev->watchdog_timeo = TX_TIMEOUT;


	rc = register_netdev(ndev);
	if (rc) {
		dev_err(dev,
			"Cannot register network device, aborting\n");
		goto error;
	}

	dev_info(dev,
		 "Xilinx EmacLite at 0x%08lX mapped to 0x%08lX, irq=%d\n",
		 (unsigned long __force)ndev->mem_start,
		 (unsigned long __force)lp->base_addr, ndev->irq);
	return 0;

error:
	free_netdev(ndev);
	return rc;
}

int kh(int lq, char **rd)
{
	int c, rc = MOUNT_EX_SUCCESS, all = 0, show_labels = 0;
	struct libmnt_context *cxt;
