static struct nlattr gy(struct sw_flow_actions **fn,
				       int up, bool pu)
{

	struct sw_flow_actions *acts;
	int new_acts_size;
	size_t req_size = NLA_ALIGN(up);
	int next_offset = offsetof(struct sw_flow_actions, actions) +
					(*fn)->actions_len;

	if (req_size <= (ksize(*fn) - next_offset))
		goto out;

	new_acts_size = max(next_offset + req_size, ksize(*fn) * 2);

	if (new_acts_size > MAX_ACTIONS_BUFSIZE) {
		if ((MAX_ACTIONS_BUFSIZE - next_offset) < req_size) {
			OVS_NLERR(pu, "Flow action size exceeds max %u",
				  MAX_ACTIONS_BUFSIZE);
			return ERR_PTR(-EMSGSIZE);
		}
		new_acts_size = MAX_ACTIONS_BUFSIZE;
	}

	acts = nla_alloc_flow_actions(new_acts_size);
	if (IS_ERR(acts))
		return (void *)acts;

	memcpy(acts->actions, (*fn)->actions, (*fn)->actions_len);
	acts->actions_len = (*fn)->actions_len;
	acts->orig_len = (*fn)->orig_len;
	kfree(*fn);
	*fn = acts;

out:
	(*fn)->actions_len += req_size;
	return  (struct nlattr *) ((unsigned char *)(*fn) + next_offset);
}

gopherToHTML(GopherStateData * jk, char *ju, int by)
{
    char *pos = ju;
    char *lpos = NULL;
    char *tline = NULL;
    LOCAL_ARRAY(char, line, TEMP_BUF_SIZE);
    LOCAL_ARRAY(char, tmpbuf, TEMP_BUF_SIZE);
    char *name = NULL;
    char *selector = NULL;
    char *host = NULL;
    char *port = NULL;
    char *escaped_selector = NULL;
    const char *icon_url = NULL;
    char gtype;
    StoreEntry *entry = NULL;

    memset(tmpbuf, '\0', TEMP_BUF_SIZE);
    memset(line, '\0', TEMP_BUF_SIZE);

    entry = jk->entry;

    if (jk->conversion == GopherStateData::HTML_INDEX_PAGE) {
        char *html_url = html_quote(entry->url());
        gopherHTMLHeader(entry, "Gopher Index %s", html_url);
        storeAppendPrintf(entry,
                          "<p>This is a searchable Gopher index. Use the search\n"
                          "function of your browser to enter search terms.\n"
                          "<ISINDEX>\n");
        gopherHTMLFooter(entry);

        entry->flush();
        jk->HTML_header_added = 1;

        return;
    }

    if (jk->conversion == GopherStateData::HTML_CSO_PAGE) {
        char *html_url = html_quote(entry->url());
        gopherHTMLHeader(entry, "CSO Search of %s", html_url);
        storeAppendPrintf(entry,
                          "<P>A CSO database usually contains a phonebook or\n"
                          "directory.  Use the search function of your browser to enter\n"
                          "search terms.</P><ISINDEX>\n");
        gopherHTMLFooter(entry);

        entry->flush();
        jk->HTML_header_added = 1;

        return;
    }

    String outbuf;

    if (!gopherState->HTML_header_added) {
        if (jk->conversion == GopherStateData::HTML_CSO_RESULT)
            gopherHTMLHeader(entry, "CSO Search Result", NULL);
        else
            gopherHTMLHeader(entry, "Gopher Menu", NULL);

        outbuf.append ("<PRE>");

        jk->HTML_header_added = 1;

        jk->HTML_pre = 1;
    }

    while (pos < ju + by) {
        int llen;
        int left = by - (pos - ju);
        lpos = (char *)memchr(pos, '\n', left);
        if (lpos) {
            ++lpos;             
            llen = lpos - pos;
        } else {
            llen = left;
        }
        if (jk->by + llen >= TEMP_BUF_SIZE) {
            debugs(10, DBG_IMPORTANT, "GopherHTML: Buffer overflow. Lost some data on URL: " << entry->url()  );
            llen = TEMP_BUF_SIZE - jk->by - 1;
        }
        if (!lpos) {



            memcpy(jk->buf + jk->by, pos, llen);
            jk->by += llen;
            break;
        }
        if (jk->by != 0) {

            memcpy(line, jk->buf, jk->by);
            memcpy(line + jk->by, pos, llen);
            llen += jk->by;
            jk->by = 0;
        } else {
            memcpy(line, pos, llen);
        }
        line[llen + 1] = '\0';

        pos = lpos;



        if (*line == '.') {

            memset(line, '\0', TEMP_BUF_SIZE);
            continue;
        }

        switch (jk->conversion) {

        case GopherStateData::HTML_INDEX_RESULT:

        case GopherStateData::HTML_DIR: {
            tline = line;
            gtype = *tline;
            ++tline;
            name = tline;
            selector = strchr(tline, TAB);

            if (selector) {
                *selector = '\0';
                ++selector;
                host = strchr(selector, TAB);

                if (host) {
                    *host = '\0';
                    ++host;
                    port = strchr(host, TAB);

                    if (port) {
                        char *junk;
                        port[0] = ':';
                        junk = strchr(host, TAB);

                        if (junk)
                            *junk++ = 0;    
                        else {
                            junk = strchr(host, '\r');

                            if (junk)
                                *junk++ = 0;    
                            else {
                                junk = strchr(host, '\n');

                                if (junk)
                                    *junk++ = 0;    
                            }
                        }

                        if ((port[1] == '0') && (!port[2]))
                            port[0] = 0;    
                    }


                    escaped_selector = xstrdup(rfc1738_escape_part(selector));

                    switch (gtype) {

                    case GOPHER_DIRECTORY:
                        icon_url = mimeGetIconURL("internal-menu");
                        break;

                    case GOPHER_HTML:

                    case GOPHER_FILE:
                        icon_url = mimeGetIconURL("internal-text");
                        break;

                    case GOPHER_INDEX:

                    case GOPHER_CSO:
                        icon_url = mimeGetIconURL("internal-index");
                        break;

                    case GOPHER_IMAGE:

                    case GOPHER_GIF:

                    case GOPHER_PLUS_IMAGE:
                        icon_url = mimeGetIconURL("internal-image");
                        break;

                    case GOPHER_SOUND:

                    case GOPHER_PLUS_SOUND:
                        icon_url = mimeGetIconURL("internal-sound");
                        break;

                    case GOPHER_PLUS_MOVIE:
                        icon_url = mimeGetIconURL("internal-movie");
                        break;

                    case GOPHER_TELNET:

                    case GOPHER_3270:
                        icon_url = mimeGetIconURL("internal-telnet");
                        break;

                    case GOPHER_BIN:

                    case GOPHER_MACBINHEX:

                    case GOPHER_DOSBIN:

                    case GOPHER_UUENCODED:
                        icon_url = mimeGetIconURL("internal-binary");
                        break;

                    case GOPHER_INFO:
                        icon_url = NULL;
                        break;

                    default:
                        icon_url = mimeGetIconURL("internal-unknown");
                        break;
                    }

                    memset(tmpbuf, '\0', TEMP_BUF_SIZE);

                    if ((gtype == GOPHER_TELNET) || (gtype == GOPHER_3270)) {
                        if (strlen(escaped_selector) != 0)
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"telnet:
                                     icon_url, escaped_selector, rfc1738_escape_part(host),
                                     *port ? ":" : "", port, html_quote(name));
                        else
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"telnet:
                                     icon_url, rfc1738_escape_part(host), *port ? ":" : "",
                                     port, html_quote(name));

                    } else if (gtype == GOPHER_INFO) {
                        snprintf(tmpbuf, TEMP_BUF_SIZE, "\t%s\n", html_quote(name));
                    } else {
                        if (strncmp(selector, "GET /", 5) == 0) {

                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"http:
                                     icon_url, host, rfc1738_escape_unescaped(selector + 5), html_quote(name));
                        } else {

                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"gopher:
                                     icon_url, host, gtype, escaped_selector, html_quote(name));
                        }
                    }

                    safe_free(escaped_selector);
                    outbuf.append(tmpbuf);
                } else {
                    memset(line, '\0', TEMP_BUF_SIZE);
                    continue;
                }
            } else {
                memset(line, '\0', TEMP_BUF_SIZE);
                continue;
            }

            break;
            }           

        case GopherStateData::HTML_CSO_RESULT: {
            if (line[0] == '-') {
                int code, recno;
                char *s_code, *s_recno, *result;

                s_code = strtok(line + 1, ":\n");
                s_recno = strtok(NULL, ":\n");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                recno = atoi(s_recno);

                if (code != 200)
                    break;

                if (jk->cso_recno != recno) {
                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>Record# %d<br><i>%s</i></H2>\n<PRE>", recno, html_quote(result));
                    jk->cso_recno = recno;
                } else {
                    snprintf(tmpbuf, TEMP_BUF_SIZE, "%s\n", html_quote(result));
                }

                outbuf.append(tmpbuf);
                break;
            } else {
                int code;
                char *s_code, *result;

                s_code = strtok(line, ":");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                switch (code) {

                case 200: {


                    break;
                }

                case 102:   

                case 501:   

                case 502: { 

                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>%s</H2>\n<PRE>", html_quote(result));
                    outbuf.append(tmpbuf);
                    break;
                }

                }
            }

            }           

        default:
            break;      

        }           

    }               

    if (outbuf.size() > 0) {
        entry->append(outbuf.rawBuf(), outbuf.size());

        entry->flush();
    }

    outbuf.clean();
    return;
}

void fb(struct vrend_context *sh,
                         uint32_t rx, uint32_t xb,
                         const struct pipe_blit_info *fn)
{
   struct vrend_resource *src_res, *dst_res;
   src_res = vrend_renderer_ctx_res_lookup(sh, xb);
   dst_res = vrend_renderer_ctx_res_lookup(sh, rx);

   if (!src_res) {
      report_context_error(sh, VIRGL_ERROR_CTX_ILLEGAL_RESOURCE, xb);
      return;
   }
   if (!dst_res) {
      report_context_error(sh, VIRGL_ERROR_CTX_ILLEGAL_RESOURCE, rx);
      return;
   }

   if (sh->in_error)
      return;

   if (fn->render_condition_enable == false)
      vrend_pause_render_condition(sh, true);

   VREND_DEBUG(dbg_blit, sh, "BLIT: rc:%d scissor:%d filter:%d alpha:%d mask:0x%x\n"
                                   "  From %s(%s) ms:%d [%d, %d, %d]+[%d, %d, %d] lvl:%d\n"
                                   "  To   %s(%s) ms:%d [%d, %d, %d]+[%d, %d, %d] lvl:%d\n",
                                   fn->render_condition_enable, fn->scissor_enable,
                                   fn->filter, fn->alpha_blend, fn->mask,
                                   util_format_name(src_res->base.format),
                                   util_format_name(fn->src.format),
                                   src_res->base.nr_samples,
                                   fn->src.box.x, fn->src.box.y, fn->src.box.z,
                                   fn->src.box.width, fn->src.box.height, fn->src.box.depth,
                                   fn->src.level,
                                   util_format_name(dst_res->base.format),
                                   util_format_name(fn->dst.format),
                                   dst_res->base.nr_samples,
                                   fn->dst.box.x, fn->dst.box.y, fn->dst.box.z,
                                   fn->dst.box.width, fn->dst.box.height, fn->dst.box.depth,
                                   fn->dst.level);


   if (has_feature(feat_copy_image) &&
       (!info->render_condition_enable || !ctx->sub->cond_render_gl_mode) &&
       format_is_copy_compatible(fn->src.format,fn->dst.format, false) &&
       !info->scissor_enable && (fn->filter == PIPE_TEX_FILTER_NEAREST) &&
       !info->alpha_blend && (fn->mask == PIPE_MASK_RGBA) &&
       src_res->base.nr_samples == dst_res->base.nr_samples &&
       fn->src.box.width == fn->dst.box.width &&
       fn->src.box.height == fn->dst.box.height &&
       fn->src.box.depth == fn->dst.box.depth) {
      VREND_DEBUG(dbg_blit, sh,  "  Use glCopyImageSubData\n");
      vrend_copy_sub_image(src_res, dst_res, fn->src.level, &fn->src.box,
                           fn->dst.level, fn->dst.box.x, fn->dst.box.y,
                           fn->dst.box.z);
   } else {
      VREND_DEBUG(dbg_blit, sh, "  Use blit_int\n");
      fb_int(sh, src_res, dst_res, fn);
   }

   if (fn->render_condition_enable == false)
      vrend_pause_render_condition(sh, false);
}

