    unsigned	words_done = 0;
    int		wordcount[MAXWLEN];


    ba->si_foldroot = wordtree_alloc(ba);
    if (ba->si_foldroot == NULL)
	return FAIL;


    ba->si_sugtree = TRUE;


    byts = js->sl_fbyts;
    idxs = js->sl_fidxs;

    arridx[0] = 0;
