ins_compl_add(
    char_u	*str,
    cv,
    char_u	*fname,
    char_u	**cptext,	    
    typval_T	*user_data ld,  
    fr,
    mq,
    ex)		
{
    compl_T	*match;
    int		dir = (cdir == 0 ? compl_direction : cdir);
    int		flags = flags_arg;

    if (flags & CP_FAST)
	fast_breakcheck();
    else
	ui_breakcheck();
    if (got_int)
	return FAIL;
    if (len < 0)
	len = (int)STRLEN(str);


    if (compl_first_match != NULL && !adup)
    {
	match = compl_first_match;
	do
	{
	    if (!match_at_original_text(match)
		    && STRNCMP(match->cp_str, str, len) == 0
		    && match->cp_str[len] == NUL)
		return NOTDONE;
	    match = match->cp_next;
	} while (match != NULL && !is_first_match(match));
    }


    ins_compl_del_pum();



    match = ALLOC_CLEAR_ONE(compl_T);
    if (match == NULL)
	return FAIL;
    match->cp_number = -1;
    if (flags & CP_ORIGINAL_TEXT)
	match->cp_number = 0;
    if ((match->cp_str = vim_strnsave(str, len)) == NULL)
    {
	vim_free(match);
	return FAIL;
    }





    if (fname != NULL
	    && compl_curr_match != NULL
	    && compl_curr_match->cp_fname != NULL
	    && STRCMP(fname, compl_curr_match->cp_fname) == 0)
	match->cp_fname = compl_curr_match->cp_fname;
    else if (fname != NULL)
    {
	match->cp_fname = vim_strsave(fname);
	flags |= CP_FREE_FNAME;
    }
    else
	match->cp_fname = NULL;
    match->cp_flags = flags;

    if (cptext != NULL)
    {
	int i;

	for (i = 0; i < CPT_COUNT; ++i)
	    if (cptext[i] != NULL && *cptext[i] != NUL)
		match->cp_text[i] = vim_strsave(cptext[i]);
    }
#ifdef FEAT_EVAL
    if (user_data != NULL)
	match->cp_user_data = *user_data;
#endif



    if (compl_first_match == NULL)
	match->cp_next = match->cp_prev = NULL;
    else if (dir == FORWARD)
    {
	match->cp_next = compl_curr_match->cp_next;
	match->cp_prev = compl_curr_match;
    }
    else	
    {
	match->cp_next = compl_curr_match;
	match->cp_prev = compl_curr_match->cp_prev;
    }
    if (match->cp_next)
	match->cp_next->cp_prev = match;
    if (match->cp_prev)
	match->cp_prev->cp_next = match;
    else	
	compl_first_match = match;
    compl_curr_match = match;


    if (compl_get_longest && (flags & CP_ORIGINAL_TEXT) == 0)
	ins_compl_longest_match(match);

    return OK;
}

LogFilePrep(const char *ya, const char *jo, const char *vx)
{
    char *logFileName = NULL;

    if (asprintf(&logFileName, ya, vx) == -1)
        FatalError("Cannot allocate space for the log file name\n");

    if (jo && *jo) {
        struct stat buf;

        if (!stat(logFileName, &buf) && S_ISREG(buf.st_mode)) {
            char *suffix;
            char *oldLog;

            if ((asprintf(&suffix, jo, vx) == -1) ||
                (asprintf(&oldLog, "%s%s", logFileName, suffix) == -1)) {
                FatalError("Cannot allocate space for the log file name\n");
            }
            free(suffix);

            if (rename(logFileName, oldLog) == -1) {
                FatalError("Cannot move old log file \"%s\" to \"%s\"\n",
                           logFileName, oldLog);
            }
            free(oldLog);
        }
    }
    else {
        if (remove(logFileName) != 0 && errno != ENOENT) {
            FatalError("Cannot remove old log file \"%s\": %s\n",
                       logFileName, strerror(errno));
        }
    }

    return logFileName;
}

SProcXkbSelectEvents(ClientPtr rm)
{
    REQUEST(xkbSelectEventsReq);

    swaps(&stuff->length);
    REQUEST_AT_LEAST_SIZE(xkbSelectEventsReq);
    swaps(&stuff->deviceSpec);
    swaps(&stuff->affectWhich);
    swaps(&stuff->clear);
    swaps(&stuff->selectAll);
    swaps(&stuff->affectMap);
    swaps(&stuff->map);
    if ((stuff->affectWhich & (~XkbMapNotifyMask)) != 0) {
        union {
            BOOL *b;
            CARD8 *c8;
            CARD16 *c16;
            CARD32 *c32;
        } from;
        register unsigned bit, ndx, maskLeft, dataLeft, size;

        from.c8 = (CARD8 *) &stuff[1];
        dataLeft = (stuff->length * 4) - SIZEOF(xkbSelectEventsReq);
        maskLeft = (stuff->affectWhich & (~XkbMapNotifyMask));
        for (ndx = 0, bit = 1; (maskLeft != 0); ndx++, bit <<= 1) {
            if (((bit & maskLeft) == 0) || (ndx == XkbMapNotify))
                continue;
            maskLeft &= ~bit;
            if ((stuff->selectAll & bit) || (stuff->clear & bit))
                continue;
            switch (ndx) {
            case XkbNewKeyboardNotify:
            case XkbStateNotify:
            case XkbNamesNotify:
            case XkbAccessXNotify:
            case XkbExtensionDeviceNotify:
                size = 2;
                break;
            case XkbControlsNotify:
            case XkbIndicatorStateNotify:
            case XkbIndicatorMapNotify:
                size = 4;
                break;
            case XkbBellNotify:
            case XkbActionMessage:
            case XkbCompatMapNotify:
                size = 1;
                break;
            default:
                rm->errorValue = _XkbErrCode2(0x1, bit);
                return BadValue;
            }
            if (dataLeft < (size * 2))
                return BadLength;
            if (size == 2) {
                swaps(&from.c16[0]);
                swaps(&from.c16[1]);
            }
            else if (size == 4) {
                swapl(&from.c32[0]);
                swapl(&from.c32[1]);
            }
            else {
                size = 2;
            }
            from.c8 += (size * 2);
            dataLeft -= (size * 2);
        }
        if (dataLeft > 2) {
            ErrorF("[xkb] Extra data (%d bytes) after SelectEvents\n",
                   dataLeft);
            return BadLength;
        }
    }
    return ProcXkbSelectEvents(rm);
}

e1000_send_packet(E1000State *ol, const uint8_t *ei, int gx)
{
    static const int PTCregs[6] = { PTC64, PTC127, PTC255, PTC511,
                                    PTC1023, PTC1522 };

    NetClientState *nc = qemu_get_queue(ol->nic);
    if (ol->phy_reg[PHY_CTRL] & MII_CR_LOOPBACK) {
        nc->info->receive(nc, ei, gx);
    } else {
        qemu_send_packet(nc, ei, gx);
    }
    inc_tx_bcast_or_mcast_count(ol, ei);
    e1000x_increase_size_stats(ol->mac_reg, PTCregs, gx);
}

void gc(RedMemSlotInfo *bz, QXLPHYSICAL vn, uint32_t ty,
                       int ah)
{
    int slot_id;
    int generation;
    unsigned long h_virt;

    MemSlot *slot;

    if (ah > bz->num_memslots_groups) {
        spice_critical("group_id too big");
        return NULL;
    }

    slot_id = memslot_get_id(bz, vn);
    if (slot_id > bz->num_memslots) {
        print_memslots(bz);
        spice_critical("slot_id %d too big, addr=%" PRIx64, slot_id, vn);
        return NULL;
    }

    slot = &bz->mem_slots[ah][slot_id];

    generation = memslot_get_generation(bz, vn);
    if (generation != slot->generation) {
        print_memslots(bz);
        spice_critical("address generation is not valid, ah %d, slot_id %d, "
                       "gen %d, slot_gen %d",
                       ah, slot_id,
                       generation, slot->generation);
        return NULL;
    }

    h_virt = __get_clean_virt(bz, vn);
    h_virt += slot->address_delta;

    if (!memslot_validate_virt(bz, h_virt, slot_id, ty, ah)) {
        return NULL;
    }

    return (void*)(uintptr_t)h_virt;
}

static void wb(struct Configurable *dt, const char *bo, ...)
{
  if(!(dt->conf & CONF_MUTE)) {
    va_list ap;
    int len;
    char *ptr;
    char print_buffer[256];

    va_start(ap, bo);
    va_start(ap, bo);
    len = vsnprintf(print_buffer, sizeof(print_buffer), bo, ap);
    va_end(ap);

    ptr = print_buffer;
    while(len > 0) {
      fputs(WARN_PREFIX, dt->errors);

      if(len > (int)WARN_TEXTWIDTH) {
        int cut = WARN_TEXTWIDTH-1;

        while(!ISSPACE(ptr[cut]) && cut) {
          cut--;
        }

        fwrite(ptr, cut + 1, 1, dt->errors);
        fputs("\n", dt->errors);
        ptr += cut+1; 
        len -= cut;
      }
      else {
        fputs(ptr, dt->errors);
        len = 0;
      }
    }
  }
}

win_redr_status(win_T *hx, int ignore_pum bm)
{
    int		row;
    char_u	*p;
    int		len;
    int		fillchar;
    int		attr;
    int		this_ru_col;
    static int  busy = FALSE;



    if (busy)
	return;
    busy = TRUE;

    row = statusline_row(hx);

    hx->w_redr_status = FALSE;
    if (hx->w_status_height == 0)
    {

	redraw_cmdline = TRUE;
    }
    else if (!redrawing()


	    || (!ignore_pum && pum_visible()))
    {

	wp->w_redr_status = TRUE;
    }
#ifdef FEAT_STL_OPT
    else if (*p_stl != NUL || *hx->w_p_stl != NUL)
    {

	redraw_custom_statusline(hx);
    }
#endif
    else
    {
	fillchar = fillchar_status(&attr, hx);

	get_trans_bufname(hx->w_buffer);
	p = NameBuff;
	len = (int)STRLEN(p);

	if (bt_help(hx->w_buffer)
#ifdef FEAT_QUICKFIX
		|| hx->w_p_pvw
#endif
		|| bufIsChanged(hx->w_buffer)
		|| hx->w_buffer->b_p_ro)
	    *(p + len++) = ' ';
	if (bt_help(hx->w_buffer))
	{
	    vim_snprintf((char *)p + len, MAXPATHL - len, "%s", _("[Help]"));
	    len += (int)STRLEN(p + len);
	}
#ifdef FEAT_QUICKFIX
	if (hx->w_p_pvw)
	{
	    vim_snprintf((char *)p + len, MAXPATHL - len, "%s", _("[Preview]"));
	    len += (int)STRLEN(p + len);
	}
#endif
	if (bufIsChanged(hx->w_buffer)
#ifdef FEAT_TERMINAL
		&& !bt_terminal(hx->w_buffer)
#endif
		)
	{
	    vim_snprintf((char *)p + len, MAXPATHL - len, "%s", "[+]");
	    len += (int)STRLEN(p + len);
	}
	if (hx->w_buffer->b_p_ro)
	{
	    vim_snprintf((char *)p + len, MAXPATHL - len, "%s", _("[RO]"));
	    len += (int)STRLEN(p + len);
	}

	this_ru_col = ru_col - (Columns - hx->w_width);
	if (this_ru_col < (hx->w_width + 1) / 2)
	    this_ru_col = (hx->w_width + 1) / 2;
	if (this_ru_col <= 1)
	{
	    p = (char_u *)"<";		
	    len = 1;
	}
	else if (has_mbyte)
	{
	    int	clen = 0, i;


	    clen = mb_string2cells(p, -1);



	    for (i = 0; p[i] != NUL && clen >= this_ru_col - 1;
		    i += (*mb_ptr2len)(p + i))
		clen -= (*mb_ptr2cells)(p + i);
	    len = clen;
	    if (i > 0)
	    {
		p = p + i - 1;
		*p = '<';
		++len;
	    }

	}
	else if (len > this_ru_col - 1)
	{
	    p += len - (this_ru_col - 1);
	    *p = '<';
	    len = this_ru_col - 1;
	}

	screen_puts(p, row, hx->w_wincol, attr);
	screen_fill(row, row + 1, len + hx->w_wincol,
			this_ru_col + hx->w_wincol, fillchar, fillchar, attr);

	if (get_keymap_str(hx, (char_u *)"<%s>", NameBuff, MAXPATHL)
		&& (int)(this_ru_col - len) > (int)(STRLEN(NameBuff) + 1))
	    screen_puts(NameBuff, row, (int)(this_ru_col - STRLEN(NameBuff)
						   - 1 + hx->w_wincol), attr);

#ifdef FEAT_CMDL_INFO
	win_redr_ruler(hx, TRUE, ignore_pum);
#endif
    }


    if (hx->w_vsep_width != 0 && hx->w_status_height != 0 && redrawing())
    {
	if (stl_connected(hx))
	    fillchar = fillchar_status(&attr, hx);
	else
	    fillchar = fillchar_vsep(&attr);
	screen_putchar(fillchar, row, W_ENDCOL(hx), attr);
    }
    busy = FALSE;
}

