 */
static void ac(void *rq, const XML_Char *nd)
{
	st_entry 			*ent1, *ent2;
	wddx_stack 			*stack = (wddx_stack *)rq;
	HashTable 			*target_hash;
	zend_class_entry 	**pce;
	zval				*obj;
	zval				*tmp;
	TSRMLS_FETCH();


	if (stack->top == 0) {
		return;
	}

	if (!strcmp(nd, EL_STRING) || !strcmp(nd, EL_NUMBER) ||
		!strcmp(nd, EL_BOOLEAN) || !strcmp(nd, EL_NULL) ||
	  	!strcmp(nd, EL_ARRAY) || !strcmp(nd, EL_STRUCT) ||
		!strcmp(nd, EL_RECORDSET) || !strcmp(nd, EL_BINARY) ||
		!strcmp(nd, EL_DATETIME)) {
		wddx_stack_top(stack, (void**)&ent1);

		if (!ent1->data) {
			if (stack->top > 1) {
				stack->top--;
			} else {
				stack->done = 1;
			}
			efree(ent1);
			return;
		}

		if (!strcmp(nd, EL_BINARY)) {
			int new_len=0;
			unsigned char *new_str;

			new_str = php_base64_decode(Z_STRVAL_P(ent1->data), Z_STRLEN_P(ent1->data), &new_len);
			STR_FREE(Z_STRVAL_P(ent1->data));
			Z_STRVAL_P(ent1->data) = new_str;
			Z_STRLEN_P(ent1->data) = new_len;
		}


		if (Z_TYPE_P(ent1->data) == IS_OBJECT) {
			zval *fname, *retval = NULL;

			MAKE_STD_ZVAL(fname);
			ZVAL_STRING(fname, "__wakeup", 1);

			call_user_function_ex(NULL, &ent1->data, fname, &retval, 0, 0, 0, NULL TSRMLS_CC);

			zval_dtor(fname);
			FREE_ZVAL(fname);
			if (retval) {
				zval_ptr_dtor(&retval);
			}
		}

		if (stack->top > 1) {
			stack->top--;
			wddx_stack_top(stack, (void**)&ent2);


			if (ent2->type == ST_FIELD && ent2->data == NULL) {
				zval_ptr_dtor(&ent1->data);
				efree(ent1);
				return;
			}

			if (Z_TYPE_P(ent2->data) == IS_ARRAY || Z_TYPE_P(ent2->data) == IS_OBJECT) {
				target_hash = HASH_OF(ent2->data);

				if (ent1->varname) {
					if (!strcmp(ent1->varname, PHP_CLASS_NAME_VAR) &&
						Z_TYPE_P(ent1->data) == IS_STRING && Z_STRLEN_P(ent1->data) &&
						ent2->type == ST_STRUCT && Z_TYPE_P(ent2->data) == IS_ARRAY) {
						zend_bool incomplete_class = 0;

						zend_str_tolower(Z_STRVAL_P(ent1->data), Z_STRLEN_P(ent1->data));
						if (zend_hash_find(EG(class_table), Z_STRVAL_P(ent1->data),
										   Z_STRLEN_P(ent1->data)+1, (void **) &pce)==FAILURE) {
							incomplete_class = 1;
							pce = &PHP_IC_ENTRY;
						}


						MAKE_STD_ZVAL(obj);
						object_init_ex(obj, *pce);


						zend_hash_merge(Z_OBJPROP_P(obj),
										Z_ARRVAL_P(ent2->data),
										(void (*)(void *)) zval_add_ref,
										(void *) &tmp, sizeof(zval *), 0);

						if (incomplete_class) {
							php_store_class_name(obj, Z_STRVAL_P(ent1->data), Z_STRLEN_P(ent1->data));
						}


						zval_ptr_dtor(&ent2->data);


						ent2->data = obj;


						zval_ptr_dtor(&ent1->data);
					} else if (Z_TYPE_P(ent2->data) == IS_OBJECT) {
						zend_class_entry *old_scope = EG(scope);

						EG(scope) = Z_OBJCE_P(ent2->data);
						Z_DELREF_P(ent1->data);
						add_property_zval(ent2->data, ent1->varname, ent1->data);
						EG(scope) = old_scope;
					} else {
						zend_symtable_update(target_hash, ent1->varname, strlen(ent1->varname)+1, &ent1->data, sizeof(zval *), NULL);
					}
					efree(ent1->varname);
				} else	{
					zend_hash_next_index_insert(target_hash, &ent1->data, sizeof(zval *), NULL);
				}
			}
			efree(ent1);
		} else {
			stack->done = 1;
		}
	} else if (!strcmp(nd, EL_VAR) && stack->varname) {
		efree(stack->varname);
		stack->varname = NULL;
	} else if (!strcmp(nd, EL_FIELD)) {
		st_entry *ent;
		wddx_stack_top(stack, (void **)&ent);
		efree(ent);
		stack->top--;
	}

processDataRcvd(ptcpsess_t *const __restrict__ lr,
	char **ct,
	const int tz,
	struct syslogTime *km,
	const time_t aj,
	multi_submit_t *nm,
	unsigned *const __restrict__ yc)
{
	DEFiRet;
	char c = **ct;
	int octatesToCopy, octatesToDiscard;

	if(lr->inputState == eAtStrtFram) {
		if(lr->bSuppOctetFram && isdigit((int) c)) {
			pThis->inputState = eInOctetCnt;
			pThis->iOctetsRemain = 0;
			pThis->eFraming = TCP_FRAMING_OCTET_COUNTING;
		} else if(lr->bSPFramingFix && c == ' ') {

			 FINALIZE;
		} else {
			pThis->inputState = eInMsg;
			pThis->eFraming = TCP_FRAMING_OCTET_STUFFING;
		}
	}

	if(lr->inputState == eInOctetCnt) {
		if(isdigit(c)) {
			pThis->iOctetsRemain = lr->iOctetsRemain * 10 + c - '0';
		} else { 
			DBGPRINTF("TCP Message with octet-counter, size %d.\n", lr->iOctetsRemain);
			if(c != ' ') {
				errmsg.LogError(0, NO_ERRCODE, "Framing Error in received TCP message: "
					    "delimiter is not SP but has ASCII value %d.", c);
			}
			if(lr->iOctetsRemain < 1) {

				DBGPRINTF("Framing Error: invalid octet count\n");
				errmsg.LogError(0, NO_ERRCODE, "Framing Error in received TCP message: "
					    "invalid octet count %d.", lr->iOctetsRemain);
			} else if(lr->iOctetsRemain > iMaxLine) {

				DBGPRINTF("truncating message with %d octets - max msg size is %d\n",
					  lr->iOctetsRemain, iMaxLine);
				errmsg.LogError(0, NO_ERRCODE, "received oversize message: size is %d bytes, "
					        "max msg size is %d, truncating...", lr->iOctetsRemain, iMaxLine);
			}
			pThis->inputState = eInMsg;
		}
	} else {
		assert(lr->inputState == eInMsg);

		if (lr->eFraming == TCP_FRAMING_OCTET_STUFFING) {
			if(lr->iMsg >= iMaxLine) {

				int i = 1;
				char currBuffChar;
				while(i < tz && ((currBuffChar = (*ct)[i]) != '\n'
					&& (lr->pLstn->pSrv->iAddtlFrameDelim == TCPSRV_NO_ADDTL_DELIMITER
						|| currBuffChar != lr->pLstn->pSrv->iAddtlFrameDelim))) {
					i++;
				}
				LogError(0, NO_ERRCODE, "error: message received is at least %d byte larger than max msg"
					" size; message will be split starting at: \"%.*s\"\n", i, (i < 32) ? i : 32, *ct);
				doSubmitMsg(lr, km, aj, nm);
				++(*yc);

			}

			if ((c == '\n')
				   || ((lr->pLstn->pSrv->iAddtlFrameDelim != TCPSRV_NO_ADDTL_DELIMITER)
					   && (c == lr->pLstn->pSrv->iAddtlFrameDelim))
				   ) { 
				doSubmitMsg(lr, km, aj, nm);
				++(*yc);
				pThis->inputState = eAtStrtFram;
			} else {

				if(lr->iMsg < iMaxLine) {
					*(lr->pMsg + lr->iMsg++) = c;
				}
			}
		} else {
			assert(lr->eFraming == TCP_FRAMING_OCTET_COUNTING);
			octatesToCopy = lr->iOctetsRemain;
			octatesToDiscard = 0;
			if (tz < octatesToCopy) {
				octatesToCopy = tz;
			}
			if (octatesToCopy + lr->iMsg > iMaxLine) {
				octatesToDiscard = octatesToCopy - (iMaxLine - lr->iMsg);
				octatesToCopy = iMaxLine - lr->iMsg;
			}

			memcpy(lr->pMsg + lr->iMsg, *ct, octatesToCopy);
			pThis->iMsg += octatesToCopy;
			pThis->iOctetsRemain -= (octatesToCopy + octatesToDiscard);
			*ct += (octatesToCopy + octatesToDiscard - 1);
			if (lr->iOctetsRemain == 0) {

				doSubmitMsg(lr, km, aj, nm);
				++(*yc);
				pThis->inputState = eAtStrtFram;
			}
		}

	}

finalize_it:
	RETiRet;
}

qf_fill_buffer(qf_list_T *hs, buf_T *qf, qfline_T *vm, int fe)
{
    linenr_T	lnum;
    qfline_T	*qfp;
    int		old_KeyTyped = KeyTyped;
    list_T	*qftf_list = NULL;
    listitem_T	*qftf_li = NULL;

    if (vm == NULL)
    {
	if (qf != curbuf)
	{
	    internal_error("qf_fill_buffer()");
	    return;
	}


	while ((curbuf->b_ml.ml_flags & ML_EMPTY) == 0)
	    (void)ml_delete((linenr_T)1);
    }


    if (hs != NULL)
    {
	char_u		dirname[MAXPATHL];
	int		invalid_val = FALSE;
	int		prev_bufnr = -1;

	*dirname = NUL;


	if (vm == NULL)
	{
	    qfp = hs->qf_start;
	    lnum = 0;
	}
	else
	{
	    if (vm->qf_next != NULL)
		qfp = vm->qf_next;
	    else
		qfp = vm;
	    lnum = qf->b_ml.ml_line_count;
	}

	qftf_list = call_qftf_func(hs, fe, (long)(lnum + 1),
							(long)hs->qf_count);
	if (qftf_list != NULL)
	    qftf_li = qftf_list->lv_first;

	while (lnum < hs->qf_count)
	{
	    char_u	*qftf_str = NULL;




	    if (qftf_li != NULL && !invalid_val)
	    {
		qftf_str = tv_get_string_chk(&qftf_li->li_tv);
		if (qftf_str == NULL)
		    invalid_val = TRUE;
	    }

	    if (qf_buf_add_line(qf, lnum, qfp, dirname,
			prev_bufnr != qfp->qf_fnum, qftf_str) == FAIL)
		break;

	    prev_bufnr = qfp->qf_fnum;
	    ++lnum;
	    qfp = qfp->qf_next;
	    if (qfp == NULL)
		break;

	    if (qftf_li != NULL)
		qftf_li = qftf_li->li_next;
	}

	if (vm == NULL)

	    (void)ml_delete(lnum + 1);
    }


    check_lnums(TRUE);

    if (vm == NULL)
    {



	++curbuf_lock;
	set_option_value_give_err((char_u *)"ft",
						0L, (char_u *)"qf", OPT_LOCAL);
	curbuf->b_p_ma = FALSE;

	keep_filetype = TRUE;		
	apply_autocmds(EVENT_BUFREADPOST, (char_u *)"quickfix", NULL,
							       FALSE, curbuf);
	apply_autocmds(EVENT_BUFWINENTER, (char_u *)"quickfix", NULL,
							       FALSE, curbuf);
	keep_filetype = FALSE;
	--curbuf_lock;


	redraw_curbuf_later(UPD_NOT_VALID);
    }


    KeyTyped = old_KeyTyped;
}

std::string jp(
		const std::string& ip,
		const std::string& ec,
		const std::string& fn,
		const std::string& in)
{
	std::string bookmark_cmd = cfg.get_configvalue("bookmark-cmd");
	bool is_interactive = cfg.get_configvalue_as_bool("bookmark-interactive");
	if (bookmark_cmd.length() > 0) {
		std::string cmdline = strprintf::fmt("%s '%s' %s %s %s",
		                                       bookmark_cmd,
		                                       utils::replace_all(ip,"'", "%27"),
		                                       quote_empty(stfl::quote(ec)),
		                                       quote_empty(stfl::quote(fn)),
		                                       quote_empty(stfl::quote(in)));

		LOG(level::DEBUG, "jp: cmd = %s", cmdline);

		if (is_interactive) {
			v->push_empty_formaction();
			stfl::reset();
			utils::run_interactively(cmdline, "jp");
			v->pop_current_formaction();
			return "";
		} else {
			char * my_argv[4];
			my_argv[0] = const_cast<char *>("/bin/sh");
			my_argv[1] = const_cast<char *>("-c");
			my_argv[2] = const_cast<char *>(cmdline.c_str());
			my_argv[3] = nullptr;
			return utils::run_program(my_argv, "");
		}
	} else {
		return _("bookmarking support is not configured. Please set the configuration variable `bookmark-cmd' accordingly.");
	}
}

