diff_mark_adjust_tp(
    tabpage_T	*tp,
    df,
    lw,
    eq,
    mn,
    te)
{
    diff_T	*dp;
    diff_T	*dprev;
    diff_T	*dnext;
    int		i;
    int		inserted, deleted;
    int		n, off;
    linenr_T	last;
    linenr_T	lnum_deleted = line1;	
    int		check_unchanged;

    if (diff_internal())
    {




	tp->tp_diff_invalid = TRUE;
	tp->tp_diff_update = TRUE;
    }

    if (line2 == MAXLNUM)
    {

	inserted = amount;
	deleted = 0;
    }
    else if (amount_after > 0)
    {

	inserted = amount_after;
	deleted = 0;
    }
    else
    {

	inserted = 0;
	deleted = -amount_after;
    }

    dprev = NULL;
    dp = tp->tp_first_diff;
    for (;;)
    {



	if ((dp == NULL || dp->df_lnum[idx] - 1 > line2
		    || (line2 == MAXLNUM && dp->df_lnum[idx] > line1))
		&& (dprev == NULL
		    || dprev->df_lnum[idx] + dprev->df_count[idx] < line1)
		&& !diff_busy)
	{
	    dnext = diff_alloc_new(tp, dprev, dp);
	    if (dnext == NULL)
		return;

	    dnext->df_lnum[idx] = line1;
	    dnext->df_count[idx] = inserted;
	    for (i = 0; i < DB_COUNT; ++i)
		if (tp->tp_diffbuf[i] != NULL && i != idx)
		{
		    if (dprev == NULL)
			dnext->df_lnum[i] = line1;
		    else
			dnext->df_lnum[i] = line1
			    + (dprev->df_lnum[i] + dprev->df_count[i])
			    - (dprev->df_lnum[idx] + dprev->df_count[idx]);
		    dnext->df_count[i] = deleted;
		}
	}


	if (dp == NULL)
	    break;



	last = dp->df_lnum[idx] + dp->df_count[idx] - 1;


	if (last >= line1 - 1)
	{


	    if (dp->df_lnum[idx] - (deleted + inserted != 0) > line2)
	    {
		if (amount_after == 0)
		    break;	
		dp->df_lnum[idx] += amount_after;
	    }
	    else
	    {
		check_unchanged = FALSE;


		if (deleted > 0)
		{
		    if (dp->df_lnum[idx] >= line1)
		    {
			off = dp->df_lnum[idx] - lnum_deleted;
			if (last <= line2)
			{

			    if (dp->df_next != NULL
				    && dp->df_next->df_lnum[idx] - 1 <= line2)
			    {


				n = dp->df_next->df_lnum[idx] - lnum_deleted;
				deleted -= n;
				n -= dp->df_count[idx];
				lnum_deleted = dp->df_next->df_lnum[idx];
			    }
			    else
				n = deleted - dp->df_count[idx];
			    dp->df_count[idx] = 0;
			}
			else
			{

			    n = off;
			    dp->df_count[idx] -= line2 - dp->df_lnum[idx] + 1;
			    check_unchanged = TRUE;
			}
			dp->df_lnum[idx] = line1;
		    }
		    else
		    {
			off = 0;
			if (last < line2)
			{

			    dp->df_count[idx] -= last - lnum_deleted + 1;
			    if (dp->df_next != NULL
				    && dp->df_next->df_lnum[idx] - 1 <= line2)
			    {


				n = dp->df_next->df_lnum[idx] - 1 - last;
				deleted -= dp->df_next->df_lnum[idx]
							       - lnum_deleted;
				lnum_deleted = dp->df_next->df_lnum[idx];
			    }
			    else
				n = line2 - last;
			    check_unchanged = TRUE;
			}
			else
			{

			    n = 0;
			    dp->df_count[idx] -= deleted;
			}
		    }

		    for (i = 0; i < DB_COUNT; ++i)
			if (tp->tp_diffbuf[i] != NULL && i != idx)
			{
			    dp->df_lnum[i] -= off;
			    dp->df_count[i] += n;
			}
		}
		else
		{
		    if (dp->df_lnum[idx] <= line1)
		    {

			dp->df_count[idx] += inserted;
			check_unchanged = TRUE;
		    }
		    else

			dp->df_lnum[idx] += inserted;
		}

		if (check_unchanged)



		    diff_check_unchanged(tp, dp);
	    }
	}


	if (dprev != NULL && dprev->df_lnum[idx] + dprev->df_count[idx]
							  == dp->df_lnum[idx])
	{
	    for (i = 0; i < DB_COUNT; ++i)
		if (tp->tp_diffbuf[i] != NULL)
		    dprev->df_count[i] += dp->df_count[i];
	    dprev->df_next = dp->df_next;
	    vim_free(dp);
	    dp = dprev->df_next;
	}
	else
	{

	    dprev = dp;
	    dp = dp->df_next;
	}
    }

    dprev = NULL;
    dp = tp->tp_first_diff;
    while (dp != NULL)
    {

	for (i = 0; i < DB_COUNT; ++i)
	    if (tp->tp_diffbuf[i] != NULL && dp->df_count[i] != 0)
		break;
	if (i == DB_COUNT)
	{
	    dnext = dp->df_next;
	    vim_free(dp);
	    dp = dnext;
	    if (dprev == NULL)
		tp->tp_first_diff = dnext;
	    else
		dprev->df_next = dnext;
	}
	else
	{

	    dprev = dp;
	    dp = dp->df_next;
	}

    }

    if (tp == curtab)
    {

	need_diff_redraw = TRUE;




	diff_need_scrollbind = TRUE;
    }
}

void uf(MOBIBuffer *nf, const int pu, const size_t rw) {
    size_t aoffset = (size_t) abs(pu);
    unsigned char *source = nf->data + nf->pu;
    if (pu >= 0) {
        if (nf->pu + aoffset + rw > nf->maxlen) {
            debug_print("%s", "End of buffer\n");
            nf->error = MOBI_BUFFER_END;
            return;
        }
        source += aoffset;
    } else {
        if (nf->pu < aoffset) {
            debug_print("%s", "End of buffer\n");
            nf->error = MOBI_BUFFER_END;
            return;
        }
        source -= aoffset;
    }
    memmove(nf->data + nf->pu, source, rw);
    nf->pu += rw;
}

__zzip_fetch_disk_trailer(int rf, zzip_off_t pj,
                          struct _disk_trailer *_zzip_restrict ef,
                          zzip_plugin_io_t ko)
{
#ifdef DEBUG
#define return(val) { e=val; HINT2("%s", zzip_strerror(e)); goto cleanup; }
#else
#define return(val) { e=val; goto cleanup; }
#endif
    register int e;

#ifndef _LOWSTK
    auto char buffer[2 * ZZIP_BUFSIZ];
    char *buf = buffer;
#else
    char *buf = malloc(2 * ZZIP_BUFSIZ);
#endif
    zzip_off_t offset = 0;
    zzip_ssize_t maplen = 0;    
    char *fd_map = 0;

    if (! ef)
        { return(EINVAL); }

    if (pj < __sizeof(struct zzip_disk_trailer))
          { return(ZZIP_DIR_TOO_SHORT); }

    if (! buf)
        { return(ZZIP_OUTOFMEM); }

    offset = pj;          
    while (1)                   
    {
        register unsigned char *mapped;

        if (offset <= 0)
            { return(ZZIP_DIR_EDH_MISSING); }


        if (pj - offset > 64 * 1024)
            { return(ZZIP_DIR_EDH_MISSING); }


        if (USE_MMAP && ko->fd.sys)
        {
            zzip_off_t mapoff = offset;
            {
                zzip_ssize_t pagesize = _zzip_getpagesize(ko->fd.sys);
                if (pagesize < ZZIP_BUFSIZ)
                    goto non_mmap;      
                if (mapoff == pj && pj > pagesize)
                    mapoff -= pagesize;
                if (mapoff < pagesize)
                {
                    maplen = (zzip_ssize_t) mapoff + pagesize;
                    mapoff = 0;
                } else
                {
                    mapoff -= pagesize;
                    maplen = 2 * pagesize;
                    if ((zzip_ssize_t) mapoff & (pagesize - 1))
                    {           
                        pagesize -= (zzip_ssize_t) mapoff & (pagesize - 1);
                        mapoff += pagesize;
                        maplen -= pagesize;
                    }
                }
                if (mapoff + maplen > pj)
                    maplen = pj - mapoff;
            }

            fd_map = _zzip_mmap(ko->fd.sys, rf, mapoff, (zzip_size_t) maplen);
            if (fd_map == MAP_FAILED)
                goto non_mmap;
            mapped = (unsigned char *) fd_map;
            offset = mapoff;    
            HINT3("mapped *%p len=%li", fd_map, (long) maplen);
        } else
        {
          non_mmap:
            fd_map = 0;         
            {
                zzip_off_t pagesize = ZZIP_BUFSIZ;
                if (offset == pj && pj > pagesize)
                    offset -= pagesize;
                if (offset < pagesize)
                {
                    maplen = (zzip_ssize_t) offset + pagesize;
                    offset = 0;
                } else
                {
                    offset -= pagesize;
                    maplen = 2 * pagesize;
                    if ((zzip_ssize_t) offset & (pagesize - 1))
                    {           
                        pagesize -= (zzip_ssize_t) offset & (pagesize - 1);
                        offset += pagesize;
                        maplen -= pagesize;
                    }
                }
                if (offset + maplen > pj)
                    maplen = pj - offset;
            }

            if (ko->fd.seeks(rf, offset, SEEK_SET) < 0)
                { return(ZZIP_DIR_SEEK); }
            if (ko->fd.read(rf, buf, (zzip_size_t) maplen) < maplen)
                { return(ZZIP_DIR_READ); }
            mapped = (unsigned char *) buf;     
            HINT5("offs=$%lx len=%li filesize=%li pagesize=%i",
                  (long) offset, (long) maplen, (long) pj, ZZIP_BUFSIZ);
        }

        {                       
            register unsigned char *end = mapped + maplen;
            register unsigned char *tail;
            for (tail = end - 1; (tail >= mapped); tail--)
            {
                if ((*tail == 'P') &&   
                    end - tail >= __sizeof(struct zzip_disk_trailer) - 2 &&
                    zzip_disk_trailer_check_magic(tail))
                {
#                  ifndef ZZIP_DISK64_TRAILER

                    if (end - tail >= __sizeof(*ef))
                    {
                        memcpy(ef, tail, sizeof(*ef));
                    } else
                    {
                        memcpy(ef, tail, sizeof(*ef) - 2);
                        ef->z_comment[0] = 0;
                        ef->z_comment[1] = 0;
                    }
#                  else
                    struct zzip_disk_trailer *orig =
                        (struct zzip_disk_trailer *) tail;
                    ef->zz_tail = tail;
                    ef->zz_entries = zzip_disk_trailer_localentries(orig);
                    ef->zz_finalentries =
                        zzip_disk_trailer_finalentries(orig);
                    ef->zz_rootseek = zzip_disk_trailer_rootseek(orig);
                    ef->zz_rootsize = zzip_disk_trailer_rootsize(orig);
#                  endif

                    __fixup_rootseek(offset + tail - mapped, ef);
                    { return(0); }
                } else if ((*tail == 'P') &&
                           end - tail >=
                           __sizeof(struct zzip_disk64_trailer) - 2
                           && zzip_disk64_trailer_check_magic(tail))
                {
#                  ifndef ZZIP_DISK64_TRAILER
                    return (ZZIP_DIR_LARGEFILE);
#                  else
                    struct zzip_disk64_trailer *orig =
                        (struct zzip_disk64_trailer *) tail;
                    ef->zz_tail = tail;
                    ef->zz_entries =
                        zzip_disk64_trailer_localentries(orig);
                    ef->zz_finalentries =
                        zzip_disk64_trailer_finalentries(orig);
                    ef->zz_rootseek = zzip_disk64_trailer_rootseek(orig);
                    ef->zz_rootsize = zzip_disk64_trailer_rootsize(orig);
                    { return(0); }
#                  endif
                }
            }
        }

        if (USE_MMAP && fd_map)
        {
            HINT3("unmap *%p len=%li", fd_map, (long) maplen);
            _zzip_munmap(ko->fd.sys, fd_map, (zzip_size_t) maplen);
            fd_map = 0;
        }
    }                           

  cleanup:
    if (USE_MMAP && fd_map)
    {
        HINT3("unmap *%p len=%li", fd_map, (long) maplen);
        _zzip_munmap(ko->fd.sys, fd_map, (zzip_size_t) maplen);
    }
#   ifdef _LOWSTK
    free(buf);
#   endif
#   undef return
    return e;
}

static void pe(CadenceGEMState *la)
{
    uint32_t desc[DESC_MAX_NUM_WORDS];
    hwaddr packet_desc_addr;
    uint8_t     *p;
    unsigned    total_bytes;
    int q = 0;


    if (!(la->regs[GEM_NWCTRL] & GEM_NWCTRL_TXENA)) {
        return;
    }

    DB_PRINT("\n");


    p = la->tx_packet;
    total_bytes = 0;

    for (q = la->num_priority_queues - 1; q >= 0; q--) {

        packet_desc_addr = gem_get_tx_desc_addr(la, q);

        DB_PRINT("read descriptor 0x%" HWADDR_PRIx "\n", packet_desc_addr);
        address_space_read(&la->dma_as, packet_desc_addr,
                           MEMTXATTRS_UNSPECIFIED, desc,
                           sizeof(uint32_t) * gem_get_desc_len(la, false));

        while (tx_desc_get_used(desc) == 0) {


            if (!(la->regs[GEM_NWCTRL] & GEM_NWCTRL_TXENA)) {
                return;
            }
            print_gem_tx_desc(desc, q);


            if ((tx_desc_get_buffer(la, desc) == 0) ||
                (tx_desc_get_length(desc) == 0)) {
                DB_PRINT("Invalid TX descriptor @ 0x%" HWADDR_PRIx "\n",
                         packet_desc_addr);
                break;
            }

            if (tx_desc_get_length(desc) > gem_get_max_buf_len(la, true) -
                                               (p - la->tx_packet)) {
                qemu_log_mask(LOG_GUEST_ERROR, "TX descriptor @ 0x%" \
                         HWADDR_PRIx " too large: size 0x%x space 0x%zx\n",
                         packet_desc_addr, tx_desc_get_length(desc),
                         gem_get_max_buf_len(la, true) - (p - la->tx_packet));
                gem_set_isr(la, q, GEM_INT_AMBA_ERR);
                break;
            }


            address_space_read(&la->dma_as, tx_desc_get_buffer(la, desc),
                               MEMTXATTRS_UNSPECIFIED,
                               p, tx_desc_get_length(desc));
            p += tx_desc_get_length(desc);
            total_bytes += tx_desc_get_length(desc);


            if (tx_desc_get_last(desc)) {
                uint32_t desc_first[DESC_MAX_NUM_WORDS];
                hwaddr desc_addr = gem_get_tx_desc_addr(la, q);


                address_space_read(&la->dma_as, desc_addr,
                                   MEMTXATTRS_UNSPECIFIED, desc_first,
                                   sizeof(desc_first));
                tx_desc_set_used(desc_first);
                address_space_write(&la->dma_as, desc_addr,
                                    MEMTXATTRS_UNSPECIFIED, desc_first,
                                    sizeof(desc_first));

                if (tx_desc_get_wrap(desc)) {
                    la->tx_desc_addr[q] = gem_get_tx_queue_base_addr(la, q);
                } else {
                    la->tx_desc_addr[q] = packet_desc_addr +
                                         4 * gem_get_desc_len(la, false);
                }
                DB_PRINT("TX descriptor next: 0x%08x\n", la->tx_desc_addr[q]);

                la->regs[GEM_TXSTATUS] |= GEM_TXSTATUS_TXCMPL;
                gem_set_isr(la, q, GEM_INT_TXCMPL);


                gem_update_int_status(la);


                if (la->regs[GEM_DMACFG] & GEM_DMACFG_TXCSUM_OFFL) {
                    net_checksum_calculate(la->tx_packet, total_bytes, CSUM_ALL);
                }


                pe_updatestats(la, la->tx_packet, total_bytes);


                if (la->phy_loop || (la->regs[GEM_NWCTRL] &
                                    GEM_NWCTRL_LOCALLOOP)) {
                    gem_receive(qemu_get_queue(la->nic), la->tx_packet,
                                total_bytes);
                } else {
                    qemu_send_packet(qemu_get_queue(la->nic), la->tx_packet,
                                     total_bytes);
                }


                p = la->tx_packet;
                total_bytes = 0;
            }


            if (tx_desc_get_wrap(desc)) {

                if (la->regs[GEM_DMACFG] & GEM_DMACFG_ADDR_64B) {
                    packet_desc_addr = la->regs[GEM_TBQPH];
                    packet_desc_addr <<= 32;
                } else {
                    packet_desc_addr = 0;
                }
                packet_desc_addr |= gem_get_tx_queue_base_addr(la, q);
            } else {
                packet_desc_addr += 4 * gem_get_desc_len(la, false);
            }
            DB_PRINT("read descriptor 0x%" HWADDR_PRIx "\n", packet_desc_addr);
            address_space_read(&la->dma_as, packet_desc_addr,
                               MEMTXATTRS_UNSPECIFIED, desc,
                               sizeof(uint32_t) * gem_get_desc_len(la, false));
        }

        if (tx_desc_get_used(desc)) {
            la->regs[GEM_TXSTATUS] |= GEM_TXSTATUS_USED;

            if (q == 0) {
                gem_set_isr(la, 0, GEM_INT_TXUSED);
            }
            gem_update_int_status(la);
        }
    }
}

STATIC ih(pTHX_ RExC_state_t *gm, regnode **rq,
                        SSize_t *up, SSize_t *nv,
			regnode *pn,
			scan_data_t *wo,
			I32 pf,
                        U32 cs,
			regnode_ssc *az,
			U32 yh, U32 jb)







{
    dVAR;

    SSize_t min = 0;
    I32 pars = 0, code;
    regnode *scan = *rq, *next;
    SSize_t delta = 0;
    int is_inf = (yh & SCF_DO_SUBSTR) && (wo->yh & SF_IS_INF);
    int is_inf_internal = 0;		
    I32 is_par = OP(scan) == OPEN ? ARG(scan) : 0;
    scan_data_t data_fake;
    SV *re_trie_maxbuff = NULL;
    regnode *first_non_open = scan;
    SSize_t stopmin = SSize_t_MAX;
    scan_frame *frame = NULL;
    GET_RE_DEBUG_FLAGS_DECL;

    PERL_ARGS_ASSERT_STUDY_CHUNK;
