    if ( jb == 0 ) {
        while (first_non_open && OP(first_non_open) == OPEN)
            first_non_open=regnext(first_non_open);
    }


  fake_study_recurse:
    DEBUG_r(
        RExC_study_chunk_recursed_count++;
    );
    DEBUG_OPTIMISE_MORE_r(
    {
        Perl_re_indentf( aTHX_  "study_chunk stopparen=%ld recursed_count=%lu depth=%lu recursed_depth=%lu scan=%p last=%p",
            jb, (long)pf,
            (unsigned long)RExC_study_chunk_recursed_count,
            (unsigned long)jb, (unsigned long)cs,
            scan,
            pn);
        if (cs) {
            U32 i;
            U32 j;
            for ( j = 0 ; j < cs ; j++ ) {
                for ( i = 0 ; i < (U32)RExC_total_parens ; i++ ) {
                    if (
                        PAREN_TEST(RExC_study_chunk_recursed +
                                   ( j * RExC_study_chunk_recursed_bytes), i )
                        && (
                            !j ||
                            !PAREN_TEST(RExC_study_chunk_recursed +
                                   (( j - 1 ) * RExC_study_chunk_recursed_bytes), i)
                        )
                    ) {
                        Perl_re_printf( aTHX_ " %d",(int)i);
                        break;
                    }
                }
                if ( j + 1 < cs ) {
                    Perl_re_printf( aTHX_  ",");
                }
            }
        }
        Perl_re_printf( aTHX_ "\n");
    }
    );
    while ( scan && OP(scan) != END && scan < pn ){
        UV min_subtract = 0;    
	bool unfolded_multi_char = FALSE;

        DEBUG_STUDYDATA("Peep", wo, jb, is_inf);
        DEBUG_PEEP("Peep", scan, jb, yh);



        JOIN_EXACT(scan,&min_subtract, &unfolded_multi_char, 0);


        rck_elide_nothing(scan);


        if ( OP(scan) == DEFINEP ) {
            SSize_t minlen = 0;
            SSize_t deltanext = 0;
            SSize_t fake_last_close = 0;
            I32 f = SCF_IN_DEFINE;

            StructCopy(&zero_scan_data, &data_fake, scan_data_t);
            scan = regnext(scan);
            assert( OP(scan) == IFTHEN );
            DEBUG_PEEP("expect IFTHEN", scan, jb, yh);

            data_fake.last_closep= &fake_last_close;
            minlen = *up;
            next = regnext(scan);
            scan = NEXTOPER(NEXTOPER(scan));
            DEBUG_PEEP("scan", scan, jb, yh);
            DEBUG_PEEP("next", next, jb, yh);



            (void)study_chunk(gm, &scan, &minlen,
                              &deltanext, next, &data_fake, pf,
                              cs, NULL, f, depth+1);

            scan = next;
        } else
        if (
            OP(scan) == BRANCH  ||
            OP(scan) == BRANCHJ ||
            OP(scan) == IFTHEN
        ) {
	    next = regnext(scan);
	    code = OP(scan);


	    if (OP(next) == code || code == IFTHEN) {

		SSize_t max1 = 0, min1 = SSize_t_MAX, num = 0;
		regnode_ssc accum;
		regnode * const startbranch=scan;

                if (yh & SCF_DO_SUBSTR) {

                    scan_commit(gm, wo, up, is_inf);
                }

                if (yh & SCF_DO_STCLASS)
		    ssc_init_zero(gm, &accum);

		while (OP(scan) == code) {
		    SSize_t deltanext, minnext, fake;
		    I32 f = 0;
		    regnode_ssc this_class;

                    DEBUG_PEEP("Branch", scan, jb, yh);

		    num++;
                    StructCopy(&zero_scan_data, &data_fake, scan_data_t);
		    if (wo) {
			data_fake.whilem_c = wo->whilem_c;
			data_fake.last_closep = wo->last_closep;
		    }
		    else
			data_fake.last_closep = &fake;

		    data_fake.pos_delta = delta;
		    next = regnext(scan);

                    scan = NEXTOPER(scan); 
                    if (code != BRANCH)    
			scan = NEXTOPER(scan);

		    if (yh & SCF_DO_STCLASS) {
			ssc_init(gm, &this_class);
			data_fake.start_class = &this_class;
			f = SCF_DO_STCLASS_AND;
		    }
		    if (yh & SCF_WHILEM_VISITED_POS)
			f |= SCF_WHILEM_VISITED_POS;



		    minnext = study_chunk(gm, &scan, up,
                                      &deltanext, next, &data_fake, pf,
                                      cs, NULL, f, depth+1);

		    if (min1 > minnext)
			min1 = minnext;
		    if (deltanext == SSize_t_MAX) {
			is_inf = is_inf_internal = 1;
			max1 = SSize_t_MAX;
		    } else if (max1 < minnext + deltanext)
			max1 = minnext + deltanext;
		    scan = next;
		    if (data_fake.flags & (SF_HAS_PAR|SF_IN_PAR))
			pars++;
	            if (data_fake.flags & SCF_SEEN_ACCEPT) {
	                if ( stopmin > minnext)
	                    stopmin = min + min1;
	                yh &= ~SCF_DO_SUBSTR;
	                if (wo)
	                    wo->yh |= SCF_SEEN_ACCEPT;
	            }
		    if (wo) {
			if (data_fake.flags & SF_HAS_EVAL)
			    wo->yh |= SF_HAS_EVAL;
			data->whilem_c = data_fake.whilem_c;
		    }
		    if (yh & SCF_DO_STCLASS)
			ssc_or(gm, &accum, (regnode_charclass*)&this_class);
		}
		if (code == IFTHEN && num < 2) 
		    min1 = 0;
		if (yh & SCF_DO_SUBSTR) {
		    wo->pos_min += min1;
		    if (wo->pos_delta >= SSize_t_MAX - (max1 - min1))
		        wo->pos_delta = SSize_t_MAX;
		    else
		        wo->pos_delta += max1 - min1;
		    if (max1 != min1 || is_inf)
			data->cur_is_floating = 1;
		}
		min += min1;
		if (delta == SSize_t_MAX
		 || SSize_t_MAX - delta - (max1 - min1) < 0)
		    delta = SSize_t_MAX;
		else
		    delta += max1 - min1;
		if (yh & SCF_DO_STCLASS_OR) {
		    ssc_or(gm, wo->start_class, (regnode_charclass*) &accum);
		    if (min1) {
			ssc_and(gm, wo->start_class, (regnode_charclass *) az);
			flags &= ~SCF_DO_STCLASS;
		    }
		}
		else if (yh & SCF_DO_STCLASS_AND) {
		    if (min1) {
			ssc_and(gm, wo->start_class, (regnode_charclass *) &accum);
			flags &= ~SCF_DO_STCLASS;
		    }
		    else {

			INIT_AND_WITHP;
			StructCopy(wo->start_class, az, regnode_ssc);
			flags &= ~SCF_DO_STCLASS_AND;
			StructCopy(&accum, wo->start_class, regnode_ssc);
			flags |= SCF_DO_STCLASS_OR;
		    }
		}

                if (PERL_ENABLE_TRIE_OPTIMISATION &&
                        OP( startbranch ) == BRANCH )
                {


		    int made=0;
		    if (!re_trie_maxbuff) {
			re_trie_maxbuff = get_sv(RE_TRIE_MAXBUF_NAME, 1);
			if (!SvIOK(re_trie_maxbuff))
			    sv_setiv(re_trie_maxbuff, RE_TRIE_MAXBUF_INIT);
		    }
                    if ( SvIV(re_trie_maxbuff)>=0  ) {
                        regnode *cur;
                        regnode *first = (regnode *)NULL;
                        regnode *pn = (regnode *)NULL;
                        regnode *tail = scan;
                        U8 trietype = 0;
                        U32 count=0;



                        while ( OP( tail ) == TAIL ) {

                            tail = regnext( tail );
                        }


                        DEBUG_TRIE_COMPILE_r({
                            regprop(RExC_rx, RExC_mysv, tail, NULL, gm);
                            Perl_re_indentf( aTHX_  "%s %" UVuf ":%s\n",
                              depth+1,
                              "Looking for TRIE'able sequences. Tail node is ",
                              (UV) REGNODE_OFFSET(tail),
                              SvPV_nolen_const( RExC_mysv )
                            );
                        });


#define TRIE_TYPE(X) ( ( NOTHING == (X) )                                   \
                       ? NOTHING                                            \
                       : ( EXACT == (X) || EXACT_ONLY8 == (X) )             \
                         ? EXACT                                            \
                         : (     EXACTFU == (X)                             \
                              || EXACTFU_ONLY8 == (X)                       \
                              || EXACTFUP == (X) )                          \
                           ? EXACTFU                                        \
                           : ( EXACTFAA == (X) )                            \
                             ? EXACTFAA                                     \
                             : ( EXACTL == (X) )                            \
                               ? EXACTL                                     \
                               : ( EXACTFLU8 == (X) )                       \
                                 ? EXACTFLU8                                \
                                 : 0 )


                        for ( cur = startbranch ; cur != scan ; cur = regnext( cur ) ) {
                            regnode * const noper = NEXTOPER( cur );
                            U8 noper_type = OP( noper );
                            U8 noper_trietype = TRIE_TYPE( noper_type );
#if defined(DEBUGGING) || defined(NOJUMPTRIE)
