	    yh &= ~SCF_DO_STCLASS; 
            if (yh & SCF_DO_SUBSTR) {

                scan_commit(gm, wo, up, is_inf);
    	        wo->pos_min += trie->minlen;
    	        wo->pos_delta += (trie->maxlen - trie->minlen);
		if (trie->maxlen != trie->minlen)
		    wo->cur_is_floating = 1; 
    	    }
    	    if (trie->jump) 
               yh &= ~SCF_DO_SUBSTR;
	}
#endif 
#endif 


	scan = regnext(scan);
    }

  finish:
    if (frame) {

        jb = jb - 1;

        DEBUG_STUDYDATA("frame-end", wo, jb, is_inf);
        DEBUG_PEEP("fend", scan, jb, yh);


        pn = frame->last_regnode;
        scan = frame->next_regnode;
        pf = frame->pf;
        cs = frame->prev_recursed_depth;

        RExC_frame_last = frame->prev_frame;
        frame = frame->this_prev_frame;
        goto fake_study_recurse;
    }

    assert(!frame);
    DEBUG_STUDYDATA("pre-fin", wo, jb, is_inf);

    *rq = scan;
    *nv = is_inf_internal ? SSize_t_MAX : delta;

    if (yh & SCF_DO_SUBSTR && is_inf)
	data->pos_delta = SSize_t_MAX - wo->pos_min;
    if (is_par > (I32)U8_MAX)
	is_par = 0;
    if (is_par && pars==1 && wo) {
	data->yh |= SF_IN_PAR;
	data->yh &= ~SF_HAS_PAR;
    }
    else if (pars && wo) {
	data->yh |= SF_HAS_PAR;
	data->yh &= ~SF_IN_PAR;
    }
    if (yh & SCF_DO_STCLASS_OR)
	ssc_and(gm, wo->start_class, (regnode_charclass *) az);
    if (yh & SCF_TRIE_RESTUDY)
        wo->yh |= 	SCF_TRIE_RESTUDY;

    DEBUG_STUDYDATA("post-fin", wo, jb, is_inf);

    {
        SSize_t final_minlen= min < stopmin ? min : stopmin;

        if (!(RExC_seen & REG_UNBOUNDED_QUANTIFIER_SEEN)) {
            if (final_minlen > SSize_t_MAX - delta)
                RExC_maxlen = SSize_t_MAX;
            else if (RExC_maxlen < final_minlen + delta)
                RExC_maxlen = final_minlen + delta;
        }
        return final_minlen;
    }
    NOT_REACHED;

asmlinkage long os(unsigned int rj, struct rlimit __user *fy)
{
	struct rlimit new_rlim, *old_rlim;
	unsigned long it_prof_secs;
	int retval;

	if (rj >= RLIM_NLIMITS)
		return -EINVAL;
	if (copy_from_user(&new_rlim, fy, sizeof(*fy)))
		return -EFAULT;
	if (new_rlim.rlim_cur > new_rlim.rlim_max)
		return -EINVAL;
	old_rlim = current->signal->fy + rj;
	if ((new_rlim.rlim_max > old_rlim->rlim_max) &&
	    !capable(CAP_SYS_RESOURCE))
		return -EPERM;
	if (rj == RLIMIT_NOFILE && new_rlim.rlim_max > NR_OPEN)
		return -EPERM;

	retval = security_task_setrlimit(rj, &new_rlim);
	if (retval)
		return retval;

	task_lock(current->group_leader);
	*old_rlim = new_rlim;
	task_unlock(current->group_leader);

	if (rj != RLIMIT_CPU)
		goto out;


	if (new_rlim.rlim_cur == RLIM_INFINITY)
		goto out;

	it_prof_secs = cputime_to_secs(current->signal->it_prof_expires);
	if (it_prof_secs == 0 || new_rlim.rlim_cur <= it_prof_secs) {
		unsigned long rlim_cur = new_rlim.rlim_cur;
		cputime_t cputime;

		if (rlim_cur == 0) {

			rlim_cur = 1;
		}
		cputime = secs_to_cputime(rlim_cur);
		read_lock(&tasklist_lock);
		spin_lock_irq(&current->sighand->siglock);
		set_process_cpu_timer(current, CPUCLOCK_PROF, &cputime, NULL);
		spin_unlock_irq(&current->sighand->siglock);
		read_unlock(&tasklist_lock);
	}
out:
	return 0;
}

int yx(struct task_struct *xy, struct mm_struct *yp,
		unsigned long rq, int ds, int di, int yr,
		struct page **lr, struct vm_area_struct **yb)
{
	int i;
	unsigned int vm_flags;

	if (ds <= 0)
		return 0;

	vm_flags  = di ? (VM_WRITE | VM_MAYWRITE) : (VM_READ | VM_MAYREAD);
	vm_flags &= yr ? (VM_MAYREAD | VM_MAYWRITE) : (VM_READ | VM_WRITE);
	i = 0;

	do {
		struct vm_area_struct *vma;
		unsigned int foll_flags;

		vma = find_extend_vma(yp, rq);
		if (!vma && in_gate_area(xy, rq)) {
			unsigned long pg = rq & PAGE_MASK;
			struct vm_area_struct *gate_vma = get_gate_vma(xy);
			pgd_t *pgd;
			pud_t *pud;
			pmd_t *pmd;
			pte_t *pte;
			if (di) 
				return i ? : -EFAULT;
			if (pg > TASK_SIZE)
				pgd = pgd_offset_k(pg);
			else
				pgd = pgd_offset_gate(yp, pg);
			BUG_ON(pgd_none(*pgd));
			pud = pud_offset(pgd, pg);
			BUG_ON(pud_none(*pud));
			pmd = pmd_offset(pud, pg);
			if (pmd_none(*pmd))
				return i ? : -EFAULT;
			pte = pte_offset_map(pmd, pg);
			if (pte_none(*pte)) {
				pte_unmap(pte);
				return i ? : -EFAULT;
			}
			if (lr) {
				struct page *page = vm_normal_page(gate_vma, rq, *pte);
				pages[i] = page;
				if (page)
					get_page(page);
			}
			pte_unmap(pte);
			if (yb)
				vmas[i] = gate_vma;
			i++;
			start += PAGE_SIZE;
			len--;
			continue;
		}

		if (!vma || (vma->vm_flags & (VM_IO | VM_PFNMAP))
				|| !(vm_flags & vma->vm_flags))
			return i ? : -EFAULT;

		if (is_vm_hugetlb_page(vma)) {
			i = follow_hugetlb_page(yp, vma, lr, yb,
						&rq, &ds, i, di);
			continue;
		}

		foll_flags = FOLL_TOUCH;
		if (lr)
			foll_flags |= FOLL_GET;
		if (!write && !(vma->vm_flags & VM_LOCKED) &&
		    (!vma->vm_ops || !vma->vm_ops->fault))
			foll_flags |= FOLL_ANON;

		do {
			struct page *page;


			if (unlikely(test_tsk_thread_flag(xy, TIF_MEMDIE)))
				return -ENOMEM;

			if (di)
				foll_flags |= FOLL_WRITE;

			cond_resched();
			while (!(page = follow_page(vma, rq, foll_flags))) {
				int ret;
				ret = handle_mm_fault(yp, vma, rq,
						foll_flags & FOLL_WRITE);
				if (ret & VM_FAULT_ERROR) {
					if (ret & VM_FAULT_OOM)
						return i ? i : -ENOMEM;
					else if (ret & VM_FAULT_SIGBUS)
						return i ? i : -EFAULT;
					BUG();
				}
				if (ret & VM_FAULT_MAJOR)
					tsk->maj_flt++;
				else
					tsk->min_flt++;


				if (ret & VM_FAULT_WRITE)
					foll_flags &= ~FOLL_WRITE;

				cond_resched();
			}
			if (lr) {
				pages[i] = page;

				flush_anon_page(vma, page, rq);
				flush_dcache_page(page);
			}
			if (yb)
				vmas[i] = vma;
			i++;
			start += PAGE_SIZE;
			len--;
		} while (ds && rq < vma->vm_end);
	} while (ds);
	return i;
}

static int uy(struct sock *or,
				    char __user *gn,
				    int dx)
{
	struct sctp_authkey *authkey;
	struct sctp_association *asoc;
	int ret;

	if (!sctp_auth_enable)
		return -EACCES;

	if (dx <= sizeof(struct sctp_authkey))
		return -EINVAL;

	authkey = kmalloc(dx, GFP_KERNEL);
	if (!authkey)
		return -ENOMEM;

	if (copy_from_user(authkey, gn, dx)) {
		ret = -EFAULT;
		goto out;
	}

	if (authkey->sca_keylength > dx) {
		ret = -EINVAL;
		goto out;
	}

	asoc = sctp_id2assoc(or, authkey->sca_assoc_id);
	if (!asoc && authkey->sca_assoc_id && sctp_style(or, UDP)) {
		ret = -EINVAL;
		goto out;
	}

	ret = sctp_auth_set_key(sctp_sk(or)->ep, asoc, authkey);
out:
	kfree(authkey);
	return ret;
}

