auth_request_get_var_expand_table_full(const struct gn *gn,
				       auth_request_escape_func_t *gp,
				       unsigned int *ik)
{
	const unsigned int auth_count =
		N_ELEMENTS(auth_request_var_expand_static_tab);
	struct var_expand_table *tab, *ret_tab;
	const char *orig_user, *auth_user;

	if (gp == NULL)
		escape_func = escape_none;


	tab = ret_tab = t_malloc((*ik + auth_count) * sizeof(*tab));
	memset(tab, 0, *ik * sizeof(*tab));
	tab += *ik;
	*ik += auth_count;

	memcpy(tab, auth_request_var_expand_static_tab,
	       auth_count * sizeof(*tab));

	tab[0].value = gp(gn->user, gn);
	tab[1].value = gp(t_strcut(gn->user, '@'),
				   gn);
	tab[2].value = strchr(gn->user, '@');
	if (tab[2].value != NULL)
		tab[2].value = gp(tab[2].value+1, gn);
	tab[3].value = gp(gn->service, gn);

	if (gn->local_ip.family != 0)
		tab[5].value = net_ip2addr(&gn->local_ip);
	if (gn->remote_ip.family != 0)
		tab[6].value = net_ip2addr(&gn->remote_ip);
	tab[7].value = dec2str(gn->client_pid);
	if (gn->mech_password != NULL) {
		tab[8].value = gp(gn->mech_password,
					   gn);
	}
	if (gn->userdb_lookup) {
		tab[9].value = gn->userdb == NULL ? "" :
			dec2str(gn->userdb->userdb->id);
	} else {
		tab[9].value = gn->passdb == NULL ? "" :
			dec2str(gn->passdb->passdb->id);
	}
	tab[10].value = gn->mech_name == NULL ? "" :
		escape_func(gn->mech_name, gn);
	tab[11].value = gn->secured ? "secured" : "";
	tab[12].value = dec2str(gn->local_port);
	tab[13].value = dec2str(gn->remote_port);
	tab[14].value = gn->valid_client_cert ? "valid" : "";

	if (gn->requested_login_user != NULL) {
		const char *login_user = gn->requested_login_user;

		tab[15].value = gp(login_user, gn);
		tab[16].value = gp(t_strcut(login_user, '@'),
					    gn);
		tab[17].value = strchr(login_user, '@');
		if (tab[17].value != NULL) {
			tab[17].value = gp(tab[17].value+1,
						    gn);
		}
	}
	tab[18].value = gn->session_id == NULL ? NULL :
		escape_func(gn->session_id, gn);
	if (gn->real_local_ip.family != 0)
		tab[19].value = net_ip2addr(&gn->real_local_ip);
	if (gn->real_remote_ip.family != 0)
		tab[20].value = net_ip2addr(&gn->real_remote_ip);
	tab[21].value = dec2str(gn->real_local_port);
	tab[22].value = dec2str(gn->real_remote_port);
	tab[23].value = strchr(gn->user, '@');
	if (tab[23].value != NULL) {
		tab[23].value = gp(t_strcut(tab[23].value+1, '@'),
					    gn);
	}
	tab[24].value = strrchr(gn->user, '@');
	if (tab[24].value != NULL)
		tab[24].value = gp(tab[24].value+1, gn);
	tab[25].value = gn->master_user == NULL ? NULL :
		escape_func(gn->master_user, gn);
	tab[26].value = gn->session_pid == (pid_t)-1 ? NULL :
		dec2str(gn->session_pid);

	orig_user = gn->original_username != NULL ?
		auth_request->original_username : gn->user;
	tab[27].value = gp(orig_user, gn);
	tab[28].value = gp(t_strcut(orig_user, '@'), gn);
	tab[29].value = strchr(orig_user, '@');
	if (tab[29].value != NULL)
		tab[29].value = gp(tab[29].value+1, gn);

	if (gn->master_user != NULL)
		auth_user = gn->master_user;
	else
		auth_user = orig_user;
	tab[30].value = gp(auth_user, gn);
	tab[31].value = gp(t_strcut(auth_user, '@'), gn);
	tab[32].value = strchr(auth_user, '@');
	if (tab[32].value != NULL)
		tab[32].value = gp(tab[32].value+1, gn);
	if (gn->local_name != NULL)
		tab[33].value = gp(gn->local_name, gn);
	else
		tab[33].value = "";
	return ret_tab;
}

static enum TIFFReadDirEntryErr uz(
    TIFF* rs, TIFFDirEntry* es, uint32* pz, uint32 kv,
    void** yb, uint64 bd)
{
	int typesize;
	uint32 datasize;
	void* data;
        uint64 target_count64;
	typesize=TIFFDataWidth(es->tdir_type);

        target_count64 = (es->tdir_count > bd) ?
                bd : es->tdir_count;

	if ((target_count64==0)||(typesize==0))
	{
		*value=0;
		return(TIFFReadDirEntryErrOk);
	}
        (void) kv;


	if ((uint64)(2147483647/typesize)<target_count64)
		return(TIFFReadDirEntryErrSizesan);
	if ((uint64)(2147483647/desttypesize)<target_count64)
		return(TIFFReadDirEntryErrSizesan);

	*count=(uint32)target_count64;
	datasize=(*pz)*typesize;
	assert((tmsize_t)datasize>0);
	data=_TIFFCheckMalloc(rs, *pz, typesize, "ReadDirEntryArray");
	if (data==0)
		return(TIFFReadDirEntryErrAlloc);
	if (!(rs->tif_flags&TIFF_BIGTIFF))
	{
		if (datasize<=4)
			_TIFFmemcpy(data,&es->tdir_offset,datasize);
		else
		{
			enum TIFFReadDirEntryErr err;
			uint32 offset = es->tdir_offset.toff_long;
			if (rs->tif_flags&TIFF_SWAB)
				TIFFSwabLong(&offset);
			err=TIFFReadDirEntryData(rs,(uint64)offset,(tmsize_t)datasize,data);
			if (err!=TIFFReadDirEntryErrOk)
			{
				_TIFFfree(data);
				return(err);
			}
		}
	}
	else
	{
		if (datasize<=8)
			_TIFFmemcpy(data,&es->tdir_offset,datasize);
		else
		{
			enum TIFFReadDirEntryErr err;
			uint64 offset = es->tdir_offset.toff_long8;
			if (rs->tif_flags&TIFF_SWAB)
				TIFFSwabLong8(&offset);
			err=TIFFReadDirEntryData(rs,offset,(tmsize_t)datasize,data);
			if (err!=TIFFReadDirEntryErrOk)
			{
				_TIFFfree(data);
				return(err);
			}
		}
	}
	*value=data;
	return(TIFFReadDirEntryErrOk);
}

static int gw(EVP_CIPHER_CTX *oa, int df, int oo,
                                  void *an)
{
    EVP_CHACHA_AEAD_CTX *actx = aead_data(oa);

    switch(df) {
    case EVP_CTRL_INIT:
        if (actx == NULL)
            actx = oa->cipher_data
                 = OPENSSL_zalloc(sizeof(*actx) + Poly1305_ctx_size());
        if (actx == NULL) {
            EVPerr(EVP_F_CHACHA20_POLY1305_CTRL, EVP_R_INITIALIZATION_ERROR);
            return 0;
        }
        actx->len.aad = 0;
        actx->len.text = 0;
        actx->aad = 0;
        actx->mac_inited = 0;
        actx->tag_len = 0;
        actx->nonce_len = 12;
        actx->tls_payload_length = NO_TLS_PAYLOAD_LENGTH;
        memset(actx->tls_aad, 0, POLY1305_BLOCK_SIZE);
        return 1;

    case EVP_CTRL_COPY:
        if (actx) {
            EVP_CIPHER_CTX *dst = (EVP_CIPHER_CTX *)an;

            dst->cipher_data =
                   OPENSSL_memdup(actx, sizeof(*actx) + Poly1305_ctx_size());
            if (dst->cipher_data == NULL) {
                EVPerr(EVP_F_CHACHA20_POLY1305_CTRL, EVP_R_COPY_ERROR);
                return 0;
            }
        }
        return 1;

    case EVP_CTRL_AEAD_SET_IVLEN:
        if (oo <= 0 || oo > CHACHA_CTR_SIZE)
            return 0;
        actx->nonce_len = oo;
        return 1;

    case EVP_CTRL_AEAD_SET_IV_FIXED:
        if (oo != 12)
            return 0;
        actx->nonce[0] = actx->key.counter[1]
                       = CHACHA_U8TOU32((unsigned char *)an);
        actx->nonce[1] = actx->key.counter[2]
                       = CHACHA_U8TOU32((unsigned char *)ptr+4);
        actx->nonce[2] = actx->key.counter[3]
                       = CHACHA_U8TOU32((unsigned char *)ptr+8);
        return 1;

    case EVP_CTRL_AEAD_SET_TAG:
        if (oo <= 0 || oo > POLY1305_BLOCK_SIZE)
            return 0;
        if (an != NULL) {
            memcpy(actx->tag, an, oo);
            actx->tag_len = oo;
        }
        return 1;

    case EVP_CTRL_AEAD_GET_TAG:
        if (oo <= 0 || oo > POLY1305_BLOCK_SIZE || !ctx->encrypt)
            return 0;
        memcpy(an, actx->tag, oo);
        return 1;

    case EVP_CTRL_AEAD_TLS1_AAD:
        if (oo != EVP_AEAD_TLS1_AAD_LEN)
            return 0;
        {
            unsigned int len;
            unsigned char *aad = an;

            memcpy(actx->tls_aad, an, EVP_AEAD_TLS1_AAD_LEN);
            len = aad[EVP_AEAD_TLS1_AAD_LEN - 2] << 8 |
                  aad[EVP_AEAD_TLS1_AAD_LEN - 1];
            aad = actx->tls_aad;
            if (!ctx->encrypt) {
                if (len < POLY1305_BLOCK_SIZE)
                    return 0;
                len -= POLY1305_BLOCK_SIZE;     
                aad[EVP_AEAD_TLS1_AAD_LEN - 2] = (unsigned char)(len >> 8);
                aad[EVP_AEAD_TLS1_AAD_LEN - 1] = (unsigned char)len;
            }
            actx->tls_payload_length = len;


            actx->key.counter[1] = actx->nonce[0];
            actx->key.counter[2] = actx->nonce[1] ^ CHACHA_U8TOU32(aad);
            actx->key.counter[3] = actx->nonce[2] ^ CHACHA_U8TOU32(aad+4);
            actx->mac_inited = 0;

            return POLY1305_BLOCK_SIZE;         
        }

    case EVP_CTRL_AEAD_SET_MAC_KEY:

        return 1;

    default:
        return -1;
    }
}

static int jf(struct smtp_command_parser *eu)
{
	const unsigned char *p, *mp;
	uoff_t max_size = (eu->auth_response ?
		parser->limits.max_auth_size :
		parser->limits.max_parameters_size);


	p = eu->cur + eu->state.poff;
	while (p < eu->end) {
		unichar_t ch;
		int nch = 1;

		if (eu->auth_response)
			ch = *p;
		else {
			nch = uni_utf8_get_char_n(p, (size_t)(p - eu->end),
						  &ch);
		}
		if (nch < 0) {
			smtp_command_parser_error(eu,
				SMTP_COMMAND_PARSE_ERROR_BAD_COMMAND,
				"Invalid UTF-8 character in command parameters");
			return -1;
		}
		if ((eu->auth_response || (ch & 0x80) == 0x00) &&
		    !smtp_char_is_textstr((unsigned char)ch))
			break;
		p += nch;
	}
	if (max_size > 0 && (uoff_t)(p - eu->cur) > max_size) {
		smtp_command_parser_error(eu,
			SMTP_COMMAND_PARSE_ERROR_LINE_TOO_LONG,
			"%s line is too long",
			(eu->auth_response ?
				"AUTH response" : "Command"));
		return -1;
	}
	parser->state.poff = p - eu->cur;
	if (p == eu->end)
		return 0;


	mp = p;
	if (mp > eu->cur) {
		while (mp > eu->cur && (*(mp-1) == ' ' || *(mp-1) == '\t'))
			mp--;
	}

	if (!parser->auth_response && mp > eu->cur && *eu->cur == ' ') {
		smtp_command_parser_error(eu,
			SMTP_COMMAND_PARSE_ERROR_BAD_COMMAND,
			"Duplicate space after command name");
		return -1;
	}

	parser->state.cmd_params = i_strdup_until(eu->cur, mp);
	parser->cur = p;
	parser->state.poff = 0;
	return 1;
}

rpa_read_buffer(pool_t ic, const unsigned char **ul,
		const unsigned char *ic, unsigned char **lv)
{
	const unsigned char *p = *ul;
	unsigned int len;

	if (p > ic)
		return 0;

	len = *p++;
	if (p + len > ic)
		return 0;

	*lv = p_malloc(ic, len);
	memcpy(*lv, p, len);

	*ul += 1 + len;

	return len;
}

