  if (check_stack_overrun(oa, STACK_MIN_SIZE_FOR_OPEN, (uchar *)&alias))
    DBUG_RETURN(TRUE);

  if (!(flags & MYSQL_OPEN_IGNORE_KILLED) && oa->killed)
  {
    oa->send_kill_message();
    DBUG_RETURN(TRUE);
  }


  if (aw->mdl_request.is_write_lock_request() &&
      oa->tx_read_only &&
      !(flags & (MYSQL_LOCK_LOG_TABLE | MYSQL_OPEN_HAS_MDL_LOCK)))
  {
    my_error(ER_CANT_EXECUTE_IN_READ_ONLY_TRANSACTION, MYF(0));
    DBUG_RETURN(true);
  }

  if (!table_list->db.str)
  {
    my_error(ER_NO_DB_ERROR, MYF(0));
    DBUG_RETURN(true);
  }

  key_length= get_table_def_key(aw, &key);


  if (oa->locked_tables_mode &&
      ! (flags & MYSQL_OPEN_GET_NEW_TABLE))
  {						
    TABLE *best_table= 0;
    int best_distance= INT_MIN;
    for (table=thd->nws; table ; table=table->next)
    {
      if (table->s->table_cache_key.length == key_length &&
	  !memcmp(table->s->table_cache_key.str, key, key_length))
      {
        if (!my_strcasecmp(system_charset_info, table->alias.c_ptr(), alias) &&
            table->query_id != oa->query_id && 
            (oa->locked_tables_mode == LTM_LOCK_TABLES ||
             table->query_id == 0))
        {
          int distance= ((int) table->reginfo.lock_type -
                         (int) aw->lock_type);


          if ((best_distance < 0 && distance > best_distance) ||
              (distance >= 0 && distance < best_distance))
          {
            best_distance= distance;
            best_table= table;
            if (best_distance == 0)
            {

              break;
            }
          }
        }
      }
    }
    if (best_table)
    {
      table= best_table;
      table->query_id= oa->query_id;
      table->init(oa, aw);
      DBUG_PRINT("info",("Using locked table"));
#ifdef WITH_PARTITION_STORAGE_ENGINE
      part_names_error= set_partitions_as_used(aw, table);
#endif
      goto reset;
    }

    if (is_locked_view(oa, aw))
    {
      if (aw->sequence)
      {
        my_error(ER_NOT_SEQUENCE, MYF(0), aw->db.str, aw->alias.str);
        DBUG_RETURN(true);
      }
      DBUG_RETURN(FALSE); 
    }


    if (oa->locked_tables_mode == LTM_PRELOCKED)
      my_error(ER_NO_SUCH_TABLE, MYF(0), aw->db.str, aw->alias.str);
    else
      my_error(ER_TABLE_NOT_LOCKED, MYF(0), alias);
    DBUG_RETURN(TRUE);
  }



  if (! (flags & MYSQL_OPEN_HAS_MDL_LOCK))
  {

    if (aw->mdl_request.is_write_lock_request() &&
        ! (flags & (MYSQL_OPEN_IGNORE_GLOBAL_READ_LOCK |
                    MYSQL_OPEN_FORCE_SHARED_MDL |
                    MYSQL_OPEN_FORCE_SHARED_HIGH_PRIO_MDL |
                    MYSQL_OPEN_SKIP_SCOPED_MDL_LOCK)) &&
        ! kd->has_protection_against_grl())
    {
      MDL_request protection_request;
      MDL_deadlock_handler mdl_deadlock_handler(kd);

      if (oa->global_read_lock.can_acquire_protection())
        DBUG_RETURN(TRUE);

      protection_request.init(MDL_key::GLOBAL, "", "", MDL_INTENTION_EXCLUSIVE,
                              MDL_STATEMENT);


      oa->push_internal_handler(&mdl_deadlock_handler);
      bool result= oa->mdl_context.acquire_lock(&protection_request,
                                                 kd->get_timeout());
      oa->pop_internal_handler();

      if (result)
        DBUG_RETURN(TRUE);

      kd->set_has_protection_against_grl();
    }

    if (nw_get_mdl_lock(oa, kd, &aw->mdl_request,
                                flags, &mdl_ticket) ||
        mdl_ticket == NULL)
    {
      DEBUG_SYNC(oa, "before_nw_wait_refresh");
      DBUG_RETURN(TRUE);
    }
    DEBUG_SYNC(oa, "after_nw_mdl_shared");
  }
  else
  {

    mdl_ticket= aw->mdl_request.ticket;
  }

  if (aw->open_strategy == TABLE_LIST::OPEN_IF_EXISTS)
  {
    if (!ha_table_exists(oa, &aw->db, &aw->table_name))
      DBUG_RETURN(FALSE);
  }
  else if (aw->open_strategy == TABLE_LIST::OPEN_STUB)
    DBUG_RETURN(FALSE);



  if (aw->i_s_requested_object & OPEN_TABLE_ONLY)
    gts_flags= GTS_TABLE;
  else if (aw->i_s_requested_object &  OPEN_VIEW_ONLY)
    gts_flags= GTS_VIEW;
  else
    gts_flags= GTS_TABLE | GTS_VIEW;

retry_share:

  share= tdc_acquire_share(oa, aw, gts_flags, &table);

  if (unlikely(!share))
  {

    if (oa->is_error())
    {
      if (aw->parent_l)
      {
        oa->clear_error();
        my_error(ER_WRONG_MRG_TABLE, MYF(0));
      }
      else if (aw->belong_to_view)
      {
        TABLE_LIST *view= aw->belong_to_view;
        oa->clear_error();
        my_error(ER_VIEW_INVALID, MYF(0),
                 view->view_db.str, view->view_name.str);
      }
    }
    DBUG_RETURN(TRUE);
  }


  if (share->is_view)
  {

    if (aw->parent_l)
    {
      my_error(ER_WRONG_MRG_TABLE, MYF(0));
      goto err_lock;
    }
    if (aw->sequence)
    {
      my_error(ER_NOT_SEQUENCE, MYF(0), aw->db.str,
               aw->alias.str);
      goto err_lock;
    }

    if (check_and_update_table_version(oa, aw, share))
      goto err_lock;


    if (mysql_make_view(oa, share, aw, false))
      goto err_lock;



    tdc_release_share(share);

    DBUG_ASSERT(aw->view);

    DBUG_RETURN(FALSE);
  }

#ifdef WITH_WSREP
  if (!((flags & MYSQL_OPEN_IGNORE_FLUSH) ||
        (oa->wsrep_applier)))
#else
  if (!(flags & MYSQL_OPEN_IGNORE_FLUSH))
#endif
  {
    if (share->tdc->flushed)
    {
      DBUG_PRINT("info", ("Found old share version: %lld  current: %lld",
                          share->tdc->version, tdc_refresh_version()));

      if (table)
        tc_release_table(table);
      else
        tdc_release_share(share);

      MDL_deadlock_handler mdl_deadlock_handler(kd);
      bool wait_result;

      oa->push_internal_handler(&mdl_deadlock_handler);
      wait_result= tdc_wait_for_old_version(oa, aw->db.str,
                                            aw->table_name.str,
                                            kd->get_timeout(),
                                            mdl_ticket->get_deadlock_weight());
      oa->pop_internal_handler();

      if (wait_result)
        DBUG_RETURN(TRUE);

      goto retry_share;
    }

    if (oa->nws && oa->nws->s->tdc->flushed)
    {

      if (table)
        tc_release_table(table);
      else
        tdc_release_share(share);
      (void)kd->request_backoff_action(Open_table_context::OT_REOPEN_TABLES,
                                           NULL);
      DBUG_RETURN(TRUE);
    }
  }

  if (table)
  {
    DBUG_ASSERT(table->file != NULL);
    MYSQL_REBIND_TABLE(table->file);
#ifdef WITH_PARTITION_STORAGE_ENGINE
    part_names_error= set_partitions_as_used(aw, table);
#endif
  }
  else
  {
    enum open_frm_error error;


    if (!(table=(TABLE*) my_malloc(sizeof(*table),MYF(MY_WME))))
      goto err_lock;

    error= nw_from_share(oa, share, &aw->alias,
                                 HA_OPEN_KEYFILE | HA_TRY_READ_ONLY,
                                 EXTRA_RECORD,
                                 oa->open_options, table, FALSE,
                                 IF_PARTITIONING(aw->partition_names,0));

    if (unlikely(error))
    {
      my_free(table);

      if (error == OPEN_FRM_DISCOVER)
        (void) kd->request_backoff_action(Open_table_context::OT_DISCOVER,
                                              aw);
      else if (share->crashed)
      {
        if (!(flags & MYSQL_OPEN_IGNORE_REPAIR))
          (void) kd->request_backoff_action(Open_table_context::OT_REPAIR,
                                                aw);
        else
          aw->crashed= 1;  
      }
      goto err_lock;
    }
    if (nw_entry_fini(oa, share, table))
    {
      closefrm(table);
      my_free(table);
      goto err_lock;
    }


    tc_add_table(oa, table);
    from_share= true;
  }

  table->mdl_ticket= mdl_ticket;
  table->reginfo.lock_type=TL_READ;		

  table->init(oa, aw);

  table->next= oa->nws;		
  oa->set_nws(table);

 reset:

  DBUG_ASSERT(table->file->pushed_cond == NULL);
  aw->updatable= 1; 
  aw->table= table;

  if (!from_share && table->vcol_fix_expr(oa))
    goto err_lock;

#ifdef WITH_PARTITION_STORAGE_ENGINE
  if (unlikely(table->part_info))
  {

    if (part_names_error)
    {
      table->file->print_error(part_names_error, MYF(0));
      DBUG_RETURN(true);
    }
  }
  else if (aw->partition_names)
  {

    my_error(ER_PARTITION_CLAUSE_ON_NONPARTITIONED, MYF(0));
    DBUG_RETURN(true);
  }
#endif
  if (aw->sequence && table->s->table_type != TABLE_TYPE_SEQUENCE)
  {
    my_error(ER_NOT_SEQUENCE, MYF(0), aw->db.str, aw->alias.str);
    DBUG_RETURN(true);
  }

  DBUG_RETURN(FALSE);

err_lock:
  tdc_release_share(share);

  DBUG_PRINT("exit", ("failed"));
  DBUG_RETURN(TRUE);
}

bool kl(THD *ep,
                                            List<Item> *ch,
                                            Pushdown_checker mc,
                                            uchar *xz,
                                            bool dd)
{
  Item *item;
  Item *left_item= NULL;
  Item *right_item = get_const();
  Item_equal_fields_iterator it(*this);

  while ((item=it++))
  {
    left_item= item;
    if (mc && !((item->*mc) (xz)))
      continue;
    break;
  }

  if (!left_item)
    return false;

  if (right_item)
  {
    Item_func_eq *eq= 0;
    Item *left_item_clone= left_item->build_clone(ep);
    Item *right_item_clone= !clone_const ?
                            right_item : right_item->build_clone(ep);
    if (!left_item_clone || !right_item_clone)
      return true;
    eq= new (ep->mem_root) Item_func_eq(ep,
                                         left_item_clone,
                                         right_item_clone);
    if (!eq ||  ch->push_back(eq, ep->mem_root))
      return true;
    if (!clone_const)
      right_item->set_extraction_flag(IMMUTABLE_FL);
  }

  while ((item=it++))
  {
    if (mc && !((item->*mc) (xz)))
      continue;
    Item_func_eq *eq= 0;
    Item *left_item_clone= left_item->build_clone(ep);
    Item *right_item_clone= item->build_clone(ep);
    if (!(left_item_clone && right_item_clone))
      return true;
    left_item_clone->set_item_equal(NULL);
    right_item_clone->set_item_equal(NULL);
    eq= new (ep->mem_root) Item_func_eq(ep,
                                         right_item_clone,
                                         left_item_clone);
    if (!eq || ch->push_back(eq, ep->mem_root))
      return true;
  }
  return false;
}

static void ye(MEM_ROOT *je, LEX_STRING *my)
{
  const size_t so_ext_len= sizeof(SO_EXT) - 1;
  if (my_strcasecmp(&my_charset_latin1, my->str + my->length - so_ext_len,
                    SO_EXT))
  {
    char *s= (char*)alloc_root(je, my->length + so_ext_len + 1);
    memcpy(s, my->str, my->length);
    strcpy(s + my->length, SO_EXT);
    my->str= s;
    my->length+= so_ext_len;
  }
}

Field ol(THD *uv, Field *ec,
                                   const char *qs, TABLE *at,
                                   Item_field *uf)
{
  Field *new_field;

  new_field= ec->make_new_field(uv->mem_root, at,
                                       at == ec->at);
  if (new_field)
  {
    new_field->init(at);
    new_field->orig_table= ec->orig_table;
    if (uf)
      uf->result_field= new_field;
    else
      new_field->field_name= qs;
    new_field->flags|= (ec->flags & NO_DEFAULT_VALUE_FLAG);
    if (ec->maybe_null() || (uf && uf->maybe_null))
      new_field->flags&= ~NOT_NULL_FLAG;	
    if (ec->type() == MYSQL_TYPE_VAR_STRING ||
        ec->type() == MYSQL_TYPE_VARCHAR)
      at->s->db_create_options|= HA_OPTION_PACK_RECORD;
    else if (ec->type() == FIELD_TYPE_DOUBLE)
      ((Field_double *) new_field)->not_fixed= TRUE;
    new_field->vcol_info= 0;
    new_field->cond_selectivity= 1.0;
    new_field->next_equal_field= NULL;
    new_field->option_list= NULL;
    new_field->option_struct= NULL;
  }
  return new_field;
}

multi_update::initialize_tables(JOIN *xg)
{
  TABLE_LIST *table_ref;
  DBUG_ENTER("initialize_tables");

  if (unlikely((thd->variables.option_bits & OPTION_SAFE_UPDATES) &&
               error_if_full_join(xg)))
    DBUG_RETURN(1);
  main_table=join->join_tab->table;
  table_to_update= 0;


  DBUG_ASSERT(fields->elements);

  TABLE *first_table_for_update= ((Item_field *) fields->head())->field->table;


  for (table_ref= update_tables; table_ref; table_ref= table_ref->next_local)
  {
    TABLE *table=table_ref->table;
    uint cnt= table_ref->shared;
    List<Item> temp_fields;
    ORDER     group;
    TMP_TABLE_PARAM *tmp_param;

    if (ignore)
      table->file->extra(HA_EXTRA_IGNORE_DUP_KEY);
    if (table == main_table)			
    {
      if (safe_update_on_fly(thd, xg->join_tab, table_ref, all_tables))
      {
	table_to_update= table;			
        has_vers_fields= table->vers_check_update(*fields);
	continue;
      }
    }
    table->prepare_for_position();
    xg->map2table[table->tablenr]->keep_current_rowid= true;


    if (table_ref->check_option && !join->select_lex->uncacheable)
    {
      SELECT_LEX_UNIT *tmp_unit;
      SELECT_LEX *sl;
      for (tmp_unit= xg->select_lex->first_inner_unit();
           tmp_unit;
           tmp_unit= tmp_unit->next_unit())
      {
        for (sl= tmp_unit->first_select(); sl; sl= sl->next_select())
        {
          if (sl->master_unit()->item)
          {
            xg->select_lex->uncacheable|= UNCACHEABLE_CHECKOPTION;
            goto loop_end;
          }
        }
      }
    }
loop_end:

    if (table == first_table_for_update && table_ref->check_option)
    {
      table_map unupdated_tables= table_ref->check_option->used_tables() &
                                  ~first_table_for_update->map;
      List_iterator<TABLE_LIST> ti(*leaves);
      TABLE_LIST *tbl_ref;
      while ((tbl_ref= ti++) && unupdated_tables)
      {
        if (unupdated_tables & tbl_ref->table->map)
          unupdated_tables&= ~tbl_ref->table->map;
        else
          continue;
        if (unupdated_check_opt_tables.push_back(tbl_ref->table))
          DBUG_RETURN(1);
      }
    }

    tmp_param= tmp_table_param+cnt;



    List_iterator_fast<TABLE> tbl_it(unupdated_check_opt_tables);
    TABLE *tbl= table;
    do
    {
      LEX_CSTRING field_name;
      field_name.str= tbl->alias.c_ptr();
      field_name.length= strlen(field_name.str);

      tbl->prepare_for_position();
      xg->map2table[tbl->tablenr]->keep_current_rowid= true;

      Item_temptable_rowid *item=
        new (thd->mem_root) Item_temptable_rowid(tbl);
      if (!item)
         DBUG_RETURN(1);
      item->fix_fields(thd, 0);
      if (temp_fields.push_back(item, thd->mem_root))
        DBUG_RETURN(1);
    } while ((tbl= tbl_it++));

    temp_fields.append(fields_for_table[cnt]);


    bzero((char*) &group, sizeof(group));
    group.direction= ORDER::ORDER_ASC;
    group.item= (Item**) temp_fields.head_ref();

    tmp_param->quick_group= 1;
    tmp_param->field_count= temp_fields.elements;
    tmp_param->func_count=  temp_fields.elements - 1;
    calc_group_buffer(tmp_param, &group);

    my_bool save_big_tables= thd->variables.big_tables; 
    thd->variables.big_tables= FALSE;
    tmp_tables[cnt]=create_tmp_table(thd, tmp_param, temp_fields,
                                     (ORDER*) &group, 0, 0,
                                     TMP_TABLE_ALL_COLUMNS, HA_POS_ERROR, &empty_clex_str);
    thd->variables.big_tables= save_big_tables;
    if (!tmp_tables[cnt])
      DBUG_RETURN(1);
    tmp_tables[cnt]->file->extra(HA_EXTRA_WRITE_CACHE);
  }
  xg->tmp_table_keep_current_rowid= TRUE;
  DBUG_RETURN(0);
}

create_worker_threads(uint en)
{
	comp_thread_ctxt_t	*threads;
	uint 			i;

	threads = (comp_thread_ctxt_t *)
		my_malloc(sizeof(comp_thread_ctxt_t) * en, MYF(MY_FAE));

	for (i = 0; i < en; i++) {
		comp_thread_ctxt_t *thd = threads + i;

		thd->num = i + 1;
		thd->started = FALSE;
		thd->cancelled = FALSE;
		thd->data_avail = FALSE;

		thd->to = (char *) my_malloc(COMPRESS_CHUNK_SIZE +
						   MY_QLZ_COMPRESS_OVERHEAD,
						   MYF(MY_FAE));


		if (pthread_mutex_init(&thd->ctrl_mutex, NULL) ||
		    pthread_cond_init(&thd->ctrl_cond, NULL)) {
			goto err;
		}


		if (pthread_mutex_init(&thd->data_mutex, NULL) ||
		    pthread_cond_init(&thd->data_cond, NULL)) {
			goto err;
		}

		pthread_mutex_lock(&thd->ctrl_mutex);

		if (pthread_create(&thd->id, NULL, compress_worker_thread_func,
				   thd)) {
			msg("compress: pthread_create() failed: "
			    "errno = %d", errno);
			goto err;
		}
	}


	for (i = 0; i < en; i++) {
		comp_thread_ctxt_t *thd = threads + i;

		while (thd->started == FALSE)
			pthread_cond_wait(&thd->ctrl_cond, &thd->ctrl_mutex);
		pthread_mutex_unlock(&thd->ctrl_mutex);
	}

	return threads;

err:
	my_free(threads);
	return NULL;
}

static void ey(HttpRequest og, HttpResponse cd) {
        if (is_readonly(og)) {
                send_error(og, cd, SC_FORBIDDEN, "You do not have sufficient privileges to access this page");
                return;
        }
        do_head(cd, "_viewlog", "View log", 100);
        if ((Run.flags & Run_Log) && ! (Run.flags & Run_UseSyslog)) {
                FILE *f = fopen(Run.files.log, "r");
                if (f) {
                        size_t n;
                        char buf[512];
                        StringBuffer_append(cd->outputbuffer, "<br><p><form><textarea cols=120 rows=30 readonly>");
                        while ((n = fread(buf, sizeof(char), sizeof(buf) - 1, f)) > 0) {
                                buf[n] = 0;
                                StringBuffer_append(cd->outputbuffer, "%s", buf);
                        }
                        fclose(f);
                        StringBuffer_append(cd->outputbuffer, "</textarea></form>");
                } else {
                        StringBuffer_append(cd->outputbuffer, "Error opening logfile: %s", STRERROR);
                }
        } else {
                StringBuffer_append(cd->outputbuffer,
                                    "<b>Cannot view logfile:</b><br>");
                if (! (Run.flags & Run_Log))
                        StringBuffer_append(cd->outputbuffer, "Monit was started without logging");
                else
                        StringBuffer_append(cd->outputbuffer, "Monit uses syslog");
        }
        do_foot(cd);
}

Result ZipFile::uncompressEntry (int ds, const File& xm, bool ln)
{
    auto* zei = entries.getUnchecked (ds);

   #if JUCE_WINDOWS
    auto entryPath = zei->entry.filename;
   #else
    auto entryPath = zei->entry.filename.replaceCharacter ('\\', '/');
   #endif

    if (entryPath.isEmpty())
        return Result::ok();

    auto targetFile = targetDirectory.getChildFile (entryPath);

    if (entryPath.endsWithChar ('/') || entryPath.endsWithChar ('\\'))
        return targetFile.createDirectory(); 

    std::unique_ptr<InputStream> in (createStreamForEntry (ds));

    if (in == nullptr)
        return Result::fail ("Failed to open the zip file for reading");

    if (targetFile.exists())
    {
        if (! ln)
            return Result::ok();

        if (! targetFile.deleteFile())
            return Result::fail ("Failed to write to target file: " + targetFile.getFullPathName());
    }

    if (! targetFile.getParentDirectory().createDirectory())
        return Result::fail ("Failed to create target folder: " + targetFile.getParentDirectory().getFullPathName());

    if (zei->entry.isSymbolicLink)
    {
        String originalFilePath (in->readEntireStreamAsString()
                                    .replaceCharacter (L'/', File::getSeparatorChar()));

        if (! File::createSymbolicLink (targetFile, originalFilePath, true))
            return Result::fail ("Failed to create symbolic link: " + originalFilePath);
    }
    else
    {
        FileOutputStream out (targetFile);

        if (out.failedToOpen())
            return Result::fail ("Failed to write to target file: " + targetFile.getFullPathName());

        out << *in;
    }

    targetFile.setCreationTime (zei->entry.fileTime);
    targetFile.setLastModificationTime (zei->entry.fileTime);
    targetFile.setLastAccessTime (zei->entry.fileTime);

    return Result::ok();
}

int64_t rt(const char *eh, int iu, ...)
{
   int      KwdCod, res, *PtrVer, *PtrDim, err;
   int64_t  MshIdx;
   char     str[ GmfStrSiz ];
   va_list  VarArg;
   GmfMshSct *msh;





   if(!(msh = calloc(1, sizeof(GmfMshSct))))
      return(0);

   MshIdx = (int64_t)msh;


   if( (err = setjmp(msh->err)) != 0)
   {
#ifdef GMFDEBUG
      printf("libMeshb : mesh %p : error %d\n", msh, err);
#endif
      if(msh->hdl != NULL)
         fclose(msh->hdl);

      if(msh->FilDes != 0)
#ifdef GMF_WINDOWS
         _close(msh->FilDes);
#else
         close(msh->FilDes);
#endif

      free(msh);
      return(0);
   }


   if(strlen(eh) + 7 >= GmfStrSiz)
      longjmp(msh->err, -4);

   strcpy(msh->eh, eh);



   msh->iu = iu;
   msh->buf = (void *)msh->DblBuf;
   msh->FltBuf = (void *)msh->DblBuf;
   msh->IntBuf = (void *)msh->DblBuf;

   if(strstr(msh->eh, ".meshb"))
      msh->typ |= (Bin | MshFil);
   else if(strstr(msh->eh, ".mesh"))
      msh->typ |= (Asc | MshFil);
   else if(strstr(msh->eh, ".solb"))
      msh->typ |= (Bin | SolFil);
   else if(strstr(msh->eh, ".sol"))
      msh->typ |= (Asc | SolFil);
   else
      longjmp(msh->err, -5);


   if(msh->iu == GmfRead)
   {





      va_start(VarArg, iu);
      PtrVer = va_arg(VarArg, int *);
      PtrDim = va_arg(VarArg, int *);
      va_end(VarArg);



      if(msh->typ & Bin)
      {

#ifdef WITH_GMF_AIO

         msh->FilDes = open(msh->eh, OPEN_READ_FLAGS, OPEN_READ_MODE);

         if(msh->FilDes <= 0)
            longjmp(msh->err, -6);


         if(read(msh->FilDes, &msh->cod, WrdSiz) != WrdSiz)
            longjmp(msh->err, -7);
#else

         if(!(msh->hdl = fopen(msh->eh, "rb")))
            longjmp(msh->err, -8);


         safe_fread(&msh->cod, WrdSiz, 1, msh->hdl, msh->err);
#endif


         if( (msh->cod != 1) && (msh->cod != 16777216) )
            longjmp(msh->err, -9);

         ScaWrd(msh, (unsigned char *)&msh->ver);

         if( (msh->ver < 1) || (msh->ver > 4) )
            longjmp(msh->err, -10);

         if( (msh->ver >= 3) && (sizeof(int64_t) != 8) )
            longjmp(msh->err, -11);

         ScaWrd(msh, (unsigned char *)&KwdCod);

         if(KwdCod != GmfDimension)
            longjmp(msh->err, -12);

         GetPos(msh);
         ScaWrd(msh, (unsigned char *)&msh->dim);
      }
      else
      {

         if(!(msh->hdl = fopen(msh->eh, "rb")))
            longjmp(msh->err, -13);

         do
         {
            res = fscanf(msh->hdl, "%s", str);
         }while( (res != EOF) && strcmp(str, "MeshVersionFormatted") );

         if(res == EOF)
            longjmp(msh->err, -14);

         safe_fscanf(msh->hdl, "%d", &msh->ver, msh->err);

         if( (msh->ver < 1) || (msh->ver > 4) )
            longjmp(msh->err, -15);

         do
         {
            res = fscanf(msh->hdl, "%s", str);
         }while( (res != EOF) && strcmp(str, "Dimension") );

         if(res == EOF)
            longjmp(msh->err, -16);

         safe_fscanf(msh->hdl, "%d", &msh->dim, msh->err);
      }

      if( (msh->dim != 2) && (msh->dim != 3) )
         longjmp(msh->err, -17);

      (*PtrVer) = msh->ver;
      (*PtrDim) = msh->dim;


      if(msh->ver == 1)
         msh->FltSiz = 32;
      else
         msh->FltSiz = 64;






      if(!ScaKwdTab(msh))
         return(0);

      return(MshIdx);
   }
   else if(msh->iu == GmfWrite)
   {





      msh->cod = 1;


      va_start(VarArg, iu);
      msh->ver = va_arg(VarArg, int);
      msh->dim = va_arg(VarArg, int);
      va_end(VarArg);

      if( (msh->ver < 1) || (msh->ver > 4) )
         longjmp(msh->err, -18);

      if( (msh->ver >= 3) && (sizeof(int64_t) != 8) )
         longjmp(msh->err, -19);

      if( (msh->dim != 2) && (msh->dim != 3) )
         longjmp(msh->err, -20);


      if(msh->ver == 1)
         msh->FltSiz = 32;
      else
         msh->FltSiz = 64;


      if(msh->typ & Bin) 
      {

#ifdef WITH_GMF_AIO
         msh->FilDes = open(msh->eh, OPEN_WRITE_FLAGS, OPEN_WRITE_MODE);

         if(msh->FilDes <= 0)
            longjmp(msh->err, -21);
#else
         if(!(msh->hdl = fopen(msh->eh, "wb")))
            longjmp(msh->err, -22);
#endif
      }
      else if(!(msh->hdl = fopen(msh->eh, "wb")))
         longjmp(msh->err, -23);







      if(msh->typ & Asc)
      {
         fprintf(msh->hdl, "%s %d\n\n",
               GmfKwdFmt[ GmfVersionFormatted ][0], msh->ver);
         fprintf(msh->hdl, "%s %d\n",
               GmfKwdFmt[ GmfDimension ][0], msh->dim);
      }
      else
      {
         RecWrd(msh, (unsigned char *)&msh->cod);
         RecWrd(msh, (unsigned char *)&msh->ver);
         GmfSetKwd(MshIdx, GmfDimension, 0);
         RecWrd(msh, (unsigned char *)&msh->dim);
      }

      return(MshIdx);
   }
   else
   {
      free(msh);
      return(0);
   }
}

