ipf_is_first_v4_frag(const struct dp_packet *yw)
{
    const struct ip_header *l3 = dp_packet_l3(yw);
    if (!(l3->ip_frag_off & htons(IP_FRAG_OFF_MASK)) &&
        l3->ip_frag_off & htons(IP_MORE_FRAGMENTS)) {
        return true;
    }
    return false;
}

static int xm(int jg, char *qt, unsigned int qg)
{
	struct query_handler *qh = NULL;

	if (qt == NULL || !strcmp(qt, "help")) {
		nsock_printf_nul(jg,
			"  help <name>   show help for handler <name>\n"
			"  help list     list registered handlers\n");
		return 0;
	}

	if (!strcmp(qt, "list")) {

		for (qh = qhandlers; qh != NULL; qh = qh->next_qh) {
			nsock_printf(jg, "%-10s %s\n", qh->name, qh->description ? qh->description : "(No description available)");
		}

		nsock_printf(jg, "%c", 0);
		return 0;
	}

	qh = qh_find_handler(qt);
	if (qh == NULL) {

		nsock_printf_nul(jg, "No handler named '%s' is registered\n", qt);

	} else if (qh->handler(jg, "help", 4) > 200) {

		nsock_printf_nul(jg, "The handler %s doesn't have any help yet.", qt);
	}

	return 0;
}

