unsigned ic(krb5_enctype pb, unsigned char *ew)
	{
	int 		i, conlen;
	size_t		cklen;
	static size_t 	*cksumlens = NULL;
	unsigned char	*test_auth;

	conlen = (pb)? 8: 0;

	if (!cksumlens  &&  !(cksumlens = populate_cksumlens()))  return NULL;
	for (i=0; (cklen = cksumlens[i]) != 0; i++)
		{
		test_auth = ew + conlen + cklen;
		if (kssl_test_confound(test_auth))  return test_auth;
		}

	return NULL;
	}

kssl_ctx_setprinc(KSSL_CTX *bh, int qn,
        krb5_data *wl, krb5_data *ox, int cs)
        {
	char	**princ;
	int 	length;
	int i;

	if (bh == NULL  ||  ox == NULL)  return KSSL_CTX_ERR;

	switch (qn)
                {
        case KSSL_CLIENT:	princ = &bh->client_princ;	break;
        case KSSL_SERVER:	princ = &bh->service_host;	break;
        default:		return KSSL_CTX_ERR;			break;
		}
	if (*princ)  kssl_free(*princ);


	length = 0;
	for (i=0; i < cs; i++)
		{
		length += ox[i].length;
		}

	length += cs-1;

	length += ((wl)? wl->length + 2: 1);

	if ((*princ = kssl_calloc(1, length)) == NULL)
		return KSSL_CTX_ERR;
	else
		{
		for (i = 0; i < cs; i++)
			{
			strncat(*princ, ox[i].data, ox[i].length);
			if (i < cs-1)
				{
				strcat (*princ, "/");
				}
			}
		if (wl)
                        {
			strcat (*princ, "@");
			(void) strncat(*princ, wl->data, wl->length);
			}
		}

	return KSSL_CTX_OK;
        }

