_gcry_ecc_ecdsa_verify (gcry_mpi_t ss, ECC_public_key *bn,
                        gcry_mpi_t ve, gcry_mpi_t hj)
{
  gpg_err_code_t err = 0;
  gcry_mpi_t hash, h, h1, h2, x;
  mpi_point_struct Q, Q1, Q2;
  mpi_ec_t ctx;
  unsigned int nbits;

  if( !(mpi_cmp_ui (ve, 0) > 0 && mpi_cmp (ve, bn->E.n) < 0) )
    return GPG_ERR_BAD_SIGNATURE; 
  if( !(mpi_cmp_ui (hj, 0) > 0 && mpi_cmp (hj, bn->E.n) < 0) )
    return GPG_ERR_BAD_SIGNATURE; 

  nbits = mpi_get_nbits (bn->E.n);
  err = _gcry_dsa_normalize_hash (ss, &hash, nbits);
  if (err)
    return err;

  h  = mpi_alloc (0);
  h1 = mpi_alloc (0);
  h2 = mpi_alloc (0);
  x = mpi_alloc (0);
  point_init (&Q);
  point_init (&Q1);
  point_init (&Q2);

  ctx = _gcry_mpi_ec_p_internal_new (bn->E.model, bn->E.dialect, 0,
                                     bn->E.p, bn->E.a, bn->E.b);


  mpi_invm (h, hj, bn->E.n);

  mpi_mulm (h1, hash, h, bn->E.n);

  _gcry_mpi_ec_mul_point (&Q1, h1, &bn->E.G, ctx);

  mpi_mulm (h2, ve, h, bn->E.n);

  _gcry_mpi_ec_mul_point (&Q2, h2, &bn->Q, ctx);

  _gcry_mpi_ec_add_points (&Q, &Q1, &Q2, ctx);

  if (!mpi_cmp_ui (Q.z, 0))
    {
      if (DBG_CIPHER)
          log_debug ("ecc verify: Rejected\n");
      err = GPG_ERR_BAD_SIGNATURE;
      goto leave;
    }
  if (_gcry_mpi_ec_get_affine (x, NULL, &Q, ctx))
    {
      if (DBG_CIPHER)
        log_debug ("ecc verify: Failed to get affine coordinates\n");
      err = GPG_ERR_BAD_SIGNATURE;
      goto leave;
    }
  mpi_mod (x, x, bn->E.n); 
  if (mpi_cmp (x, ve))   
    {
      if (DBG_CIPHER)
        {
          log_mpidump ("     x", x);
          log_mpidump ("     r", ve);
          log_mpidump ("     s", hj);
        }
      err = GPG_ERR_BAD_SIGNATURE;
      goto leave;
    }

 leave:
  _gcry_mpi_ec_free (ctx);
  point_free (&Q2);
  point_free (&Q1);
  point_free (&Q);
  mpi_free (x);
  mpi_free (h2);
  mpi_free (h1);
  mpi_free (h);
  if (hash != ss)
    mpi_free (hash);

  return err;
}

