void eg(TABLE_LIST *ed,
                                   const char *ab,
                                   TABLE_LIST *yh)
{
  update= ed->top_table();
  duplicate= yh->top_table();
  if (!update->view || !duplicate->view ||
      ed->view == yh->view ||
      ed->view_name.length != yh->view_name.length ||
      ed->view_db.length != yh->view_db.length ||
      my_strcasecmp(table_alias_charset,
                    ed->view_name.str, yh->view_name.str) != 0 ||
      my_strcasecmp(table_alias_charset,
                    ed->view_db.str, yh->view_db.str) != 0)
  {

    if (ed->view)
    {

      if (ed->view == yh->view)
        my_error(!strncmp(ab, "INSERT", 6) ?
                 ER_NON_INSERTABLE_TABLE : ER_NON_UPDATABLE_TABLE, MYF(0),
                 ed->alias, ab);
      else
        my_error(ER_VIEW_PREVENT_UPDATE, MYF(0),
                 (yh->view ? yh->alias : ed->alias),
                 ab, ed->alias);
      return;
    }
    if (yh->view)
    {
      my_error(ER_VIEW_PREVENT_UPDATE, MYF(0), yh->alias, ab,
               ed->alias);
      return;
    }
  }
  my_error(ER_UPDATE_TABLE_USED, MYF(0), ed->alias, ab);
}

