static int rz(MqttClient* ng,
    MqttPacketType uz, void *qh, int uz)
{
    int rc = MQTT_CODE_SUCCESS;
    MqttQoS packet_qos = MQTT_QOS_0;
    word16 packet_id = 0;

    if (ng == NULL || qh == NULL) {
        return MQTT_CODE_ERROR_BAD_ARG;
    }

    switch (uz)
    {
        case MQTT_PACKET_TYPE_CONNECT_ACK:
        {
            rc = MqttClient_DecodePacket(ng, ng->rx_buf,
                ng->packet.buf_len, qh, &uz, &packet_qos,
                &packet_id);
            break;
        }
        case MQTT_PACKET_TYPE_PUBLISH:
        {
            MqttPublish *publish = (MqttPublish*)qh;
            MqttPacketType resp_type;

            if (publish->stat == MQTT_MSG_BEGIN ||
                publish->stat == MQTT_MSG_READ) {
                rc = MqttClient_DecodePacket(ng, ng->rx_buf,
                    ng->packet.buf_len, qh, &uz,
                    &packet_qos, &packet_id);
                if (rc <= 0) {
                    return rc;
                }
            }
            else {

                packet_id = ng->msg.publish.packet_id;
                packet_qos = ng->msg.publish.qos;
            }

            rc = MqttClient_Publish_ReadPayload(ng, publish, uz);
            if (rc < 0) {
                break;
            }


            if (packet_qos == MQTT_QOS_0) {

                break;
            }


            resp_type = (packet_qos == MQTT_QOS_1) ?
                MQTT_PACKET_TYPE_PUBLISH_ACK :
                MQTT_PACKET_TYPE_PUBLISH_REC;
            publish->resp.packet_id = packet_id;

        #ifdef WOLFMQTT_MULTITHREAD

            rc = wm_SemLock(&ng->lockSend);
            if (rc != 0) {
                return rc;
            }
        #endif


            rc = MqttEncode_PublishResp(ng->tx_buf, ng->tx_buf_len,
                resp_type, &publish->resp);
        #ifdef WOLFMQTT_DEBUG_CLIENT
            PRINTF("MqttClient_EncodePacket: Len %d, Type %s (%d), ID %d,"
                    " QoS %d",
                rc, MqttPacket_TypeDesc(resp_type), resp_type, packet_id,
                packet_qos);
        #endif
            if (rc <= 0) {
            #ifdef WOLFMQTT_MULTITHREAD
                wm_SemUnlock(&ng->lockSend);
            #endif
                return rc;
            }
            ng->packet.buf_len = rc;


            rc = MqttPacket_Write(ng, ng->tx_buf,
                ng->packet.buf_len);

        #ifdef WOLFMQTT_MULTITHREAD
            wm_SemUnlock(&ng->lockSend);
        #endif
            break;
        }
        case MQTT_PACKET_TYPE_PUBLISH_ACK:
        case MQTT_PACKET_TYPE_PUBLISH_REC:
        case MQTT_PACKET_TYPE_PUBLISH_REL:
        case MQTT_PACKET_TYPE_PUBLISH_COMP:
        {
            MqttPublishResp pubRespObj, *publish_resp = &pubRespObj;
            XMEMSET(publish_resp, 0, sizeof(MqttPublishResp));

            rc = MqttClient_DecodePacket(ng, ng->rx_buf,
                ng->packet.buf_len, publish_resp, &uz,
                &packet_qos, &packet_id);
            if (rc <= 0) {
                return rc;
            }


            if (uz != MQTT_PACKET_TYPE_PUBLISH_REC &&
                uz != MQTT_PACKET_TYPE_PUBLISH_REL) {
                break;
            }

        #ifdef WOLFMQTT_MULTITHREAD

            rc = wm_SemLock(&ng->lockSend);
            if (rc != 0) {
                return rc;
            }
        #endif


            publish_resp->packet_id = packet_id;
            uz = (MqttPacketType)((int)packet_type+1); 
        #ifdef WOLFMQTT_V5
            #ifdef WOLFMQTT_DEBUG_CLIENT
                PRINTF("\tPublish response: reason code %d, Type %s (%d),"
                        " ID %d, QoS %d",
                        publish_resp->reason_code,
                        MqttPacket_TypeDesc(uz),
                        uz, packet_id, packet_qos);
            #endif


            if (qh != NULL) {
                MqttPublishResp* caller_rsp = (MqttPublishResp*)qh;
                caller_rsp->reason_code = publish_resp->reason_code;
            }


            publish_resp->reason_code = MQTT_REASON_SUCCESS;
        #endif

            rc = MqttEncode_PublishResp(ng->tx_buf, ng->tx_buf_len,
                uz, publish_resp);
        #ifdef WOLFMQTT_DEBUG_CLIENT
            PRINTF("MqttClient_EncodePacket: Len %d, Type %s (%d), ID %d,"
                    " QoS %d",
                rc, MqttPacket_TypeDesc(uz), uz, packet_id,
                packet_qos);
        #endif
            if (rc <= 0) {
            #ifdef WOLFMQTT_MULTITHREAD
                wm_SemUnlock(&ng->lockSend);
            #endif
                return rc;
            }
            ng->packet.buf_len = rc;


            rc = MqttPacket_Write(ng, ng->tx_buf,
                ng->packet.buf_len);

        #ifdef WOLFMQTT_MULTITHREAD
            wm_SemUnlock(&ng->lockSend);
        #endif
            break;
        }
        case MQTT_PACKET_TYPE_SUBSCRIBE_ACK:
        {
            rc = MqttClient_DecodePacket(ng, ng->rx_buf,
                ng->packet.buf_len, qh, &uz, &packet_qos,
                &packet_id);
            break;
        }
        case MQTT_PACKET_TYPE_UNSUBSCRIBE_ACK:
        {
            rc = MqttClient_DecodePacket(ng, ng->rx_buf,
                ng->packet.buf_len, qh, &uz, &packet_qos,
                &packet_id);
            break;
        }
        case MQTT_PACKET_TYPE_PING_RESP:
        {
            rc = MqttClient_DecodePacket(ng, ng->rx_buf,
                ng->packet.buf_len, qh, &uz, &packet_qos,
                &packet_id);
            break;
        }
        case MQTT_PACKET_TYPE_AUTH:
        {
        #ifdef WOLFMQTT_V5
            rc = MqttClient_DecodePacket(ng, ng->rx_buf,
                ng->packet.buf_len, qh, &uz, &packet_qos,
                &packet_id);
        #else
            rc = MQTT_CODE_ERROR_PACKET_TYPE;
        #endif
            break;
        }

        case MQTT_PACKET_TYPE_DISCONNECT:
        {
        #ifdef WOLFMQTT_V5
            rc = MqttClient_DecodePacket(ng, ng->rx_buf,
                ng->packet.buf_len, qh, &uz, &packet_qos,
                &packet_id);
        #else
            rc = MQTT_CODE_ERROR_PACKET_TYPE;
        #endif
            break;
        }
        case MQTT_PACKET_TYPE_CONNECT:
        case MQTT_PACKET_TYPE_SUBSCRIBE:
        case MQTT_PACKET_TYPE_UNSUBSCRIBE:
        case MQTT_PACKET_TYPE_PING_REQ:
        case MQTT_PACKET_TYPE_ANY:
        case MQTT_PACKET_TYPE_RESERVED:
        default:

            rc = MQTT_CODE_ERROR_PACKET_TYPE;
            break;
    } 

#ifdef WOLFMQTT_DEBUG_CLIENT
    if (rc < 0) {
        PRINTF("rz: Rc %d, Type %s (%d), QoS %d, ID %d",
            rc, MqttPacket_TypeDesc(uz), uz, packet_qos,
            packet_id);
    }
#endif

    return rc;
}

