pcx256_print_page(gx_device_printer * pl, gp_file * sq)
{
    pcx_header header;
    int code;

    header = pcx_header_prototype;
    header.version = version_3_0;
    header.bpp = 8;
    header.nplanes = 1;
    assign_ushort(header.palinfo,
                  (pl->color_info.num_components > 1 ?
                   palinfo_color : palinfo_gray));
    code = pcx_write_page(pl, sq, &header, false);
    if (code >= 0) {		
        gp_fputc(0x0c, sq);
        code = pc_write_palette((gx_device *) pl, 256, sq);
    }
    return code;
}

pcx_write_page(gx_device_printer * if, gp_file * ak, pcx_header * th,
               bool az)
{
    int raster = gdev_prn_raster(if);
    uint rsize = ROUND_UP((if->width * th->bpp + 7) >> 3, 2);	
    int height = if->height;
    int depth = if->color_info.depth;
    uint lsize = raster + rsize;
    byte *line = gs_alloc_bytes(if->memory, lsize, "pcx ak buffer");
    byte *plane = line + raster;
    int y;
    int code = 0;		

    if (line == 0)		
        return_error(gs_error_VMerror);



    assign_ushort(th->x2, if->width - 1);
    assign_ushort(th->y2, height - 1);
    assign_ushort(th->hres, (int)if->x_pixels_per_inch);
    assign_ushort(th->vres, (int)if->y_pixels_per_inch);
    assign_ushort(th->bpl, (az || depth == 1 ? rsize :
                              raster + (raster & 1)));



    if (gp_fwrite((const char *)th, 1, 128, ak) < 128) {
        code = gs_error_ioerror;
        goto pcx_done;
    }

    for (y = 0; y < height; y++) {
        byte *row;
        byte *end;

        code = gdev_prn_get_bits(if, y, line, &row);
        if (code < 0)
            break;
        end = row + raster;
        if (!planar) {		
            if (raster & 1) {	
                *end = end[-1];
                ++end;
            }
            pcx_write_rle(row, end, 1, ak);
        } else
            switch (depth) {

                case 4:
                    {
                        byte *pend = plane + rsize;
                        int shift;

                        for (shift = 0; shift < 4; shift++) {
                            register byte *from, *to;
                            register int bright = 1 << shift;
                            register int bleft = bright << 4;

                            for (from = row, to = plane;
                                 from < end; from += 4
                                ) {
                                *to++ =
                                    (from[0] & bleft ? 0x80 : 0) |
                                    (from[0] & bright ? 0x40 : 0) |
                                    (from[1] & bleft ? 0x20 : 0) |
                                    (from[1] & bright ? 0x10 : 0) |
                                    (from[2] & bleft ? 0x08 : 0) |
                                    (from[2] & bright ? 0x04 : 0) |
                                    (from[3] & bleft ? 0x02 : 0) |
                                    (from[3] & bright ? 0x01 : 0);
                            }

                            if (to < pend)
                                *to = to[-1];
                            pcx_write_rle(plane, pend, 1, ak);
                        }
                    }
                    break;

                case 24:
                    {
                        int pnum;

                        for (pnum = 0; pnum < 3; ++pnum) {
                            pcx_write_rle(row + pnum, row + raster, 3, ak);
                            if (if->width & 1)
                                gp_fputc(0, ak);		
                        }
                    }
                    break;

                default:
                    code = gs_note_error(gs_error_rangecheck);
                    goto pcx_done;

            }
    }

  pcx_done:
    gs_free_object(if->memory, line, "pcx ak buffer");

    return code;
}

pcx_write_rle(const byte * bz, const byte * pq, int ly, gp_file * sh)
{				
#define MAX_RUN_COUNT 15
    int max_run = ly * MAX_RUN_COUNT;

    while (bz < pq) {
        byte data = *bz;

        bz += ly;
        if (bz >= pq || data != *bz) {
            if (data >= 0xc0)
                gp_fputc(0xc1, sh);
        } else {
            const byte *start = bz;

            while ((bz < pq) && (*bz == data))
                bz += ly;

            while (bz - start >= max_run) {
                gp_fputc(0xc0 + MAX_RUN_COUNT, sh);
                gp_fputc(data, sh);
                start += max_run;
            }
            if (bz > start || data >= 0xc0)
                gp_fputc((bz - start) / ly + 0xc1, sh);
        }
        gp_fputc(data, sh);
    }
#undef MAX_RUN_COUNT
}

pcx16_print_page(gx_device_printer * hv, gp_file * hi)
{
