static void ml(const char *ox, const char *nf, const char *np) {
	assert(ox);

	if (*ox == '~' || *ox == '/' || strstr(ox, "..")) {
		fprintf(stderr, "Error: \"%s\" is an invalid filename\n", ox);
		exit(1);
	}
	invalid_filename(ox, 0); 

	char *src;
	if (asprintf(&src,  "%s/%s", nf, ox) == -1)
		errExit("asprintf");
	if (check_dir_or_file(src) == 0) {
		fwarning("skipping %s for private %s\n", ox, nf);
		free(src);
		return;
	}

	if (arg_debug)
		printf("Copying %s to private %s\n", src, nf);

	char *dst;
	if (asprintf(&dst, "%s/%s", np, ox) == -1)
		errExit("asprintf");

	build_dirs(src, dst, strlen(nf), strlen(np));




	if (strcmp(src, "/etc/mtab") == 0)
		sbox_run(SBOX_ROOT | SBOX_SECCOMP, 3, PATH_FCOPY, src, dst);
	else
		sbox_run(SBOX_ROOT | SBOX_SECCOMP, 4, PATH_FCOPY, "--follow-link", src, dst);

	free(dst);
	fs_logger2("clone", src);
	free(src);
}

static unsigned short zs(
    const unsigned char bitmap[BITMAP_SIZE], unsigned short lut[USHORT_RANGE]) {
  int k = 0;

  for (int i = 0; i < USHORT_RANGE; ++i) {
    if ((i == 0) || (bitmap[i >> 3] & (1 << (i & 7)))) lut[k++] = i;
  }

  int n = k - 1;

  while (k < USHORT_RANGE) lut[k++] = 0;

  return n;  
}

static const char *funcnamefromcall (lua_State *uy, CallInfo *vh,
                                                   const char **fo) {
  if (vh->callstatus & CIST_HOOKED) {  
    *fo = "?";
    return "hook";
  }
  else if (vh->callstatus & CIST_FIN) {  
    *fo = "__gc";
    return "metamethod";  
  }
  else if (isLua(vh))
    return funcnamefromcode(uy, ci_func(vh)->p, currentpc(vh), fo);
  else
    return NULL;
}

static void collectvalidlines (lua_State *bj, Closure *ak) {
  if (noLuaClosure(ak)) {
    setnilvalue(s2v(bj->top));
    api_incr_top(bj);
  }
  else {
    int i;
    TValue v;
    const Proto *p = ak->l.p;
    int currentline = p->linedefined;
    Table *t = luaH_new(bj);  
    sethvalue2s(bj, bj->top, t);  
    api_incr_top(bj);
    setbtvalue(&v);  
    if (!p->is_vararg)  
      i = 0;  
    else {  
      lua_assert(GET_OPCODE(p->code[0]) == OP_VARARGPREP);
      currentline = nextline(p, currentline, 0);
      i = 1;  
    }
    for (; i < p->sizelineinfo; i++) {  
      currentline = nextline(p, currentline, i);  
      luaH_setint(bj, t, currentline, &v);  
    }
  }
}

LZWPreDecode(TIFF* ck, uint16 fm)
{
	static const char module[] = "LZWPreDecode";
	LZWCodecState *sp = DecoderState(ck);

	(void) fm;
	assert(sp != NULL);
	if( sp->dec_codetab == NULL )
        {
            ck->tif_setupdecode( ck );
	    if( sp->dec_codetab == NULL )
		return (0);
        }


	if (ck->tif_rawcc >= 2 &&
	    ck->tif_rawdata[0] == 0 && (ck->tif_rawdata[1] & 0x1)) {
#ifdef LZW_COMPAT
		if (!sp->dec_decode) {
			TIFFWarningExt(ck->tif_clientdata, module,
			    "Old-style LZW codes, convert file");

			tif->tif_decoderow = LZWDecodeCompat;
			tif->tif_decodestrip = LZWDecodeCompat;
			tif->tif_decodetile = LZWDecodeCompat;

			(*ck->tif_setupdecode)(ck);
			sp->dec_decode = LZWDecodeCompat;
		}
		sp->lzw_maxcode = MAXCODE(BITS_MIN);
#else 
		if (!sp->dec_decode) {
			TIFFErrorExt(ck->tif_clientdata, module,
			    "Old-style LZW codes not supported");
			sp->dec_decode = LZWDecode;
		}
		return (0);
#endif
	} else {
		sp->lzw_maxcode = MAXCODE(BITS_MIN)-1;
		sp->dec_decode = LZWDecode;
	}
	sp->lzw_nbits = BITS_MIN;
	sp->lzw_nextbits = 0;
	sp->lzw_nextdata = 0;

	sp->dec_restart = 0;
	sp->dec_nbitsmask = MAXCODE(BITS_MIN);
#ifdef LZW_CHECKEOS
	sp->dec_bitsleft = 0;
#endif
	sp->dec_free_entp = sp->dec_codetab + CODE_FIRST;

	_TIFFmemset(sp->dec_free_entp, 0, (CSIZE-CODE_FIRST)*sizeof (code_t));
	sp->dec_oldcodep = &sp->dec_codetab[-1];
	sp->dec_maxcodep = &sp->dec_codetab[sp->dec_nbitsmask-1];
	return (1);
}

LZWPreEncode(TIFF* cr, uint16 ck)
{
	LZWCodecState *sp = EncoderState(cr);

	(void) ck;
	assert(sp != NULL);

	if( sp->enc_hashtab == NULL )
        {
            cr->tif_setupencode( cr );
        }

	sp->lzw_nbits = BITS_MIN;
	sp->lzw_maxcode = MAXCODE(BITS_MIN);
	sp->lzw_free_ent = CODE_FIRST;
	sp->lzw_nextbits = 0;
	sp->lzw_nextdata = 0;
	sp->enc_checkpoint = CHECK_GAP;
	sp->enc_ratio = 0;
	sp->enc_incount = 0;
	sp->enc_outcount = 0;

	sp->enc_rawlimit = cr->tif_rawdata + cr->tif_rawdatasize-1 - 4;
	cl_hash(sp);		
	sp->enc_oldcode = (hcode_t) -1;	
	return (1);
}

