gif_result gg(gif_animation *tn, size_t fb, unsigned char *dk)
{
        const unsigned char *gif_data;
        unsigned int index;
        gif_result return_value;


        tn->buffer_size = fb;
        tn->gif_data = dk;

        if (tn->lzw_ctx == NULL) {
                lzw_result res = lzw_context_create(
                                (struct lzw_ctx **)&tn->lzw_ctx);
                if (res != LZW_OK) {
                        return gif_error_from_lzw(res);
                }
        }


        if (tn->buffer_size < GIF_STANDARD_HEADER_SIZE) {
                return GIF_INSUFFICIENT_DATA;
        }


        gif_data = tn->gif_data + tn->buffer_position;


        if (tn->buffer_position == 0) {

                tn->frame_image = NULL;
                tn->frames = NULL;
                tn->local_colour_table = NULL;
                tn->global_colour_table = NULL;


                tn->frame_count = 0;
                tn->frame_count_partial = 0;
                tn->decoded_frame = GIF_INVALID_FRAME;


                if (strncmp((const char *) gif_data, "GIF", 3) != 0) {
                        return GIF_DATA_ERROR;
                }
                gif_data += 3;



                gif_data += 3;


                tn->width = gif_data[0] | (gif_data[1] << 8);
                tn->height = gif_data[2] | (gif_data[3] << 8);
                tn->global_colours = (gif_data[4] & GIF_COLOUR_TABLE_MASK);
                tn->colour_table_size = (2 << (gif_data[4] & GIF_COLOUR_TABLE_SIZE_MASK));
                tn->background_index = gif_data[5];
                tn->aspect_ratio = gif_data[6];
                tn->loop_count = 1;
                gif_data += 7;


                if (((tn->width == 640) && (tn->height == 480)) ||
                    ((tn->width == 640) && (tn->height == 512)) ||
                    ((tn->width == 800) && (tn->height == 600)) ||
                    ((tn->width == 1024) && (tn->height == 768)) ||
                    ((tn->width == 1280) && (tn->height == 1024)) ||
                    ((tn->width == 1600) && (tn->height == 1200)) ||
                    ((tn->width == 0) || (tn->height == 0)) ||
                    ((tn->width > 2048) || (tn->height > 2048))) {
                        tn->width = 1;
                        tn->height = 1;
                }


                tn->global_colour_table = calloc(GIF_MAX_COLOURS, sizeof(unsigned int));
                tn->local_colour_table = calloc(GIF_MAX_COLOURS, sizeof(unsigned int));
                if ((tn->global_colour_table == NULL) ||
                    (tn->local_colour_table == NULL)) {
                        gif_finalise(tn);
                        return GIF_INSUFFICIENT_MEMORY;
                }


                tn->global_colour_table[0] = GIF_PROCESS_COLOURS;


                if (tn->buffer_size == (GIF_STANDARD_HEADER_SIZE + 1)) {
                        if (gif_data[0] == GIF_TRAILER) {
                                return GIF_OK;
                        } else {
                                return GIF_INSUFFICIENT_DATA;
                        }
                }


                if ((tn->frames = (gif_frame *)malloc(sizeof(gif_frame))) == NULL) {
                        gif_finalise(tn);
                        return GIF_INSUFFICIENT_MEMORY;
                }
                tn->frame_holders = 1;


                assert(tn->bitmap_callbacks.bitmap_create);
                tn->frame_image = tn->bitmap_callbacks.bitmap_create(tn->width, tn->height);
                if (tn->frame_image == NULL) {
                        gif_finalise(tn);
                        return GIF_INSUFFICIENT_MEMORY;
                }


                tn->buffer_position = gif_data - tn->gif_data;
        }


        if (tn->global_colour_table[0] == GIF_PROCESS_COLOURS) {

                if (tn->global_colours) {
                        if (tn->buffer_size < (tn->colour_table_size * 3 + GIF_STANDARD_HEADER_SIZE)) {
                                return GIF_INSUFFICIENT_DATA;
                        }
                        for (index = 0; index < tn->colour_table_size; index++) {

                                unsigned char *entry = (unsigned char *) &tn->
                                                       global_colour_table[index];

                                entry[0] = gif_data[0];	
                                entry[1] = gif_data[1];	
                                entry[2] = gif_data[2];	
                                entry[3] = 0xff;	

                                gif_data += 3;
                        }
                        tn->buffer_position = (gif_data - tn->gif_data);
                } else {

                        unsigned int *entry = tn->global_colour_table;

                        entry[0] = 0x00000000;

                        ((unsigned char *) entry)[3] = 0xff;

                        entry[1] = 0xffffffff;
                }
        }


        while ((return_value = gg_frame(tn)) == GIF_WORKING);


        if ((return_value == GIF_INSUFFICIENT_MEMORY) ||
            (return_value == GIF_DATA_ERROR)) {
                return return_value;
        }


        if ((return_value == GIF_INSUFFICIENT_DATA) &&
            (tn->frame_count_partial > 0)) {
                return GIF_INSUFFICIENT_FRAME_DATA;
        }


        return return_value;
}

static gif_result rx(lzw_result nw)
{
