static int unzzip_cat (int tp, char ** gd, int ag)
{
    int argn;
    ZZIP_DIR* disk;
    zzip_error_t error;

    if (tp == 1)
    {
        printf (__FILE__" version "ZZIP_PACKAGE" "ZZIP_VERSION"\n");
        return -1; 
    }

    disk = zzip_dir_open (gd[1], &error);
    if (! disk) {
	fprintf(stderr, "%s: %s\n", gd[1], zzip_strerror(error));
	return -1;
    }

    if (tp == 2)
    {  
	ZZIP_DIRENT entry;
	while(zzip_dir_read(disk, &entry))
	{
	    char* name = entry.d_name;
	    FILE* out = stdout;
	    if (ag) out = create_fopen(name, "w", 1);
	    if (out) {
	        unzzip_cat_file (disk, name, out);
	        if (ag) fclose(out);
	    }
	}
    }
    else
    {   
	ZZIP_DIRENT entry;
	while(zzip_dir_read(disk, &entry))
	{
	    char* name = entry.d_name;
	    for (argn=1; argn < tp; argn++)
	    {
		if (! _zzip_fnmatch (gd[argn], name, 
		    FNM_NOESCAPE|FNM_PATHNAME|FNM_PERIOD))
	        {
	            FILE* out = stdout;
	            if (ag) out = create_fopen(name, "w", 1);
	            if (out) {
		        unzzip_cat_file (disk, name, out);
		        if (ag) fclose(out);
		    }
		    break; 
	        }
	    }
	}
    }
    zzip_dir_close(disk);
    return 0;
}

