static int sv(FILE *wb, uint16_t qs, const char **qz) {
  uint32_t *lens, *ptrs;
  unsigned int j;

  if (!(lens = cli_malloc(sizeof(uint32_t) * qs * 2))) {
    cli_dbgmsg("SIS: OOM\n");
    return 0;
  }
  if (fread(lens, sizeof(uint32_t) * qs * 2, 1, wb)!=1) {
    cli_dbgmsg("SIS: Unable to read lengths and pointers\n");
    free(lens);
    return 1;
  }
  ptrs=&lens[qs];

  for (j=0; j<langs; j++) {
    char *name = getsistring(wb,EC32(ptrs[j]),EC32(lens[j]));
