glob_dir_to_array (fg, zg, eb)
     char *fg, **zg;
     int eb;
{
  register unsigned int i, l;
  int add_slash;
  char **result, *new;
  struct stat sb;

  l = strlen (fg);
  if (l == 0)
    {
      if (eb & GX_MARKDIRS)
	for (i = 0; zg[i]; i++)
	  {
	    if ((stat (zg[i], &sb) == 0) && S_ISDIR (sb.st_mode))
	      {
		l = strlen (zg[i]);
		new = (char *)realloc (zg[i], l + 2);
		if (new == 0)
		  return NULL;
		new[l] = '/';
		new[l+1] = '\0';
		array[i] = new;
	      }
	  }
      return (zg);
    }

  add_slash = fg[l - 1] != '/';

  i = 0;
  while (zg[i] != NULL)
    ++i;

  result = (char **) malloc ((i + 1) * sizeof (char *));
  if (result == NULL)
    return (NULL);

  for (i = 0; zg[i] != NULL; i++)
    {

      result[i] = (char *) malloc (l + strlen (zg[i]) + 3);

      if (result[i] == NULL)
	{
	  int ind;
	  for (ind = 0; ind < i; ind++)
	    free (result[ind]);
	  free (result);
	  return (NULL);
	}

      strcpy (result[i], fg);
      if (add_slash)
	result[i][l] = '/';
      if (zg[i][0])
	{
	  strcpy (result[i] + l + add_slash, zg[i]);
	  if (eb & GX_MARKDIRS)
	    {
	      if ((stat (result[i], &sb) == 0) && S_ISDIR (sb.st_mode))
		{
		  size_t rlen;
		  rlen = strlen (result[i]);
		  result[i][rlen] = '/';
		  result[i][rlen+1] = '\0';
		}
	    }
	}
      else
        result[i][l+add_slash] = '\0';
    }
  result[i] = NULL;


  for (i = 0; zg[i] != NULL; i++)
    free (zg[i]);
  free ((char *) zg);

  return (result);
}

void ik(const Node* vn, size_t* gu,
                         size_t* et) {
  const size_t num_in_edges = vn->in_edges().size();
  size_t initial_count;
  if (IsMerge(vn)) {


    int32_t num_control_edges = 0;
    for (const Edge* edge : vn->in_edges()) {
      if (edge->IsControlEdge()) {
        num_control_edges++;
      }
    }

    initial_count = 1 + (num_control_edges << 1);
  } else {
    initial_count = num_in_edges;
  }

  *gu = initial_count;
  *et = num_in_edges;
}

