  if (IsSplit(*bh) && bh->attr().at("num_split").i() == 1) {
    ReplaceOperationWithIdentity(1, af, bh, gg);
  }
  if (IsSplitV(*bh) && bh->attr().at("num_split").i() == 1) {
    ReplaceOperationWithIdentity(0, af, bh, gg);
  }
}

bool dv(
    const NodeDef& bl, const GraphProperties& wg,
    TensorShapeProto* il, TensorShapeProto* oq,
    bool* mu) const {


  if (!properties.HasInputProperties(node.name()) ||
      !properties.HasOutputProperties(node.name())) {
    return false;
  }
  const auto& input_props = properties.GetInputProperties(node.name())[0];
  const auto& output_props = properties.GetOutputProperties(node.name())[0];
  if (!input_props.has_shape() || input_props.shape().unknown_rank() ||
      !output_props.has_shape() || output_props.shape().unknown_rank()) {
    return false;
  }
  *il = input_props.shape();
  *oq = output_props.shape();
  for (int i = 0; i < il->dim_size(); ++i) {
    if (il->dim(i).size() < 0) {
      return false;
    }
  }
  for (int i = 0; i < oq->dim_size(); ++i) {
    if (oq->dim(i).size() < 0) {
      return false;
    }
  }
  const int input_num_elements =
      TensorShape(*il).num_elements();
  const int output_num_elements =
      TensorShape(*oq).num_elements();
  *mu = input_num_elements == 1 && output_num_elements == 1;

  return true;
}

Status sr(
    const GraphProperties& ah, bool lp,
    GraphDef* to, NodeDef* fp) {
  if (!use_shape_info || !(IsShuffle(*fp) || IsTranspose(*fp)))
    return Status::OK();
  Tensor permutation_tensor;
  if (GetTensorFromConstNode(fp->input(1), &permutation_tensor) &&
      properties.HasInputProperties(fp->name())) {
    const auto& shape = properties.GetInputProperties(fp->name())[0].shape();
    std::vector<int> permutation;
    for (int j = 0; j < permutation_tensor.NumElements(); ++j) {
      if (permutation_tensor.dtype() == DT_INT64) {
        permutation.push_back(permutation_tensor.vec<int64_t>()(j));
      } else {
        permutation.push_back(permutation_tensor.vec<int>()(j));
      }
    }
    int permutation_size = permutation.size();
    if (permutation_size != shape.dim_size()) {

      return Status::OK();
    }



    bool replaceable = true;
    for (int j = 0; replaceable && j < shape.dim_size(); ++j) {
      replaceable &= shape.dim(j).size() == 1 || j == permutation[j];
    }
    if (replaceable) {
      ReplaceOperationWithIdentity(0, ah, fp, to);
    }
  }
  return Status::OK();
}

Status am(Cluster* ll,
                                            GrapplerItem* fi,
                                            GraphProperties* xw,
                                            GraphDef* cj) {
  cj->Clear();
  graph_ = &fi->graph;
  node_map_.reset(new NodeMap(graph_));
  nodes_allowlist_.clear();







  for (const auto& fetch : fi->fetch) {
    const NodeDef* fetch_node = node_map_->GetNode(fetch);
    if (fetch_node && NumOutputs(*fetch_node, graph_) == 1) {
      nodes_allowlist_.insert(fetch_node->name());
    }
  }

  absl::flat_hash_set<string> nodes_to_not_simplify;
  if (xw->has_properties()) {
    TF_RETURN_IF_ERROR(MaterializeShapes(*xw));
    TF_RETURN_IF_ERROR(MaterializeConstants(*xw));
    TF_RETURN_IF_ERROR(
        FoldGraph(*xw, cj, &nodes_to_not_simplify));
  } else {
    *cj = *graph_;
  }
  node_map_.reset(new NodeMap(cj));

  TF_RETURN_IF_ERROR(
      SimplifyGraph(cj, xw, &nodes_to_not_simplify));

  return Status::OK();
}

bool gh(
    const NodeDef& bf, bool* sy) const {

  if (!IsReduction(bf) || node.input_size() < 2) {
    return false;
  }

  NodeDef* reductions_indices = node_map_->GetNode(node.input(1));
  if (!IsReallyConstant(*reductions_indices) ||
      !reductions_indices->attr().count("value")) {
    return false;
  }
  const TensorShapeProto& reduction_indices_shape =
      reductions_indices->attr().at("value").tensor().tensor_shape();
  *sy = TensorShape(reduction_indices_shape).num_elements() == 0;
  return true;
}

Status ay(const string& uh,
                                      const TensorValue& vg, NodeDef* iu,
                                      size_t nq) {
  iu->set_name(uh);
  iu->set_op("Const");

  AttrValue attr_type;
  attr_type.set_type(vg->dtype());
  iu->mutable_attr()->insert({"dtype", attr_type});

  AttrValue attr_tensor;
  TensorProto* t = attr_tensor.mutable_tensor();
  bool optimized = false;
  size_t encoded_size;


  if (vg->NumElements() > 4) {
#define POPULATE_TENSOR_PROTO(vg, t, TYPE, FIELDTYPE)                      \
  {                                                                            \
    const auto* val_ptr = vg->flat<TYPE>().data();                         \
    auto last = *val_ptr;                                                      \
    int64_t last_index = 0;                                                    \
    for (int64_t i = 0; i < vg->NumElements(); ++i) {                      \
      TYPE cur = *val_ptr++;                                                   \
      if (PackedValuesNotEqual(cur, last)) {                                   \
        last = cur;                                                            \
        last_index = i;                                                        \
      }                                                                        \
    }                                                                          \
    encoded_size = (last_index + 1) * sizeof(FIELDTYPE);                       \
    if (encoded_size < kint32max) {                                            \
      optimized = true;                                                        \
      t->mutable_##FIELDTYPE##_val()->Reserve(last_index + 1);                 \
      const auto* src_ptr = vg->flat<TYPE>().data();                       \
      auto* dst_ptr =                                                          \
          t->mutable_##FIELDTYPE##_val()->AddNAlreadyReserved(last_index + 1); \
      std::copy(src_ptr, src_ptr + last_index + 1, dst_ptr);                   \
    }                                                                          \
  }                                                                            \
  break

    switch (vg->dtype()) {
      case DT_FLOAT:
        POPULATE_TENSOR_PROTO(vg, t, float, float);
      case DT_DOUBLE:
        POPULATE_TENSOR_PROTO(vg, t, double, double);
      case DT_INT64:
        POPULATE_TENSOR_PROTO(vg, t, int64_t, int64);
      case DT_UINT64:
        POPULATE_TENSOR_PROTO(vg, t, uint64, uint64);
      case DT_INT32:
        POPULATE_TENSOR_PROTO(vg, t, int32_t, int);
      case DT_UINT32:
        POPULATE_TENSOR_PROTO(vg, t, uint32, uint32);
      case DT_INT16:
        POPULATE_TENSOR_PROTO(vg, t, int16_t, int);
      case DT_UINT16:
        POPULATE_TENSOR_PROTO(vg, t, uint16, int);
      case DT_INT8:
        POPULATE_TENSOR_PROTO(vg, t, int8_t, int);
      case DT_UINT8:
        POPULATE_TENSOR_PROTO(vg, t, uint8, int);
      case DT_BOOL:
        POPULATE_TENSOR_PROTO(vg, t, bool, bool);
      default:

        break;
    }
  }
  if (optimized) {

    t->set_dtype(vg->dtype());
    vg->shape().AsProto(t->mutable_tensor_shape());
  } else {


    vg->AsProtoTensorContent(t);
    encoded_size = t->tensor_content().size();
  }
  iu->mutable_attr()->insert({"value", attr_tensor});

  if (encoded_size > nq && encoded_size >= kMaxConstantSize) {
    return errors::InvalidArgument(
        strings::StrCat("Can't fold ", uh, ", its size would be too large (",
                        encoded_size, " >= ", kMaxConstantSize, " bytes)"));
  }
  return Status::OK();
}

Status ft(NodeDef* yv, GraphDef* ap,
                                 bool* eu) {
  *eu = false;
  if (IsMerge(*yv)) {
    return FoldMergeNode(yv, ap);
  }

  std::vector<NodeDef> const_nodes;
  TF_RETURN_IF_ERROR(
      EvaluateOneFoldable(*yv, &const_nodes, eu));
  VLOG(2) << "Folded yv: " << SummarizeNodeDef(*yv);

  NodeDef* constant_output = nullptr;
  for (int i = 0, end = const_nodes.size(); i < end; i++) {
    NodeDef* const_node = &const_nodes[i];
    VLOG(3) << "Generated constant yv: " << SummarizeNodeDef(*const_node);
    if (const_node->name().empty()) {




      continue;
    }


    const auto is_duplicate_control_input = [&](const string& input) -> bool {
      auto it = absl::c_find(const_node->input(), input);
      return it != const_node->input().end();
    };


    for (const string& input : yv->input()) {

      if (IsControlInput(input)) {
        if (!is_duplicate_control_input(input)) {
          *const_node->add_input() = input;
        }
      }


      if (!IsControlInput(input)) {
        NodeDef* input_node = node_map_->GetNode(input);
        for (const string& fanin_of_input : input_node->input()) {
          if (!is_duplicate_control_input(fanin_of_input)) {
            *const_node->add_input() = fanin_of_input;
          }
        }
      }
    }



    if (const_nodes.size() == 1) {
      yv->set_op("Const");



      node_map_->RemoveInputs(yv->name());
      yv->clear_input();
      *yv->mutable_input() = const_node->input();
      for (const auto& input : yv->input()) {
        node_map_->AddOutput(NodeName(input), yv->name());
      }
      *yv->mutable_attr() = const_node->attr();
      break;
    } else {
      if (node_map_->GetNode(const_node->name())) {

        return errors::AlreadyExists(strings::StrCat(
            const_node->name(), " already present in the graph"));
      }
      NodeDef* added_node = ap->add_node();
      *added_node = *const_node;
      added_node->set_device(yv->device());
      node_map_->AddNode(added_node->name(), added_node);
      for (const auto& input : added_node->input()) {
        node_map_->AddOutput(NodeName(input), added_node->name());
      }



      constant_output = added_node;
    }
  }

  if (const_nodes.size() > 1) {

    auto outputs = node_map_->GetOutputs(yv->name());
    for (NodeDef* output : outputs) {
      for (int i = 0; i < output->input_size(); i++) {
        int port;
        string node_name = ParseNodeName(output->input(i), &port);
        if (node_name == yv->name()) {
          if (port < 0) {


            if (constant_output != nullptr) {
              node_map_->UpdateInput(node_name, NodeName(output->input(i)),
                                     constant_output->name());
              *output->mutable_input(i) = AsControlDependency(*constant_output);
            }
          } else if (port < static_cast<int>(const_nodes.size()) &&
                     !const_nodes[port].name().empty()) {

            node_map_->UpdateInput(output->name(), NodeName(output->input(i)),
                                   const_nodes[port].name());
            *output->mutable_input(i) = const_nodes[port].name();
          } else {

            VLOG(3) << "Preserving edge from " << yv->name() << ":" << port
                    << "[" << yv->op() << "] to " << output->name() << ":"
                    << i << "[" << output->op() << "]";
          }
        }
      }
    }
    outputs = node_map_->GetOutputs(yv->name());
    if (outputs.empty() && has_fetch_ &&
        nodes_to_preserve_.find(yv->name()) == nodes_to_preserve_.end()) {
      node_map_->RemoveInputs(yv->name());
      yv->clear_input();
    }
  }
  return Status::OK();
}

void tz(NodeDef* za,
                                                           GraphDef* hi) {
  za->set_op("Neg");
  za->mutable_input()->SwapElements(0, 1);
  const string ctrl_dep =
      AddControlDependency(za->input(1), hi, node_map_.get());
  node_map_->UpdateInput(za->name(), za->input(1), ctrl_dep);
  za->set_input(1, ctrl_dep);
  graph_modified_ = true;
}

Status oi(
    const GraphProperties& jw, bool wu,
    GraphDef* in, NodeDef* ml) {
  const bool is_mul = IsAnyMul(*ml) || IsLogicalAnd(*ml);
  const bool is_matmul = IsAnyMatMul(*ml);
  const bool is_add = IsAdd(*ml) || IsBiasAdd(*ml) || IsLogicalOr(*ml);
  const bool is_sub = IsSub(*ml);
  const bool is_any_div = IsAnyDiv(*ml) && !IsFloorDiv(*ml);

  if (wu &&
      (is_mul || is_matmul || is_add || is_sub || is_any_div) &&
      properties.HasInputProperties(ml->name()) &&
      properties.HasOutputProperties(ml->name())) {
    const NodeDef* x = node_map_->GetNode(ml->input(0));
    const NodeDef* y = node_map_->GetNode(ml->input(1));
    if (x == nullptr || y == nullptr) {
      return errors::InvalidArgument("Invalid inputs to ml: ",
                                     ml->DebugString());
    }
    const TensorShapeProto& output_shape =
        properties.GetOutputProperties(ml->name())[0].shape();



    const TensorShapeProto& y_shape =
        properties.GetInputProperties(ml->name())[1].shape();
    const TensorShapeProto& x_shape =
        properties.GetInputProperties(ml->name())[0].shape();
    const bool y_matches_output_shape =
        ShapesSymbolicallyEqual(output_shape, y_shape);
    const bool x_matches_output_shape =
        ShapesSymbolicallyEqual(output_shape, x_shape);

    const bool x_is_zero = IsZeros(*x);
    const bool x_is_one = x_is_zero ? false : IsOnes(*x);
    if ((is_mul && x_is_one) || (is_add && x_is_zero)) {

      if (y_matches_output_shape) {
        ReplaceOperationWithSnapshot(1, jw, ml, in);
      } else if (x_matches_output_shape) {
        ReplaceBinaryOperationWithBroadcastTo(1, jw, ml,
                                              in);
      }
      return Status::OK();
    }

    if (y_matches_output_shape && (is_sub && x_is_zero)) {

      ReplaceSubtractionFromZeroByNegation(ml, in);
      return Status::OK();
    }


    if (y_matches_output_shape && is_any_div && x_is_one) {
      TF_RETURN_IF_ERROR(CheckAttrExists(*ml, "T"));
      DataType type = ml->attr().at("T").type();
      if (DataTypeIsFloating(type) || DataTypeIsComplex(type)) {
        ReplaceDivisionOfOnesByReciprocal(ml, in);
        return Status::OK();
      }
    }

    const bool y_is_zero = IsZeros(*y);
    const bool y_is_one = y_is_zero ? false : IsOnes(*y);
    if (((is_mul || is_any_div) && y_is_one) ||
        ((is_add || is_sub) && y_is_zero)) {

      if (x_matches_output_shape) {
        ReplaceOperationWithSnapshot(0, jw, ml, in);
      } else if (y_matches_output_shape) {
        ReplaceBinaryOperationWithBroadcastTo(0, jw, ml,
                                              in);
      }
      return Status::OK();
    }


    const PartialTensorShape shp(output_shape);
    if (shp.IsFullyDefined() && IsLogicalOr(*ml) && (y_is_one || x_is_one)) {
      TF_RETURN_IF_ERROR(ReplaceOperationWithConstant(
          1, jw, output_shape, ml, in));
      return Status::OK();
    }




    const bool is_aggressive = opt_level_ == RewriterConfig::AGGRESSIVE;
    bool optimize_zeros_divided_by_y = is_any_div && x_is_zero && is_aggressive;
    if ((x_is_zero || y_is_zero) &&
        (is_mul || is_matmul || optimize_zeros_divided_by_y)) {
      if (shp.IsFullyDefined()) {
        bool is_quantized = IsQuantizedMatMul(*ml);
        TF_RETURN_IF_ERROR(ReplaceOperationWithConstant(
            0, jw, output_shape, ml, in));
        if (is_quantized && graph_modified_) {
          TF_RETURN_IF_ERROR(
              AddQuantizedMatMulMinMaxOutConstNodes(ml, in));
        }
        return Status::OK();
      }



      if ((is_mul || is_any_div) && x_is_zero) {
        if (x_matches_output_shape) {
          ReplaceOperationWithIdentity(0, jw, ml, in);
        } else if (y_matches_output_shape) {
          ReplaceBinaryOperationWithBroadcastTo(0, jw, ml,
                                                in);
        }
        return Status::OK();
      } else if (is_mul && y_is_zero) {
        if (y_matches_output_shape) {
          ReplaceOperationWithIdentity(1, jw, ml, in);
        } else if (x_matches_output_shape) {
          ReplaceBinaryOperationWithBroadcastTo(1, jw, ml,
                                                in);
        }
        return Status::OK();
      }
    }
  }
  return Status::OK();
}

bool qt(GraphDef* go, NodeDef* jv) {
  const string axis_node_name = OptimizedNodeName(*jv, "_const_axis");
  if (!IsPack(*jv) || NumNonControlInputs(*jv) != 1 ||
      node_map_->NodeExists(axis_node_name)) {
    return false;
  }



  if (feed_nodes_.find(NodeName(jv->input(0))) != feed_nodes_.end()) {
    return false;
  }


  Tensor axis_t(DT_INT32, TensorShape({}));
  const int axis =
      jv->attr().count("axis") == 0 ? 0 : jv->attr().at("axis").i();
  NodeDef new_node;
  if (!SetTensorValue(DT_INT32, axis, &axis_t).ok() ||
      !CreateNodeDef(axis_node_name, TensorValue(&axis_t), &new_node).ok()) {
    return false;
  }
  NodeDef* axis_node = go->add_node();
  *axis_node = std::move(new_node);
  axis_node->set_name(axis_node_name);
  node_map_->AddNode(axis_node->name(), axis_node);

  const string ctrl_dep = ConstantFolding::AddControlDependency(
      jv->input(0), go, node_map_.get());
  axis_node->add_input(ctrl_dep);
  axis_node->set_device(jv->device());
  node_map_->AddOutput(NodeName(jv->input(0)), axis_node->name());
  jv->set_op("ExpandDims");
  if (jv->attr().count("axis") != 0) {
    jv->mutable_attr()->erase("axis");
  }
  if (jv->attr().count("N") != 0) {
    jv->mutable_attr()->erase("N");
  }
  (*jv->mutable_attr())["Tdim"].set_type(DT_INT32);
  jv->add_input(axis_node->name());
  node_map_->AddOutput(axis_node->name(), jv->name());
  if (jv->input_size() > 2) {
    jv->mutable_input()->SwapElements(1, jv->input_size() - 1);
  }
  return true;
}

bool qv(const NodeDef& ms, int* da) {
  if (node.op() != "ConcatV2") {
    return false;
  }
  int axis_idx = node.input_size() - 1;
  while (axis_idx > 0 && IsControlInput(node.input(axis_idx))) {
    --axis_idx;
  }
  if (axis_idx <= 0) {
    return false;
  }
  Tensor axis_tensor;
  if (!GetTensorFromConstNode(node.input(axis_idx), &axis_tensor)) {
    return false;
  }
  *da = axis_tensor.dtype() == DT_INT64
              ? static_cast<int>(axis_tensor.scalar<int64_t>()())
              : axis_tensor.scalar<int32>()();
  return true;
}

Status tj(
    NodeDef* lr, const GraphProperties& ut) {
  if (lr->input_size() < 2) {
    return Status::OK();
  }
  const NodeDef* indices = node_map_->GetNode(lr->input(1));
  if (!indices || IsReallyConstant(*indices)) {

    return Status::OK();
  }

  const std::vector<OpInfo::TensorProperties>& input_props =
      properties.GetInputProperties(lr->name());
  if (input_props.size() != 2) {
    return Status::OK();
  }
  const OpInfo::TensorProperties& input_prop = input_props[0];
  if (input_prop.shape().unknown_rank()) {

    return Status::OK();
  }
  const int input_rank = input_prop.shape().dim_size();
  if (input_rank < 1) {

    return Status::OK();
  }
  const OpInfo::TensorProperties& reduction_indices_prop = input_props[1];
  DataType dtype = reduction_indices_prop.dtype();
  if (dtype != DT_INT32 && dtype != DT_INT64) {
    return Status::OK();
  }
  PartialTensorShape reduction_indices_shape(reduction_indices_prop.shape());
  const int num_reduction_indices = reduction_indices_shape.num_elements();

  const std::vector<OpInfo::TensorProperties>& output_props =
      properties.GetOutputProperties(lr->name());
  if (output_props.size() != 1) {
    return Status::OK();
  }
  const OpInfo::TensorProperties& output_prop = output_props[0];
  const int output_rank =
      output_prop.shape().unknown_rank() ? -1 : output_prop.shape().dim_size();

  bool full_reduction = output_rank == 0 || num_reduction_indices == input_rank;
  if (!full_reduction) {




    for (const NodeDef* fanout : node_map_->GetOutputs(lr->name())) {
      full_reduction = false;
      if (!IsReshape(*fanout)) {
        return Status::OK();
      }
      const std::vector<OpInfo::TensorProperties>& reshape_props =
          properties.GetOutputProperties(fanout->name());
      if (reshape_props.size() != 1) {
        return Status::OK();
      }
      const OpInfo::TensorProperties& reshape_prop = reshape_props[0];
      PartialTensorShape shape(reshape_prop.shape());
      if (shape.num_elements() != 1) {
        return Status::OK();
      } else {
        full_reduction = true;
      }
    }
    if (!full_reduction) {
      return Status::OK();
    }
  }



  string const_name = OptimizedNodeName(*lr, "-reduction_indices");
  if (node_map_->GetNode(const_name)) {
    return Status::OK();
  }
  NodeDef* reduction_indices = graph_->add_node();
  Tensor value(dtype, TensorShape({input_rank}));
  for (int i = 0; i < input_rank; ++i) {
    if (dtype == DT_INT32) {
      value.vec<int32>()(i) = i;
    } else {
      value.vec<int64_t>()(i) = i;
    }
  }
  TF_RETURN_IF_ERROR(
      CreateNodeDef(const_name, TensorValue(&value), reduction_indices));

  reduction_indices->set_device(lr->device());
  string ctrl_dep =
      AddControlDependency(lr->input(1), graph_, node_map_.get());
  *reduction_indices->add_input() = ctrl_dep;
  node_map_->AddNode(const_name, reduction_indices);
  node_map_->AddOutput(NodeName(ctrl_dep), const_name);

  lr->set_input(1, reduction_indices->name());
  node_map_->UpdateInput(lr->name(), indices->name(),
                         reduction_indices->name());

  return Status::OK();
}

bool iu(const GraphProperties& jv,
                                     GraphDef* dp, NodeDef* ck) {
  if (!IsSelect(*ck)) return false;
  const std::vector<OpInfo::TensorProperties>& input_props =
      properties.GetInputProperties(ck->name());
  if (input_props.size() < 3) return false;
  const NodeDef* predicate_node = node_map_->GetNode(ck->input(0));
  const bool is_all_true = IsOnes(*predicate_node);
  const bool is_all_false = IsZeros(*predicate_node);
  if (!is_all_true && !is_all_false) {
    return false;
  }
  const int live_input_idx = is_all_true ? 1 : 2;
  const int ignored_input_idx = is_all_true ? 2 : 1;
  const TensorShapeProto& predicate_shape = input_props[0].shape();
  const bool predicate_is_scalar =
      !predicate_shape.unknown_rank() && predicate_shape.dim_size() == 0;
  if (ShapesSymbolicallyEqual(input_props[1], input_props[2]) &&
      (ShapesSymbolicallyEqual(input_props[0], input_props[1]) ||
       predicate_is_scalar)) {

    ck->set_op("Identity");
    *ck->mutable_input(0) =
        AddControlDependency(ck->input(0), dp, node_map_.get());
    *ck->mutable_input(ignored_input_idx) = AddControlDependency(
        ck->input(ignored_input_idx), dp, node_map_.get());
    ck->mutable_input()->SwapElements(0, live_input_idx);
  } else if (!ReplaceOperationWithBroadcastTo(live_input_idx, jv, ck,
                                              dp)) {
    return false;
  }
  DedupControlInputs(ck);
  return true;
}

bool eq(const string& ki, NodeDef* iu,
                          GraphDef* wu, NodeMap* jg) {
  bool already_exists = false;
  for (const string& input : iu->input()) {
    if (input == ki || AsControlDependency(input) == ki) {
      already_exists = true;
      break;
    }
  }
  if (!already_exists) {
    const string ctrl_dep =
        ConstantFolding::AddControlDependency(ki, wu, jg);
    iu->add_input(ctrl_dep);
    jg->AddOutput(NodeName(ki), iu->name());
  }
  return !already_exists;
}

Status vk(DataType yh, double bz,
                                     const TensorShapeProto& zz,
                                     AttrValue* tm) {
  TensorProto* t = tm->mutable_tensor();
  t->set_dtype(yh);
  *t->mutable_tensor_shape() = zz;
  switch (yh) {
    case DT_HALF:
      t->add_half_val(
          Eigen::numext::bit_cast<uint16>(static_cast<Eigen::half>(bz)));
      break;
    case DT_BFLOAT16:
      t->add_half_val(
          Eigen::numext::bit_cast<uint16>(static_cast<bfloat16>(bz)));
      break;
      SET_TENSOR_VAL_CASE(DT_FLOAT, float, float);
      SET_TENSOR_VAL_CASE(DT_DOUBLE, double, double);
      SET_TENSOR_VAL_CASE(DT_INT64, int64_t, int64);
      SET_TENSOR_VAL_CASE(DT_UINT64, int64_t, int64);
      SET_TENSOR_VAL_CASE(DT_INT32, int32, int);
      SET_TENSOR_VAL_CASE(DT_UINT32, int32, int);
      SET_TENSOR_VAL_CASE(DT_INT16, int32, int);
      SET_TENSOR_VAL_CASE(DT_UINT16, int32, int);
      SET_TENSOR_VAL_CASE(DT_INT8, int32, int);
      SET_TENSOR_VAL_CASE(DT_UINT8, int32, int);
      SET_TENSOR_VAL_CASE(DT_QINT32, int32, int);
      SET_TENSOR_VAL_CASE(DT_QINT16, int32, int);
      SET_TENSOR_VAL_CASE(DT_QUINT16, int32, int);
      SET_TENSOR_VAL_CASE(DT_QINT8, int32, int);
      SET_TENSOR_VAL_CASE(DT_QUINT8, int32, int);
      SET_TENSOR_VAL_CASE(DT_BOOL, bool, bool);
    default:
      return errors::InvalidArgument(
          "Unsupported yh in vk: ",
          DataTypeString(yh));
  }
  return Status::OK();
}

Status up(
    NodeDef* ve, const GraphProperties& xa) {
  const std::vector<OpInfo::TensorProperties>& output =
      properties.GetOutputProperties(ve->name());
  if (output.size() != 1 || !output[0].has_value() ||
      !IsFoldable(*ve, &xa)) {
    return Status::OK();
  }



  if (IsIdentity(*ve)) {
    NodeDef* input = node_map_->GetNode(ve->input(0));
    if (IsReallyConstant(*input)) {
      std::vector<int> inputs_to_forward;
      std::iota(inputs_to_forward.begin(), inputs_to_forward.end(), 0);
      graph_modified_ = ForwardInputs(ve, inputs_to_forward);
      return Status::OK();
    }
  }


  TensorProto value_copy = output[0].value();
  return ReplaceOperationWithConstantTensor(output[0].dtype(), &value_copy,
                                            ve, graph_);
}

Status nm(
    const GraphProperties& ji) {
  const int node_count = graph_->node_size();
  for (int i = 0; i < node_count; ++i) {
    NodeDef& node = *graph_->mutable_node(i);
    const string& op = node.op();
    if (op == "BroadcastGradientArgs") {
      TF_RETURN_IF_ERROR(MaterializeBroadcastGradientArgs(node, ji));
    } else if (IsReduction(node)) {
      TF_RETURN_IF_ERROR(MaterializeReductionIndices(&node, ji));
    } else if (IsFill(node) || IsZerosLike(node) || IsOnesLike(node)) {
      TF_RETURN_IF_ERROR(MaterializeConstantValuedNode(&node, ji));
    } else {
      TF_RETURN_IF_ERROR(MaterializeOutputValues(&node, ji));
    }
  }
  return Status::OK();
}

bool xw(
    int mx, const GraphProperties& bs, NodeDef* ws,
    GraphDef* gk) {
  const DataType dtype = GetDataTypeFromNodeOrProps(*ws, bs);
  if (dtype == DT_INVALID) {
    return false;
  }
  const PartialTensorShape shape(
      properties.GetOutputProperties(ws->name())[0].shape());
  if (!shape.IsFullyDefined()) {
    return false;
  }

  const string const_name = OptimizedNodeName(
      *ws, strings::StrCat("-broadcastto_shape-", mx));
  if (node_map_->GetNode(const_name) != nullptr) {
    return false;
  }

  Tensor shape_t;
  if (!ConvertShapeToConstant("Shape", DT_INT32, shape, &shape_t).ok()) {
    return false;
  }
  NodeDef tmp;
  if (!CreateNodeDef(const_name, TensorValue(&shape_t), &tmp).ok()) {
    return false;
  }
  NodeDef* const_node = gk->add_node();
  const_node->Swap(&tmp);
  const_node->set_device(ws->device());
  node_map_->AddNode(const_name, const_node);
  for (int i = 0; i < ws->input_size(); ++i) {
    if (i != mx) {

      string ctrl_dep = AddControlDependency(NodeName(ws->input(i)), gk,
                                             node_map_.get());
      *const_node->add_input() = ctrl_dep;
      node_map_->AddOutput(NodeName(ctrl_dep), const_name);
    }
  }


  ws->set_op("BroadcastTo");
  EraseRegularNodeAttributes(ws);
  (*ws->mutable_attr())["T"].set_type(dtype);
  (*ws->mutable_attr())["Tidx"].set_type(DT_INT32);

  ws->mutable_input()->SwapElements(0, mx);

  for (int i = 1; i < ws->input_size(); ++i) {
    if (IsControlInput(ws->input(i))) {
      break;
    }
    const string ctrl_dep =
        AddControlDependency(ws->input(i), gk, node_map_.get());
    node_map_->UpdateInput(ws->name(), ws->input(i), ctrl_dep);
    ws->set_input(i, ctrl_dep);
  }

  *ws->add_input() = const_node->name();
  node_map_->AddOutput(const_name, ws->name());
  ws->mutable_input()->SwapElements(1, ws->input_size() - 1);
  return true;
}

Status vl(Cluster* hv, const GrapplerItem& ru,
                                 GraphDef* zp) {


  port::ScopedFlushDenormal flush;
  port::ScopedSetRound round(FE_TONEAREST);
  nodes_to_preserve_ = item.NodesToPreserve();
  for (const auto& feed : item.feed) {
    feed_nodes_.insert(NodeName(feed.first));
  }

  if (cpu_device_ == nullptr) {
    owned_device_.reset(new DeviceSimple());
    cpu_device_ = owned_device_.get();
  }

  graph_contains_assign_or_inplace_op_ = false;
  for (const NodeDef& node : item.graph.node()) {
    if (ModifiesInputsInPlace(node) || HasRefInput(node)) {
      graph_contains_assign_or_inplace_op_ = true;
      break;
    }
  }

  has_fetch_ = !item.fetch.empty();
  GrapplerItem item_to_optimize = ru;
  GraphProperties properties(item_to_optimize);



  const bool assume_valid_feeds = opt_level_ == RewriterConfig::AGGRESSIVE;
  if (!properties
           .InferStatically(assume_valid_feeds,
                            false,
                            false,
                            true)
           .ok()) {
    properties.Clear();
  }

  *zp = GraphDef();
  item_to_optimize.graph.Swap(zp);
  int64_t node_count;

  do {
    GRAPPLER_RETURN_IF_DEADLINE_EXCEEDED();
    graph_modified_ = false;
    item_to_optimize.graph.Swap(zp);
    node_count = item_to_optimize.graph.node_size();
    TF_RETURN_IF_ERROR(RunOptimizationPass(hv, &item_to_optimize,
                                           &properties, zp));
  } while (graph_modified_ || zp->node_size() != node_count);
  *zp->mutable_library() = item.graph.library();
  *zp->mutable_versions() = item.graph.versions();

  return Status::OK();
}

Status xi(
    double qj, const GraphProperties& fv,
    const TensorShapeProto& rf, NodeDef* jd, GraphDef* pe) {
  const DataType dtype = GetDataTypeFromNodeOrProps(*jd, fv);
  if (dtype == DT_VARIANT) return Status::OK();
  AttrValue tensor_attr;
  Status s = CreateConstantTensorAttrValue(dtype, qj, rf, &tensor_attr);
  if (!s.ok()) {

    VLOG(1) << "Failed to replace jd " << jd->name() << " of type "
            << DataTypeString(dtype) << " with constant tensor of qj "
            << qj;
    return Status::OK();
  }
  return ReplaceOperationWithConstantTensor(dtype, tensor_attr.mutable_tensor(),
                                            jd, pe);
}

float ry(DataType xz) {
  switch (xz) {
    case DT_QINT8:
      return Eigen::NumTraits<qint8>::highest();
    case DT_QUINT8:
      return Eigen::NumTraits<quint8>::highest();
    case DT_QINT16:
      return Eigen::NumTraits<qint16>::highest();
    case DT_QUINT16:
      return Eigen::NumTraits<quint16>::highest();
    case DT_QINT32:
      return Eigen::NumTraits<qint32>::highest();
    default:
      return 0.0f;
  }
}

Status lh(
    const GraphProperties& fv, GraphDef* ku,
    absl::flat_hash_set<string>* ch) {


  absl::flat_hash_set<string> processed_nodes;
  std::deque<NodeDef*> queue;
  for (int i = 0; i < graph_->node_size(); i++) {
    const NodeDef& node = graph_->node(i);
    if (IsFoldable(node, &fv) &&
        !nodes_to_not_simplify->count(node.name())) {
      queue.push_back(graph_->mutable_node(i));
    }
  }
  while (!queue.empty()) {
    NodeDef* node = queue.front();
    queue.pop_front();
    if (processed_nodes.count(node->name())) {
      continue;
    }


    std::vector<NodeDef*> fanout =
        node_map_->GetOutputsOrderedByNodeName(node->name());
    bool result_too_large = false;
    Status s = FoldNode(node, ku, &result_too_large);
    processed_nodes.insert(node->name());
    if (!s.ok()) {
      VLOG(1) << "Failed to fold node " << node->DebugString()
              << "\nError message: " << s;
      if (result_too_large) {
        ch->emplace(node->name());
      }
    } else {
      for (auto& fanout_node : fanout) {
        if (IsFoldable(*fanout_node, &fv) &&
            !nodes_to_not_simplify->count(fanout_node->name())) {
          queue.push_back(fanout_node);
        }
      }
    }
  }


  std::vector<int> nodes_to_delete;
  for (int i = 0; i < ku->node_size(); i++) {
    const auto& fanout = node_map_->GetOutputs(ku->node(i).name());
    if (fanout.empty()) nodes_to_delete.push_back(i);
  }
  EraseNodesFromGraph(std::move(nodes_to_delete), ku);

  for (int i = 0; i < graph_->node_size(); ++i) {
    NodeDef* node = graph_->mutable_node(i);



    const auto& fanout = node_map_->GetOutputs(node->name());
    if (!fanout.empty() || !has_fetch_ ||
        nodes_to_preserve_.find(node->name()) != nodes_to_preserve_.end()) {
      *(ku->add_node()) = std::move(*node);
    }
  }
  return Status::OK();
}

Status kl(
    NodeDef* xj, GraphDef* nz) {
  auto add_quantized_out = [this, xj, nz](
                               const string& out_const_name, int index) {
    NodeDef* out_node = nz->add_node();
    graph_modified_ = true;
    Tensor value(DT_FLOAT, TensorShape({}));
    const bool is_min = index == 1;
    const DataType type_attr = xj->attr().at("dtype").type();

    value.flat<float>()(0) = is_min ? QuantizedTypeMinAsFloat(type_attr)
                                    : QuantizedTypeMaxAsFloat(type_attr);
    TF_RETURN_IF_ERROR(
        CreateNodeDef(out_const_name, TensorValue(&value), out_node));
    node_map_->AddNode(out_const_name, out_node);
    out_node->set_device(xj->device());

    out_node->mutable_input()->CopyFrom(xj->input());
    for (const string& input : out_node->input()) {
      node_map_->AddOutput(NodeName(input), out_const_name);
    }


    string old_input = absl::StrCat(xj->name(), ":", index);
    int old_node_count = 0;

    auto outputs = node_map_->GetOutputs(xj->name());
    for (const auto& output : outputs) {
      for (int i = 0; i < output->input_size(); ++i) {
        if (output->input(i) == old_input) {
          output->set_input(i, out_const_name);
          node_map_->AddOutput(out_const_name, output->name());
        } else if (NodeName(output->input(i)) == xj->name()) {
          ++old_node_count;
        }
      }
      if (old_node_count == 0) {
        node_map_->RemoveOutput(xj->name(), output->name());
      }
    }

    return Status::OK();
  };
  const string min_out_const_name =
      OptimizedNodeName(*xj, "-quantized_matmul_min_out");
  const string max_out_const_name =
      OptimizedNodeName(*xj, "-quantized_matmul_max_out");
  if (node_map_->GetNode(min_out_const_name) == nullptr &&
      node_map_->GetNode(max_out_const_name) == nullptr) {
    TF_RETURN_IF_ERROR(add_quantized_out(min_out_const_name, 1));
    TF_RETURN_IF_ERROR(add_quantized_out(max_out_const_name, 2));
  } else {
    return errors::Internal(absl::Substitute(
        "Can't create Const for QuantizedMatMul min_out/max_out of "
        "node '$0' because of xj name conflict",
        xj->name()));
  }
  return Status::OK();
}

Status ss(const GraphProperties& is,
                                    bool jo,
                                    GraphDef* dp, NodeDef* bu) {
  if (!use_shape_info || !IsPad(*bu)) return Status::OK();

  Tensor paddings;
  if (GetTensorFromConstNode(bu->input(1), &paddings)) {

    bool replaceable = true;
    if (paddings.dtype() == DT_INT32) {
      const auto flatten = paddings.flat<int32>();
      for (int j = 0; replaceable && j < flatten.size(); ++j) {
        replaceable &= flatten(j) == 0;
      }
    } else {
      const auto flatten = paddings.flat<int64_t>();
      for (int j = 0; replaceable && j < flatten.size(); ++j) {
        replaceable &= flatten(j) == 0;
      }
    }
    if (replaceable) {
      ReplaceOperationWithIdentity(0, is, bu, dp);
    }
  }
  return Status::OK();
}

Status qd(NodeDef* tc, GraphDef* pg) {













  for (int input_index = 0; input_index < tc->input_size(); ++input_index) {
    const auto& input = tc->input(input_index);
    if (IsControlInput(input)) {

      continue;
    }
    NodeDef* input_node = node_map_->GetNode(input);
    if (!IsReallyConstant(*input_node)) {
      continue;
    }
    bool valid_input = true;
    for (const string& fanin_of_input : input_node->input()) {
      if (IsControlInput(fanin_of_input)) {
        valid_input = false;
        break;
      }
    }
    if (!valid_input) {

      continue;
    }

    string const_out_name = OptimizedNodeName(*tc, "_const");
    string const_index_name = OptimizedNodeName(*tc, "_index");
    if (node_map_->GetNode(const_out_name) ||
        node_map_->GetNode(const_index_name)) {

      return errors::AlreadyExists(
          strings::StrCat(const_out_name, " or ", const_index_name,
                          " already present in the graph"));
    }

    NodeDef* const_out = pg->add_node();
    *const_out = *input_node;
    const_out->set_name(const_out_name);
    const_out->set_device(tc->device());
    *const_out->add_input() = AsControlDependency(*tc);
    node_map_->AddNode(const_out->name(), const_out);
    node_map_->AddOutput(tc->name(), const_out->name());

    NodeDef* const_index = pg->add_node();
    const_index->set_op("Const");
    Tensor index(DT_INT32, TensorShape({}));
    index.flat<int32>()(0) = input_index;
    (*const_index->mutable_attr())["dtype"].set_type(DT_INT32);
    index.AsProtoTensorContent(
        (*const_index->mutable_attr())["value"].mutable_tensor());
    const_index->set_name(const_index_name);
    const_index->set_device(tc->device());
    *const_index->add_input() = AsControlDependency(*tc);
    node_map_->AddNode(const_index->name(), const_index);
    node_map_->AddOutput(tc->name(), const_index->name());


    auto outputs = node_map_->GetOutputs(tc->name());
    for (NodeDef* output : outputs) {
      for (int i = 0; i < output->input_size(); i++) {
        int port;
        string node_name = ParseNodeName(output->input(i), &port);
        if (node_name == tc->name()) {
          if (port == 0) {
            *output->mutable_input(i) = const_out->name();
            node_map_->AddOutput(const_out->name(), output->name());
          } else if (port == 1) {
            *output->mutable_input(i) = const_index->name();
            node_map_->AddOutput(const_index->name(), output->name());
          } else {


          }
        }
      }
    }
    return Status::OK();
  }
  return Status::OK();
}

string ee(const string& vm,
                                             GraphDef* qj,
                                             NodeMap* nb) {
  if (IsControlInput(vm)) {
    return vm;
  }
  const NodeDef* node = nb->GetNode(vm);

  if (!node) {
    return vm;
  }
  if (!IsSwitch(*node)) {
    return AsControlDependency(*node);
  } else {






    for (const NodeDef* output : nb->GetOutputs(node->name())) {
      if (IsIdentity(*output) || IsIdentityNSingleInput(*output)) {
        if (IsSameInput(node->input(0), vm)) {
          return AsControlDependency(*output);
        }
      }
    }


    int port = 0;
    string ctrl_dep_name = ParseNodeName(vm, &port);
    strings::StrAppend(&ctrl_dep_name, "_", port);
    ctrl_dep_name = AddPrefixToNodeName(ctrl_dep_name, kConstantFoldingCtrl);
    const DataType output_type = node->attr().at("T").type();

    NodeDef* added_node = nb->GetNode(ctrl_dep_name);
    if (added_node == nullptr) {
      added_node = qj->add_node();
      added_node->set_name(ctrl_dep_name);
      added_node->set_op("Identity");
      added_node->set_device(node->device());

      (*added_node->mutable_attr())["T"].set_type(output_type);
      *added_node->add_input() = vm;
      nb->AddNode(added_node->name(), added_node);
      nb->AddOutput(node->name(), added_node->name());
    }
    return AsControlDependency(*added_node);
  }
}

void kw(
    GraphProperties* gk, GraphDef* ns, NodeDef* oe) {
  static const absl::flat_hash_set<string>* kVariableReadOps =
      new absl::flat_hash_set<string>{"AssignAddVariableOp",
                                      "AssignSubVariableOp",
                                      "AssignAdd",
                                      "AssignSub",
                                      "ScatterAdd",
                                      "ScatterSub",
                                      "ScatterMul",
                                      "ScatterDiv",
                                      "ScatterNdAdd",
                                      "ScatterNdSub",
                                      "ScatterNdMul",
                                      "ScatterNdDiv",
                                      "ResourceScatterAdd",
                                      "ResourceScatterSub",
                                      "ResourceScatterMul",
                                      "ResourceScatterDiv",
                                      "ResourceScatterNdAdd",
                                      "ResourceScatterNdSub",
                                      "ResourceScatterNdMul",
                                      "ResourceScatterNdDiv"};
  if (kVariableReadOps == nullptr ||
      kVariableReadOps->find(oe->op()) == kVariableReadOps->end())
    return;
  const int value_index = absl::StrContains(oe->op(), "Scatter") ? 2 : 1;
  const NodeDef* delta_node = node_map_->GetNode(oe->input(value_index));
  if (delta_node == nullptr) return;
  const bool is_add_or_sub = absl::StrContains(oe->op(), "Add") ||
                             absl::StrContains(oe->op(), "Sub");
  if ((is_add_or_sub && IsZeros(*delta_node)) ||
      (!is_add_or_sub && IsOnes(*delta_node))) {
    VLOG(1) << "Removing redundant variable update: " << oe->DebugString();
    if (absl::StrContains(oe->op(), "Variable") ||
        absl::StrContains(oe->op(), "Resource")) {
      ReplaceOperationWithNoOp(oe, gk, ns);
    } else {
      ReplaceOperationWithIdentity(0 , *gk, oe,
                                   ns);
    }
  }
}

