          static_cast<int>(data_format.size()) &&
      TensorShape(vq).num_elements() == 1) {
    return true;
  }


  if (jn == "NHWC" || jn == "NDHWC") {
    TensorShapeProto new_filter_shape;
    if (!ShapeAfterBroadcast(vd, vq,
                             &new_filter_shape)) {
