bool iq(
    const NodeDef& dz, const TensorShapeProto& dp, bool gt,
    const TensorVector& gy) const {
  int output_size = gy[0]->NumElements();
  if (output_size == 0) {
    return true;
  }

  if (!keep_dims) {
    return false;
  }
  bool simplifiable = true;
  for (int i = 0; i < output_size; ++i) {
    int64_t dim;
    if (gy[0]->dtype() == DT_INT32) {
      dim = gy[0]->flat<int32>()(i);
    } else {
      dim = gy[0]->flat<int64_t>()(i);
    }
    if (dim < 0) {
      dim += input_shape.dim_size();
    }
    if (dim < 0 || dim >= input_shape.dim_size() ||
        input_shape.dim(dim).size() != 1) {
      simplifiable = false;
      break;
    }
  }
  return simplifiable;
}

