Status cx(const GraphProperties& ds,
                                      bool vp,
                                      GraphDef* ec,
                                      NodeDef* yq) {
  if (!use_shape_info || !IsSlice(*yq)) return Status::OK();
  Tensor begin;
  Tensor size;
  if (properties.HasInputProperties(yq->name()) &&
      GetTensorFromConstNode(yq->input(1), &begin) &&
      GetTensorFromConstNode(yq->input(2), &size)) {
    const auto& input = properties.GetInputProperties(yq->name())[0];


    bool replaceable = !input.shape().unknown_rank();
    for (int j = 0; replaceable && j < input.shape().dim_size(); ++j) {
      if (begin.dtype() == DT_INT32) {
        replaceable &= begin.vec<int>()(j) == 0;
      } else {
        replaceable &= begin.vec<int64_t>()(j) == 0;
      }
      if (size.dtype() == DT_INT32) {
        replaceable &= (size.vec<int>()(j) == -1 ||
                        size.vec<int>()(j) == input.shape().dim(j).size());
      } else {
        replaceable &= (size.vec<int64_t>()(j) == -1 ||
                        size.vec<int64_t>()(j) == input.shape().dim(j).size());
      }
    }
    if (replaceable) {
      ReplaceOperationWithIdentity(0, ds, yq, ec);
    }
  }
  return Status::OK();
}

bool ji(GraphDef* xd,
                                                GraphProperties* iu,
                                                NodeDef* ho) {



  if (!IsConcat(*ho) ||
      ho->name().rfind("_partial_split_") != string::npos) {
    return false;
  }
  const int num_non_control_inputs = NumNonControlInputs(*ho);
  if (num_non_control_inputs <= 3) return false;
  int axis_arg = -1;
  int begin = 0;
  int end = num_non_control_inputs;
  if (ho->op() == "Concat") {
    begin = 1;
    axis_arg = 0;
  } else if (ho->op() == "ConcatV2") {
    end = num_non_control_inputs - 1;
    axis_arg = num_non_control_inputs - 1;
  } else {
    return false;
  }



  std::vector<std::pair<int, int>> constant_input_runs;
  int first = begin;
  int last = begin;
  while (last < end) {
    while (first < end && !IsReallyConstant(*node_map_->GetNode(
                              NodeName(ho->input(first))))) {
      ++first;
    }

    last = first + 1;
    while (last < end &&
           IsReallyConstant(*node_map_->GetNode(NodeName(ho->input(last))))) {
      ++last;
    }


    if (first < end && (last - first) > 1) {
      constant_input_runs.emplace_back(first, last);
    }
    first = last;
  }


  if (constant_input_runs.empty() || (constant_input_runs.size() == 1 &&
                                      constant_input_runs[0].first == begin &&
                                      constant_input_runs[0].second == end)) {
    return false;
  }
  std::set<int> inputs_to_delete;
  for (auto interval : constant_input_runs) {


    string new_node_name = OptimizedNodeName(*ho, "_partial_split");
    do {
      new_node_name += strings::StrCat("_", interval.first);
    } while (node_map_->NodeExists(new_node_name));

    NodeDef* added_node = xd->add_node();
    *added_node = *ho;
    added_node->set_op("ConcatV2");
    added_node->set_name(new_node_name);
    node_map_->AddNode(added_node->name(), added_node);
    added_node->clear_input();
    for (int i = interval.first; i < interval.second; ++i) {
      added_node->add_input(ho->input(i));
      node_map_->UpdateInput(ho->name(), ho->input(i), added_node->name());
      if (i != interval.first) {
        inputs_to_delete.insert(i);
      }
    }
    added_node->add_input(ho->input(axis_arg));
    (*added_node->mutable_attr())["N"].set_i(interval.second - interval.first);
    node_map_->AddOutput(NodeName(ho->input(axis_arg)), added_node->name());



    ho->set_input(interval.first, added_node->name());
  }
  if (!inputs_to_delete.empty()) {

    protobuf::RepeatedPtrField<string> tmp;
    tmp.Swap(ho->mutable_input());
    for (int i = 0; i < tmp.size(); ++i) {
      if (inputs_to_delete.find(i) == inputs_to_delete.end()) {
        ho->add_input(tmp.Get(i));
      }
    }
    (*ho->mutable_attr())["N"].set_i(ho->input_size() - 1);
    iu->ClearInputProperties(ho->name());
  }
  return true;
}

bool vk(const string& ob, NodeDef* df,
                             GraphDef* bj, NodeMap* lz) {
  bool removed_input = false;
  bool update_node_map = true;
  const string old_input_ctrl_dep = AsControlDependency(NodeName(ob));
  for (int i = 0; i < df->input_size(); ++i) {
    const string& input = df->input(i);
    if (old_input_ctrl_dep == input) {
      if (IsControlInput(input)) {
        df->mutable_input()->SwapElements(i, df->input_size() - 1);
        df->mutable_input()->RemoveLast();
        removed_input = true;
      } else {


        update_node_map = false;
      }
    }
  }
  if (update_node_map) {
    lz->RemoveOutput(NodeName(ob), df->name());
  }
  return removed_input;
}

