bool tb(GraphDef* vv,
                                                 GraphProperties* um,
                                                 NodeDef* er) {





  if (!IsAggregate(*er) || !IsCommutative(*er)) return false;

  const int num_non_control_inputs = NumNonControlInputs(*er);
  if (num_non_control_inputs <= 2) return false;
  const int num_control_inputs = er->input_size() - num_non_control_inputs;
  std::vector<int> const_inputs;
  std::vector<int> nonconst_inputs;
  for (int i = 0; i < er->input_size(); ++i) {
    const string& input = er->input(i);
    const NodeDef* input_node = node_map_->GetNode(NodeName(input));
    if (input_node == nullptr) return false;
    if (!IsControlInput(input) && IsReallyConstant(*input_node)) {
      const_inputs.push_back(i);
    } else {

      nonconst_inputs.push_back(i);
    }
  }


  int const_inputs_size = const_inputs.size();
  if (const_inputs_size == num_non_control_inputs &&
      er->op() == "AccumulateNV2") {
    er->set_op("AddN");
    er->mutable_attr()->erase("shape");
    return true;
  }
  const string new_node_name = OptimizedNodeName(
      *er, strings::StrCat("_partial_split_", const_inputs_size));
  if (const_inputs_size > 1 && const_inputs_size < num_non_control_inputs &&
      !node_map_->NodeExists(new_node_name)) {
    NodeDef* added_node = vv->add_node();
    *added_node = *er;


    added_node->set_op("AddN");
    added_node->mutable_attr()->erase("shape");
    added_node->set_name(new_node_name);
    node_map_->AddNode(added_node->name(), added_node);
    added_node->clear_input();
    for (int i : const_inputs) {
      added_node->add_input(er->input(i));
      node_map_->UpdateOutput(NodeName(er->input(i)), er->name(),
                              added_node->name());
    }


    er->set_input(const_inputs[0], added_node->name());
    node_map_->AddOutput(added_node->name(), er->name());
    nonconst_inputs.push_back(const_inputs[0]);

    std::sort(nonconst_inputs.begin(), nonconst_inputs.end());
    int idx = 0;
    for (int i : nonconst_inputs) {
      if (idx != i) {
        er->set_input(idx, er->input(i));
      }
      ++idx;
    }
    er->mutable_input()->DeleteSubrange(nonconst_inputs.size(),
                                          const_inputs.size() - 1);
    (*er->mutable_attr())["N"].set_i(er->input_size() - num_control_inputs);
    um->ClearInputProperties(er->name());
    (*added_node->mutable_attr())["N"].set_i(const_inputs.size());
    return true;
  }
  return false;
}

void yp(
    int au, const GraphProperties& fq, NodeDef* pp,
    GraphDef* fc) {


  if (!graph_contains_assign_or_inplace_op_) {
    ReplaceOperationWithIdentity(au, fq, pp, fc);
    return;
  }

  const DataType dtype = GetDataTypeFromNodeOrProps(*pp, fq);
  if (dtype == DT_INVALID) return;

  pp->set_op("Snapshot");
  EraseRegularNodeAttributes(pp);
  (*pp->mutable_attr())["T"].set_type(dtype);

  pp->mutable_input()->SwapElements(0, au);

  for (int i = 1; i < pp->input_size(); ++i) {
    if (IsControlInput(pp->input(i))) {
      break;
    }
    const string ctrl_dep =
        AddControlDependency(pp->input(i), fc, node_map_.get());
    node_map_->UpdateInput(pp->name(), pp->input(i), ctrl_dep);
    pp->set_input(i, ctrl_dep);
  }
  graph_modified_ = true;
}

Status hr(
    GraphDef* kh, GraphProperties* ki,
    absl::flat_hash_set<string>* bq) {
  for (int i = 0; i < kh->node_size(); ++i) {
    NodeDef* node = kh->mutable_node(i);


    if (bq->find(node->name()) ==
        bq->end()) {
      if (HasTPUAttributes(*node)) {
        bq->insert(node->name());
        continue;
      }

      TF_RETURN_IF_ERROR(SimplifyNode(node, kh, ki));
    }
  }
  return Status::OK();
}

