bool dp(
    const NodeDef& oz, const GraphProperties& so,
    bool cp, ConstantPushDownContext* ok) const {
  if (ok == nullptr || !has_fetch_ || NumNonControlInputs(oz) != 2) {
    return false;
  }
  NodeDef* left_child = node_map_->GetNode(parent.input(0));
  NodeDef* right_child = node_map_->GetNode(parent.input(1));


  if (left_child == nullptr || right_child == nullptr) {
    return false;
  }

  ok->left_child_is_const = IsReallyConstant(*left_child);
  ok->right_child_is_const = IsReallyConstant(*right_child);
  ok->op_child = ok->left_child_is_const ? right_child : left_child;
  ok->const_child = ok->left_child_is_const ? left_child : right_child;


  if (!ctx->left_child_is_const && !ctx->right_child_is_const) {
    return false;
  }


  if (parent.device() != ok->op_child->device() ||
      parent.device() != ok->const_child->device()) {
    return false;
  }


  if (ok->op_child->input_size() < 2 ||
      nodes_to_preserve_.find(ok->op_child->name()) !=
          nodes_to_preserve_.end() ||
      NumNonControlOutputs(*ok->op_child, *node_map_) > 1) {
    return false;
  }



  if (!CheckAttrExists(oz, "T").ok()) return false;
  DataType dtype = parent.attr().at("T").type();
  if (dtype == DT_BFLOAT16 || dtype == DT_HALF) {
    return false;
  }



  const auto& child_output = node_map_->GetOutputs(ok->op_child->name());
  if (child_output.find(ok->const_child) != child_output.end()) {
    return false;
  }


  ok->left_leaf = node_map_->GetNode(ok->op_child->input(0));
  ok->right_leaf = node_map_->GetNode(ok->op_child->input(1));
  ok->left_leaf_is_const = IsReallyConstant(*ok->left_leaf);
  ok->right_leaf_is_const = IsReallyConstant(*ok->right_leaf);

  if (ok->left_leaf_is_const && ok->right_leaf_is_const) {

    return false;
  }


  if (parent.device() != ok->left_leaf->device() ||
      parent.device() != ok->right_leaf->device()) {
    return false;
  }


  ok->parent_input_props = &properties.GetInputProperties(parent.name());
  ok->op_child_input_props =
      &properties.GetInputProperties(ok->op_child->name());
  if (cp && (ok->parent_input_props == nullptr ||
                               ok->parent_input_props->size() < 2 ||
                               ok->op_child_input_props == nullptr ||
                               ok->op_child_input_props->size() < 2)) {
    return false;
  }

  VLOG(1) << "\n++++++++ PushDown for node " << parent.name() << ": "
          << parent.op() << "(" << left_child->op() << ", " << right_child->op()
          << ")";

  return true;
}

