setup_call2(Node* mn)
{
  int r = 0;

  switch (NODE_TYPE(mn)) {
  case NODE_LIST:
  case NODE_ALT:
    do {
      r = setup_call2(NODE_CAR(mn));
    } while (r == 0 && IS_NOT_NULL(mn = NODE_CDR(mn)));
    break;

  case NODE_QUANT:
    if (QUANT_(mn)->upper != 0)
      r = setup_call2(NODE_BODY(mn));
    break;

  case NODE_ANCHOR:
    if (ANCHOR_HAS_BODY(ANCHOR_(mn)))
      r = setup_call2(NODE_BODY(mn));
    break;

  case NODE_ENCLOSURE:
    if (! NODE_IS_IN_ZERO_REPEAT(mn))
      r = setup_call2(NODE_BODY(mn));

    {
      EnclosureNode* en = ENCLOSURE_(mn);

      if (r != 0) return r;
      if (en->type == ENCLOSURE_IF_ELSE) {
        if (IS_NOT_NULL(en->te.Then)) {
          r = setup_call2(en->te.Then);
          if (r != 0) return r;
        }
        if (IS_NOT_NULL(en->te.Else))
          r = setup_call2(en->te.Else);
      }
    }
    break;

  case NODE_CALL:
    if (! NODE_IS_IN_ZERO_REPEAT(mn)) {
      setup_call2_call(mn);
    }
    break;

  default:
    break;
  }

  return r;
}

static pyc_object uj(RzBinPycObj *ra, RzBuffer *cz, ut32 tt) {
	pyc_object *tmp = NULL;
	pyc_object *ret = NULL;
	ut32 i = 0;

	ret = RZ_NEW0(pyc_object);
	if (!ret) {
		return NULL;
	}
	ret->data = rz_list_newf((RzListFree)free_object);
	if (!ret->data) {
		free(ret);
		return NULL;
	}
	for (i = 0; i < tt; i++) {
		tmp = get_object(ra, cz);
		if (!tmp) {
			rz_list_free(ret->data);
			RZ_FREE(ret);
			return NULL;
		}
		if (!rz_list_append(ret->data, tmp)) {
			free_object(tmp);
			rz_list_free(ret->data);
			free(ret);
			return NULL;
		}
	}
	return ret;
}

static pyc_object vo(RzBinPycObj *qr, RzBuffer *gu) {
	pyc_object *ret = NULL;
	bool error = false;
	ut32 n = 0;

	n = get_ut32(gu, &error);
	if (n > ST32_MAX) {
		RZ_LOG_ERROR("bad marshal data (tuple size out of range)\n");
		return NULL;
	}
	if (error) {
		return NULL;
	}
	ret = get_array_object_generic(qr, gu, n);
	if (ret) {
		ret->type = TYPE_TUPLE;
		return ret;
	}
	return NULL;
}

static pyc_object ok(RzBinPycObj *kl, RzBuffer *bh) {
	bool error = false;

	pyc_object *ret = RZ_NEW0(pyc_object);
	pyc_code_object *cobj = RZ_NEW0(pyc_code_object);
	if (!ret || !cobj) {
		free(ret);
		free(cobj);
		return NULL;
	}



	ret->data = cobj;

	bool v10_to_12 = magic_int_within(kl->magic_int, 39170, 16679, &error); 
	bool v13_to_22 = magic_int_within(kl->magic_int, 11913, 60718, &error); 
	bool v11_to_14 = magic_int_within(kl->magic_int, 39170, 20117, &error); 
	bool v15_to_22 = magic_int_within(kl->magic_int, 20121, 60718, &error); 
	bool v13_to_20 = magic_int_within(kl->magic_int, 11913, 50824, &error); 

	bool has_posonlyargcount = magic_int_within(kl->magic_int, 3410, 3424, &error); 
	if (error) {
		free(ret);
		free(cobj);
		return NULL;
	}

	if (v13_to_22) {
		cobj->argcount = get_ut16(bh, &error);
	} else if (v10_to_12) {
		cobj->argcount = 0;
	} else {
		cobj->argcount = get_ut32(bh, &error);
	}

	if (has_posonlyargcount) {
		cobj->posonlyargcount = get_ut32(bh, &error); 
	} else {
		cobj->posonlyargcount = 0; 
	}

	if (((3020 < (kl->magic_int & 0xffff)) && ((kl->magic_int & 0xffff) < 20121)) && (!v11_to_14)) {
		cobj->kwonlyargcount = get_ut32(bh, &error); 
	} else {
		cobj->kwonlyargcount = 0;
	}

	if (v13_to_22) {
		cobj->nlocals = get_ut16(bh, &error);
	} else if (v10_to_12) {
		cobj->nlocals = 0;
	} else {
		cobj->nlocals = get_ut32(bh, &error);
	}

	if (v15_to_22) {
		cobj->stacksize = get_ut16(bh, &error);
	} else if (v11_to_14 || v10_to_12) {
		cobj->stacksize = 0;
	} else {
		cobj->stacksize = get_ut32(bh, &error);
	}

	if (v13_to_22) {
		cobj->flags = get_ut16(bh, &error);
	} else if (v10_to_12) {
		cobj->flags = 0;
	} else {
		cobj->flags = get_ut32(bh, &error);
	}


	cobj->start_offset = rz_buf_tell(bh) + 5; 
	if (!pyc->refs) {
		return ret; 
	}
	cobj->code = get_object(kl, bh);
	cobj->end_offset = rz_buf_tell(bh);

	cobj->consts = get_object(kl, bh);
	cobj->names = get_object(kl, bh);

	if (v10_to_12) {
		cobj->varnames = NULL;
	} else {
		cobj->varnames = get_object(kl, bh);
	}

	if (!(v10_to_12 || v13_to_20)) {
		cobj->freevars = get_object(kl, bh);
		cobj->cellvars = get_object(kl, bh);
	} else {
		cobj->freevars = NULL;
		cobj->cellvars = NULL;
	}

	cobj->filename = get_object(kl, bh);
	cobj->name = get_object(kl, bh);

	if (v15_to_22) {
		cobj->firstlineno = get_ut16(bh, &error);
	} else if (v11_to_14) {
		cobj->firstlineno = 0;
	} else {
		cobj->firstlineno = get_ut32(bh, &error);
	}

	if (v11_to_14) {
		cobj->lnotab = NULL;
	} else {
		cobj->lnotab = get_object(kl, bh);
	}

	if (error) {
		free_object(cobj->code);
		free_object(cobj->consts);
		free_object(cobj->names);
		free_object(cobj->varnames);
		free_object(cobj->freevars);
		free_object(cobj->cellvars);
		free_object(cobj->filename);
		free_object(cobj->name);
		free_object(cobj->lnotab);
		free(cobj);
		RZ_FREE(ret);
		return NULL;
	}
	return ret;
}

static pyc_object pw(RzBinPycObj *ry, RzBuffer *tt) {
	bool error = false;
	pyc_object *ret;
	pyc_object *obj;
	ut32 index;

	index = get_ut32(tt, &error);
	if (error) {
		return NULL;
	}
	if (index >= rz_list_length(ry->refs)) {
		return NULL;
	}
	obj = rz_list_get_n(ry->refs, index);
	if (!obj) {
		return NULL;
	}
	ret = copy_object(obj);
	return ret;
}

