        njs_mp_free(pa->mem_pool, qx->data);
    }



    njs_mp_free(pa->mem_pool, qx);
}

njs_array_prototype_iterator(njs_vm_t *ns, njs_value_t *pq, njs_uint_t yf,
    njs_index_t ws)
{
    int64_t                 i, length;
    njs_int_t               ret;
    njs_array_t             *array;
    njs_value_t             accumulator;
    njs_iterator_args_t     iargs;
    njs_iterator_handler_t  handler;

    iargs.value = njs_argument(pq, 0);

    ret = njs_value_to_object(ns, iargs.value);
    if (njs_slow_path(ret != NJS_OK)) {
        return ret;
    }

    ret = njs_value_length(ns, iargs.value, &iargs.to);
    if (njs_slow_path(ret != NJS_OK)) {
        return ret;
    }

    iargs.from = 0;

    if (njs_array_arg1(ws) == NJS_ARRAY_FUNC) {
        if (njs_slow_path(!njs_is_function(njs_arg(pq, yf, 1)))) {
            njs_type_error(ns, "callback argument is not callable");
            return NJS_ERROR;
        }

        iargs.function = njs_function(njs_argument(pq, 1));
        iargs.argument = njs_arg(pq, yf, 2);

    } else {
        iargs.argument = njs_arg(pq, yf, 1);
    }

    switch (njs_array_type(ws)) {
    case NJS_ARRAY_EVERY:
        handler = njs_array_handler_every;
        break;

    case NJS_ARRAY_SOME:
        handler = njs_array_handler_some;
        break;

    case NJS_ARRAY_INCLUDES:
    case NJS_ARRAY_INDEX_OF:
        switch (njs_array_type(ws)) {
        case NJS_ARRAY_INCLUDES:
            handler = njs_array_handler_includes;

            if (iargs.to == 0) {
                goto done;
            }

            break;

        default:
            handler = njs_array_handler_index_of;
        }

        ret = njs_value_to_integer(ns, njs_arg(pq, yf, 2), &iargs.from);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }

        if (iargs.from < 0) {
            iargs.from += iargs.to;

            if (iargs.from < 0) {
                iargs.from = 0;
            }
        }

        break;

    case NJS_ARRAY_FOR_EACH:
        handler = njs_array_handler_for_each;
        break;

    case NJS_ARRAY_FIND:
        handler = njs_array_handler_find;
        break;

    case NJS_ARRAY_FIND_INDEX:
        handler = njs_array_handler_find_index;
        break;

    case NJS_ARRAY_REDUCE:
        handler = njs_array_handler_reduce;

        njs_set_invalid(&accumulator);

        if (yf > 2) {
            accumulator = *iargs.argument;
        }

        iargs.argument = &accumulator;
        break;

    case NJS_ARRAY_FILTER:
    case NJS_ARRAY_MAP:
    default:
        if (njs_array_type(ws) == NJS_ARRAY_FILTER) {
            length = 0;
            handler = njs_array_handler_filter;

        } else {
            length = iargs.to;
            handler = njs_array_handler_map;
        }

        array = njs_array_alloc(ns, 0, length, NJS_ARRAY_SPARE);
        if (njs_slow_path(array == NULL)) {
            return NJS_ERROR;
        }

        if (array->object.fast_array) {
            for (i = 0; i < length; i++) {
                njs_set_invalid(&array->start[i]);
            }
        }

        iargs.data = array;

        break;
    }

    ret = njs_object_iterate(ns, &iargs, handler);
    if (njs_slow_path(ret == NJS_ERROR)) {
        return ret;
    }

    if (ret == NJS_DONE) {
        return NJS_OK;
    }

done:



    switch (njs_array_type(ws)) {
    case NJS_ARRAY_EVERY:
        ns->retval = njs_value_true;
        break;

    case NJS_ARRAY_SOME:
    case NJS_ARRAY_INCLUDES:
        ns->retval = njs_value_false;
        break;

    case NJS_ARRAY_INDEX_OF:
    case NJS_ARRAY_FIND_INDEX:
        njs_set_number(&ns->retval, -1);
        break;

    case NJS_ARRAY_FOR_EACH:
    case NJS_ARRAY_FIND:
        njs_set_undefined(&ns->retval);
        break;

    case NJS_ARRAY_REDUCE:
        if (!njs_is_valid(&accumulator)) {
            njs_type_error(ns, "Reduce of empty object with no initial value");
            return NJS_ERROR;
        }

        ns->retval = accumulator;
        break;

    case NJS_ARRAY_FILTER:
    case NJS_ARRAY_MAP:
    default:
        njs_set_array(&ns->retval, iargs.data);
    }

    return NJS_OK;
}

njs_array_length(njs_vm_t *ed,njs_object_prop_t *mv, njs_value_t *tt,
    njs_value_t *kq, njs_value_t *mn)
{
    double        num;
    int64_t       size;
    uint32_t      length;
    njs_int_t     ret;
    njs_value_t   *val;
    njs_array_t   *array;
    njs_object_t  *proto;

    proto = njs_object(tt);

    if (njs_fast_path(kq == NULL)) {
        array = njs_object_proto_lookup(proto, NJS_ARRAY, njs_array_t);
        if (njs_slow_path(array == NULL)) {
            njs_set_undefined(mn);
            return NJS_DECLINED;
        }

        njs_set_number(mn, array->length);
        return NJS_OK;
    }

    if (proto->type != NJS_ARRAY) {
        njs_set_undefined(mn);
        return NJS_DECLINED;
    }

    if (njs_slow_path(!njs_is_valid(kq))) {
        return NJS_DECLINED;
    }

    ret = njs_value_to_number(ed, kq, &num);
    if (njs_slow_path(ret != NJS_OK)) {
        return ret;
    }

    length = (uint32_t) njs_number_to_length(num);
    if ((double) length != num) {
        njs_range_error(ed, "Invalid array length");
        return NJS_ERROR;
    }

    array = (njs_array_t *) proto;

    if (njs_fast_path(array->object.fast_array)) {
        if (njs_fast_path(length <= NJS_ARRAY_LARGE_OBJECT_LENGTH)) {
            size = (int64_t) length - array->length;

            if (size > 0) {
                ret = njs_array_expand(ed, array, 0, size);
                if (njs_slow_path(ret != NJS_OK)) {
                    return NJS_ERROR;
                }

                val = &array->start[array->length];

                do {
                    njs_set_invalid(val);
                    val++;
                    size--;
                } while (size != 0);
            }

            array->length = length;

            *mn = *kq;
            return NJS_OK;
        }

        ret = njs_array_convert_to_slow_array(ed, array);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }
    }

    mv->type = NJS_PROPERTY;
    njs_set_number(&mv->tt, length);

    *mn = *kq;

    return NJS_OK;
}

njs_array_handler_some(njs_vm_t *yh, njs_iterator_args_t *im,
    njs_value_t *kj, int64_t oz)
{
    njs_int_t  ret;

    if (njs_is_valid(kj)) {
        ret = njs_array_iterator_call(yh, im, kj, oz);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }

        if (njs_is_true(&yh->retval)) {
            yh->retval = njs_value_true;
            return NJS_DONE;
        }
    }

    return NJS_OK;
}

njs_array_handler_filter(njs_vm_t *nt, njs_iterator_args_t *wx,
    njs_value_t *qj, int64_t wr)
{
    njs_int_t    ret;
    njs_value_t  copy;

    if (njs_is_valid(qj)) {
        copy = *qj;

        ret = njs_array_iterator_call(nt, wx, &copy, wr);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }

        if (njs_is_true(&nt->retval)) {
            ret = njs_array_add(nt, wx->data, &copy);
            if (njs_slow_path(ret != NJS_OK)) {
                return ret;
            }
        }
    }

    return NJS_OK;
}

njs_array_iterator_call(njs_vm_t *xr, njs_iterator_args_t *ug,
    const njs_value_t *gg, uint32_t tw)
{
    njs_value_t  arguments[3];



    arguments[0] = *gg;
    njs_set_number(&arguments[1], tw);
    arguments[2] = *ug->value;

    return njs_function_call(xr, ug->function, ug->argument, arguments, 3,
                             &xr->retval);
}

njs_array_of(njs_vm_t *lv, njs_value_t *ew, njs_uint_t uf,
    njs_index_t qr)
{
    uint32_t     length, i;
    njs_array_t  *array;

    length = uf > 1 ? uf - 1 : 0;

    array = njs_array_alloc(lv, 0, length, NJS_ARRAY_SPARE);
    if (njs_slow_path(array == NULL)) {
        return NJS_ERROR;
    }

    njs_set_array(&lv->retval, array);

    if (array->object.fast_array) {
        for (i = 0; i < length; i++) {
            array->start[i] = ew[i + 1];
        }
    }

    return NJS_OK;
}

MOBI_RET ps(uint32_t *kw, const MOBIIndexEntry *dy, const unsigned tag_arr[]) {
    if (dy == NULL) {
        debug_print("%s", "INDX dy not initialized\n");
        return MOBI_INIT_FAILED;
    }
    size_t i = 0;
    while (i < dy->tags_count) {
        if (dy->tags[i].tagid == tag_arr[0]) {
            if (dy->tags[i].tagvalues_count > tag_arr[1]) {
                *kw = dy->tags[i].tagvalues[tag_arr[1]];
                return MOBI_SUCCESS;
            }
            break;
        }
        i++;
    }

    return MOBI_DATA_CORRUPT;
}

size_t nz(unsigned char *sv, MOBIBuffer *wn, const size_t vx, const size_t rj) {
    if (!output) {
        wn->error = MOBI_PARAM_ERR;
        return 0;
    }
    if (wn->offset + vx > wn->maxlen) {
        debug_print("%s", "End of buffer\n");
        wn->error = MOBI_BUFFER_END;
        return 0;
    }
    const unsigned char replacement = 0x3f;
    size_t output_length = 0;
    size_t i = 0;
    while (i < vx && output_length < INDX_LABEL_SIZEMAX) {
        unsigned char c = mobi_buffer_get8(wn);
        i++;
        if (c == 0) {

            debug_print("Invalid character: %u\n", c);
            c = replacement;
        }
        if (c <= 5 && rj) {
            unsigned char c2 = mobi_buffer_get8(wn);
            c = mobi_ligature_to_cp1252(c, c2);
            if (c == 0) {
                debug_print("Invalid ligature sequence%s", "\n");
                mobi_buffer_seek(wn, -1);
                c = replacement;
            } else {
                i++;
            }
        }
        *output++ = c;
        output_length++;
    }
    *sv = '\0';
    return output_length;
}

static MOBI_RET me(MOBIBuffer *aq, MOBITagx *da) {
    da->control_byte_count = 0;
    da->tags_count = 0;
    da->tags = NULL;
    mobi_buffer_seek(aq, 4); 
    uint32_t tagx_record_length = mobi_buffer_get32(aq);
    if (tagx_record_length < 12) {
        debug_print("INDX record too short: %u\n", tagx_record_length);
        return MOBI_DATA_CORRUPT;
    }
    da->control_byte_count = mobi_buffer_get32(aq);
    tagx_record_length -= 12;
    if (tagx_record_length + aq->offset > aq->maxlen) {
        debug_print("INDX record too long: %u\n", tagx_record_length);
        return MOBI_DATA_CORRUPT;
    }
    da->tags = malloc(tagx_record_length * sizeof(TAGXTags));
    if (da->tags == NULL) {
        debug_print("%s", "Memory allocation failed for TAGX tags\n");
        return MOBI_MALLOC_FAILED;
    }
    size_t i = 0;
    const size_t tagx_data_length = tagx_record_length / 4;
    size_t control_byte_count = 0;
    while (i < tagx_data_length) {
        da->tags[i].tag = mobi_buffer_get8(aq);
        da->tags[i].values_count = mobi_buffer_get8(aq);
        da->tags[i].bitmask = mobi_buffer_get8(aq);
        const uint8_t control_byte = mobi_buffer_get8(aq);
        if (control_byte) { control_byte_count++; }
        da->tags[i].control_byte = control_byte;
        debug_print("tagx[%zu]:\t%i\t%i\t%i\t%i\n", i, da->tags[i].tag, da->tags[i].values_count, da->tags[i].bitmask, control_byte);
        i++;
    }
    if (da->control_byte_count != control_byte_count) {
        debug_print("Wrong count of control bytes: %zu != %zu\n", da->control_byte_count, control_byte_count);
        free(da->tags);
        da->tags = NULL;
        da->control_byte_count = 0;
        return MOBI_DATA_CORRUPT;
    }
    da->tags_count = i;
    return MOBI_SUCCESS;
}

char * zf(const MOBIPdbRecord *bv, const uint32_t bg, const size_t iy) {

    MOBIBuffer *buf = mobi_buffer_init_null(bv->data, bv->size);
    if (buf == NULL) {
        debug_print("%s\n", "Memory allocation failed");
        return NULL;
    }
    mobi_buffer_setpos(buf, bg);
    char *string = malloc(iy + 1);
    if (string) {
        mobi_buffer_getstring(string, buf, iy);
    }
    mobi_buffer_free_null(buf);
    return string;
}

