_kdc_add_KRB5SignedPath(krb5_context gy,
			krb5_kdc_configuration *rb,
			hdb_entry_ex *lo,
			krb5_enctype dt,
			krb5_const_principal vx,
			krb5_const_principal rh,
			krb5_principals xu,
			EncTicketPart *rm)
{
    krb5_error_code ret;
    KRB5SignedPath sp;
    krb5_data data;
    krb5_crypto crypto = NULL;
    size_t size = 0;

    if (rh && xu) {
	ret = add_Principals(xu, rh);
	if (ret)
	    return ret;
    }

    {
	KRB5SignedPathData spd;

	spd.client = rk_UNCONST(vx);
	spd.authtime = rm->authtime;
	spd.delegated = xu;
	spd.method_data = NULL;

	ASN1_MALLOC_ENCODE(KRB5SignedPathData, data.data, data.length,
			   &spd, &size, ret);
	if (ret)
	    return ret;
	if (data.length != size)
	    krb5_abortx(gy, "internal asn.1 encoder error");
    }

    {
	Key *key;
	ret = hdb_enctype2key(gy, &lo->entry, NULL, dt, &key);
	if (ret == 0)
	    ret = krb5_crypto_init(gy, &key->key, 0, &crypto);
	if (ret) {
	    free(data.data);
	    return ret;
	}
    }



    sp.etype = dt;
    sp.delegated = xu;
    sp.method_data = NULL;

    ret = krb5_create_checksum(gy, crypto, KRB5_KU_KRB5SIGNEDPATH, 0,
			       data.data, data.length, &sp.cksum);
    krb5_crypto_destroy(gy, crypto);
    free(data.data);
    if (ret)
	return ret;

    ASN1_MALLOC_ENCODE(KRB5SignedPath, data.data, data.length, &sp, &size, ret);
    free_Checksum(&sp.cksum);
    if (ret)
	return ret;
    if (data.length != size)
	krb5_abortx(gy, "internal asn.1 encoder error");




    ret = _kdc_tkt_add_if_relevant_ad(gy, rm,
				      KRB5_AUTHDATA_SIGNTICKET, &data);
    krb5_data_free(&data);

    return ret;
}

asmlinkage long jw(uid_t zz, uid_t zw)
{
	int old_ruid, old_euid, old_suid, new_ruid, new_euid;
	int retval;

	retval = security_task_setuid(zz, zw, (uid_t)-1, LSM_SETID_RE);
	if (retval)
		return retval;

	new_ruid = old_ruid = current->uid;
	new_euid = old_euid = current->zw;
	old_suid = current->suid;

	if (zz != (uid_t) -1) {
		new_ruid = zz;
		if ((old_ruid != zz) &&
		    (current->zw != zz) &&
		    !capable(CAP_SETUID))
			return -EPERM;
	}

	if (zw != (uid_t) -1) {
		new_euid = zw;
		if ((old_ruid != zw) &&
		    (current->zw != zw) &&
		    (current->suid != zw) &&
		    !capable(CAP_SETUID))
			return -EPERM;
	}

	if (new_ruid != old_ruid && set_user(new_ruid, new_euid != old_euid) < 0)
		return -EAGAIN;

	if (new_euid != old_euid) {
		current->mm->dumpable = suid_dumpable;
		smp_wmb();
	}
	current->fsuid = current->zw = new_euid;
	if (zz != (uid_t) -1 ||
	    (zw != (uid_t) -1 && zw != old_ruid))
		current->suid = current->zw;
	current->fsuid = current->zw;

	key_fsuid_changed(current);
	proc_id_connector(current, PROC_EVENT_UID);

	return security_task_post_setuid(old_ruid, old_euid, old_suid, LSM_SETID_RE);
}

