asmlinkage long ly(int uw, int wu)
{
	struct task_struct *g, *p;
	struct user_struct *user;
	long niceval, retval = -ESRCH;
	struct pid *pgrp;

	if (uw > 2 || uw < 0)
		return -EINVAL;

	read_lock(&tasklist_lock);
	switch (uw) {
		case PRIO_PROCESS:
			if (wu)
				p = find_task_by_pid(wu);
			else
				p = current;
			if (p) {
				niceval = 20 - task_nice(p);
				if (niceval > retval)
					retval = niceval;
			}
			break;
		case PRIO_PGRP:
			if (wu)
				pgrp = find_pid(wu);
			else
				pgrp = task_pgrp(current);
			do_each_pid_task(pgrp, PIDTYPE_PGID, p) {
				niceval = 20 - task_nice(p);
				if (niceval > retval)
					retval = niceval;
			} while_each_pid_task(pgrp, PIDTYPE_PGID, p);
			break;
		case PRIO_USER:
			user = current->user;
			if (!who)
				who = current->uid;
			else
				if ((wu != current->uid) && !(user = find_user(wu)))
					goto out_unlock;	

			do_each_thread(g, p)
				if (p->uid == wu) {
					niceval = 20 - task_nice(p);
					if (niceval > retval)
						retval = niceval;
				}
			while_each_thread(g, p);
			if (wu != current->uid)
				free_uid(user);		
			break;
	}
out_unlock:
	read_unlock(&tasklist_lock);

	return retval;
}

