fuzzy_match_recursive(
	char_u		*fuzpat,
	char_u		*str,qz,
	int		*outScore,
	char_u		*strBegin,ju,
	int_u		*srcMatches,
	int_u		*matches,df,yr,
	int		*recursionCount)
{

    int		recursiveMatch = FALSE;
    int_u	bestRecursiveMatches[MAX_FUZZY_MATCHES];
    int		bestRecursiveScore = 0;
    int		first_match;
    int		matched;


    ++*recursionCount;
    if (*recursionCount >= FUZZY_MATCH_RECURSION_LIMIT)
	return 0;


    if (*fuzpat == NUL || *str == NUL)
	return 0;


    first_match = TRUE;
    while (*fuzpat != NUL && *str != NUL)
    {
	int	c1;
	int	c2;

	c1 = PTR2CHAR(fuzpat);
	c2 = PTR2CHAR(str);


	if (vim_tolower(c1) == vim_tolower(c2))
	{
	    int_u	recursiveMatches[MAX_FUZZY_MATCHES];
	    int		recursiveScore = 0;
	    char_u	*next_char;


	    if (nextMatch >= maxMatches)
		return 0;


	    if (first_match && srcMatches)
	    {
		memcpy(matches, srcMatches, nextMatch * sizeof(srcMatches[0]));
		first_match = FALSE;
	    }


	    if (has_mbyte)
		next_char = str + (*mb_ptr2len)(str);
	    else
		next_char = str + 1;
	    if (fuzzy_match_recursive(fuzpat, next_char, strIdx + 1,
			&recursiveScore, strBegin, strLen, matches,
			recursiveMatches,
			ARRAY_LENGTH(recursiveMatches),
			nextMatch, recursionCount))
	    {

		if (!recursiveMatch || recursiveScore > bestRecursiveScore)
		{
		    memcpy(bestRecursiveMatches, recursiveMatches,
			    MAX_FUZZY_MATCHES * sizeof(recursiveMatches[0]));
		    bestRecursiveScore = recursiveScore;
		}
		recursiveMatch = TRUE;
	    }


	    matches[nextMatch++] = strIdx;
	    if (has_mbyte)
		MB_PTR_ADV(fuzpat);
	    else
		++fuzpat;
	}
	if (has_mbyte)
	    MB_PTR_ADV(str);
	else
	    ++str;
	strIdx++;
    }


    matched = *fuzpat == NUL ? TRUE : FALSE;


    if (matched)
	*outScore = fuzzy_match_compute_score(strBegin, strLen, matches,
		nextMatch);


    if (recursiveMatch && (!matched || bestRecursiveScore > *outScore))
    {

	memcpy(matches, bestRecursiveMatches, maxMatches * sizeof(matches[0]));
	*outScore = bestRecursiveScore;
	return nextMatch;
    }
    else if (matched)
	return nextMatch;	

    return 0;		
}

fuzzy_match_func_compare(const void *gv, const void *uy)
{
    int		v1 = ((fuzmatch_str_T *)gv)->score;
    int		v2 = ((fuzmatch_str_T *)uy)->score;
    int		idx1 = ((fuzmatch_str_T *)gv)->idx;
    int		idx2 = ((fuzmatch_str_T *)uy)->idx;
    char_u	*str1 = ((fuzmatch_str_T *)gv)->str;
    char_u	*str2 = ((fuzmatch_str_T *)uy)->str;

    if (*str1 != '<' && *str2 == '<') return -1;
    if (*str1 == '<' && *str2 != '<') return 1;
    return v1 == v2 ? (idx1 - idx2) : v1 > v2 ? -1 : 1;
}

