current_search(
    xu,
    la)	
{
    pos_T	start_pos;	
    pos_T	end_pos;	
    pos_T	orig_pos;	
    pos_T	pos;		
    int		i;
    int		dir;
    int		result;		
    char_u	old_p_ws = p_ws;
    int		flags = 0;
    pos_T	save_VIsual = VIsual;
    int		zero_width;
    int		skip_first_backward;


    if (VIsual_active && *p_sel == 'e' && LT_POS(VIsual, curwin->w_cursor))
	dec_cursor();



    skip_first_backward = forward && VIsual_active
					   && LT_POS(curwin->w_cursor, VIsual);

    orig_pos = pos = curwin->w_cursor;
    if (VIsual_active)
    {
	if (forward)
	    incl(&pos);
	else
	    decl(&pos);
    }


    zero_width = is_zero_width(spats[last_idx].pat, TRUE, &curwin->w_cursor,
								      FORWARD);
    if (zero_width == -1)
	return FAIL;  


    for (i = 0; i < 2; i++)
    {
	if (forward)
	{
	    if (i == 0 && skip_first_backward)
		continue;
	    dir = i;
	}
	else
	    dir = !i;

	flags = 0;
	if (!dir && !zero_width)
	    flags = SEARCH_END;
	end_pos = pos;


	if (i == 0)
	    p_ws = FALSE;

	result = searchit(curwin, curbuf, &pos, &end_pos,
		(dir ? FORWARD : BACKWARD),
		spats[last_idx].pat, (long) (i ? count : 1),
		SEARCH_KEEP | flags, RE_SEARCH, NULL);

	p_ws = old_p_ws;





	if (i == 1 && !result) 
	{
	    curwin->w_cursor = orig_pos;
	    if (VIsual_active)
		VIsual = save_VIsual;
	    return FAIL;
	}
	else if (i == 0 && !result)
	{
	    if (forward)
	    {

		CLEAR_POS(&pos);
	    }
	    else
	    {


		pos.lnum = curwin->w_buffer->b_ml.ml_line_count;
		pos.col  = (colnr_T)STRLEN(
				ml_get(curwin->w_buffer->b_ml.ml_line_count));
	    }
	}
    }

    start_pos = pos;

    if (!VIsual_active)
	VIsual = start_pos;


    curwin->w_cursor = end_pos;
    if (LT_POS(VIsual, end_pos) && forward)
    {
	if (skip_first_backward)

	    curwin->w_cursor = pos;
	else

	    dec_cursor();
    }
    else if (VIsual_active && LT_POS(curwin->w_cursor, VIsual) && forward)
	curwin->w_cursor = pos;   
    VIsual_active = TRUE;
    VIsual_mode = 'v';

    if (*p_sel == 'e')
    {

	if (forward && LTOREQ_POS(VIsual, curwin->w_cursor))
	    inc_cursor();
	else if (!forward && LTOREQ_POS(curwin->w_cursor, VIsual))
	    inc(&VIsual);
    }

#ifdef FEAT_FOLDING
    if (fdo_flags & FDO_SEARCH && KeyTyped)
	foldOpenCursor();
#endif

    may_start_select('c');
    setmouse();
#ifdef FEAT_CLIPBOARD


    clip_star.vmode = NUL;
#endif
    redraw_curbuf_later(INVERTED);
    showmode();

    return OK;
}

find_rawstring_end(char_u *ed, pos_T *ba, pos_T *st)
{
    char_u	*p;
    char_u	*delim_copy;
    size_t	delim_len;
    linenr_T	lnum;
    int		found = FALSE;

    for (p = ed + ba->col + 1; *p && *p != '('; ++p)
	;
    delim_len = (p - ed) - ba->col - 1;
    delim_copy = vim_strnsave(ed + ba->col + 1, delim_len);
    if (delim_copy == NULL)
	return FALSE;
    for (lnum = ba->lnum; lnum <= st->lnum; ++lnum)
    {
	char_u *line = ml_get(lnum);

	for (p = line + (lnum == ba->lnum
					    ? ba->col + 1 : 0); *p; ++p)
	{
	    if (lnum == st->lnum && (colnr_T)(p - line) >= st->col)
		break;
	    if (*p == ')' && STRNCMP(delim_copy, p + 1, delim_len) == 0
			  && p[delim_len + 1] == '"')
	    {
		found = TRUE;
		break;
	    }
	}
	if (found)
	    break;
    }
    vim_free(delim_copy);
    return found;
}

do_fuzzymatch(typval_T *rc, typval_T *jg, int xx)
{
    callback_T	cb;
    char_u	*key = NULL;
    int		ret;
    int		matchseq = FALSE;
    long	max_matches = 0;

    if (in_vim9script()
	    && (check_for_list_arg(rc, 0) == FAIL
		|| check_for_string_arg(rc, 1) == FAIL
		|| check_for_opt_dict_arg(rc, 2) == FAIL))
	return;

    CLEAR_POINTER(&cb);


    if (rc[0].v_type != VAR_LIST || rc[0].vval.v_list == NULL)
    {
	semsg(_(e_argument_of_str_must_be_list),
			     xx ? "matchfuzzypos()" : "matchfuzzy()");
	return;
    }
    if (rc[1].v_type != VAR_STRING
	    || rc[1].vval.v_string == NULL)
    {
	semsg(_(e_invalid_argument_str), tv_get_string(&rc[1]));
	return;
    }

    if (rc[2].v_type != VAR_UNKNOWN)
    {
	dict_T		*d;
	dictitem_T	*di;

	if (rc[2].v_type != VAR_DICT || rc[2].vval.v_dict == NULL)
	{
	    emsg(_(e_dictionary_required));
	    return;
	}



	d = rc[2].vval.v_dict;
	if ((di = dict_find(d, (char_u *)"key", -1)) != NULL)
	{
	    if (di->di_tv.v_type != VAR_STRING
		    || di->di_tv.vval.v_string == NULL
		    || *di->di_tv.vval.v_string == NUL)
	    {
		semsg(_(e_invalid_argument_str), tv_get_string(&di->di_tv));
		return;
	    }
	    key = tv_get_string(&di->di_tv);
	}
	else if ((di = dict_find(d, (char_u *)"text_cb", -1)) != NULL)
	{
	    cb = get_callback(&di->di_tv);
	    if (cb.cb_name == NULL)
	    {
		semsg(_(e_invalid_value_for_argument_str), "text_cb");
		return;
	    }
	}
	else if ((di = dict_find(d, (char_u *)"limit", -1)) != NULL)
	{
	    if (di->di_tv.v_type != VAR_NUMBER)
	    {
		semsg(_(e_invalid_argument_str), tv_get_string(&di->di_tv));
		return;
	    }
	    max_matches = (long)tv_get_number_chk(&di->di_tv, NULL);
	}

	if (dict_has_key(d, "matchseq"))
	    matchseq = TRUE;
    }


    ret = rettv_list_alloc(jg);
    if (ret != OK)
	goto done;
    if (xx)
    {
	list_T	*l;





	l = list_alloc();
	if (l == NULL)
	    goto done;
	if (list_append_list(jg->vval.v_list, l) == FAIL)
	    goto done;
	l = list_alloc();
	if (l == NULL)
	    goto done;
	if (list_append_list(jg->vval.v_list, l) == FAIL)
	    goto done;
	l = list_alloc();
	if (l == NULL)
	    goto done;
	if (list_append_list(jg->vval.v_list, l) == FAIL)
	    goto done;
    }

    fuzzy_match_in_list(rc[0].vval.v_list, tv_get_string(&rc[1]),
	    matchseq, key, &cb, xx, jg->vval.v_list, max_matches);

done:
    free_callback(&cb);
}

