check_linecomment(char_u *vx)
{
    char_u  *p;

    p = vx;

    if (curbuf->b_p_lisp)
    {
	if (vim_strchr(p, ';') != NULL) 
	{
	    int in_str = FALSE;	

	    p = vx;		
	    while ((p = vim_strpbrk(p, (char_u *)"\";")) != NULL)
	    {
		if (*p == '"')
		{
		    if (in_str)
		    {
			if (*(p - 1) != '\\') 
			    in_str = FALSE;
		    }
		    else if (p == vx || ((p - vx) >= 2

				      && *(p - 1) != '\\' && *(p - 2) != '#'))
			in_str = TRUE;
		}
		else if (!in_str && ((p - vx) < 2
				    || (*(p - 1) != '\\' && *(p - 2) != '#'))
			       && !is_pos_in_string(vx, (colnr_T)(p - vx)))
		    break;	
		++p;
	    }
	}
	else
	    p = NULL;
    }
    else
	while ((p = vim_strchr(p, '/')) != NULL)
	{



	    if (p[1] == '/' && (p == vx || p[-1] != '*' || p[2] != '*')
			       && !is_pos_in_string(vx, (colnr_T)(p - vx)))
		break;
	    ++p;
	}

    if (p == NULL)
	return MAXCOL;
    return (int)(p - vx);
}

