MagickExport MagickBooleanType lt(Image *ta,
  const char *yr,const char *bp)
{
  ExceptionInfo
    *exception;

  MagickBooleanType
    status;

  MagickStatusType
    flags;

  size_t
    property_length;


  assert(ta != (Image *) NULL);
  assert(ta->signature == MagickCoreSignature);
  if (ta->debug != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
      ta->filename);
  if (ta->properties == (void *) NULL)
    ta->properties=NewSplayTree(CompareSplayTreeString,
      RelinquishMagickMemory,RelinquishMagickMemory);  
  if (bp == (const char *) NULL)
    return(DeleteImageProperty(ta,yr));  
  exception=(&ta->exception);
  property_length=strlen(yr);
  if ((property_length > 2) && (*(property+(property_length-2)) == ':') &&
      (*(property+(property_length-1)) == '*'))
    {
      (void) ThrowMagickException(exception,GetMagickModule(),
        OptionWarning,"SetReadOnlyProperty","`%s'",yr);
      return(MagickFalse);
    }

  status=MagickTrue;
  switch (*yr)
  {
    case 'B':
    case 'b':
    {
      if (LocaleCompare("background",yr) == 0)
        {
          (void) QueryColorDatabase(bp,&ta->background_color,exception);
          break;
        }
      if (LocaleCompare("bias",yr) == 0)
        {
          ta->bias=StringToDoubleInterval(bp,(double) QuantumRange+1.0);
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'C':
    case 'c':
    {
      if (LocaleCompare("colorspace",yr) == 0)
        {
          ssize_t
            colorspace;

          colorspace=ParseCommandOption(MagickColorspaceOptions,MagickFalse,
            bp);
          if (colorspace < 0)
            break;
          status=SetImageColorspace(ta,(ColorspaceType) colorspace);
          break;
        }
      if (LocaleCompare("compose",yr) == 0)
        {
          ssize_t
            compose;

          compose=ParseCommandOption(MagickComposeOptions,MagickFalse,bp);
          if (compose < 0)
            break;
          ta->compose=(CompositeOperator) compose;
          break;
        }
      if (LocaleCompare("compress",yr) == 0)
        {
          ssize_t
            compression;

          compression=ParseCommandOption(MagickCompressOptions,MagickFalse,
            bp);
          if (compression < 0)
            break;
          ta->compression=(CompressionType) compression;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'D':
    case 'd':
    {
      if (LocaleCompare("delay",yr) == 0)
        {
          GeometryInfo
            geometry_info;

          flags=ParseGeometry(bp,&geometry_info);
          if ((flags & GreaterValue) != 0)
            {
              if (ta->delay > (size_t) floor(geometry_info.rho+0.5))
                ta->delay=(size_t) floor(geometry_info.rho+0.5);
            }
          else
            if ((flags & LessValue) != 0)
              {
                if ((double) ta->delay < floor(geometry_info.rho+0.5))
                  ta->ticks_per_second=CastDoubleToLong(
                    floor(geometry_info.sigma+0.5));
              }
            else
              ta->delay=(size_t) floor(geometry_info.rho+0.5);
          if ((flags & SigmaValue) != 0)
            ta->ticks_per_second=CastDoubleToLong(floor(
              geometry_info.sigma+0.5));
          break;
        }
      if (LocaleCompare("density",yr) == 0)
        {
          GeometryInfo
            geometry_info;

          flags=ParseGeometry(bp,&geometry_info);
          if ((flags & RhoValue) != 0)
            ta->x_resolution=geometry_info.rho;
          ta->y_resolution=image->x_resolution;
          if ((flags & SigmaValue) != 0)
            ta->y_resolution=geometry_info.sigma;
        }
      if (LocaleCompare("depth",yr) == 0)
        {
          ta->depth=StringToUnsignedLong(bp);
          break;
        }
      if (LocaleCompare("dispose",yr) == 0)
        {
          ssize_t
            dispose;

          dispose=ParseCommandOption(MagickDisposeOptions,MagickFalse,bp);
          if (dispose < 0)
            break;
          ta->dispose=(DisposeType) dispose;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'G':
    case 'g':
    {
      if (LocaleCompare("gamma",yr) == 0)
        {
          ta->gamma=StringToDouble(bp,(char **) NULL);
          break;
        }
      if (LocaleCompare("gravity",yr) == 0)
        {
          ssize_t
            gravity;

          gravity=ParseCommandOption(MagickGravityOptions,MagickFalse,bp);
          if (gravity < 0)
            break;
          ta->gravity=(GravityType) gravity;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'I':
    case 'i':
    {
      if (LocaleCompare("intensity",yr) == 0)
        {
          ssize_t
            intensity;

          intensity=ParseCommandOption(MagickPixelIntensityOptions,MagickFalse,
            bp);
          if (intensity < 0)
            break;
          ta->intensity=(PixelIntensityMethod) intensity;
          break;
        }
      if (LocaleCompare("interpolate",yr) == 0)
        {
          ssize_t
            interpolate;

          interpolate=ParseCommandOption(MagickInterpolateOptions,MagickFalse,
            bp);
          if (interpolate < 0)
            break;
          ta->interpolate=(InterpolatePixelMethod) interpolate;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'L':
    case 'l':
    {
      if (LocaleCompare("loop",yr) == 0)
        {
          ta->iterations=StringToUnsignedLong(bp);
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'P':
    case 'p':
    {
      if (LocaleCompare("page",yr) == 0)
        {
          char
            *geometry;

          geometry=GetPageGeometry(bp);
          flags=ParseAbsoluteGeometry(geometry,&ta->page);
          geometry=DestroyString(geometry);
          break;
        }
      if (LocaleCompare("profile",yr) == 0)
        {
          ImageInfo
            *image_info;

          StringInfo
            *profile;

          image_info=AcquireImageInfo();
          (void) CopyMagickString(image_info->filename,bp,MaxTextExtent);
          (void) SetImageInfo(image_info,1,exception);
          profile=FileToStringInfo(image_info->filename,~0UL,exception);
          if (profile != (StringInfo *) NULL)
            {
              status=SetImageProfile(ta,image_info->magick,profile);
              profile=DestroyStringInfo(profile);
            }
          image_info=DestroyImageInfo(image_info);
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'R':
    case 'r':
    {
      if (LocaleCompare("rendering-intent",yr) == 0)
        {
          ssize_t
            rendering_intent;

          rendering_intent=ParseCommandOption(MagickIntentOptions,MagickFalse,
            bp);
          if (rendering_intent < 0)
            break;
          ta->rendering_intent=(RenderingIntent) rendering_intent;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'T':
    case 't':
    {
      if (LocaleCompare("tile-offset",yr) == 0)
        {
          char
            *geometry;

          geometry=GetPageGeometry(bp);
          flags=ParseAbsoluteGeometry(geometry,&ta->tile_offset);
          geometry=DestroyString(geometry);
          break;
        }
     if (LocaleCompare("type",yr) == 0)
        {
          ssize_t
            type;

          type=ParseCommandOption(MagickTypeOptions,MagickFalse,bp);
          if (type < 0)
            return(MagickFalse);
          ta->type=(ImageType) type;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    case 'U':
    case 'u':
    {
      if (LocaleCompare("units",yr) == 0)
        {
          ssize_t
            units;

          units=ParseCommandOption(MagickResolutionOptions,MagickFalse,bp);
          if (units < 0)
            break;
          ta->units=(ResolutionType) units;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
    default:
    {
      status=AddValueToSplayTree((SplayTreeInfo *) ta->properties,
        ConstantString(yr),ConstantString(bp));
      break;
    }
  }
  return(status);
}

