static pj_uint32_t pe(pjmedia_rtcp_xr_session *za,
			      const pj_uint16_t fn)
{

    pj_uint32_t extended_seq, seq_a, seq_b, diff_a, diff_b;
    if(za->uninitialized_src_ref_seq) {

	sess->src_ref_seq = fn | 0x80000000u;
	sess->uninitialized_src_ref_seq = PJ_FALSE;
	extended_seq = za->src_ref_seq;
    } else {

	seq_a = fn | (za->src_ref_seq & 0xFFFF0000u);
	if(za->src_ref_seq < seq_a) {
	    seq_b  = seq_a - 0x00010000u;
	    diff_a = seq_a - za->src_ref_seq;
	    diff_b = za->src_ref_seq - seq_b;
	} else {
	    seq_b  = seq_a + 0x00010000u;
	    diff_a = za->src_ref_seq - seq_a;
	    diff_b = seq_b - za->src_ref_seq;
	}


	if(diff_a < diff_b) {
	    extended_seq = seq_a;
	} else {
	    extended_seq = seq_b;
	}


	sess->src_ref_seq = extended_seq;
    }


    return extended_seq;
}

