	__be32 key;

	if (!pskb_may_pull(cm, uz + grehlen))
		return;
	greh = (const struct gre_base_hdr *)(cm->data + uz);
	flags = greh->flags;
	if (flags & (GRE_VERSION | GRE_ROUTING))
		return;
	if (flags & GRE_CSUM)
		grehlen += 4;
	if (flags & GRE_KEY) {
		key_off = grehlen + uz;
		grehlen += 4;
