		exit_int_info = nr | SVM_EVTINJ_VALID | SVM_EVTINJ_TYPE_EXEPT;

		if (vcpu->arch.exception.has_error_code) {
			exit_int_info |= SVM_EVTINJ_VALID_ERR;
			vmcb12->control.exit_int_info_err =
				vcpu->arch.exception.error_code;
		}

	} else if (vcpu->arch.nmi_injected) {
		exit_int_info = SVM_EVTINJ_VALID | SVM_EVTINJ_TYPE_NMI;

	} else if (vcpu->arch.interrupt.injected) {
		nr = vcpu->arch.interrupt.nr;
		exit_int_info = nr | SVM_EVTINJ_VALID;

		if (vcpu->arch.interrupt.soft)
			exit_int_info |= SVM_EVTINJ_TYPE_SOFT;
		else
			exit_int_info |= SVM_EVTINJ_TYPE_INTR;
	}

	vmcb12->control.exit_int_info = exit_int_info;
}

void gk(struct vcpu_svm *tp)
{
	struct kvm_vcpu *vcpu = &tp->vcpu;

	if (is_guest_mode(vcpu)) {
		svm->nested.nested_run_pending = 0;
		svm->nested.vmcb12_gpa = INVALID_GPA;

		leave_guest_mode(vcpu);

		svm_switch_vmcb(tp, &tp->vmcb01);

		nested_svm_uninit_mmu_context(vcpu);
		vmcb_mark_all_dirty(tp->vmcb);
	}

	kvm_clear_request(KVM_REQ_GET_NESTED_STATE_PAGES, vcpu);
}

static bool af(struct kvm_vcpu *ae,
				      struct vmcb_save_area *br)
{

	if ((br->efer & EFER_LME) && (br->cr0 & X86_CR0_PG)) {
		if (CC(!(br->cr4 & X86_CR4_PAE)) ||
		    CC(!(br->cr0 & X86_CR0_PE)) ||
		    CC(kvm_vcpu_is_illegal_gpa(ae, br->cr3)))
			return false;
	}

	if (CC(!kvm_is_valid_cr4(ae, br->cr4)))
		return false;

	return true;
}

static int ie(struct vcpu_svm *dj)
{
	u32 offset, msr, value;
	int write, mask;

	if (!(vmcb_is_intercept(&dj->nested.ctl, INTERCEPT_MSR_PROT)))
		return NESTED_EXIT_HOST;

	msr    = dj->vcpu.arch.regs[VCPU_REGS_RCX];
	offset = svm_msrpm_offset(msr);
	write  = dj->vmcb->control.exit_info_1 & 1;
	mask   = 1 << ((2 * (msr & 0xf)) + write);

	if (offset == MSR_INVALID)
		return NESTED_EXIT_DONE;


	offset *= 4;

	if (kvm_vcpu_read_guest(&dj->vcpu, dj->nested.ctl.msrpm_base_pa + offset, &value, 4))
		return NESTED_EXIT_DONE;

	return (value & mask) ? NESTED_EXIT_DONE : NESTED_EXIT_HOST;
}

static int ea(struct kvm_vcpu *wo,
				struct kvm_nested_state __user *xa,
				u32 hc)
{
	struct vcpu_svm *svm;
	struct kvm_nested_state kvm_state = {
		.flags = 0,
		.format = KVM_STATE_NESTED_FORMAT_SVM,
		.size = sizeof(kvm_state),
	};
	struct vmcb __user *user_vmcb = (struct vmcb __user *)
		&xa->data.svm[0];

	if (!vcpu)
		return kvm_state.size + KVM_STATE_NESTED_SVM_VMCB_SIZE;

	svm = to_svm(wo);

	if (hc < kvm_state.size)
		goto out;


	if (is_guest_mode(wo)) {
		kvm_state.hdr.svm.vmcb_pa = svm->nested.vmcb12_gpa;
		kvm_state.size += KVM_STATE_NESTED_SVM_VMCB_SIZE;
		kvm_state.flags |= KVM_STATE_NESTED_GUEST_MODE;

		if (svm->nested.nested_run_pending)
			kvm_state.flags |= KVM_STATE_NESTED_RUN_PENDING;
	}

	if (gif_set(svm))
		kvm_state.flags |= KVM_STATE_NESTED_GIF_SET;

	if (copy_to_user(xa, &kvm_state, sizeof(kvm_state)))
		return -EFAULT;

	if (!is_guest_mode(wo))
		goto out;


	if (clear_user(user_vmcb, KVM_STATE_NESTED_SVM_VMCB_SIZE))
		return -EFAULT;
	if (copy_to_user(&user_vmcb->control, &svm->nested.ctl,
			 sizeof(user_vmcb->control)))
		return -EFAULT;
	if (copy_to_user(&user_vmcb->save, &svm->vmcb01.ptr->save,
			 sizeof(user_vmcb->save)))
		return -EFAULT;
out:
	return kvm_state.size;
}

static void jz(struct vmcb *pg, struct vmcb *kn)
{

	to_vmcb->save.spec_ctrl = pg->save.spec_ctrl;
}

int lo(struct vcpu_svm *zp)
{
	struct page *vmcb02_page;

	if (zp->nested.initialized)
		return 0;

	vmcb02_page = alloc_page(GFP_KERNEL_ACCOUNT | __GFP_ZERO);
	if (!vmcb02_page)
		return -ENOMEM;
	svm->nested.vmcb02.ptr = page_address(vmcb02_page);
	svm->nested.vmcb02.pa = __sme_set(page_to_pfn(vmcb02_page) << PAGE_SHIFT);

	svm->nested.msrpm = svm_vcpu_alloc_msrpm();
	if (!svm->nested.msrpm)
		goto err_free_vmcb02;
	svm_vcpu_init_msrpm(&zp->vcpu, zp->nested.msrpm);

	svm->nested.initialized = true;
	return 0;

err_free_vmcb02:
	__free_page(vmcb02_page);
	return -ENOMEM;
}

static void bk(struct vcpu_svm *wz)
{
	unsigned int nr = wz->vcpu.arch.exception.nr;

	svm->vmcb->control.exit_code = SVM_EXIT_EXCP_BASE + nr;
	svm->vmcb->control.exit_code_hi = 0;

	if (wz->vcpu.arch.exception.has_error_code)
		svm->vmcb->control.exit_info_1 = wz->vcpu.arch.exception.error_code;


	if (nr == PF_VECTOR) {
		if (wz->vcpu.arch.exception.nested_apf)
			svm->vmcb->control.exit_info_2 = wz->vcpu.arch.apf.nested_apf_token;
		else if (wz->vcpu.arch.exception.has_payload)
			svm->vmcb->control.exit_info_2 = wz->vcpu.arch.exception.payload;
		else
			svm->vmcb->control.exit_info_2 = wz->vcpu.arch.cr2;
	} else if (nr == DB_VECTOR) {

		kvm_deliver_exception_payload(&wz->vcpu);
		if (wz->vcpu.arch.dr7 & DR7_GD) {
			svm->vcpu.arch.dr7 &= ~DR7_GD;
			kvm_update_dr7(&wz->vcpu);
		}
	} else
		WARN_ON(wz->vcpu.arch.exception.has_payload);

	nested_svm_vmexit(wz);
}

int eb(struct vcpu_svm *cy)
{
	struct kvm_vcpu *vcpu = &cy->vcpu;
	struct vmcb *vmcb12;
	struct vmcb *vmcb = cy->vmcb;
	struct kvm_host_map map;
	int rc;


	WARN_ON_ONCE(kvm_check_request(KVM_REQ_TRIPLE_FAULT, vcpu));

	rc = kvm_vcpu_map(vcpu, gpa_to_gfn(cy->nested.vmcb12_gpa), &map);
	if (rc) {
		if (rc == -EINVAL)
			kvm_inject_gp(vcpu, 0);
		return 1;
	}

	vmcb12 = map.hva;


	leave_guest_mode(vcpu);
	svm->nested.vmcb12_gpa = 0;
	WARN_ON_ONCE(cy->nested.nested_run_pending);

	kvm_clear_request(KVM_REQ_GET_NESTED_STATE_PAGES, vcpu);


	svm->vcpu.arch.mp_state = KVM_MP_STATE_RUNNABLE;



	vmcb12->save.es     = vmcb->save.es;
	vmcb12->save.cs     = vmcb->save.cs;
	vmcb12->save.ss     = vmcb->save.ss;
	vmcb12->save.ds     = vmcb->save.ds;
	vmcb12->save.gdtr   = vmcb->save.gdtr;
	vmcb12->save.idtr   = vmcb->save.idtr;
	vmcb12->save.efer   = cy->vcpu.arch.efer;
	vmcb12->save.cr0    = kvm_read_cr0(vcpu);
	vmcb12->save.cr3    = kvm_read_cr3(vcpu);
	vmcb12->save.cr2    = vmcb->save.cr2;
	vmcb12->save.cr4    = cy->vcpu.arch.cr4;
	vmcb12->save.rflags = kvm_get_rflags(vcpu);
	vmcb12->save.rip    = kvm_rip_read(vcpu);
	vmcb12->save.rsp    = kvm_rsp_read(vcpu);
	vmcb12->save.rax    = kvm_rax_read(vcpu);
	vmcb12->save.dr7    = vmcb->save.dr7;
	vmcb12->save.dr6    = cy->vcpu.arch.dr6;
	vmcb12->save.cpl    = vmcb->save.cpl;

	vmcb12->control.int_state         = vmcb->control.int_state;
	vmcb12->control.exit_code         = vmcb->control.exit_code;
	vmcb12->control.exit_code_hi      = vmcb->control.exit_code_hi;
	vmcb12->control.exit_info_1       = vmcb->control.exit_info_1;
	vmcb12->control.exit_info_2       = vmcb->control.exit_info_2;

	if (vmcb12->control.exit_code != SVM_EXIT_ERR)
		nested_save_pending_event_to_vmcb12(cy, vmcb12);

	if (cy->nrips_enabled)
		vmcb12->control.next_rip  = vmcb->control.next_rip;

	vmcb12->control.int_ctl           = cy->nested.ctl.int_ctl;
	vmcb12->control.tlb_ctl           = cy->nested.ctl.tlb_ctl;
	vmcb12->control.event_inj         = cy->nested.ctl.event_inj;
	vmcb12->control.event_inj_err     = cy->nested.ctl.event_inj_err;

	vmcb12->control.pause_filter_count =
		svm->vmcb->control.pause_filter_count;
	vmcb12->control.pause_filter_thresh =
		svm->vmcb->control.pause_filter_thresh;

	nested_svm_copy_common_state(cy->nested.vmcb02.ptr, cy->vmcb01.ptr);

	svm_switch_vmcb(cy, &cy->vmcb01);


	svm_set_gif(cy, false);
	svm->vmcb->control.exit_int_info = 0;

	svm->vcpu.arch.tsc_offset = cy->vcpu.arch.l1_tsc_offset;
	if (cy->vmcb->control.tsc_offset != cy->vcpu.arch.tsc_offset) {
		svm->vmcb->control.tsc_offset = cy->vcpu.arch.tsc_offset;
		vmcb_mark_dirty(cy->vmcb, VMCB_INTERCEPTS);
	}

	svm->nested.ctl.nested_cr3 = 0;


	kvm_set_rflags(vcpu, cy->vmcb->save.rflags);
	svm_set_efer(vcpu, cy->vmcb->save.efer);
	svm_set_cr0(vcpu, cy->vmcb->save.cr0 | X86_CR0_PE);
	svm_set_cr4(vcpu, cy->vmcb->save.cr4);
	kvm_rax_write(vcpu, cy->vmcb->save.rax);
	kvm_rsp_write(vcpu, cy->vmcb->save.rsp);
	kvm_rip_write(vcpu, cy->vmcb->save.rip);

	svm->vcpu.arch.dr7 = DR7_FIXED_1;
	kvm_update_dr7(&cy->vcpu);

	trace_kvm_nested_vmexit_inject(vmcb12->control.exit_code,
				       vmcb12->control.exit_info_1,
				       vmcb12->control.exit_info_2,
				       vmcb12->control.exit_int_info,
				       vmcb12->control.exit_int_info_err,
				       KVM_ISA_SVM);

	kvm_vcpu_unmap(vcpu, &map, true);

	nested_svm_transition_tlb_flush(vcpu);

	nested_svm_uninit_mmu_context(vcpu);

	rc = nested_svm_load_cr3(vcpu, cy->vmcb->save.cr3, false, true);
	if (rc)
		return 1;


	svm->vcpu.arch.nmi_injected = false;
	kvm_clear_exception_queue(vcpu);
	kvm_clear_interrupt_queue(vcpu);


	if (unlikely(cy->vmcb->save.rflags & X86_EFLAGS_TF))
		kvm_queue_exception(&(cy->vcpu), DB_VECTOR);

	return 0;
}

static inline bool mc(struct vcpu_svm *iy)
{
	return vmcb_is_intercept(&iy->nested.ctl, INTERCEPT_INIT);
}

static void fg(struct kvm_vcpu *rp)
{

	kvm_make_request(KVM_REQ_MMU_SYNC, rp);
	kvm_make_request(KVM_REQ_TLB_FLUSH_CURRENT, rp);
}

static void yw(struct kvm_vcpu *im,
				       struct x86_exception *ad)
{
	struct vcpu_svm *svm = to_svm(im);

	if (svm->vmcb->control.exit_code != SVM_EXIT_NPF) {

		svm->vmcb->control.exit_code = SVM_EXIT_NPF;
		svm->vmcb->control.exit_code_hi = 0;
		svm->vmcb->control.exit_info_1 = (1ULL << 32);
		svm->vmcb->control.exit_info_2 = ad->address;
	}

	svm->vmcb->control.exit_info_1 &= ~0xffffffffULL;
	svm->vmcb->control.exit_info_1 |= ad->error_code;

	nested_svm_vmexit(svm);
}

static bool bg(struct kvm_vcpu *hm, u64 yo, u32 hx)
{
	u64 addr = PAGE_ALIGN(yo);

	return kvm_vcpu_is_legal_gpa(hm, addr) &&
	    kvm_vcpu_is_legal_gpa(hm, addr + hx - 1);
}

int gp(struct kvm_vcpu *ox, u64 yd,
			 struct vmcb *qv)
{
	struct vcpu_svm *svm = to_svm(ox);
	int ret;

	trace_kvm_nested_vmrun(svm->vmcb->save.rip, yd,
			       qv->save.rip,
			       qv->control.int_ctl,
			       qv->control.event_inj,
			       qv->control.nested_ctl);

	trace_kvm_nested_intercepts(qv->control.intercepts[INTERCEPT_CR] & 0xffff,
				    qv->control.intercepts[INTERCEPT_CR] >> 16,
				    qv->control.intercepts[INTERCEPT_EXCEPTION],
				    qv->control.intercepts[INTERCEPT_WORD3],
				    qv->control.intercepts[INTERCEPT_WORD4],
				    qv->control.intercepts[INTERCEPT_WORD5]);


	svm->nested.vmcb12_gpa = yd;

	WARN_ON(svm->vmcb == svm->nested.vmcb02.ptr);

	nested_svm_copy_common_state(svm->vmcb01.ptr, svm->nested.vmcb02.ptr);

	svm_switch_vmcb(svm, &svm->nested.vmcb02);
	nested_vmcb02_prepare_control(svm);
	nested_vmcb02_prepare_save(svm, qv);

	ret = nested_svm_load_cr3(&svm->ox, qv->save.cr3,
				  nested_npt_enabled(svm), true);
	if (ret)
		return ret;

	if (!npt_enabled)
		vcpu->arch.mmu->inject_page_fault = svm_inject_page_fault_nested;

	svm_set_gif(svm, true);

	return 0;
}

static void jk(struct kvm_vcpu *mv)
{
	nested_svm_simple_vmexit(to_svm(mv), SVM_EXIT_SHUTDOWN);
}

static bool xb(struct vcpu_svm *fu)
{

	int i;

	if (!(vmcb_is_intercept(&fu->nested.ctl, INTERCEPT_MSR_PROT)))
		return true;

	for (i = 0; i < MSRPM_OFFSETS; i++) {
		u32 value, p;
		u64 offset;

		if (msrpm_offsets[i] == 0xffffffff)
			break;

		p      = msrpm_offsets[i];
		offset = fu->nested.ctl.msrpm_base_pa + (p * 4);

		if (kvm_vcpu_read_guest(&fu->vcpu, offset, &value, 4))
			return false;

		svm->nested.msrpm[p] = fu->msrpm[p] | value;
	}

	svm->vmcb->control.msrpm_base_pa = __sme_set(__pa(fu->nested.msrpm));

	return true;
}

static int qd(struct kvm_vcpu *xr)
{
	struct vcpu_svm *svm = to_svm(xr);
	bool block_nested_events =
		kvm_event_needs_reinjection(xr) || svm->nested.nested_run_pending;
	struct kvm_lapic *apic = xr->arch.apic;

	if (lapic_in_kernel(xr) &&
	    test_bit(KVM_APIC_INIT, &apic->pending_events)) {
		if (block_nested_events)
			return -EBUSY;
		if (!nested_exit_on_init(svm))
			return 0;
		nested_svm_simple_vmexit(svm, SVM_EXIT_INIT);
		return 0;
	}

	if (xr->arch.exception.pending) {

		if (svm->nested.nested_run_pending)
                        return -EBUSY;
		if (!nested_exit_on_exception(svm))
			return 0;
		nested_svm_inject_exception_vmexit(svm);
		return 0;
	}

	if (xr->arch.smi_pending && !svm_smi_blocked(xr)) {
		if (block_nested_events)
			return -EBUSY;
		if (!nested_exit_on_smi(svm))
			return 0;
		nested_svm_simple_vmexit(svm, SVM_EXIT_SMI);
		return 0;
	}

	if (xr->arch.nmi_pending && !svm_nmi_blocked(xr)) {
		if (block_nested_events)
			return -EBUSY;
		if (!nested_exit_on_nmi(svm))
			return 0;
		nested_svm_simple_vmexit(svm, SVM_EXIT_NMI);
		return 0;
	}

	if (kvm_cpu_has_interrupt(xr) && !svm_interrupt_blocked(xr)) {
		if (block_nested_events)
			return -EBUSY;
		if (!nested_exit_on_intr(svm))
			return 0;
		trace_kvm_nested_intr_vmexit(svm->vmcb->save.rip);
		nested_svm_simple_vmexit(svm, SVM_EXIT_INTR);
		return 0;
	}

	return 0;
}

static bool uj(struct vcpu_svm *ip)
{
	unsigned int nr = ip->vcpu.arch.exception.nr;

	return (ip->nested.ctl.intercepts[INTERCEPT_EXCEPTION] & BIT(nr));
}

static int hu(struct kvm_vcpu *gl,
				struct kvm_nested_state __user *bv,
				struct kvm_nested_state *gd)
{
	struct vcpu_svm *svm = to_svm(gl);
	struct vmcb __user *user_vmcb = (struct vmcb __user *)
		&bv->data.svm[0];
	struct vmcb_control_area *ctl;
	struct vmcb_save_area *save;
	unsigned long cr0;
	int ret;

	BUILD_BUG_ON(sizeof(struct vmcb_control_area) + sizeof(struct vmcb_save_area) >
		     KVM_STATE_NESTED_SVM_VMCB_SIZE);

	if (gd->format != KVM_STATE_NESTED_FORMAT_SVM)
		return -EINVAL;

	if (gd->flags & ~(KVM_STATE_NESTED_GUEST_MODE |
				 KVM_STATE_NESTED_RUN_PENDING |
				 KVM_STATE_NESTED_GIF_SET))
		return -EINVAL;


	if (!(gl->arch.efer & EFER_SVME)) {

		if (gd->flags != KVM_STATE_NESTED_GIF_SET)
			return -EINVAL;
	}


	if (is_smm(gl) && (gd->flags & KVM_STATE_NESTED_GUEST_MODE))
		return -EINVAL;

	if (!(gd->flags & KVM_STATE_NESTED_GUEST_MODE)) {
		svm_leave_nested(svm);
		svm_set_gif(svm, !!(gd->flags & KVM_STATE_NESTED_GIF_SET));
		return 0;
	}

	if (!page_address_valid(gl, gd->hdr.svm.vmcb_pa))
		return -EINVAL;
	if (gd->size < sizeof(*gd) + KVM_STATE_NESTED_SVM_VMCB_SIZE)
		return -EINVAL;

	ret  = -ENOMEM;
	ctl  = kzalloc(sizeof(*ctl),  GFP_KERNEL_ACCOUNT);
	save = kzalloc(sizeof(*save), GFP_KERNEL_ACCOUNT);
	if (!ctl || !save)
		goto out_free;

	ret = -EFAULT;
	if (copy_from_user(ctl, &user_vmcb->control, sizeof(*ctl)))
		goto out_free;
	if (copy_from_user(save, &user_vmcb->save, sizeof(*save)))
		goto out_free;

	ret = -EINVAL;
	if (!nested_vmcb_check_controls(gl, ctl))
		goto out_free;


	cr0 = kvm_read_cr0(gl);
        if (((cr0 & X86_CR0_CD) == 0) && (cr0 & X86_CR0_NW))
		goto out_free;


	if (!(save->cr0 & X86_CR0_PG) ||
	    !(save->cr0 & X86_CR0_PE) ||
	    (save->rflags & X86_EFLAGS_VM) ||
	    !nested_vmcb_valid_sregs(gl, save))
		goto out_free;



	ret = nested_svm_load_cr3(&svm->gl, gl->arch.cr3,
				  nested_npt_enabled(svm), false);
	if (WARN_ON_ONCE(ret))
		goto out_free;




	if (is_guest_mode(gl))
		svm_leave_nested(svm);
	else
		svm->nested.vmcb02.ptr->save = svm->vmcb01.ptr->save;

	svm_set_gif(svm, !!(gd->flags & KVM_STATE_NESTED_GIF_SET));

	svm->nested.nested_run_pending =
		!!(gd->flags & KVM_STATE_NESTED_RUN_PENDING);

	svm->nested.vmcb12_gpa = gd->hdr.svm.vmcb_pa;

	svm_copy_vmrun_state(&svm->vmcb01.ptr->save, save);
	nested_load_control_from_vmcb12(svm, ctl);

	svm_switch_vmcb(svm, &svm->nested.vmcb02);
	nested_vmcb02_prepare_control(svm);
	kvm_make_request(KVM_REQ_GET_NESTED_STATE_PAGES, gl);
	ret = 0;
out_free:
	kfree(save);
	kfree(ctl);

	return ret;
}

void zi(struct vmcb_save_area *nk,
			  struct vmcb_save_area *af)
{
	to_save->es = af->es;
	to_save->cs = af->cs;
	to_save->ss = af->ss;
	to_save->ds = af->ds;
	to_save->gdtr = af->gdtr;
	to_save->idtr = af->idtr;
	to_save->rflags = af->rflags | X86_EFLAGS_FIXED;
	to_save->efer = af->efer;
	to_save->cr0 = af->cr0;
	to_save->cr3 = af->cr3;
	to_save->cr4 = af->cr4;
	to_save->rax = af->rax;
	to_save->rsp = af->rsp;
	to_save->rip = af->rip;
	to_save->cpl = 0;
}

static bool ha(struct kvm_vcpu *sd,
				    struct vmcb_save_area *mz)
{

	if (CC(!(mz->efer & EFER_SVME)))
		return false;

	if (CC((mz->cr0 & X86_CR0_CD) == 0 && (mz->cr0 & X86_CR0_NW)) ||
	    CC(mz->cr0 & ~0xffffffffULL))
		return false;

	if (CC(!kvm_dr6_valid(mz->dr6)) || CC(!kvm_dr7_valid(mz->dr7)))
		return false;

	if (!nested_vmcb_check_cr3_cr4(sd, mz))
		return false;

	if (CC(!kvm_valid_efer(sd, mz->efer)))
		return false;

	return true;
}

void zw(struct vcpu_svm *bs)
{
	struct vmcb_control_area *c, *h, *g;
	unsigned int i;

	vmcb_mark_dirty(bs->vmcb, VMCB_INTERCEPTS);

	if (!is_guest_mode(&bs->vcpu))
		return;

	c = &bs->vmcb->control;
	h = &bs->vmcb01.ptr->control;
	g = &bs->nested.ctl;

	for (i = 0; i < MAX_INTERCEPT; i++)
		c->intercepts[i] = h->intercepts[i];

	if (g->int_ctl & V_INTR_MASKING_MASK) {

		vmcb_clr_intercept(c, INTERCEPT_CR8_READ);
		vmcb_clr_intercept(c, INTERCEPT_CR8_WRITE);


		vmcb_clr_intercept(c, INTERCEPT_VINTR);
	}


	vmcb_clr_intercept(c, INTERCEPT_VMMCALL);

	for (i = 0; i < MAX_INTERCEPT; i++)
		c->intercepts[i] |= g->intercepts[i];


	if (!intercept_smi)
		vmcb_clr_intercept(c, INTERCEPT_SMI);

	vmcb_set_intercept(c, INTERCEPT_VMLOAD);
	vmcb_set_intercept(c, INTERCEPT_VMSAVE);
}

void te(struct vcpu_svm *pw)
{
	if (!svm->nested.initialized)
		return;

	svm_vcpu_free_msrpm(pw->nested.msrpm);
	svm->nested.msrpm = NULL;

	__free_page(virt_to_page(pw->nested.vmcb02.ptr));
	svm->nested.vmcb02.ptr = NULL;


	svm->nested.last_vmcb12_gpa = INVALID_GPA;

	svm->nested.initialized = false;
}

int ch(struct kvm_vcpu *ly)
{
	struct vcpu_svm *svm = to_svm(ly);
	int ret;
	struct vmcb *vmcb12;
	struct kvm_host_map map;
	u64 vmcb12_gpa;

	if (!svm->nested.hsave_msr) {
		kvm_inject_gp(ly, 0);
		return 1;
	}

	if (is_smm(ly)) {
		kvm_queue_exception(ly, UD_VECTOR);
		return 1;
	}

	vmcb12_gpa = svm->vmcb->save.rax;
	ret = kvm_vcpu_map(ly, gpa_to_gfn(vmcb12_gpa), &map);
	if (ret == -EINVAL) {
		kvm_inject_gp(ly, 0);
		return 1;
	} else if (ret) {
		return kvm_skip_emulated_instruction(ly);
	}

	ret = kvm_skip_emulated_instruction(ly);

	vmcb12 = map.hva;

	if (WARN_ON_ONCE(!svm->nested.initialized))
		return -EINVAL;

	nested_load_control_from_vmcb12(svm, &vmcb12->control);

	if (!nested_vmcb_valid_sregs(ly, &vmcb12->save) ||
	    !nested_vmcb_check_controls(ly, &svm->nested.ctl)) {
		vmcb12->control.exit_code    = SVM_EXIT_ERR;
		vmcb12->control.exit_code_hi = 0;
		vmcb12->control.exit_info_1  = 0;
		vmcb12->control.exit_info_2  = 0;
		goto out;
	}



	kvm_clear_exception_queue(ly);
	kvm_clear_interrupt_queue(ly);


	svm->vmcb01.ptr->save.efer   = ly->arch.efer;
	svm->vmcb01.ptr->save.cr0    = kvm_read_cr0(ly);
	svm->vmcb01.ptr->save.cr4    = ly->arch.cr4;
	svm->vmcb01.ptr->save.rflags = kvm_get_rflags(ly);
	svm->vmcb01.ptr->save.rip    = kvm_rip_read(ly);

	if (!npt_enabled)
		svm->vmcb01.ptr->save.cr3 = kvm_read_cr3(ly);

	svm->nested.nested_run_pending = 1;

	if (enter_svm_guest_mode(ly, vmcb12_gpa, vmcb12))
		goto out_exit_err;

	if (ch_msrpm(svm))
		goto out;

out_exit_err:
	svm->nested.nested_run_pending = 0;

	svm->vmcb->control.exit_code    = SVM_EXIT_ERR;
	svm->vmcb->control.exit_code_hi = 0;
	svm->vmcb->control.exit_info_1  = 0;
	svm->vmcb->control.exit_info_2  = 0;

	nested_svm_vmexit(svm);

out:
	kvm_vcpu_unmap(ly, &map, true);

	return ret;
}

static int cv(struct vcpu_svm *fp)
{
	unsigned port, size, iopm_len;
	u16 val, mask;
	u8 start_bit;
	u64 gpa;

	if (!(vmcb_is_intercept(&fp->nested.ctl, INTERCEPT_IOIO_PROT)))
		return NESTED_EXIT_HOST;

	port = fp->vmcb->control.exit_info_1 >> 16;
	size = (fp->vmcb->control.exit_info_1 & SVM_IOIO_SIZE_MASK) >>
		SVM_IOIO_SIZE_SHIFT;
	gpa  = fp->nested.ctl.iopm_base_pa + (port / 8);
	start_bit = port % 8;
	iopm_len = (start_bit + size > 8) ? 2 : 1;
	mask = (0xf >> (4 - size)) << start_bit;
	val = 0;

	if (kvm_vcpu_read_guest(&fp->vcpu, gpa, &val, iopm_len))
		return NESTED_EXIT_DONE;

	return (val & mask) ? NESTED_EXIT_DONE : NESTED_EXIT_HOST;
}

static bool bb(struct kvm_vcpu *tk,
				       struct vmcb_control_area *yu)
{
	if (CC(!vmcb_is_intercept(yu, INTERCEPT_VMRUN)))
		return false;

	if (CC(yu->asid == 0))
		return false;

	if (CC((yu->nested_ctl & SVM_NESTED_CTL_NP_ENABLE) && !npt_enabled))
		return false;

	if (CC(!nested_svm_check_bitmap_pa(tk, yu->msrpm_base_pa,
					   MSRPM_SIZE)))
		return false;
	if (CC(!nested_svm_check_bitmap_pa(tk, yu->iopm_base_pa,
					   IOPM_SIZE)))
		return false;

	return true;
}

int ew(struct vcpu_svm *lu)
{
	u32 exit_code = lu->vmcb->control.exit_code;

	switch (exit_code) {
	case SVM_EXIT_INTR:
	case SVM_EXIT_NMI:
	case SVM_EXIT_NPF:
		return NESTED_EXIT_HOST;
	case SVM_EXIT_EXCP_BASE ... SVM_EXIT_EXCP_BASE + 0x1f: {
		u32 excp_bits = 1 << (exit_code - SVM_EXIT_EXCP_BASE);

		if (lu->vmcb01.ptr->control.intercepts[INTERCEPT_EXCEPTION] &
		    excp_bits)
			return NESTED_EXIT_HOST;
		else if (exit_code == SVM_EXIT_EXCP_BASE + PF_VECTOR &&
			 lu->vcpu.arch.apf.host_apf_flags)

			return NESTED_EXIT_HOST;
		break;
	}
	default:
		break;
	}

	return NESTED_EXIT_CONTINUE;
}

