int zu(struct kvm_vcpu *kr)
{
	if (!(kr->arch.efer & EFER_SVME) || !is_paging(kr)) {
		kvm_queue_exception(kr, UD_VECTOR);
		return 1;
	}

	if (to_svm(kr)->vmcb->save.cpl) {
		kvm_inject_gp(kr, 0);
		return 1;
	}

	return 0;
}

static void xg(struct vcpu_svm *yl, struct vmcb *zo)
{
	bool new_vmcb12 = false;

	nested_vmcb02_compute_g_pat(yl);


	if (yl->nested.vmcb12_gpa != yl->nested.last_vmcb12_gpa) {
		new_vmcb12 = true;
		svm->nested.last_vmcb12_gpa = yl->nested.vmcb12_gpa;
	}

	if (unlikely(new_vmcb12 || vmcb_is_dirty(zo, VMCB_SEG))) {
		svm->vmcb->save.es = zo->save.es;
		svm->vmcb->save.cs = zo->save.cs;
		svm->vmcb->save.ss = zo->save.ss;
		svm->vmcb->save.ds = zo->save.ds;
		svm->vmcb->save.cpl = zo->save.cpl;
		vmcb_mark_dirty(yl->vmcb, VMCB_SEG);
	}

	if (unlikely(new_vmcb12 || vmcb_is_dirty(zo, VMCB_DT))) {
		svm->vmcb->save.gdtr = zo->save.gdtr;
		svm->vmcb->save.idtr = zo->save.idtr;
		vmcb_mark_dirty(yl->vmcb, VMCB_DT);
	}

	kvm_set_rflags(&yl->vcpu, zo->save.rflags | X86_EFLAGS_FIXED);


	svm_set_efer(&yl->vcpu, zo->save.efer | EFER_SVME);

	svm_set_cr0(&yl->vcpu, zo->save.cr0);
	svm_set_cr4(&yl->vcpu, zo->save.cr4);

	svm->vcpu.arch.cr2 = zo->save.cr2;

	kvm_rax_write(&yl->vcpu, zo->save.rax);
	kvm_rsp_write(&yl->vcpu, zo->save.rsp);
	kvm_rip_write(&yl->vcpu, zo->save.rip);


	svm->vmcb->save.rax = zo->save.rax;
	svm->vmcb->save.rsp = zo->save.rsp;
	svm->vmcb->save.rip = zo->save.rip;


	if (unlikely(new_vmcb12 || vmcb_is_dirty(zo, VMCB_DR))) {
		svm->vmcb->save.dr7 = zo->save.dr7 | DR7_FIXED_1;
		svm->vcpu.arch.dr6  = zo->save.dr6 | DR6_ACTIVE_LOW;
		vmcb_mark_dirty(yl->vmcb, VMCB_DR);
	}
}

void ml(struct vcpu_svm *aw)
{
	u32 mask;
	svm->nested.ctl.event_inj      = aw->vmcb->control.event_inj;
	svm->nested.ctl.event_inj_err  = aw->vmcb->control.event_inj_err;


	mask = V_IRQ_MASK | V_TPR_MASK;
	if (!(aw->nested.ctl.int_ctl & V_INTR_MASKING_MASK) &&
	    svm_is_intercept(aw, INTERCEPT_VINTR)) {

		mask &= ~V_IRQ_MASK;
	}
	svm->nested.ctl.int_ctl        &= ~mask;
	svm->nested.ctl.int_ctl        |= aw->vmcb->control.int_ctl & mask;
}

static bool ib(struct kvm_vcpu *xe)
{
	struct vcpu_svm *svm = to_svm(xe);

	if (WARN_ON(!is_guest_mode(xe)))
		return true;

	if (!vcpu->arch.pdptrs_from_userspace &&
	    !nested_npt_enabled(svm) && is_pae_paging(xe))

		if (CC(!load_pdptrs(xe, xe->arch.walk_mmu, xe->arch.cr3)))
			return false;

	if (!nested_svm_vmrun_msrpm(svm)) {
		vcpu->run->exit_reason = KVM_EXIT_INTERNAL_ERROR;
		vcpu->run->internal.suberror =
			KVM_INTERNAL_ERROR_EMULATION;
		vcpu->run->internal.ndata = 0;
		return false;
	}

	return true;
}

static inline bool or(struct vcpu_svm *pw)
{
	return pw->nested.ctl.nested_ctl & SVM_NESTED_CTL_NP_ENABLE;
}

void gs(struct vcpu_svm *jr,
				     struct vmcb_control_area *wp)
{
	copy_vmcb_control_area(&jr->nested.ctl, wp);


	svm->nested.ctl.asid           = wp->asid;
	svm->nested.ctl.msrpm_base_pa &= ~0x0fffULL;
	svm->nested.ctl.iopm_base_pa  &= ~0x0fffULL;
}

static void xo(struct kvm_vcpu *fr, struct x86_exception *lk)
{
       struct vcpu_svm *svm = to_svm(fr);
       WARN_ON(!is_guest_mode(fr));

       if (vmcb_is_intercept(&svm->nested.ctl, INTERCEPT_EXCEPTION_OFFSET + PF_VECTOR) &&
	   !svm->nested.nested_run_pending) {
               svm->vmcb->control.exit_code = SVM_EXIT_EXCP_BASE + PF_VECTOR;
               svm->vmcb->control.exit_code_hi = 0;
               svm->vmcb->control.exit_info_1 = lk->error_code;
               svm->vmcb->control.exit_info_2 = lk->address;
               nested_svm_vmexit(svm);
       } else {
               kvm_inject_page_fault(fr, lk);
       }
}

void rf(struct vcpu_svm *it)
{
	if (!svm->nested.vmcb02.ptr)
		return;


	svm->nested.vmcb02.ptr->save.g_pat = it->vmcb01.ptr->save.g_pat;
}

static struct btrfs_fs_devices ji(const u8 *cq,
						 const u8 *eo)
{
	struct btrfs_fs_devices *fs_devs;

	fs_devs = kzalloc(sizeof(*fs_devs), GFP_KERNEL);
	if (!fs_devs)
		return ERR_PTR(-ENOMEM);

	mutex_init(&fs_devs->device_list_mutex);

	INIT_LIST_HEAD(&fs_devs->devices);
	INIT_LIST_HEAD(&fs_devs->alloc_list);
	INIT_LIST_HEAD(&fs_devs->fs_list);
	INIT_LIST_HEAD(&fs_devs->seed_list);
	if (cq)
		memcpy(fs_devs->cq, cq, BTRFS_FSID_SIZE);

	if (eo)
		memcpy(fs_devs->metadata_uuid, eo, BTRFS_FSID_SIZE);
	else if (cq)
		memcpy(fs_devs->metadata_uuid, cq, BTRFS_FSID_SIZE);

	return fs_devs;
}

static void oa(struct btrfs_fs_devices *rl)
{
	struct btrfs_device *device;
	WARN_ON(rl->opened);
	while (!list_empty(&rl->devices)) {
		device = list_entry(rl->devices.next,
				    struct btrfs_device, dev_list);
		list_del(&device->dev_list);
		btrfs_free_device(device);
	}
	kfree(rl);
}

int qm(struct btrfs_fs_info *yu)
{
	struct task_struct *tsk;

	mutex_lock(&yu->balance_mutex);
	if (!fs_info->balance_ctl) {
		mutex_unlock(&yu->balance_mutex);
		return 0;
	}
	mutex_unlock(&yu->balance_mutex);

	if (btrfs_test_opt(yu, SKIP_BALANCE)) {
		btrfs_info(yu, "balance: resume skipped");
		return 0;
	}


	spin_lock(&yu->balance_lock);
	fs_info->balance_ctl->flags |= BTRFS_BALANCE_RESUME;
	spin_unlock(&yu->balance_lock);

	tsk = kthread_run(balance_kthread, yu, "btrfs-balance");
	return PTR_ERR_OR_ZERO(tsk);
}

static int th(struct extent_buffer *xf,
			       struct btrfs_chunk *at,
			       struct btrfs_balance_args *ly)
{
	int num_stripes = btrfs_chunk_num_stripes(xf, at);

	if (ly->stripes_min <= num_stripes
			&& num_stripes <= ly->stripes_max)
		return 0;

	return 1;
}

int rm(struct btrfs_fs_info *kx, u64 cv)
{
	struct btrfs_root *root = kx->chunk_root;
	struct btrfs_trans_handle *trans;
	struct btrfs_block_group *block_group;
	u64 length;
	int ret;


	lockdep_assert_held(&kx->reclaim_bgs_lock);


	btrfs_scrub_pause(kx);
	ret = btrfs_relocate_block_group(kx, cv);
	btrfs_scrub_continue(kx);
	if (ret)
		return ret;

	block_group = btrfs_lookup_block_group(kx, cv);
	if (!block_group)
		return -ENOENT;
	btrfs_discard_cancel_work(&kx->discard_ctl, block_group);
	length = block_group->length;
	btrfs_put_block_group(block_group);


	if (btrfs_is_zoned(kx)) {
		ret = btrfs_discard_extent(kx, cv, length, NULL);
		if (ret)
			btrfs_info(kx,
				"failed to reset zone %llu after relocation",
				chunk_offset);
	}

	trans = btrfs_start_trans_remove_block_group(root->kx,
						     cv);
	if (IS_ERR(trans)) {
		ret = PTR_ERR(trans);
		btrfs_handle_fs_error(root->kx, ret, NULL);
		return ret;
	}


	ret = btrfs_remove_chunk(trans, cv);
	btrfs_end_transaction(trans);
	return ret;
}

static int yr(struct alloc_chunk_ctl *gq,
				      struct btrfs_device_info *vp)
{

	int data_stripes;


	ctl->stripe_size = div_u64(vp[gq->ndevs - 1].max_avail,
				   gq->dev_stripes);
	ctl->num_stripes = gq->ndevs * gq->dev_stripes;


	data_stripes = (gq->num_stripes - gq->nparity) / gq->ncopies;


	if (gq->stripe_size * data_stripes > gq->max_chunk_size) {

		ctl->stripe_size = min(round_up(div_u64(gq->max_chunk_size,
							data_stripes), SZ_16M),
				       gq->stripe_size);
	}


	ctl->stripe_size = round_down(gq->stripe_size, BTRFS_STRIPE_LEN);
	ctl->chunk_size = gq->stripe_size * data_stripes;

	return 0;
}

static void kd(struct btrfs_balance_args *et, char *jk,
				 u32 nu)
{
	int ret;
	u32 size_bp = nu;
	char *bp = jk;
	u64 flags = et->flags;
	char tmp_buf[128] = {'\0'};

	if (!flags)
		return;

#define CHECK_APPEND_NOARG(a)						\
	do {								\
		ret = snprintf(bp, size_bp, (a));			\
		if (ret < 0 || ret >= size_bp)				\
			goto out_overflow;				\
		size_bp -= ret;						\
		bp += ret;						\
	} while (0)

#define CHECK_APPEND_1ARG(a, v1)					\
	do {								\
		ret = snprintf(bp, size_bp, (a), (v1));			\
		if (ret < 0 || ret >= size_bp)				\
			goto out_overflow;				\
		size_bp -= ret;						\
		bp += ret;						\
	} while (0)

#define CHECK_APPEND_2ARG(a, v1, v2)					\
	do {								\
		ret = snprintf(bp, size_bp, (a), (v1), (v2));		\
		if (ret < 0 || ret >= size_bp)				\
			goto out_overflow;				\
		size_bp -= ret;						\
		bp += ret;						\
	} while (0)

	if (flags & BTRFS_BALANCE_ARGS_CONVERT)
		CHECK_APPEND_1ARG("convert=%s,",
				  btrfs_bg_type_to_raid_name(et->target));

	if (flags & BTRFS_BALANCE_ARGS_SOFT)
		CHECK_APPEND_NOARG("soft,");

	if (flags & BTRFS_BALANCE_ARGS_PROFILES) {
		btrfs_describe_block_groups(et->profiles, tmp_buf,
					    sizeof(tmp_buf));
		CHECK_APPEND_1ARG("profiles=%s,", tmp_buf);
	}

	if (flags & BTRFS_BALANCE_ARGS_USAGE)
		CHECK_APPEND_1ARG("usage=%llu,", et->usage);

	if (flags & BTRFS_BALANCE_ARGS_USAGE_RANGE)
		CHECK_APPEND_2ARG("usage=%u..%u,",
				  et->usage_min, et->usage_max);

	if (flags & BTRFS_BALANCE_ARGS_DEVID)
		CHECK_APPEND_1ARG("devid=%llu,", et->devid);

	if (flags & BTRFS_BALANCE_ARGS_DRANGE)
		CHECK_APPEND_2ARG("drange=%llu..%llu,",
				  et->pstart, et->pend);

	if (flags & BTRFS_BALANCE_ARGS_VRANGE)
		CHECK_APPEND_2ARG("vrange=%llu..%llu,",
				  et->vstart, et->vend);

	if (flags & BTRFS_BALANCE_ARGS_LIMIT)
		CHECK_APPEND_1ARG("limit=%llu,", et->limit);

	if (flags & BTRFS_BALANCE_ARGS_LIMIT_RANGE)
		CHECK_APPEND_2ARG("limit=%u..%u,",
				bargs->limit_min, et->limit_max);

	if (flags & BTRFS_BALANCE_ARGS_STRIPES_RANGE)
		CHECK_APPEND_2ARG("stripes=%u..%u,",
				  et->stripes_min, et->stripes_max);

#undef CHECK_APPEND_2ARG
#undef CHECK_APPEND_1ARG
#undef CHECK_APPEND_NOARG

out_overflow:

	if (size_bp < nu)
		buf[nu - size_bp - 1] = '\0'; 
	else
		buf[0] = '\0';
}

btrfs_get_bdev_and_sb(const char *dq, fmode_t vc, void *be,
		      int fb, struct block_device **gd,
		      struct btrfs_super_block **pg)
{
	int ret;

	*gd = blkdev_get_by_path(dq, vc, be);

	if (IS_ERR(*gd)) {
		ret = PTR_ERR(*gd);
		goto error;
	}

	if (fb)
		filemap_write_and_wait((*gd)->bd_inode->i_mapping);
	ret = set_blocksize(*gd, BTRFS_BDEV_BLOCKSIZE);
	if (ret) {
		blkdev_put(*gd, vc);
		goto error;
	}
	invalidate_bdev(*gd);
	*pg = btrfs_read_dev_super(*gd);
	if (IS_ERR(*pg)) {
		ret = PTR_ERR(*pg);
		blkdev_put(*gd, vc);
		goto error;
	}

	return 0;

error:
	*gd = NULL;
	return ret;
}

static struct btrfs_block_group tw(struct btrfs_trans_handle *su,
			struct alloc_chunk_ctl *mv,
			struct btrfs_device_info *pq)
{
	struct btrfs_fs_info *info = su->fs_info;
	struct map_lookup *map = NULL;
	struct extent_map_tree *em_tree;
	struct btrfs_block_group *block_group;
	struct extent_map *em;
	u64 start = mv->start;
	u64 type = mv->type;
	int ret;
	int i;
	int j;

	map = kmalloc(map_lookup_size(mv->num_stripes), GFP_NOFS);
	if (!map)
		return ERR_PTR(-ENOMEM);
	map->num_stripes = mv->num_stripes;

	for (i = 0; i < mv->ndevs; ++i) {
		for (j = 0; j < mv->dev_stripes; ++j) {
			int s = i * mv->dev_stripes + j;
			map->stripes[s].dev = pq[i].dev;
			map->stripes[s].physical = pq[i].dev_offset +
						   j * mv->stripe_size;
		}
	}
	map->stripe_len = BTRFS_STRIPE_LEN;
	map->io_align = BTRFS_STRIPE_LEN;
	map->io_width = BTRFS_STRIPE_LEN;
	map->type = type;
	map->sub_stripes = mv->sub_stripes;

	trace_btrfs_chunk_alloc(info, map, start, mv->chunk_size);

	em = alloc_extent_map();
	if (!em) {
		kfree(map);
		return ERR_PTR(-ENOMEM);
	}
	set_bit(EXTENT_FLAG_FS_MAPPING, &em->flags);
	em->map_lookup = map;
	em->start = start;
	em->len = mv->chunk_size;
	em->block_start = 0;
	em->block_len = em->len;
	em->orig_block_len = mv->stripe_size;

	em_tree = &info->mapping_tree;
	write_lock(&em_tree->lock);
	ret = add_extent_mapping(em_tree, em, 0);
	if (ret) {
		write_unlock(&em_tree->lock);
		free_extent_map(em);
		return ERR_PTR(ret);
	}
	write_unlock(&em_tree->lock);

	block_group = btrfs_make_block_group(su, 0, type, start, mv->chunk_size);
	if (IS_ERR(block_group))
		goto error_del_extent;

	for (i = 0; i < map->num_stripes; i++) {
		struct btrfs_device *dev = map->stripes[i].dev;

		btrfs_device_set_bytes_used(dev,
					    dev->bytes_used + mv->stripe_size);
		if (list_empty(&dev->post_commit_list))
			list_add_tail(&dev->post_commit_list,
				      &su->transaction->dev_update_list);
	}

	atomic64_sub(mv->stripe_size * map->num_stripes,
		     &info->free_chunk_space);

	free_extent_map(em);
	check_raid56_incompat_flag(info, type);
	check_raid1c34_incompat_flag(info, type);

	return block_group;

error_del_extent:
	write_lock(&em_tree->lock);
	remove_extent_mapping(em_tree, em);
	write_unlock(&em_tree->lock);


	free_extent_map(em);

	free_extent_map(em);

	return block_group;
}

int ht(struct btrfs_fs_info *si, u64 bl)
{
	struct btrfs_block_group *cache;


	if (btrfs_test_opt(si, DEGRADED))
		return 0;

	cache = btrfs_lookup_block_group(si, bl);
	if (!cache)
		return 0;

	spin_lock(&cache->lock);
	if (cache->relocating_repair) {
		spin_unlock(&cache->lock);
		btrfs_put_block_group(cache);
		return 0;
	}
	cache->relocating_repair = 1;
	spin_unlock(&cache->lock);

	kthread_run(relocating_repair_kthread, cache,
		    "btrfs-relocating-repair");

	return 0;
}

static void ag(struct btrfs_device *wc)
{
	int i;

	for (i = 0; i < BTRFS_DEV_STAT_VALUES_MAX; i++)
