			break;
	if (i == BTRFS_DEV_STAT_VALUES_MAX)
		return; 

	btrfs_info_in_rcu(wc->fs_info,
		"bdev %s errs: wr %u, rd %u, flush %u, corrupt %u, gen %u",
	       rcu_str_deref(wc->name),
	       btrfs_dev_stat_read(wc, BTRFS_DEV_STAT_WRITE_ERRS),
	       btrfs_dev_stat_read(wc, BTRFS_DEV_STAT_READ_ERRS),
	       btrfs_dev_stat_read(wc, BTRFS_DEV_STAT_FLUSH_ERRS),
	       btrfs_dev_stat_read(wc, BTRFS_DEV_STAT_CORRUPTION_ERRS),
	       btrfs_dev_stat_read(wc, BTRFS_DEV_STAT_GENERATION_ERRS));
}

static int zu(u64 up, int co)
{
	u64 mask = (co ? BTRFS_EXTENDED_PROFILE_MASK :
			       BTRFS_BLOCK_GROUP_PROFILE_MASK);

	flags &= ~BTRFS_BLOCK_GROUP_TYPE_MASK;


	if (up & ~mask)
		return 0;


	if (up == 0)
		return !extended; 

	return has_single_bit_set(up);
}

