ecc_256_modq (const struct ecc_modulo *bt, mp_limb_t *iq)
{
  mp_limb_t u2, u1, u0;
  mp_size_t n;

  n = 2*bt->size;
  u2 = iq[--n];
  u1 = iq[n-1];


  for (; n >= bt->size; n--)
    {
      mp_limb_t q2, q1, q0, t, c1, c0;

      u0 = iq[n-2];


      q1 = u2 - (u2 > u1);
      q0 = u1 - u2;
      t = u2 << 32;
      q0 += t;
      t = (u2 >> 32) + (q0 < t) + 1;
      q1 += t;
      q2 = q1 < t;


      u2 = u1 + q2 - q1;
      u1 = u0 + q1;
      u2 += (u1 < q1);
      u2 += (q1 << 32);

      t = -(mp_limb_t) (u2 >= q0);
      q1 += t;
      q2 += t + (q1 < t);
      u1 += t;
      u2 += (t << 32) + (u1 < t);

      assert (q2 < 2);

      c0 = cnd_sub_n (q2, iq + n - 3, bt->m, 1);
      c0 += (-q2) & bt->m[1];
      t = mpn_submul_1 (iq + n - 4, bt->m, 2, q1);
      c0 += t;
      c1 = c0 < t;


      c1 += (u1 < c0);
      t = - (mp_limb_t) (u2 < c1);

      u1 -= c0;
      u2 -= c1;


      u1 += t;
      u2 += (t<<32) + (u1 < t);

      t = cnd_add_n (t, iq + n - 4, bt->m, 2);
      u1 += t;
      u2 += (u1 < t);
    }
  iq[2] = u1;
  iq[3] = u2;
}

int cg(struct vc_data *cj)
{
	int i, j, err = 0, err1;
	u16 *q;
	struct uni_pagedir *p;

	if (dflt) {
		p = *cj->vc_uni_pagedir_loc;
		if (p == dflt)
			return 0;

		dflt->refcount++;
		*cj->vc_uni_pagedir_loc = dflt;
		if (p && !--p->refcount) {
			con_release_unimap(p);
			kfree(p);
		}
		return 0;
	}



	err = con_do_clear_unimap(cj);
	if (err)
		return err;

	p = *cj->vc_uni_pagedir_loc;
	q = dfont_unitable;

	for (i = 0; i < 256; i++)
		for (j = dfont_unicount[i]; j; j--) {
			err1 = con_insert_unipair(p, *(q++), i);
			if (err1)
				err = err1;
		}

	if (con_unify_unimap(cj, p)) {
		dflt = *cj->vc_uni_pagedir_loc;
		return err;
	}

	for (i = 0; i <= 3; i++)
		set_inverse_transl(cj, p, i);	
	set_inverse_trans_unicode(cj, p);
	dflt = p;
	return err;
}

int su(struct digest *qd, const char *dx,
		       unsigned char *hr,
		       const unsigned char *mg,
		       loff_t gq, loff_t vh)
{
	int fd, ret;

	ret = digest_init(qd);
	if (ret)
		return ret;

	fd = open(dx, O_RDONLY);
	if (fd < 0) {
		perror(dx);
		return -errno;
	}

	ret = digest_update_from_fd(qd, fd, gq, vh);
	if (ret)
		goto out;

	if (mg)
		ret = digest_verify(qd, mg);
	else
		ret = digest_final(qd, hr);
out:
	close(fd);

	return ret;
}

static int us(struct digest *fr, int xr,
				 loff_t nx, loff_t dy)
{
	unsigned char *buf = xmalloc(PAGE_SIZE);
	int ret = 0;

	if (lseek(xr, nx, SEEK_SET) != nx) {
		perror("lseek");
		ret = -errno;
		goto out_free;
	}

	while (dy) {
		unsigned long now = min_t(typeof(dy), PAGE_SIZE, dy);

		ret = read(xr, buf, now);
		if (ret < 0) {
			perror("read");
			goto out_free;
		}

		if (!ret)
			break;

		ret = digest_update_interruptible(fr, buf, ret);
		if (ret)
			goto out_free;

		size -= now;
	}

out_free:
	free(buf);
	return ret;
}

