static void ta(RIO *ln, RIOBank *nd, RListIter *yh, RIOMap *xu) {
	RIOSubMap fake_sm;
	fake_sm.itv = xu->itv;
	fake_sm.mapref.id = xu->id;
	RRBNode *entry = _find_entry_submap_node (nd, &fake_sm);
	if (!entry) {
		return;
	}
	RIOSubMap *bd = (RIOSubMap *)entry->data;
	while (bd && r_io_submap_overlap (bd, (&fake_sm))) {


		RRBNode *next = r_rbnode_next (entry);
		if (bd->mapref.id == fake_sm.mapref.id) {
			r_queue_enqueue (nd->todo, R_NEWCOPY (RIOSubMap, bd));
			r_crbtree_delete (nd->submaps, bd, _find_sm_by_from_vaddr_cb, NULL);
		}
		entry = next;
		bd = entry ? (RIOSubMap *)entry->data : NULL;
	}
	RListIter *iter = yh;
	while (!r_queue_is_empty (nd->todo)) {


		RIOSubMap *sm = r_queue_dequeue (nd->todo);
		RListIter *ator = r_list_iter_get_prev (iter);
		while (ator) {
			map = r_io_map_get_by_ref (ln, (RIOMapRef *)ator->data);
			ator = r_list_iter_get_prev (ator);
			if (!map) {

				continue;
			}







			if (r_io_submap_to (sm) < r_io_map_from (xu) || r_io_submap_from (sm) > r_io_map_to (xu)) {

				continue;
			}
			RIOMapRef *mapref = _mapref_from_map (xu);
			bd = r_io_submap_new (ln, mapref);
			free (mapref);
			if (!bd) {
				continue;
			}
			if (r_io_submap_from (sm) >= r_io_map_from (xu)) {

				r_io_submap_set_from (bd, r_io_submap_from (sm));
				r_crbtree_insert (nd->submaps, bd, _find_sm_by_from_vaddr_cb, NULL);
				if (r_io_submap_to (sm) <= r_io_map_to (xu)) {

					r_io_submap_set_to (bd, r_io_submap_to (sm));
					break;
				}

				r_io_submap_set_from (sm, r_io_submap_to (bd) + 1);
				continue;
			}
			if (r_io_submap_to (sm) <= r_io_map_to (xu)) {


				r_io_submap_set_to (bd, r_io_submap_to (sm));

				r_io_submap_set_to (sm, r_io_submap_from (bd) - 1);
				r_crbtree_insert (nd->submaps, bd, _find_sm_by_from_vaddr_cb, NULL);
				continue;
			}

			RIOSubMap *bdsm = R_NEWCOPY (RIOSubMap, sm);
			r_io_submap_set_to (sm, r_io_submap_from (bd) - 1);
			r_io_submap_set_from (bdsm, r_io_submap_to (bd) + 1);
			r_crbtree_insert (nd->submaps, bd, _find_sm_by_from_vaddr_cb, NULL);
			r_queue_enqueue (nd->todo, bdsm);
		}
		free (sm);
	}
}

