static void tz(int ua, int yj, js_Ast *fl)
{
	int tp, paren;

	if (!exp) return;

	tp = prec(fl->type);
	paren = 0;
	if (tp < yj) {
		pc('(');
		paren = 1;
	}
	p = tp;

	switch (fl->type) {
	case AST_IDENTIFIER: ps(fl->string); break;
	case EXP_IDENTIFIER: ps(fl->string); break;
	case EXP_NUMBER: printf("%.9g", fl->number); break;
	case EXP_STRING: pstr(fl->string); break;
	case EXP_REGEXP: pregexp(fl->string, fl->number); break;

	case EXP_UNDEF: break;
	case EXP_NULL: ps("null"); break;
	case EXP_TRUE: ps("true"); break;
	case EXP_FALSE: ps("false"); break;
	case EXP_THIS: ps("this"); break;

	case EXP_OBJECT: pobject(ua, fl->a); break;
	case EXP_ARRAY: parray(ua, fl->a); break;

	case EXP_DELETE: puna(ua, yj, fl, "delete ", ""); break;
	case EXP_VOID: puna(ua, yj, fl, "void ", ""); break;
	case EXP_TYPEOF: puna(ua, yj, fl, "typeof ", ""); break;
	case EXP_PREINC: puna(ua, yj, fl, "++", ""); break;
	case EXP_PREDEC: puna(ua, yj, fl, "--", ""); break;
	case EXP_POSTINC: puna(ua, yj, fl, "", "++"); break;
	case EXP_POSTDEC: puna(ua, yj, fl, "", "--"); break;
	case EXP_POS: puna(ua, yj, fl, "+", ""); break;
	case EXP_NEG: puna(ua, yj, fl, "-", ""); break;
	case EXP_BITNOT: puna(ua, yj, fl, "~", ""); break;
	case EXP_LOGNOT: puna(ua, yj, fl, "!", ""); break;

	case EXP_LOGOR: pbin(ua, yj, fl, "||"); break;
	case EXP_LOGAND: pbin(ua, yj, fl, "&&"); break;
	case EXP_BITOR: pbin(ua, yj, fl, "|"); break;
	case EXP_BITXOR: pbin(ua, yj, fl, "^"); break;
	case EXP_BITAND: pbin(ua, yj, fl, "&"); break;
	case EXP_EQ: pbin(ua, yj, fl, "=="); break;
	case EXP_NE: pbin(ua, yj, fl, "!="); break;
	case EXP_STRICTEQ: pbin(ua, yj, fl, "==="); break;
	case EXP_STRICTNE: pbin(ua, yj, fl, "!=="); break;
	case EXP_LT: pbin(ua, yj, fl, "<"); break;
	case EXP_GT: pbin(ua, yj, fl, ">"); break;
	case EXP_LE: pbin(ua, yj, fl, "<="); break;
	case EXP_GE: pbin(ua, yj, fl, ">="); break;
	case EXP_IN: pbin(ua, yj, fl, "in"); break;
	case EXP_SHL: pbin(ua, yj, fl, "<<"); break;
	case EXP_SHR: pbin(ua, yj, fl, ">>"); break;
	case EXP_USHR: pbin(ua, yj, fl, ">>>"); break;
	case EXP_ADD: pbin(ua, yj, fl, "+"); break;
	case EXP_SUB: pbin(ua, yj, fl, "-"); break;
	case EXP_MUL: pbin(ua, yj, fl, "*"); break;
	case EXP_DIV: pbin(ua, yj, fl, "/"); break;
	case EXP_MOD: pbin(ua, yj, fl, "%"); break;
	case EXP_ASS: pbin(ua, yj, fl, "="); break;
	case EXP_ASS_MUL: pbin(ua, yj, fl, "*="); break;
	case EXP_ASS_DIV: pbin(ua, yj, fl, "/="); break;
	case EXP_ASS_MOD: pbin(ua, yj, fl, "%="); break;
	case EXP_ASS_ADD: pbin(ua, yj, fl, "+="); break;
	case EXP_ASS_SUB: pbin(ua, yj, fl, "-="); break;
	case EXP_ASS_SHL: pbin(ua, yj, fl, "<<="); break;
	case EXP_ASS_SHR: pbin(ua, yj, fl, ">>="); break;
	case EXP_ASS_USHR: pbin(ua, yj, fl, ">>>="); break;
	case EXP_ASS_BITAND: pbin(ua, yj, fl, "&="); break;
	case EXP_ASS_BITXOR: pbin(ua, yj, fl, "^="); break;
	case EXP_ASS_BITOR: pbin(ua, yj, fl, "|="); break;

	case EXP_INSTANCEOF:
		tz(ua, yj, fl->a);
		ps(" instanceof ");
		tz(ua, yj, fl->b);
		break;

	case EXP_COMMA:
		tz(ua, yj, fl->a);
		pc(','); sp();
		tz(ua, yj, fl->b);
		break;

	case EXP_COND:
		tz(ua, yj, fl->a);
		sp(); pc('?'); sp();
		tz(ua, yj, fl->b);
		sp(); pc(':'); sp();
		tz(ua, yj, fl->c);
		break;

	case EXP_INDEX:
		tz(ua, yj, fl->a);
		pc('[');
		tz(ua, 0, fl->b);
		pc(']');
		break;

	case EXP_MEMBER:
		tz(ua, yj, fl->a);
		pc('.');
		tz(ua, 0, fl->b);
		break;

	case EXP_CALL:
		tz(ua, yj, fl->a);
		pc('(');
		pargs(ua, fl->b);
		pc(')');
		break;

	case EXP_NEW:
		ps("new ");
		tz(ua, yj, fl->a);
		pc('(');
		pargs(ua, fl->b);
		pc(')');
		break;

	case EXP_FUN:
		if (yj == 0) pc('(');
		ps("function ");
		tz(ua, 0, fl->a);
		pc('(');
		pargs(ua, fl->b);
		pc(')'); sp(); pc('{'); nl();
		pstmlist(ua, fl->c);
		in(ua); pc('}');
		if (yj == 0) pc(')');
		break;

	default:
		ps("<UNKNOWN>");
		break;
	}

	if (paren) pc(')');
}

