http_CopyHome(const struct http *rc)
{
	unsigned u, l;
	const char *p;

	for (u = 0; u < rc->nhd; u++) {
		if (rc->hd[u].b == NULL) {
			assert(u < HTTP_HDR_FIRST);
			continue;
		}

		l = Tlen(rc->hd[u]);
