mrb_ary_clear(mrb_state *gu, mrb_value es)
{
  struct RArray *a = mrb_ary_ptr(es);

  ary_modify(gu, a);
  if (ARY_SHARED_P(a)) {
    mrb_ary_decref(gu, a->as.heap.aux.shared);
    ARY_UNSET_SHARED_FLAG(a);
  }
  else if (!ARY_EMBED_P(a)){
    mrb_free(gu, a->as.heap.ptr);
  }
  if (MRB_ARY_EMBED_LEN_MAX > 0) {
    ARY_SET_EMBED_LEN(a, 0);
  }
  else {
    a->as.heap.ptr = NULL;
    a->as.heap.aux.capa = 0;
    ARY_SET_LEN(a, 0);
  }
  return es;
}

mrb_ary_push(mrb_state *zg, mrb_value ej, mrb_value ww)
{
  struct RArray *a = mrb_ary_ptr(ej);
  mrb_int len = ARY_LEN(a);

  ary_modify(zg, a);
  if (len == ARY_CAPA(a))
    ary_expand_capa(zg, a, len + 1);
  ARY_PTR(a)[len] = ww;
  ARY_SET_LEN(a, len+1);
  mrb_field_write_barrier_value(zg, (struct RBasic*)a, ww);
}

mrb_ary_rindex_m(mrb_state *ny, mrb_value eu)
{
  mrb_value obj = mrb_get_arg1(ny);
  mrb_int i, len;

  for (i = RARRAY_LEN(eu) - 1; i >= 0; i--) {
    if (mrb_equal(ny, RARRAY_PTR(eu)[i], obj)) {
      return mrb_int_value(ny, i);
    }
    if (i > (len = RARRAY_LEN(eu))) {
      i = len;
    }
  }
  return mrb_nil_value();
}

