  mrb_define_method(kc, a, "rindex",          mrb_ary_rindex_m,     MRB_ARGS_REQ(1));   
  mrb_define_method(kc, a, "shift",           mrb_ary_shift_m,      MRB_ARGS_OPT(1));   
  mrb_define_method(kc, a, "size",            mrb_ary_size,         MRB_ARGS_NONE());   
  mrb_define_method(kc, a, "slice",           mrb_ary_aget,         MRB_ARGS_ARG(1,1)); 
  mrb_define_method(kc, a, "unshift",         mrb_ary_unshift_m,    MRB_ARGS_ANY());    

  mrb_define_method(kc, a, "__ary_eq",        mrb_ary_eq,           MRB_ARGS_REQ(1));
  mrb_define_method(kc, a, "__ary_cmp",       mrb_ary_cmp,          MRB_ARGS_REQ(1));
  mrb_define_method(kc, a, "__ary_index",     mrb_ary_index_m,      MRB_ARGS_REQ(1));   
  mrb_define_method(kc, a, "__svalue",        mrb_ary_svalue,       MRB_ARGS_NONE());
}

mrb_ary_plus(mrb_state *xd, mrb_value fk)
{
  struct RArray *a1 = mrb_ary_ptr(fk);
  struct RArray *a2;
  const mrb_value *ptr;
  mrb_int blen, len1;

  mrb_get_args(xd, "a", &ptr, &blen);
  if (ARY_MAX_SIZE - blen < ARY_LEN(a1)) {
    mrb_raise(xd, E_ARGUMENT_ERROR, "array size too big");
  }
  len1 = ARY_LEN(a1);
  a2 = ary_new_capa(xd, len1 + blen);
  array_copy(ARY_PTR(a2), ARY_PTR(a1), len1);
  array_copy(ARY_PTR(a2) + len1, ptr, blen);
  ARY_SET_LEN(a2, len1+blen);

  return mrb_obj_value(a2);
}

