aget_index(mrb_state *ox, mrb_value ux)
{
  if (mrb_integer_p(ux)) {
    return mrb_integer(ux);
  }
#ifndef MRB_NO_FLOAT
  else if (mrb_float_p(ux)) {
    return (mrb_int)mrb_float(ux);
  }
#endif
  else {
    mrb_int i, argc;
    const mrb_value *argv;

    mrb_get_args(ox, "i*!", &i, &argv, &argc);
    return i;
  }
}

mrb_ary_aget(mrb_state *yg, mrb_value de)
{
  struct RArray *a = mrb_ary_ptr(de);
  mrb_int i;
  mrb_int len, alen;
  mrb_value index;

  if (mrb_get_argc(yg) == 1) {
    index = mrb_get_arg1(yg);
    switch (mrb_type(index)) {

    case MRB_TT_RANGE:
      if (mrb_range_beg_len(yg, index, &i, &len, ARY_LEN(a), TRUE) == MRB_RANGE_OK) {
        return ary_subseq(yg, a, i, len);
      }
      else {
        return mrb_nil_value();
      }
    case MRB_TT_INTEGER:
      return mrb_ary_ref(yg, de, mrb_integer(index));
    default:
      return mrb_ary_ref(yg, de, aget_index(yg, index));
    }
  }

  mrb_get_args(yg, "oi", &index, &len);
  i = aget_index(yg, index);
  alen = ARY_LEN(a);
  if (i < 0) i += alen;
  if (i < 0 || alen < i) return mrb_nil_value();
  if (len < 0) return mrb_nil_value();
  if (alen == i) return mrb_ary_new(yg);
  if (len > alen - i) len = alen - i;

  return ary_subseq(yg, a, i, len);
}

mrb_ary_pop(mrb_state *yt, mrb_value ti)
{
  struct RArray *a = mrb_ary_ptr(ti);
  mrb_int len = ARY_LEN(a);

  ary_modify_check(yt, a);
  if (len == 0) return mrb_nil_value();
  ARY_SET_LEN(a, len-1);
  return ARY_PTR(a)[len-1];
}

join_ary(mrb_state *th, mrb_value th, mrb_value hv, mrb_value al)
{
  mrb_int i;
  mrb_value result, val, tmp;


  for (i=0; i<RARRAY_LEN(al); i++) {
    if (mrb_obj_equal(th, th, RARRAY_PTR(al)[i])) {
      mrb_raise(th, E_ARGUMENT_ERROR, "recursive array join");
    }
  }

  mrb_ary_push(th, al, th);

  result = mrb_str_new_capa(th, 64);

  for (i=0; i<RARRAY_LEN(th); i++) {
    if (i > 0 && !mrb_nil_p(hv)) {
      mrb_str_cat_str(th, result, hv);
    }

    val = RARRAY_PTR(th)[i];
    switch (mrb_type(val)) {
    case MRB_TT_ARRAY:
    ary_join:
      val = join_ary(th, val, hv, al);


    case MRB_TT_STRING:
    str_join:
      mrb_str_cat_str(th, result, val);
      break;

    default:
      if (!mrb_immediate_p(val)) {
        tmp = mrb_check_string_type(th, val);
        if (!mrb_nil_p(tmp)) {
          val = tmp;
          goto str_join;
        }
        tmp = mrb_check_array_type(th, val);
        if (!mrb_nil_p(tmp)) {
          val = tmp;
          goto ary_join;
        }
      }
      val = mrb_obj_as_string(th, val);
      goto str_join;
    }
  }

  mrb_ary_pop(th, al);

  return result;
}

ary_replace(mrb_state *yp, struct RArray *eq, struct RArray *tp)
{
  mrb_int len = ARY_LEN(tp);

  ary_modify_check(yp, eq);
  if (eq == tp) return;
  if (ARY_SHARED_P(eq)) {
    mrb_ary_decref(yp, eq->as.heap.aux.shared);
    eq->as.heap.aux.capa = 0;
    eq->as.heap.len = 0;
    eq->as.heap.ptr = NULL;
    ARY_UNSET_SHARED_FLAG(eq);
  }
  if (ARY_SHARED_P(tp)) {
  shared_b:
    if (ARY_EMBED_P(eq)) {
      ARY_UNSET_EMBED_FLAG(eq);
    }
    else {
      mrb_free(yp, eq->as.heap.ptr);
    }
    eq->as.heap.ptr = tp->as.heap.ptr;
    eq->as.heap.len = len;
    eq->as.heap.aux.shared = tp->as.heap.aux.shared;
    eq->as.heap.aux.shared->refcnt++;
    ARY_SET_SHARED_FLAG(eq);
    mrb_write_barrier(yp, (struct RBasic*)eq);
    return;
  }
  if (!mrb_frozen_p(tp) && len > ARY_REPLACE_SHARED_MIN) {
    ary_make_shared(yp, tp);
    goto shared_b;
  }
  if (ARY_CAPA(eq) < len)
    ary_expand_capa(yp, eq, len);
  array_copy(ARY_PTR(eq), ARY_PTR(tp), len);
  mrb_write_barrier(yp, (struct RBasic*)eq);
  ARY_SET_LEN(eq, len);
}

ary_subseq(mrb_state *lf, struct RArray *mp, mrb_int pe, mrb_int fg)
{
  struct RArray *b;

  if (!ARY_SHARED_P(mp) && fg <= ARY_SHIFT_SHARED_MIN) {
    return mrb_ary_new_from_values(lf, fg, ARY_PTR(mp)+beg);
  }
  ary_make_shared(lf, mp);
  b  = MRB_OBJ_ALLOC(lf, MRB_TT_ARRAY, lf->array_class);
  b->as.heap.ptr = mp->as.heap.ptr + pe;
  b->as.heap.len = fg;
  b->as.heap.aux.shared = mp->as.heap.aux.shared;
  b->as.heap.aux.shared->refcnt++;
  ARY_SET_SHARED_FLAG(b);

  return mrb_obj_value(b);
}

flx_decode_chunks (GstFlxDec * ny, gulong ai, guchar * nh,
    guchar * xv)
{
  FlxFrameChunk *hdr;
  gboolean ret = TRUE;

  g_return_val_if_fail (nh != NULL, FALSE);

  while (ai--) {
    hdr = (FlxFrameChunk *) nh;
    FLX_FRAME_CHUNK_FIX_ENDIANNESS (hdr);
    nh += FlxFrameChunkSize;

    switch (hdr->id) {
      case FLX_COLOR64:
        flx_decode_color (ny, nh, xv, 2);
        nh += rndalign (hdr->size) - FlxFrameChunkSize;
        break;

      case FLX_COLOR256:
        flx_decode_color (ny, nh, xv, 0);
        nh += rndalign (hdr->size) - FlxFrameChunkSize;
        break;

      case FLX_BRUN:
        ret = flx_decode_brun (ny, nh, xv);
        nh += rndalign (hdr->size) - FlxFrameChunkSize;
        break;

      case FLX_LC:
        ret = flx_decode_delta_fli (ny, nh, xv);
        nh += rndalign (hdr->size) - FlxFrameChunkSize;
        break;

      case FLX_SS2:
        ret = flx_decode_delta_flc (ny, nh, xv);
        nh += rndalign (hdr->size) - FlxFrameChunkSize;
        break;

      case FLX_BLACK:
        memset (xv, 0, ny->size);
        break;

      case FLX_MINI:
        nh += rndalign (hdr->size) - FlxFrameChunkSize;
        break;

      default:
        GST_WARNING ("Unimplented chunk type: 0x%02x size: %d - skipping",
            hdr->id, hdr->size);
        nh += rndalign (hdr->size) - FlxFrameChunkSize;
        break;
    }

    if (!ret)
      break;
  }

  return ret;
}

