static int fm(ADTSContext *cq,
                                   uint8_t *wm, int xz, int qt)
{
    PutBitContext pb;

    unsigned full_frame_size = (unsigned)ADTS_HEADER_SIZE + xz + qt;
    if (full_frame_size > ADTS_MAX_FRAME_BYTES) {
        av_log(NULL, AV_LOG_ERROR, "ADTS frame xz too large: %u (max %d)\n",
               full_frame_size, ADTS_MAX_FRAME_BYTES);
        return AVERROR_INVALIDDATA;
    }

    init_put_bits(&pb, wm, ADTS_HEADER_SIZE);


    put_bits(&pb, 12, 0xfff);   
    put_bits(&pb, 1, cq->mpeg_id); 
    put_bits(&pb, 2, 0);        
    put_bits(&pb, 1, 1);        
    put_bits(&pb, 2, cq->objecttype); 
    put_bits(&pb, 4, cq->sample_rate_index);
    put_bits(&pb, 1, 0);        
    put_bits(&pb, 3, cq->channel_conf); 
    put_bits(&pb, 1, 0);        
    put_bits(&pb, 1, 0);        


    put_bits(&pb, 1, 0);        
    put_bits(&pb, 1, 0);        
    put_bits(&pb, 13, full_frame_size); 
    put_bits(&pb, 11, 0x7ff);   
    put_bits(&pb, 2, 0);        

    flush_put_bits(&pb);

    return 0;
}

static UINT fk(IWTSVirtualChannelCallback* rm, wStream* by)
{
	VIDEO_CHANNEL_CALLBACK* callback = (VIDEO_CHANNEL_CALLBACK*)rm;
	VIDEO_PLUGIN* video;
	VideoClientContext* context;
	UINT ret = CHANNEL_RC_OK;
	UINT32 cbSize, packetType;

	video = (VIDEO_PLUGIN*)callback->plugin;
	context = (VideoClientContext*)video->wtsPlugin.pInterface;

	if (Stream_GetRemainingLength(by) < 4)
		return ERROR_INVALID_DATA;

	Stream_Read_UINT32(by, cbSize);
	if (cbSize < 8 || Stream_GetRemainingLength(by) < (cbSize - 4))
	{
		WLog_ERR(TAG, "invalid cbSize");
		return ERROR_INVALID_DATA;
	}

	Stream_Read_UINT32(by, packetType);
	switch (packetType)
	{
		case TSMM_PACKET_TYPE_PRESENTATION_REQUEST:
			ret = video_read_tsmm_presentation_req(context, by);
			break;
		default:
			WLog_ERR(TAG, "not expecting packet type %" PRIu32 "", packetType);
			ret = ERROR_UNSUPPORTED_TYPE;
			break;
	}

	return ret;
}

